  ctx: {
    ledgerPath: string;
    runId: string;
    headSha: string;
    decisionDigest: string;
    prUrl: string;
    row: Record<string, unknown>;
    log: (step: string, extra?: Record<string, unknown>) => void;
    say: (msg: string) => void;
  },
  readLines: (path: string) => ReadonlyArray<Record<string, unknown>> = readLedgerLines,
