function ciEvidenceDisagreementObservation(args: {
  checksState?: OpenPrView["checksState"];
  redChecks?: readonly string[];
  ciFailures: readonly CiFailure[];
  sha?: string;
}): CiEvidenceDisagreementObservation {
  return {
    ...(args.sha ? { sha: args.sha } : {}),
    rollup: {
      checks_state: args.checksState ?? "red",
      red_checks: [...(args.redChecks ?? [])],
    },
    miner: {
      enumerable_failures: args.ciFailures.map((failure) => ({ name: failure.name })),
    },
  };
}

/**
 * W1-T177: the real live-state reader every fix-rung/sweep spending site
 * wires — ONE fresh read, never a cached snapshot. A throw (rate limit,
 * network, auth) reports `ok:false` — INDETERMINATE, never treated as
 * terminal (`terminalStateReason` is never even called on it; see every call
 * site's fail-open handling).
 *
 * W1-T511: reads over REST (`liveStateFromRest`, one `GET /pulls/{n}` call),
 * never `gh pr view --json state` (GraphQL). Measured 2026-08-15: 31 of 114
 * `sweep.post_review` attempts aborted whole on exactly this call's GraphQL
 * error while the REST/core budget sat healthy throughout — see this task's
 * rationale. `prUrlTarget` parses owner/repo/number from the URL every call
 * site here already passes; a URL that fails to parse is treated exactly
 * like a failed fetch (`ok:false`), never a crash, mirroring the pre-existing
 * catch-and-fail-open contract.
 */
function ghLiveState(prUrl: string): LiveStateResult {
  return runStepsSync(liveStateSteps(prUrl, ghJson));
}

export function ghLiveStateAsync(prUrl: string): Promise<LiveStateResult> {
  return runStepsAsync(liveStateSteps(prUrl, args => ghJsonAsync(args)));
}

function* liveStateSteps(prUrl: string, read: GhApiFetcher): Steps<LiveStateResult> {
  const target = prUrlTarget(prUrl);
  if (!target) return { ok: false };
  try {
    const row = (yield* step(() => read(singlePrRestArgs(target.owner, target.repo, target.number)))) as RestPullRow;
    const state = prStateFromRest(row);
    const headSha = row.head?.sha;
    return state ? { ok: true, state, ...(typeof headSha === "string" ? { headSha } : {}) } : { ok: false };
  } catch {
    return { ok: false };
  }
}

/**
 * W1-T296: one fresh, live read of a PR's head commit sha + its author —
 * the branch-authorship stand-down's evidence. `ok:false` marks a genuinely
 * FAILED or INDETERMINATE read (network/auth/rate-limit), mirroring
 * {@link LiveStateResult}'s own contract: the caller must treat that exactly
 * as if no check ran at all, never as foreign. `headSha`/`author` are present
 * only when `ok`; `author` itself may still be absent (an unattributable
 * commit, e.g. a squash-merge bot) even on an otherwise-successful read.
 */

/**
 * W1-T296: the real live-head reader the fix rung wires for its pre-strike
 * branch-authorship check — a fresh `gh pr view --json headRefOid,commits`
 * read (never a cached snapshot, and never the headRefOid-only read
 * {@link realArmDeps} uses, which carries no author). Names the HEAD
 * commit's author specifically (matched by `oid`, not just "the last commit
 * listed") so the escalation this stands down into names the right person
 * even when `commits` is not sha-ordered. A throw (rate limit, network,
 * auth) or a response missing `headRefOid` reports `ok:false`.
 */
export function ghLiveHead(prUrl: string, gh: (args: string[]) => unknown = ghJson): LiveHeadResult {
  try {
    const v = gh(["pr", "view", prUrl, "--json", "headRefOid,headRefName,commits"]) as {
      headRefOid?: string;
      headRefName?: string;
      commits?: Array<{ oid?: string; authors?: Array<{ login?: string; name?: string }> }>;
    };
    if (!v?.headRefOid) return { ok: false };
    const headCommit = v.commits?.find((c) => c.oid === v.headRefOid);
    const author = headCommit?.authors?.[0]?.login ?? headCommit?.authors?.[0]?.name;
    return { ok: true, headSha: v.headRefOid, author, headRefName: v.headRefName };
  } catch {
    return { ok: false };
  }
}

