/** The once-per-run guard both enders share. Best-effort: a ledger failure never replaces the run's own outcome. */

/** W1-T4656: a pre-push census refusal read off a push error — the hook's block, the censuses its rows name,
 *  and the baseline files a row itself offers ("or record … in <file>"). Undefined for any other failure. */

export function censusPushRefusal(err: unknown): CensusPushRefusal | undefined {
  const lines = String((err as Error)?.message ?? err).split("\n");
  const at = lines.findIndex((l) => /^census-precheck: this branch grows \d+ census count/.test(l));
  const rows: string[] = [];
  for (const line of at < 0 ? [] : lines.slice(at + 1)) {
    if (!/^\s+[a-z][\w-]*: /.test(line)) break;
    rows.push(line);
  }
  if (rows.length === 0) return undefined;
  const uniq = (xs: string[]) => [...new Set(xs)].sort();
  return {
    text: [lines[at]!, ...rows].join("\n"),
    censuses: uniq(rows.map((r) => r.trim().split(":")[0]!)),
    offeredBaselines: uniq(rows.flatMap((r) => r.match(/\bor record .* in (\S+)$/)?.[1] ?? [])),
  };
}

const CENSUS_BASELINE_FILES = ["scripts/clock-signature-baseline.json", "scripts/comment-load-baseline.json", "scripts/fixture-copy-baseline.json"];
const CENSUS_PUSH_CHECK = "pre-push census-precheck";
const CENSUS_SNAPSHOT_ENV = "RMD_CENSUS_SNAPSHOT";
const CENSUS_SNAPSHOT_ROOTS = [...MEASURED_ROOTS, "test", "plan"];
const COVERAGE_PUSH_CHECK = "pre-push coverage-precheck";
const MERGED_TYPECHECK_PUSH_CHECK = "merged-tree-typecheck";
const CENSUS_PUSH_NEVER_BYPASS =
  "Apply the remedy each row names, preferring the code change; record a baseline row only where that row offers\n" +
  "one. Never push with --no-verify or RMD_PREPUSH_GATES=0: the harness retries the push through the hook.";

/** W1-T8918: core's census suites (census-precheck and the reach ratchet) measure core's own registry and shrink-only
 *  baselines, so they run only for the harness's own repository. Decided by repository IDENTITY — the task's repo
 *  against the repo the harness serves — never by whether a baseline file exists: a core branch that deletes
 *  scripts/affected-reach-baseline.json must still be refused. A repo that is not core's is ledgered
 *  `fix.census_check` "not-applicable" so the skip is visible. An unnamed repo or an unresolvable core identity
 *  keeps the check (fail closed), and says why. */
export function fixCensusAppliesToRepo(
  repo: string | undefined,
  log: (step: string, extra?: Record<string, unknown>) => void,
  resolveSelf: () => { owner: string; repo: string } = resolveOwnerRepo,
): boolean {
  if (repo === undefined) return true;
  let coreRepo: string;
  try {
    coreRepo = resolveSelf().repo;
  } catch (error) {
    log("fix.census_check", { outcome: "core-identity-unresolved", repo, reason: String(error) });
    return true;
  }
  if (repo === coreRepo) return true;
  log("fix.census_check", { outcome: "not-applicable", repo, core_repo: coreRepo });
  return false;
}

export async function censusSnapshotForCheck(
  root: string, path: string | undefined, merging: boolean,
  write: ((root: string, log: (step: string, extra?: Record<string, unknown>) => void) => string | undefined | Promise<string | undefined>) | undefined,
  log: (step: string, extra?: Record<string, unknown>) => void,
): Promise<string | undefined> {
  return fixCommandHelpers(fixCommandHost()).censusSnapshotForCheck(root, path, merging, write, log);
}

export function writeFixCensusSnapshot(root: string, log: (step: string, extra?: Record<string, unknown>) => void, runGit: typeof hostWorktreeGit = hostWorktreeGit): string | undefined {
  return runStepsSync(writeFixCensusSnapshotSteps(root, log, runGit));
}

export function writeFixCensusSnapshotAsync(root: string, log: (step: string, extra?: Record<string, unknown>) => void, runGit: (root: string, args: string[], options?: HostWorktreeGitOptions) => string | Promise<string> = hostWorktreeGitAsync): Promise<string | undefined> {
  return runStepsAsync(writeFixCensusSnapshotSteps(root, log, runGit));
}

function* writeFixCensusSnapshotSteps(
  root: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  runGit: (root: string, args: string[], options?: HostWorktreeGitOptions) => string | Promise<string>,
): Steps<string | undefined> {
  try {
    const headSha = (yield* step(() => runGit(root, ["rev-parse", "HEAD"]))).trim();
    const mainSha = (yield* step(() => runGit(root, ["rev-parse", "origin/main"]))).trim();
    const mergeHeadPath = resolve(root, (yield* step(() => runGit(root, ["rev-parse", "--git-path", "MERGE_HEAD"]))).trim());
    const mergingMain = existsSync(mergeHeadPath) && readFileSync(mergeHeadPath, "utf8").split("\n")[0]!.trim() === mainSha;
    const mergeBase = mergingMain ? mainSha : (yield* step(() => runGit(root, ["merge-base", headSha, mainSha]))).trim();
    const censusPath = (p: string) =>
      (CENSUS_SNAPSHOT_ROOTS.some((dir: string) => p.startsWith(`${dir}/`)) || ["package.json", ".dependency-cruiser.cjs"].includes(p)) &&
      (/\.(?:ts|mts|mjs|js|cjs|json|ya?ml|sh|md|toml|txt)$/.test(p) || !basename(p).includes("."));
    function* paths(args: string[]): Steps<string[]> {
      return [...new Set((yield* step(() => runGit(root, args))).split("\n").filter((p) => p && censusPath(p)))];
    }
    const headPaths = yield* paths(["ls-files"]);
    const basePaths = yield* paths(["ls-tree", "-r", "--name-only", mergeBase]);
    const mainPaths = (yield* paths(["ls-tree", "-r", "--name-only", mainSha, "--", "scripts"]))
      .filter((p) => p.endsWith("baseline.json"));
    function* blobs(ref: string, names: string[]): Steps<Record<string, string>> {
      if (names.length === 0) return {};
      const output = Buffer.from(yield* step(() => runGit(root, ["cat-file", "--batch"], {
        input: names.map((p) => `${ref}:${p}\n`).join(""), maxBuffer: 128 * 1024 * 1024,
      })));
      const texts: Record<string, string> = {};
      let offset = 0;
      for (const path of names) {
        const end = output.indexOf(10, offset);
        const header = output.subarray(offset, end).toString("utf8");
        const match = /^[a-f0-9]+ blob (\d+)$/.exec(header);
        if (end < 0 || !match) throw new Error(`census base blob unreadable: ${path}`);
        const size = Number(match[1]);
        offset = end + 1;
        if (output[offset + size] !== 10) throw new Error(`census base blob truncated: ${path}`);
        texts[path] = output.subarray(offset, offset + size).toString("utf8");
        offset += size + 1;
      }
      return texts;
    };
    const snapshot = { version: 1, root: resolve(root), headSha, mainSha, mergeBase, headPaths, basePaths,
      baseBlobs: yield* blobs(mergeBase, basePaths), mainBlobs: yield* blobs(mainSha, mainPaths),
      instrumentSurface: INSTRUMENT_SURFACE, instrumentExclusions: INSTRUMENT_SURFACE_EXCLUSIONS };
    mkdirSync(join(root, "state"), { recursive: true });
    if (lstatSync(join(root, "state")).isSymbolicLink()) throw new Error("census state directory is a symlink");
    const path = join(mkdtempSync(join(root, "state", "rmd-census-")), "snapshot.json");
    writeFileSync(path, JSON.stringify(snapshot), { flag: "wx", mode: 0o444 });
    log("fix.census_snapshot", { outcome: "available", path, head_sha: headSha, main_sha: mainSha, merge_base: mergeBase,
      ...(mergingMain ? { merge_head: mainSha } : {}) });
    return path;
  } catch (error) {
    log("fix.census_snapshot", { outcome: "unavailable", reason: String(error) });
    return undefined;
  }
}

/** A census child's result: `spawnSync`'s own fields, or the same fields from {@link spawnCensusChild}. */
/** How a census check runs one child: `spawnSync` on the CLI, an awaited spawn on the daemon's loop (W1-T7744). */

/** W1-T10935: only the witnessed relative-to-package-imports contract migration is a refresh
 * candidate. This is context for a refusing gate, never permission to skip it or raise its baseline. */
export function readInheritedCensusContextAsync(root: string, path: string): Promise<import("./cli/commands/run-task-verb.js").InheritedCensusContext> {
  return runStepsAsync(inheritedCensusContextSteps(root, path, hostWorktreeGitAsync));
}

function* inheritedCensusContextSteps(
  root: string, path: string,
  git: (root: string, args: string[], options?: HostWorktreeGitOptions) => string | Promise<string>,
): Steps<import("./cli/commands/run-task-verb.js").InheritedCensusContext> {
  const baselinePath = "scripts/affected-reach-baseline.json";
  try {
    // Read only the small, writer-owned identity prefix, not the snapshot's large baseBlobs union.
    const fd = openSync(path, fsConstants.O_RDONLY | fsConstants.O_NOFOLLOW | fsConstants.O_NONBLOCK);
    let prefix: string;
    try {
      if (!fstatSync(fd).isFile()) throw new Error("census snapshot is not a regular file");
      const bytes = Buffer.alloc(8192);
      prefix = bytes.subarray(0, readSync(fd, bytes, 0, bytes.length, 0)).toString("utf8");
    } finally { closeSync(fd); }
    const end = prefix.indexOf(',"headPaths":');
    if (end < 0) throw new Error("census snapshot identity prefix unavailable");
    const identity = JSON.parse(prefix.slice(0, end) + "}");
    if (identity.version !== 1 || identity.root !== resolve(root) ||
        ![identity.headSha, identity.mainSha, identity.mergeBase].every(sha => typeof sha === "string" && /^[a-f0-9]{40}$/.test(sha))) {
      throw new Error("census snapshot identity invalid");
    }
    const read = function* (args: string[]): Steps<string> {
      return (yield* step(() => git(root, args, { maxBuffer: 256 * 1024, timeout: 120_000 }))).trim();
    };
    if ((yield* read(["rev-parse", "HEAD"])) !== identity.headSha ||
        (yield* read(["rev-parse", "origin/main"])) !== identity.mainSha ||
        (yield* read(["merge-base", identity.headSha, identity.mainSha])) !== identity.mergeBase) {
      throw new Error("census snapshot refs changed");
    }
    const branchEdits = yield* read(["diff", "--name-only", identity.mergeBase, identity.headSha, "--", baselinePath]);
    if (branchEdits !== "" || (yield* read(["diff", "HEAD", "--", baselinePath])) !== "" ||
        (yield* read(["diff", "--cached", "HEAD", "--", baselinePath])) !== "") {
      return { state: "not-inherited", reason: "branch or saved work edits the reach baseline" };
    }
    const base = yield* read(["show", `${identity.mergeBase}:${baselinePath}`]);
    const main = yield* read(["show", `${identity.mainSha}:${baselinePath}`]);
    if (JSON.parse(base).resolution !== undefined || JSON.parse(main).resolution !== "package-imports") {
      return { state: "not-inherited", reason: "no witnessed reach resolution migration on main" };
    }
    return { state: "inherited", headSha: identity.headSha, mainSha: identity.mainSha,
      mergeBase: identity.mergeBase, baselinePath };
  } catch (error) {
    return { state: "unavailable", reason: String(error).slice(0, 512) };
  }
}

export function checkFixCensusSnapshot(
  root: string,
  path: string | undefined,
  log: (step: string, extra?: Record<string, unknown>) => void,
  run: typeof spawnSync = spawnSync,
): { refusal?: CensusPushRefusal; unmeasured?: string } | undefined {
  return runStepsSync(fixCensusSnapshotSteps(root, path, log, (file, args, options) => run(file, args, options), hostWorktreeGit));
}

/** W1-T7744 — the census check with both children awaited, for the fix rung and the census-push repair, which the
 *  daemon runs on its own loop (up to 5.9 s held, 2026-10-10). The same steps as the sync form, so the refusal, the
 *  unmeasured reading and the child bounds cannot drift between them. */
export async function checkFixCensusSnapshotAsync(
  root: string,
  path: string | undefined,
  log: (step: string, extra?: Record<string, unknown>) => void,
  run: CensusChildRunner<Promise<CensusChildResult>> = spawnCensusChild,
): Promise<{ refusal?: CensusPushRefusal; unmeasured?: string } | undefined> {
  return runStepsAsync(fixCensusSnapshotSteps(root, path, log, run, hostWorktreeGitAsync));
}

/** One census child off the event loop, in `spawnSync`'s result shape: `status` is the exit code (null when killed
 *  or never started), `signal` the killing signal, `error` a spawn failure or the bound's kill. */
export function spawnCensusChild(file: string, args: string[], options: SpawnSyncOptionsWithStringEncoding): Promise<CensusChildResult> {
  return new Promise((resolveChild) => {
    const child = execFile(file, args, { cwd: options.cwd, env: options.env, encoding: "utf8", maxBuffer: options.maxBuffer },
      (error, stdout, stderr) => {
        bound?.cancel();
        // The bound's kill keeps its named error beside the signal, as spawnSync's ETIMEDOUT does: a refusal then says the
        // budget stopped the child instead of reading as an outside SIGTERM. The output stays on stdout/stderr, so the
        // error's text cannot be cut away by the refusal's 4,000-character tail.
        const failed = (bound?.timedOut ? bound.timeoutError(file) : error) as (Error & { code?: unknown; signal?: NodeJS.Signals | null }) | null;
        const status = failed === null ? 0 : typeof failed.code === "number" ? failed.code : null;
        const signal = failed?.signal ?? null;
        resolveChild({ status, signal, stdout: String(stdout), stderr: String(stderr),
          ...(failed !== null && status === null && (signal === null || bound?.timedOut) ? { error: failed } : {}) } as CensusChildResult);
      });
    const bound = options.timeout ? boundChildByLoopTime(child, options.timeout) : undefined;
  });
}

function* fixCensusSnapshotSteps(
  root: string,
  path: string | undefined,
  log: (step: string, extra?: Record<string, unknown>) => void,
  run: CensusChildRunner<CensusChildResult | Promise<CensusChildResult>>,
  runGit: (root: string, args: string[], options?: HostWorktreeGitOptions) => string | Promise<string>,
): Steps<{ refusal?: CensusPushRefusal; unmeasured?: string } | undefined> {
  if (!path) return undefined;
  const env = Object.fromEntries(Object.entries(process.env)
    .filter(([key]) => !/^(?:GIT_|NODE_TEST_CONTEXT$|RMD_SELF_SYNC_DONE$)/.test(key)));
  env[CENSUS_SNAPSHOT_ENV] = path;
  const scriptsRoot = repoRoot;
  // Pinned to scripts/census-precheck.mjs's CENSUS_SUITE_CHILD_TIME_BOUND_MS: a budget reporting any other value refuses.
  const childTimeBoundMs = 120_000;
  // The trusted controller reports its own fixed stage inventory; no worker code/table is loaded here.
  const budgetRead = yield* step(() => run(process.execPath, [join(scriptsRoot, "scripts/census-precheck.mjs"), "--snapshot-budget"],
    { cwd: scriptsRoot, env, encoding: "utf8", timeout: childTimeBoundMs, maxBuffer: 64 * 1024 * 1024 }));
  let controllerTimeBoundMs: number;
  try {
    if (budgetRead.status !== 0 || budgetRead.signal || budgetRead.error) throw new Error("budget inspector did not complete");
    const budget = JSON.parse(String(budgetRead.stdout)) as { version?: number; childTimeBoundMs?: number;
      stages?: Record<string, number>; timeoutMs?: number };
    const stages = budget.stages;
    const keys = ["setup", "admission", "reach", "joinedGitFree", "structuralGitFree"];
    if (budget.version !== 1 || budget.childTimeBoundMs !== childTimeBoundMs || !stages || Array.isArray(stages) ||
        Object.keys(stages).length !== keys.length || keys.some(key => !Number.isSafeInteger(stages[key]) || stages[key]! < 0) ||
        stages.setup !== 1 || stages.admission !== 1 || stages.reach !== 2 || stages.joinedGitFree !== 2 || stages.structuralGitFree! % 2 !== 0) {
      throw new Error("unsupported controller stage inventory");
    }
    const derived = keys.reduce((sum, key) => sum + stages[key]!, 0) * childTimeBoundMs;
    if (!Number.isSafeInteger(derived) || budget.timeoutMs !== derived || derived <= childTimeBoundMs) throw new Error("invalid derived controller deadline");
    controllerTimeBoundMs = derived;
  } catch (error) {
    const reason = `controller budget UNKNOWN (${error instanceof Error ? error.message : String(error)})`;
    const refusal = { text: `census-precheck: NOT MEASURED — ${reason}`, censuses: [], offeredBaselines: [] };
    log("fix.census_check", { outcome: "refused", refusal: refusal.text, reason });
    return { refusal, unmeasured: reason };
  }
  const precheck = yield* step(() => run(process.execPath, [join(scriptsRoot, "scripts/census-precheck.mjs"), "--root", root],
    { cwd: scriptsRoot, env, encoding: "utf8", timeout: controllerTimeBoundMs, maxBuffer: 64 * 1024 * 1024 }));
  const text = `${precheck.stdout ?? ""}${precheck.stderr ?? ""}`;
  let refusal = censusPushRefusal(text);
  let unmeasured = precheck.status === 2 ? text.trim() : undefined;
  const unavailable = (subject: string, result: CensusChildResult, output: string) => {
    unmeasured = `${subject}: ${String(result.error ?? result.signal ?? (output || `exit ${result.status} without a complete test summary`)).slice(-4000)}`;
    return { text: `census-precheck: NOT MEASURED — ${unmeasured}`, censuses: [], offeredBaselines: [] };
  };
  if (!refusal && (precheck.error || precheck.signal || (precheck.status !== 0 && precheck.status !== 2))) {
    refusal = unavailable("census precheck child", precheck, text);
  }
  if (!refusal) {
    const reach = "test/the-affected-suite-reach-ratchet.test.ts";
    // W1-T8379: judged — an exit 0 passes only when the suite reached its own summary (scripts/pure-test-pool.mjs).
    const judged = prepareJudgedTestRun(["--test", "--test-reporter=tap", "--import", "tsx", "--import",
      "./test/setup/tmp-hygiene.ts", reach], scriptsRoot, "reach-ratchet census suite");
    try {
      const result = yield* step(() => run(process.execPath, judged.args,
        { cwd: scriptsRoot, env: { ...env, ...judged.env }, encoding: "utf8", timeout: childTimeBoundMs, maxBuffer: 64 * 1024 * 1024 }));
      const output = `${result.stdout ?? ""}${result.stderr ?? ""}`;
      const stopped = (reason: string): CensusPushRefusal => ({ text: `census-precheck: this branch grows 1 census count(s) CI will refuse:\n  census-suite: ${reach} fails — ${reason}`,
        censuses: ["census-suite"], offeredBaselines: [] });
      if (result.error || result.signal || result.status === null || !/^# tests [1-9]\d*$/m.test(output)) {
        refusal = unavailable(`census suite ${reach}`, result, output);
      } else if (result.status !== 0) {
        refusal = stopped(String(precheck.error ?? precheck.signal ?? result.error ?? result.signal ?? output).slice(-4000));
        refusal.inheritedMain = yield* inheritedCensusContextSteps(root, path, runGit);
      } else {
        const verdict = judged.judge(0);
        if (!verdict.complete) refusal = stopped(verdict.line);
      }
    } finally {
      judged.cleanup();
    }
  }
  log("fix.census_check", { outcome: refusal ? "refused" : unmeasured ? "partially-measured" : "passed",
    ...(refusal ? { refusal: refusal.text } : {}), ...(unmeasured ? { reason: unmeasured } : {}) });
  return { refusal, unmeasured };
}

/** Preserve this owner before requesting a remote refresh. No reset, clean or sibling ref update. */
export async function preserveInheritedCensusWork(root: string, worktreePath: string, branch: string,
  context: Extract<import("./cli/commands/run-task-verb.js").InheritedCensusContext, { state: "inherited" }>): Promise<Record<string, string>> {
  const git = (args: string[]) => hostWorktreeGitAsync(worktreePath, args, { maxBuffer: 1 << 24 });
  if ((await git(["rev-parse", "HEAD"])).trim() !== context.headSha) throw new Error("saved work head changed");
  const tracked = (await git(["diff", "HEAD", "--name-only", "-z"])).split("\0").filter(Boolean);
  const staged = (await git(["diff", "--cached", "HEAD", "--name-only", "-z"])).split("\0").filter(Boolean);
  const untracked = (await git(["ls-files", "--others", "--exclude-standard", "-z"])).split("\0").filter(Boolean);
  const mainChanged = new Set((await git(["diff", "--name-only", "-z", context.mergeBase, context.mainSha])).split("\0"));
  if ([...tracked, ...staged, ...untracked].some(path => mainChanged.has(path))) throw new Error("saved work overlaps main migration");
  if (untracked.length > 0) return { saved_path: preserveStaleDirtyFixOwner(root, worktreePath, worktreePath, branch, context.headSha) };
  return {
    ...(staged.length > 0 ? { index_recovery_ref: preserveStagedFixOwnerResidue(worktreePath, worktreePath, branch, context.headSha) } : {}),
    ...(tracked.length > 0 ? { recovery_ref: preserveTrackedDirtyFixOwner(worktreePath, worktreePath, branch, context.headSha) } : {}),
  };
}

/** W1-T4693: a fix round's push that did not land — `refusal` set when the pre-push census refused it. */
export class FixRoundPushError extends RmdError {
  constructor(readonly pushCause: RunErrorCause, readonly refusal: CensusPushRefusal | undefined, readonly detail: string) {
    super("git", GENERIC_EXIT_CODE, `fix round push did not land (${pushCause}): ${detail}`, { pushCause });
    this.name = "FixRoundPushError";
  }
}




export function fixRoundLandingFields(landing: FixRoundLanding | undefined, workerSubtype: string, workerFixOutcome: string): Record<string, unknown> {
  return fixCommandHelpers(fixCommandHost()).fixRoundLandingFields(landing, workerSubtype, workerFixOutcome);
}

/** W1-T4693: the one push both fix-rung sites run. Stderr is piped so a refusal is readable; a foreign head
 *  still raises; the only silent failure is a remote that already holds this exact head. W1-T5284: every git
 *  child is awaited — the sweep and runTaskBody run fix rounds on the daemon's loop. */
export async function pushFixRound(
  wt: string, branch: string, expectedHeadSha?: string, priorHeadSha?: string,
  deps: Pick<PushRunBranchAsyncOpts, "capture" | "exec"> & { mergedTypecheck?: MergedTypecheckPorts } = {},
): Promise<FixRoundPushReceipt> {
  // W1-T5658: BOTH fix paths (the run loop's and the sweep's) push through here, so this is the one place a head
  // that compiles alone but not merged with main is refused before it leaves the worktree.
  const merged = await mergedHeadTypechecks(wt, deps.mergedTypecheck);
  if (merged.outcome === "merged_fails") {
    const text = `${MERGED_TYPECHECK_PUSH_CHECK}: this head compiles alone but NOT merged with origin/main (${merged.mainSha.slice(0, 9)}), ` +
      `which is the tree CI builds — merge origin/main into the branch and fix the errors:\n${merged.text}`;
    throw new FixRoundPushError("run-error", { text, censuses: ["merged-tree-typecheck"], offeredBaselines: [] }, text);
  }
  const capture = deps.capture ?? worktreeGitCaptureAsync(wt);
  const push = deps.exec ?? worktreePushExecAsync(wt);
  try {
    if (priorHeadSha !== undefined && expectedHeadSha === undefined) throw new Error("refusing a leased fix push without the committed head sha");
    await gitPushRunBranchAsync(wt, { expectedHeadSha, capture, exec: async (file, args) => {
      const pushArgs = priorHeadSha === undefined ? args : ["-C", wt, "push",
        `--force-with-lease=refs/heads/${branch}:${priorHeadSha}`, "origin", `${expectedHeadSha}:refs/heads/${branch}`];
      await push(file, pushArgs, { stdio: "ignore" });
      if (priorHeadSha !== undefined) {
        const observed = (await capture("git", ["-C", wt, "ls-remote", "origin", `refs/heads/${branch}`])).split(/\s/)[0];
        if (observed !== expectedHeadSha) throw new Error(`leased push of ${branch} expected ${expectedHeadSha}, observed ${observed || "<absent>"}`);
      }
    } });
    return { fixRoundPushedHead: expectedHeadSha };
  } catch (err) {
    if (err instanceof LanePushForeignHeadError && priorHeadSha === undefined) throw err;
    // An unreadable remote simply is not the expected head, so its failure reads as no head at all.
    const remote = await hostWorktreeGitAsync(wt, ["ls-remote", "origin", `refs/heads/${branch}`])
      .then((stdout) => stdout.split(/\s/)[0], () => undefined);
    if (expectedHeadSha !== undefined && remote === expectedHeadSha) return { fixRoundPushedHead: expectedHeadSha };
    throw new FixRoundPushError(runErrorCause(err), censusPushRefusal(err) ?? prePushGateRefusal(err), String((err as Error)?.message ?? err));
  }
}

/**
 * W1-T4797: the pre-push DIFF-COVERAGE precheck's answers — never collapsed.
 * `uncovered` refuses the round before any push, carrying CI's own uncovered-lines text; `covered`
 * pushes as today; `unavailable` (timeout, spawn failure, unreadable lcov, a selector that cannot
 * scope) ALSO pushes: a precheck that cannot look must never block; consumer repos return `not-applicable`.
 */

/** What one scoped `diff-coverage-local.mjs` run came back with. */

/** Everything the precheck reads or spawns, so a test can drive each arm without an instrumented suite. */

/** W1-T5309: CI's own gate predicate — src/ TypeScript and src/ or scripts/ ESM — so an .mjs change is measured. */
const COVERAGE_SRC_FILE = COVERAGE_SOURCE_FILE;
const COVERAGE_UNCOVERED_HEADLINE = /^diff-coverage: (?:BLOCKED -- this diff adds|INVALID process-boundary)/m;
const COVERAGE_MISSING_SF = /no SF record in the coverage report/;
const COVERAGE_TEXT_CAP = 4000;

/** W1-T7744: awaited — the precheck runs inside a build the daemon runs on its own loop. */
const realCoverageChangedFiles = async (wt: string): Promise<string[]> =>
  (await hostWorktreeGitAsync(wt, MERGE_BASE_DIFF_ARGS)).split("\n").map((f) => f.trim()).filter(Boolean);

/**
 * W1-T5074: ASYNC on purpose. `runTask` runs inside the daemon process, so a `spawnSync` here froze every
 * sweep, tick, ledger write and the installation-token refresh timer for the precheck's whole duration
 * (42 minutes, observed). `spawn` + a promise releases the event loop; the bound, output capture and
 * timeout/spawn-error mapping are the ones `spawnSync` gave.
 */
const COVERAGE_RUN_MAX_BUFFER = 64 * 1024 * 1024;
const coverageSandboxText = (reason: unknown): string => new ProofSandboxUnavailableError(String((reason as Error)?.message ?? reason).slice(0, 300)).message;
const coverageSandboxRefusal = (reason: unknown): CoverageRunResult => ({ status: null, output: "", timedOut: false, spawnError: coverageSandboxText(reason) });
const coverageSandboxStart = (binary: string, sandbox: string[], cwd: string, env: NodeJS.ProcessEnv): Promise<string | undefined> =>
  execFileLoopBounded(binary, [...sandbox, process.execPath, "-e", ""], { cwd, env, encoding: "utf8", timeout: 10_000, killSignal: "SIGKILL" }).then(
    () => undefined, (error: { stderr?: unknown; message: string }) => String(error.stderr ?? "").trim().split("\n")[0] || error.message);
const realCoverageRun = async (wt: string, suites: string[], timeoutMs: number, maxOutputBytes: number): Promise<CoverageRunResult> => {
  const status = proofSandboxStatus();
  if (status.mode !== "bwrap") return coverageSandboxRefusal(status.reason);
  const home = makeTempDir("proof-home");
  try {
    const env: NodeJS.ProcessEnv = { ...proofChildEnv(home), TMPDIR: "/tmp", NODE_V8_COVERAGE: "" };
    let sandbox: string[];
    try {
      sandbox = proofSandboxArgv({ cwd: wt, home });
    } catch (error) {
      return { status: null, output: "", timedOut: false, spawnError: coverageSandboxText(error) };
    }
    const startFailure = await coverageSandboxStart(status.binary, sandbox, wt, env);
    if (startFailure !== undefined) return coverageSandboxRefusal(startFailure);
    const argv = [...sandbox, process.execPath, join(wt, "scripts", "diff-coverage-local.mjs"), "--base", "origin/main", "--lcov", "coverage/precheck-lcov.info", ...suites];
    return await spawnCoverageChild(status.binary, argv, wt, env, timeoutMs, maxOutputBytes);
  } finally {
    rmSync(home, { recursive: true, force: true });
  }
};
export const spawnCoverageChild = (file: string, args: string[], wt: string, env: NodeJS.ProcessEnv, timeoutMs: number, maxOutputBytes: number): Promise<CoverageRunResult> =>
  new Promise<CoverageRunResult>((resolve) => {
    const stdout: Buffer[] = [];
    const stderr: Buffer[] = [];
    let retainedBytes = 0;
    let outputLimitExceeded = false;
    let timedOut = false;
    let spawnError: string | undefined;
    let settled = false;
    let bound: LoopBound | undefined;
    const finish = (status: number | null) => {
      if (settled) return;
      settled = true;
      bound?.cancel();
      const decode = (chunks: Buffer[]) => {
        const decoder = new StringDecoder("utf8");
        return decoder.write(Buffer.concat(chunks)) + (outputLimitExceeded ? "" : decoder.end());
      };
      resolve({ status, output: `${decode(stdout)}\n${decode(stderr)}`, timedOut, ...(spawnError === undefined ? {} : { spawnError }) });
    };
    // withoutNodeTestContextEnv: diff-coverage-local.mjs shells its OWN nested `node --test`. `spawn` copies
    // the environment synchronously, so clearing it around the call is enough.
    const child = withoutNodeTestContextEnv(() =>
      spawn(file, args, {
        cwd: wt,
        env,
        stdio: ["ignore", "pipe", "pipe"],
      }),
    );
    const collect = (chunk: Buffer, into: "out" | "err") => {
      if (settled || timedOut || outputLimitExceeded) return;
      const remaining = maxOutputBytes - retainedBytes;
      const kept = Math.min(chunk.byteLength, remaining);
      if (kept > 0) (into === "out" ? stdout : stderr).push(Buffer.from(chunk.subarray(0, kept)));
      retainedBytes += kept;
      if (chunk.byteLength > remaining) {
        outputLimitExceeded = true;
        spawnError = "maxBuffer exceeded (ENOBUFS)";
        bound?.cancel();
        child.kill();
        killAfterGrace(child);
      }
    };
    child.stdout?.on("data", (c: Buffer) => collect(c, "out"));
    child.stderr?.on("data", (c: Buffer) => collect(c, "err"));
    bound = boundChildByLoopTime(child, timeoutMs, { onExpire: () => void (timedOut = true), escalateAfterMs: GIT_FETCH_KILL_GRACE_MS });
    child.on("error", (e) => {
      spawnError ??= e.message;
      finish(null);
    });
    child.on("close", (code) => finish(code));
  });

/** The gate's own refusal lines (its `diff-coverage:` headline and `  - file:line` rows), bounded. */
function coverageRefusalText(output: string): string {
  const at = output.search(/^diff-coverage: (?:BLOCKED|INVALID)/m);
  const lines = output.slice(at < 0 ? 0 : at).split("\n").filter((l) => /^diff-coverage:|^\s+- |^\s+! /.test(l));
  return lines.join("\n").slice(0, COVERAGE_TEXT_CAP);
}

/**
 * W1-T4797: run CI's own diff-coverage (scripts/diff-coverage-local.mjs, the same invocation, W1-T4084) over
 * only the suites the affected-suite selector maps to the changed src files — fast tier first, widening to the
 * slow-tier siblings only when a changed file has no `SF:` record. Each pass is bounded by the tier manifest's
 * OWN measured durations for exactly the suites it runs (never a fixed number of seconds); a run over that
 * bound is `unavailable`, not `uncovered`.
 */
export async function coveragePrecheck(wt: string, ports: CoveragePrecheckPorts = {}): Promise<CoveragePrecheck> {
  if (ports.repo !== undefined && !fixCensusAppliesToRepo(ports.repo, () => {})) {
    return { outcome: "not-applicable", repo: ports.repo, reason: `core's diff-coverage selector does not apply to ${ports.repo}` };
  }
  const reasonOf = (e: unknown) => String((e as Error)?.message ?? e).slice(0, 300);
  let changed: string[];
  try {
    changed = await (ports.changedFiles ?? realCoverageChangedFiles)(wt);
  } catch (e) {
    return { outcome: "unavailable", reason: `changed files unreadable: ${reasonOf(e)}` };
  }
  if (!changed.some((f) => COVERAGE_SRC_FILE.test(f))) {
    return { outcome: "covered", reason: "no changed src file for diff-coverage to prove", suites: 0 };
  }
  // W1-T9483: the diff's own test files and the direct importers of its changed src files run FIRST (lib/coverage-narrow.ts).
  // An unreadable listing is no narrow pass, never a verdict: the reach passes then decide exactly as they always did.
  let narrow: string[] = [];
  let narrowUnreadable = "";
  try {
    narrow = await (ports.narrow ?? coverageNarrowSuites)(wt, changed);
  } catch (e) {
    narrowUnreadable = ` (the narrow suite listing was unreadable: ${reasonOf(e)})`;
  }
  let selection: AffectedSelection;
  let manifest: { thresholdMs: number; files: Record<string, number> };
  try {
    // W1-T7744: the default selection awaits its git and diff-class listing children (14.9 s held, 2026-10-10).
    selection = await (ports.select ?? ((w, c) => affectedSelectionOrFullAsync(c, () => readAffectedSuitesInputAsync(w, c))))(wt, changed);
    manifest = (ports.manifest ?? ((w) => loadManifest(join(w, DEFAULT_MANIFEST_RELATIVE_PATH))))(wt);
  } catch (e) {
    return { outcome: "unavailable", reason: `could not derive the affected-suite scope: ${reasonOf(e)}` };
  }
  const run = ports.run ?? ((w: string, suites: string[], timeoutMs: number) => realCoverageRun(w, suites, timeoutMs, ports.maxOutputBytes ?? COVERAGE_RUN_MAX_BUFFER));
  const tiers = tierFiles(selection.suites, manifest) as { fast: string[]; slow: string[] };
  const passes = [tiers.fast.length > 0 ? tiers.fast : tiers.slow];
  if (tiers.fast.length > 0 && tiers.slow.length > 0) passes.push([...tiers.fast, ...tiers.slow]);
  return judgeCoverage({
    narrow, narrowUnreadable, selection, passes, ceiling: PREFLIGHT_SCOPED_COVERAGE_SUITE_CEILING,
    bounded: async (suites) => {
      const predictedMs = suites.reduce((sum, f) => sum + (weightedDurationMs(f, manifest) as number), 0);
      const boundMs = Math.max(manifest.thresholdMs, Math.ceil(predictedMs * (DURATION_STALENESS_FACTOR as number)));
      return { predictedMs, boundMs, r: await run(wt, suites, boundMs) };
    },
    head: () => (ports.head ?? ((w) => hostWorktreeGitAsync(w, ["rev-parse", "HEAD"]).then((t) => t.trim())))(wt),
    isUncovered: (output) => COVERAGE_UNCOVERED_HEADLINE.test(output),
    refusalText: coverageRefusalText,
    isMissingSf: (output) => COVERAGE_MISSING_SF.test(output),
  });
}

/** W1-T4797: ledger the precheck's outcome and reason, then hand back a refusal only for `uncovered`. */
export function coveragePushRefusal(
  result: CoveragePrecheck,
  log: (step: string, extra?: Record<string, unknown>) => void,
  site: string,
): CensusPushRefusal | undefined {
  log("push.coverage_precheck", {
    site,
    outcome: result.outcome,
    reason: result.outcome === "uncovered" ? "diff-coverage would refuse this head" : result.reason,
    ...(result.outcome === "covered" || result.outcome === "uncovered" || result.outcome === "uncovered-narrow" ? { suites: result.suites } : {}),
    ...(result.outcome === "not-applicable" ? { repo: result.repo } : {}),
    ...(result.outcome === "uncovered" ? { refusal: result.text } : {}),
    // W1-T9483: advisory only — the lines to cover and the head they were judged on, never a refusal.
    ...coverageNarrowRowFields(result),
  });
  if (result.outcome !== "uncovered") return undefined;
  return { text: `${COVERAGE_PUSH_CHECK}: CI's coverage-ratchet would refuse this head —\n${result.text}`, censuses: ["diff-coverage"], offeredBaselines: [] };
}

/** W1-T4797: the fix rung's push with the precheck in front — an uncovered head never leaves the worktree. */
export async function pushFixRoundPrechecked(
  log: (step: string, extra?: Record<string, unknown>) => void,
  wt: string,
  branch: string,
  expectedHeadSha?: string,
  ports: CoveragePrecheckPorts = {},
  push: (wt: string, branch: string, expectedHeadSha?: string, priorHeadSha?: string) => unknown = pushFixRound,
  priorHeadSha?: string,
  reapply: { ports?: FixRoundReapplyPorts; attempted?: boolean } = {},
): Promise<unknown> {
  // W1-T5227: a head carrying a conflict marker never leaves the worktree, whoever committed it.
  let markerFiles: string[] = [];
  try {
    markerFiles = (ports.conflictMarkers ?? ((dir) => leftoverConflictMarkerPaths(
      worktreeGitRunner(dir), [], { against: "origin/main", head: "HEAD" })))(wt);
  } catch (error) {
    // Unreadable (no origin/main, not a repo): the coverage precheck below fails open the same way.
    log("push.conflict_marker_check_unavailable", { site: "rung.fix_push", error: String((error as Error)?.message ?? error) });
  }
  if (markerFiles.length > 0) {
    const text = `conflict-marker-check: this head carries leftover conflict markers in ${markerFiles.join(", ")}; resolve them before pushing`;
    log("push.conflict_marker_refused", { site: "rung.fix_push", files: markerFiles });
    throw new FixRoundPushError("run-error", { text, censuses: ["conflict-marker"], offeredBaselines: [] }, text);
  }
  const refusal = coveragePushRefusal(await coveragePrecheck(wt, ports), log, "rung.fix_push");
  if (refusal) throw new FixRoundPushError("run-error", refusal, refusal.text);
  try {
    return await push(wt, branch, expectedHeadSha, priorHeadSha);
  } catch (error) {
    // A census refusal is the round's own red; only a leased push the remote outran may be re-applied, once.
    if (!(error instanceof FixRoundPushError) || error.refusal !== undefined || reapply.attempted ||
      priorHeadSha === undefined || expectedHeadSha === undefined) throw error;
    const result = await reapplyFixRoundOnMovedTip({ wt, branch, leaseBaseSha: priorHeadSha, committedSha: expectedHeadSha },
      reapply.ports ?? realFixRoundReapplyPorts, log);
    if (!result.reapplied) throw error;
    return await pushFixRoundPrechecked(log, wt, branch, result.mergedHeadSha, ports, push, result.remoteTip, { ...reapply, attempted: true });
  }
}


/**
 * W1-T4656: the fix rung's own strike — ci-log prompt, fix mount, wall-clock bound, harness commit, strike
 * cap — run on a refused push BEFORE any PR exists, which `runFixRung` itself cannot serve (it re-judges
 * through the PR's CI and review). Each strike retries the push THROUGH the hook; a baseline the refusal
 * does not offer is never pushed, and the remedy taken is ledgered.
 */
export async function repairCensusRefusedPush(input: {
  refusal: CensusPushRefusal;
  task: Task;
  runId: string;
  worktreePath: string;
  branch: string;
  resumeSessionId: string;
  resumeSessionProvider?: WorkerResult["provider"];
  mount: Mount;
  stepUpMount?: Mount;
  settingsFile: string;
  config: Config;
  budgetUsd: number;
  ledgerPath: string;
  spawnWallClockBoundMs?: number;
  spawn: (args: SpawnWorkerArgs) => Promise<WorkerResult>;
  account: (r: WorkerResult) => WorkerResult;
  log: (step: string, extra?: Record<string, unknown>) => void;
  say: (msg: string) => void;
  /** W1-T4797: re-run a NON-hook gate (the diff-coverage precheck) after each strike's commit, before the push;
   *  a refusal it returns becomes the next strike's evidence exactly as a hook refusal does. */
  recheck?: () => Promise<CensusPushRefusal | undefined>;
  /** Only the implement fallback offers closure catalog edits; the fix lane never does. */
  catalogFiles?: (refusal: CensusPushRefusal) => readonly string[];
}): Promise<CensusPushRungOutcome> {
  return runTaskCommandHelpers(runTaskCommandHost()).repairCensusRefusedPush(input);
}

export async function runTaskBody(ctx: RunTaskContext): Promise<RunResult> {
  return runTaskBodyFromModule(ctx, runTaskCommandHost());
}

/**
 * `rmd review <pr-number>` — the ESCAPE HATCH for hand-opened PRs. PR #13 made
 * `remudero-review` a REQUIRED check, but only `rmd run-task` posts it; a manual
 * plan/doc PR therefore sits BLOCKED forever with no status. This command posts the
 * status by hand — using the SAME deterministic {@link judgeReview}, NEVER a bypass
 * and NEVER a --force. It is the same judge, invoked by a human.
 *
 * Criteria resolution: a `Remudero-Task: <id>` trailer in the PR body → that task's
 * acceptance from plan/tasks.yaml; otherwise the PR body's `Acceptance:` block
 * (manual plan/doc PRs). ABSENT criteria are `[]` ⇒ judgeReview FAILS CLOSED —
 * nothing to judge is never a pass. The PR body doubles as the REPORT (where a
 * manual author pastes the proofs the judge checks).
 */
// resolveReviewTarget moved to src/lib/report-commands.ts (W1-T2888) — imported/re-exported
// below.

// ── W1-T185 (Gap 2): materialize a PR-head worktree for `rmd review` ────────
//
// GROUND TRUTH this closes: every review hand-posted on 2026-07-20 read
// `proof_exec: 0/N` — #391 0/3, #394 0/4, #397 0/4, #407 0/6, #411 0/5,
// #418 0/5 — while the automated fix rung, which HAS a worktree at the head,
// recorded `executed_fail` on the SAME proofs of #411. The operator path was
// keyword-only BY CONSTRUCTION, not by defect: it never checked anything out.
//
// Preferred fix, per the task's own design note: materialize a throwaway
// worktree at the PR's exact head commit and execute there. GitHub's read-only
// `refs/pull/<number>/head` ref makes that object available; the REST-supplied
// SHA remains checkout authority even when the mutable source branch moves.
// Teardown is the CALLER's job (a `finally` in `reviewCommand`, below) so it
// covers every exit path.
//
// W1-T232: the original shape here ALSO ran `git checkout -B <branch>
// origin/<branch>` after the `worktree add`, purely to give the throwaway
// worktree a branch NAME — nothing downstream ever reads it; proof execution
// only reads files at the checked-out tip, which `worktree add` alone already
// provides (as a DETACHED HEAD — confirmed by hand: `git worktree add <path>
// origin/<branch>` prints "Preparing worktree (detached HEAD ...)" with no
// second command). `checkout -B` FORCE-CREATES/RESETS a local branch of that
// name, which THROWS the moment any other worktree already holds it — e.g.
// the operator's own filing worktrees, or simply another `rmd review` in
// flight on the same branch. That collision was reproduced verbatim on
// 2026-07-21 and cost five PRs a keyword-only CAPPED verdict for a reason
// that had nothing to do with whether the review could actually run.
// Dropping the branch pin removes an implicit freshness check, so this now
// asserts the materialized tip equals the PR head SHA and fails LOUDLY
// (throws, no verdict posted) on a mismatch — reviewing the wrong tree
// silently would be worse than not reviewing at all.
// ────────────────────────────────────────────────────────────────────────────

/** Named CLASS of a materialization failure (W1-T233) — carried alongside the
 * raw message so a pattern is visible across runs (grep the class) without
 * parsing git's prose: `worktree-collision` (another worktree already holds
 * this ref — the defect W1-T232 removed from the common path; still reachable
 * via a race), `fetch-failure` (network/auth, thrown by `deps.fetch`), or
 * `other` (disk, permissions, or any other `deps.addWorktree`/`revParseHead`
 * failure). */

/** The named reason a materialization attempt failed — never a bare, thrown-
 * away Error. Carried to every surface that reports the degradation: the
 * console line, the CAPPED verdict description, and the `review.posted`
 * ledger's `degraded_reason`/`degraded_reason_class` fields. */



/** The posted CAPPED description, carrying the named materialization-failure
 * reason (W1-T233) — a capped verdict caused by a failed materialization
 * names WHY on the commit status itself, not only in the ledger. A non-capped
 * verdict, or a capped one with no materialization failure at all (rmd
 * review's checkout was simply never attempted), is returned unchanged. */
export function reviewPostedDescription(
  verdict: Pick<ReviewVerdict, "summary" | "capped"> & Partial<Pick<ReviewVerdict, "criteria">>,
  materializationFailure?: MaterializationFailure,
): string {
  // W1-DH: a capped verdict names WHY it was capped even when materialization was fine — the
  // code-span defect capped 0/N with a perfectly healthy checkout, and the description said nothing.
  const skipReason = verdict.capped && verdict.criteria ? cappedReason(verdict.criteria) : undefined;
  if (verdict.capped && !materializationFailure && skipReason) {
    return `${verdict.summary} — capped: ${skipReason}`;
  }
  return verdict.capped && materializationFailure
    ? `${verdict.summary} — degraded: ${materializationFailure.errorClass}: ${materializationFailure.message}`
    : verdict.summary;
}

export function reviewVerdictAnnotation(
  verdict: Pick<ReviewVerdict, "keywordOnly"> & Partial<Pick<ReviewRunResult, "decisionDisposition">>,
): string {
  return reviewVerdictAnnotationFromModule(verdict);
}

export function degradedReasonLedgerFields(materializationFailure?: MaterializationFailure): {
  degraded_reason?: string;
  degraded_reason_class?: MaterializationErrorClass;
} {
  return degradedReasonLedgerFieldsFromModule(materializationFailure);
}

export function reviewLedgerReasonFields(args: {
  decisionDisposition?: ReviewRunResult["decisionDisposition"];
  materializationFailure?: MaterializationFailure;
}): {
  review_reason?: "decision_in_flight" | "materialization_failure";
  review_reason_detail?: string;
  decision_disposition?: "in_flight";
  degraded_reason?: string;
  degraded_reason_class?: MaterializationErrorClass;
} {
  return reviewLedgerReasonFieldsFromModule(args);
}

/**
 * Materialize a throwaway worktree at a PR's exact head SHA so `rmd review` can
 * execute whitelisted proofs exactly like the automated fix rung does.
 * Returns `{ worktreePath }` on success; on an ORDINARY materialization
 * failure (network, disk, a detached/deleted head) returns `{ worktreePath:
 * undefined, failure }` naming the error CLASS + message (W1-T233) — the
 * caller then falls back to a keyword-only, CAPPED verdict (acceptance
 * criterion 5), never a thrown command reaching the operator, and never a
 * bare discarded reason.
 *
 * A materialized tip that does NOT match `headSha`, though, is not an
 * ordinary failure — it means the fetch was stale or the ref moved out from
 * under us, and reviewing that tree would silently produce a verdict against
 * the WRONG code. That case throws (uncaught by this function) rather than
 * degrading to keyword-only, so `reviewCommand` fails loudly and posts no
 * verdict at all (W1-T232, criterion "tip mismatch after fetch fails
 * materialization loudly").
 *
 * W1-T233: THIS function owns teardown of whatever IT creates. A worktree
 * `deps.addWorktree` already registered on disk is removed, best-effort,
 * before any failure return AND before the tip-mismatch throw — a failed (or
 * discarded) attempt leaves the workspace exactly as it found it, rather than
 * stranding a `review-PR*` worktree (39 were found stranded on 2026-07-21,
 * one per failed attempt, because this used to return/throw with the
 * worktree still on disk and `withMaterializedWorktree`'s teardown keyed on a
 * truthy path it was never given). Teardown of a SUCCESSFULLY returned path
 * remains the CALLER's responsibility (`reviewCommand`'s `withMaterializedWorktree`),
 * so a throw from `runReview` itself still tears that one down (criterion 6).
 */
export function materializeReviewWorktree(
  config: Config,
  repoDir: string,
  prNumber: number,
  headSha: string,
  deps: ReviewWorktreeDeps = realDeps().reviewWorktree,
): MaterializeReviewWorktreeResult {
  const worktreePath = join(worktreesDir(config), `review-PR${prNumber}-${Date.now()}`);
  const removeWorktree = deps.removeWorktree ?? worktreeRemove;

  try {
    deps.fetch(repoDir, prNumber, headSha);
  } catch (e) {
    // Nothing was created yet — no cleanup needed, only a named reason.
    return {
      worktreePath: undefined,
      failure: { errorClass: "fetch-failure", message: String((e as Error)?.message ?? e) },
    };
  }

  let created = false;
  let tip: string;
  try {
    deps.addWorktree(repoDir, worktreePath, headSha);
    created = true; // the worktree is now on disk — any exit from here must clean it up.
    tip = deps.revParseHead(worktreePath);
  } catch (e) {
    if (created) cleanupMaterializedWorktree(removeWorktree, repoDir, worktreePath);
    const message = String((e as Error)?.message ?? e);
    const errorClass: MaterializationErrorClass = /already used by worktree/.test(message)
      ? "worktree-collision"
      : "other";
    return { worktreePath: undefined, failure: { errorClass, message } };
  }

  if (tip !== headSha) {
    cleanupMaterializedWorktree(removeWorktree, repoDir, worktreePath);
    throw new Error(
      `materialized worktree at ${worktreePath} is at ${tip}, not the PR head ${headSha} — ` +
        "a stale fetch or a moved ref; refusing to review a possibly-wrong tree rather than posting a false verdict",
    );
  }
  registerReviewerCheckout(worktreePath);
  // Held until withMaterializedWorktree's teardown: a review slower than the sweep's grace window is still live.
  holdReviewWorktree(worktreePath);
  return { worktreePath };
}

export function materializePlanRoundWorktree(config: Config, repoDir: string, prNumber: number, headSha: string,
  deps: Pick<ReviewCommandDeps, "materialize"> & { prepare?: FreshTreeReviewSeams["prepareWorktree"] } = {},
): MaterializeReviewWorktreeResult {
  const result = (deps.materialize ?? materializeReviewWorktree)(config, repoDir, prNumber, headSha);
  if (result.worktreePath && !(deps.prepare ?? prepareWorktreeToolchain)(repoDir, result.worktreePath)) {
    cleanupMaterializedWorktree(worktreeRemove, repoDir, result.worktreePath);
    return { worktreePath: undefined, failure: { errorClass: "other", message: "plan round toolchain unavailable" } };
  }
  return result;
}

/** Best-effort removal of a worktree a materialization attempt itself just
 * created, on that SAME attempt's failure — swallows a removal error rather
 * than masking the materialization failure/mismatch that triggered it (the
 * console still hears about a removal failure, mirroring {@link
 * withMaterializedWorktree}'s own teardown-failure handling). */
function cleanupMaterializedWorktree(
  remove: (repoDir: string, worktreePath: string) => void,
  repoDir: string,
  worktreePath: string,
): void {
  try {
    remove(repoDir, worktreePath);
  } catch (e) {
    console.error(
      `(worktree teardown failed for ${worktreePath} after a materialization failure: ` +
        `${String((e as Error)?.message ?? e)})`,
    );
  }
}

/**
 * `rmd review`'s OWN `Remudero-Task: <id>` trailer extraction (W1-T70). The worker prompt
 * DICTATES the contract ("Include this exact trailer as the LAST line of the PR body") but
 * the pre-W1-T70 read here was an UNANCHORED `body.match(/Remudero-Task:\s*(\S+)/)` — any
 * body that QUOTES the trailer format mid-prose (increasingly common on plan/ratify PRs,
 * which routinely discuss the trailer contract itself — observed live on #119 and one
 * earlier) was captured ahead of the genuine final line. 4th instance of the first-match
 * parser class: the DECISION_REQUEST near-miss, `parseReport`'s first-URL bug (W1-T62 —
 * `anchoredPrUrl` in lib/worker.ts is the SAME matchAll-and-take-last idiom this mirrors),
 * and `deriveStatus` rung (c) (W1-T69). LINE-ANCHORED (`^...$`, per line) so a mid-prose
 * mention never matches; LAST-LINE-WINS (scanning ALL anchored matches, keeping the final
 * one) because that is the contract's own phrasing. No anchored trailer at all ⇒ `undefined`,
 * unchanged from before — the caller falls through to the PR body's `Acceptance:` block.
 */
/**
 * TRUE when the body's ONLY judgeable Acceptance block is the generic PR-open-time fallback
 * ({@link PR_OPEN_TIME_ACCEPTANCE_FALLBACK} / {@link ACCEPTANCE_GATE_BODY_REPAIR_FALLBACK} — both
 * carry the SAME claim/proof pair, so one string comparison covers either origin).
 *
 * WHY THIS EXISTS: `ghPrCreateFillCommand` (the retro's own PR-creation call site) already installs
 * that fallback whenever the commit-derived body carried no Acceptance block — BEFORE
 * `repairRetroAcceptanceBlock` runs. Its proof, `grep: ^export function acceptanceAuthorTimeCheck in
 * src/lib/review.ts`, greps a function that predates every PR that could ever reach this fallback,
 * so `check-proof --base` reads it `executed_stale` on every retro that takes this path — measured
 * live on #5769, which failed the REQUIRED `proof-discrimination` check for exactly this proof.
 * `bodyNeedsAcceptanceRepair` alone does not see this: the fallback parses fine and its proof is
 * non-empty, so it calls the body "healthy" — the retro's diff-anchored repair below never gets
 * a chance to replace it. This predicate closes that gap by recognising the ONE known-stale generic
 * shape and routing it back into repair, without touching `bodyNeedsAcceptanceRepair` itself (which
 * other callers, e.g. `acceptanceGateBodyRepair`, still need to read this same body as healthy).
 */
export function bodyCarriesGenericAcceptanceFallback(body: string): boolean {
  const criteria = parseAcceptanceBlock(body);
  if (criteria.length !== 1) return false;
  return criteria[0].proof?.trim() === PR_OPEN_TIME_ACCEPTANCE_FALLBACK[0].proof;
}

/**
 * THE RETRO'S ACCEPTANCE-BLOCK REPAIR RUNG, extracted so the DECISION is reachable by a test.
 *
 * It was inline in `retroCommand`, which meant the trigger — the thing this change fixes — could
 * only be pinned by source text and earned zero coverage. diff-coverage flagged it as a wiring line
 * with `DA:0`, which is this repo's "seam built but never called" hazard pointed at the exact
 * predicate being widened. Extracting it is the honest answer to that, not a wider lcov.
 *
 * Deps are injected LAST and default to the real bindings by object-spread (never `??`, which V8
 * instruments as a branch and would leave the untaken real side permanently uncovered).
 *
 * Best-effort by contract: `retroCommand` must never fail because a repair attempt failed, so every
 * throw is caught and ledgered as `acceptance.repair.error` rather than propagating.
 */
export function repairRetroAcceptanceBlock(
  prUrl: Parameters<RunTaskCommandHost["repairRetroAcceptanceBlock"]>[0],
  log: Parameters<RunTaskCommandHost["repairRetroAcceptanceBlock"]>[1],
  deps: Parameters<RunTaskCommandHost["repairRetroAcceptanceBlock"]>[2] = {},
): ReturnType<RunTaskCommandHost["repairRetroAcceptanceBlock"]> {
  const { fetchBody, editBody, diffText } = {
    fetchBody: defaultRetroFetchBody,
    editBody: defaultRetroEditBody,
    diffText: defaultRetroDiffText,
    ...deps,
  };
  try {
    const body = fetchBody(prUrl);
    // The SAME predicate ensureJudgeableBody itself uses (bodyNeedsAcceptanceRepair,
    // plan-pr-emitter.ts) — this call site used to carry its own `=== 0` copy, which meant widening
    // the repair would have left the duplicate here still declining to fire on a body that parses
    // to one criterion with an empty proof. One definition, two consumers. ALSO repair a body whose
    // only criterion is the generic PR-open-time fallback: that proof is stale by construction
    // (see bodyCarriesGenericAcceptanceFallback), so `proof-discrimination` REFUSES the retro
    // otherwise, even though `bodyNeedsAcceptanceRepair` alone calls it healthy.
    if (!bodyNeedsAcceptanceRepair(body) && !bodyCarriesGenericAcceptanceFallback(body)) return "healthy";
    // W1-T4263: the proof greps a line this PR adds, and a missing anchor is ledgered. Only an UNREADABLE diff falls
    // back to the static grep. A diff that was read but has no safe line stays W1-T3819's honest refusal, and so
    // does a body that already carries the static grep, since rewriting it would change nothing.
    let diff: string | undefined = deps.diff;
    if (!Object.hasOwn(deps, "diff")) {
      try {
        diff = diffText(prUrl);
      } catch (e) {
        void e; // an unreadable diff is the `no-diff` reason ledgered below
      }
    }
    const staticFallback: AcceptanceCriterion[] = [
      { claim: "the retro's plan-only sync PR is gate-compliant", proof: PR_OPEN_TIME_ACCEPTANCE_FALLBACK[0].proof },
    ];
    const fallback = diffAnchoredFallback(diff, staticFallback, "retro-repair", log, { pr_url: prUrl });
    const unreadable = (diff ?? "").trim() === "";
    if (fallback === staticFallback && (!unreadable || !bodyNeedsAcceptanceRepair(body))) {
      log("acceptance.repair.unrepresentable", { pr_url: prUrl, reason: "no safe added diff line" });
      return "unrepresentable";
    }
    // `ensureJudgeableBody` re-checks `bodyNeedsAcceptanceRepair` internally and no-ops when it reads
    // healthy — exactly the generic-fallback case this function exists to catch. Use the unconditional
    // half directly whenever THIS repair fired for a reason that predicate cannot see.
    const repaired = bodyNeedsAcceptanceRepair(body) ? ensureJudgeableBody(body, fallback) : replaceAcceptanceBlock(body, fallback);
    editBody(prUrl, repaired);
    log("acceptance.repaired", { pr_url: prUrl });
    return "repaired";
  } catch (e) {
    log("acceptance.repair.error", { error: String((e as Error)?.message ?? e) });
    return "error";
  }
}

/**
 * W1-T4425 — a run PR's OWN `## Acceptance`/`Acceptance:` block must never diverge from its plan.
 * `trailerBodyProofDivergenceRefusal` (scripts/acceptance-author-gate.mjs, W1-T3658) refuses a
 * trailered PR whose own block names different proofs than the task it credits (#6888, #6929,
 * #6931 each paid a fix-lane round for this). W1-T3739's {@link
 * "./lib/plan-pr-emitter.js".renderAcceptanceBlock} round-trips through {@link
 * "./lib/review.js".parseAcceptanceBlock} by construction, but the worker-opened PR path never
 * called it — this closes that gap, called once from `runTaskBody` right before W1-T1012's
 * trailer-amend push, so the divergence is unreachable rather than refused-then-repaired.
 * `taskId`/`planCriteria` come from the SAME task record this run is building, never re-resolved
 * from the body's own (possibly still-unstamped) trailer.
 *
 * Compares proof TEXT AS A SET (order/claim wording ignored) — the exact comparison the gate
 * itself runs. `"no-block"` (a trailer-only body, or none at all) is the gate's own "nothing to
 * compare" shape and is left alone, as is a block that already names the identical proof set
 * (`"healthy"`). {@link "./lib/review.js".acceptanceBlockRegion} gives the block's own
 * `[headerLine, endLine)` span, spliced out for `renderAcceptanceBlock(planCriteria)` so the rest
 * of the worker's prose survives; any trailer is stripped and re-appended LAST (the worker
 * prompt's contract), so it can never end up stranded above the fresh block.
 *
 * Best-effort like {@link repairRetroAcceptanceBlock}: every throw is caught and ledgered, never
 * propagated. `pr.body_normalized` carries `removed_proofs` (named only in the old block) and
 * `rendered_proofs` (the plan's own proof set now rendered).
 */
export function normalizeRunPrAcceptanceFromPlan(
  prUrl: string,
  taskId: string,
  planCriteria: readonly AcceptanceCriterion[],
  log: (step: string, extra?: Record<string, unknown>) => void,
  // The SAME two leaves (and the same defaults) repairRetroAcceptanceBlock injects — reused from its
  // own signature rather than a second inline copy; its retro-only `diff` input is omitted here.
  deps: Omit<NonNullable<Parameters<typeof repairRetroAcceptanceBlock>[2]>, "diff"> = {},
): "rewritten" | "healthy" | "no-block" | "raced" | "error" {
  return runTaskCommandHelpers(runTaskCommandHost()).normalizeRunPrAcceptanceFromPlan(prUrl, taskId, planCriteria, log, deps);
}

/** Show the exact closure catalog files the harness staged, above the task trailer. */
export function recordBakedClosureCatalog(
  prUrl: string,
  files: readonly string[],
  log: (step: string, extra?: Record<string, unknown>) => void,
  deps: Pick<NonNullable<Parameters<typeof repairRetroAcceptanceBlock>[2]>, "fetchBody" | "editBody"> = {},
): void {
  return runTaskCommandHelpers(runTaskCommandHost()).recordBakedClosureCatalog(prUrl, files, log, deps);
}

function defaultRetroFetchBody(url: string): string {
  const view = ghJson(["pr", "view", url, "--json", "body"]) as { body?: string };
  return view.body ?? "";
}

/** W1-T2948: the retro's repair goes through the SAME REST writer as the acceptance repair and the
 *  trailer stamp — one transport, one place to fix. */
function defaultRetroEditBody(url: string, body: string): void {
  writePrBodyRest(url, body);
}

/** W1-T4263: {@link repairRetroAcceptanceBlock}'s diff read, the full-text sibling of {@link defaultRetroChangedFiles}. */
function defaultRetroDiffText(url: string): string {
  return ghExec(["pr", "diff", url], { encoding: "utf8", maxBuffer: 1 << 26 });
}

/**
 * W1-T908 — the changed-path read for {@link repairRetroChangesetClaim}. Appended LAST in that
 * function's deps object so no existing positional caller shifts (#977/#978), and exercised by a
 * test that really shells out, so the default is not left as an uncovered seam.
 */
function defaultRetroChangedFiles(url: string): string[] {
  const out = ghExec(["pr", "diff", url, "--name-only"], { encoding: "utf8", maxBuffer: 1 << 26 });
  return out.split("\n").map((l) => l.trim()).filter((l) => l.length > 0);
}

/**
 * W1-T911 — THE RETRO'S CHANGESET-CLAIM REPAIR RUNG, the sibling of
 * {@link repairRetroAcceptanceBlock} and called from the same place for the same reason.
 *
 * WHY A POST-HOC RUNG RATHER THAN A BETTER TEMPLATE. `retroCommand` spawns the Architect, which
 * edits MASTER-PLAN.md, commits, pushes and OPENS THE PR WITH A BODY IT AUTHORED. Only then does
 * `regenerateOrientation` and citation stamping run after the Architect opens the PR. The body is
 * therefore written before the harness-owned follow-up changes are known, and no wording can fix
 * that. Reordering cannot fix it either: ORIENTATION.md is regenerated FROM what the Architect
 * just wrote, so it cannot run first. The only point where the changeset is knowable is after
 * those follow-up commits — which is exactly where this runs.
 *
 * The actual string fold is {@link "./lib/plan-pr-emitter.js".reconcileRetroChangesetClaim} — a
 * PURE reconciler living beside every other plan-PR body primitive, repairing BOTH arms
 * `bodyContradictsDiff` reads (originally W1-T908's count-only rung; W1-T911 added the "no
 * <path>" denial arm and moved the fold here). This rung stays the I/O seam: it reads the PR
 * body and the real changeset, hands both to the pure fold, and writes back only if it changed
 * anything.
 *
 * Deps injected LAST and defaulted by object-spread (never `??`, which V8 instruments as a branch
 * and would leave the untaken real side permanently uncovered) — the same discipline
 * `repairRetroAcceptanceBlock` uses.
 *
 * Best-effort by contract, like its sibling: `retroCommand` must never fail because a repair
 * attempt failed, so every throw is caught and ledgered rather than propagating.
 */
export function repairRetroChangesetClaim(
  prUrl: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  deps: {
    fetchBody?: (url: string) => string;
    editBody?: (url: string, body: string) => void;
    changedFiles?: (url: string) => string[];
  } = {},
): "repaired" | "healthy" | "error" {
  const { fetchBody, editBody, changedFiles } = {
    fetchBody: defaultRetroFetchBody,
    editBody: defaultRetroEditBody,
    changedFiles: defaultRetroChangedFiles,
    ...deps,
  };
  try {
    const paths = changedFiles(prUrl);
    const body = fetchBody(prUrl);
    const repaired = reconcileRetroChangesetClaim(body, paths);
    if (repaired === undefined) return "healthy";
    editBody(prUrl, repaired);
    // A step of its own rather than reusing `acceptance.repaired`: that line means a different
    // repair happened, and a line whose reason belongs to another decision is worse than a terse
    // one (CLAUDE.md, #981). `changed_files` is carried so a later reading can adjudicate the row
    // instead of being blind to what was named.
    log("changeset_claim.repaired", { pr_url: prUrl, changed_files: paths });
    return "repaired";
  } catch (e) {
    log("changeset_claim.repair.error", { error: String((e as Error)?.message ?? e) });
    return "error";
  }
}

