/** W1-T9103: the fleet lane's production `sameFinding` port — one question to the `inbox-draft` lane's mount, whose
 *  answer is "same", "distinct" or, when no answer can be read, "unavailable" (the failure is logged, never read as "distinct"). */
export function fleetLaneSamenessJudge(
  config: Config,
  log: (step: string, extra?: Record<string, unknown>) => void,
  rawSpawn: typeof spawnWorker = spawnWorker,
): ((earlier: string, later: string) => Promise<"same" | "distinct" | "unavailable">) | undefined {
  try {
    const settingsFile = renderWorkerSettings({
      templatePath: join(resolveInstallRoot(config), "settings", "worker.json"),
      hooksDir: join(resolveInstallRoot(config), "hooks"),
      outPath: join(config.root, "tmp", "fleet-lane-sameness-settings.json"),
    });
    const mount = loadMounts(mountsPath(repoRoot)).synthesis.inbox_draft;
    return async (earlier, later) => {
      const prompt = [
        "Two follow-up findings were written by different rounds of one run. Say whether the LATER one restates the EARLIER one",
        "(the same request, possibly in other words, possibly with more detail) or asks something distinct.",
        'Answer with one JSON object only: {"answer": "same"} or {"answer": "distinct"}.',
        "", `EARLIER: ${earlier}`, "", `LATER: ${later}`,
      ].join("\n");
      try {
        const result = await benchmarkNonDispatchSpawn("inbox-draft", rawSpawn)({
          ...buildInboxDraftSpawnArgs({ cwd: config.root, settingsFile, mount, config, prompt, disallowedTools: INBOX_DRAFT_DISALLOWED_TOOLS }),
          onSelectionAssignment: undefined,
        });
        const answer = /\{[^{}]*\}/.exec(result.text)?.[0];
        const parsed = answer === undefined ? undefined : (JSON.parse(answer) as { answer?: unknown }).answer;
        return parsed === "same" || parsed === "distinct" ? parsed : "unavailable";
      } catch (e) {
        log("fleet_lane.sameness_judge_failed", { error: String((e as Error)?.message ?? e) });
        return "unavailable";
      }
    };
  } catch (e) {
    log("fleet_lane.sameness_judge_unavailable", { error: String((e as Error)?.message ?? e) });
    return undefined;
  }
}

/** W1-T4409/W1-T4421 — ledger every quarantined task and escalate each duplicated id once (escalate dedups). */
export function reportQuarantined(
  quarantined: QuarantinedTask[],
  log: (step: string, extra?: Record<string, unknown>) => void,
  raise: (escalation: Escalation) => string,
  requestRepair?: (q: QuarantinedTask) => void,
): void {
  for (const q of quarantined) {
    if (q.reason === "shard_invalid") {
      reportInvalidShard(q, log, raise, requestRepair);
      continue;
    }
    log("plan.duplicate_quarantined", { id: q.id, files: q.files, reason: q.reason });
    if (q.reason !== "duplicate_id") continue;
    const escalation: Escalation = {
      class: "BLOCKED",
      taskId: q.id,
      summary: `task id ${q.id} is declared more than once (${q.files.length} file(s)) — the daemon quarantined it and keeps running`,
      detail:
        `The daemon held ${q.id} (and every task depending on it) out of its plan instead of exiting at boot. ` +
        `Declared in:\n${q.files.map((f) => `- ${f}`).join("\n")}\n\nNothing can dispatch or credit ${q.id} until one declaration remains.`,
      options: [{ label: "remove-duplicate", detail: "delete or renumber every declaration but one, in a plan-only PR" }],
      recommendation: "remove-duplicate",
      headDedup: "independent",
    };
    try {
      log("plan.duplicate_escalated", { id: q.id, issue_url: raise(escalation) });
    } catch (e) {
      log("plan.duplicate_escalation_failed", { id: q.id, reason: e instanceof Error ? e.message : String(e) });
    }
  }
}

/** A tasks.d shard that does not parse or validate: one ledger row naming the file and the error, one escalation. */
function reportInvalidShard(
  q: QuarantinedTask,
  log: (step: string, extra?: Record<string, unknown>) => void,
  raise: (escalation: Escalation) => string,
  requestRepair?: (q: QuarantinedTask) => void,
): void {
  const file = q.files[0] ?? q.id;
  log("plan.shard_quarantined", { id: q.id, file, error: q.error });
  const escalation: Escalation = {
    class: "BLOCKED",
    taskId: q.id,
    summary: `plan shard ${file} does not load — the daemon quarantined it and keeps running`,
    detail:
      `The daemon held ${q.id} (and every task depending on it) out of its plan instead of refusing the whole plan.\n\n` +
      `File: ${file}\nError: ${q.error ?? "(none recorded)"}\n\nNothing can dispatch ${q.id} until the shard loads again.`,
    options: [{ label: "repair-shard", detail: "fix the shard in a plan-only PR so it parses and validates" }],
    recommendation: "repair-shard",
    headDedup: "independent",
  };
  try {
    log("plan.shard_escalated", { id: q.id, file, issue_url: raise(escalation) });
  } catch (e) {
    log("plan.shard_escalation_failed", { id: q.id, file, reason: e instanceof Error ? e.message : String(e) });
  }
  if (!requestRepair || !isDuplicateKeyError(q.error)) return;
  try {
    requestRepair(q);
  } catch (e) {
    log("plan.shard_repair_failed", { id: q.id, file, stage: "request", reason: e instanceof Error ? e.message : String(e) });
  }
}

/** {@link reportQuarantined} for a daemon that re-reads its plan every tick: each quarantine is reported the first time
 *  this process sees it, so a bad shard is ledgered and escalated once rather than on every load. */
export function quarantineReporter(
  log: (step: string, extra?: Record<string, unknown>) => void,
  raise: (escalation: Escalation) => string,
  requestRepair?: (q: QuarantinedTask) => void,
): (quarantined: QuarantinedTask[]) => void {
  const reported = new Set<string>();
  return (quarantined) => {
    const fresh = quarantined.filter((q) => {
      const key = JSON.stringify([q.reason, q.id, q.files, q.error]);
      if (reported.has(key)) return false;
      reported.add(key);
      return true;
    });
    reportQuarantined(fresh, log, raise, requestRepair);
  };
}

/**
 * W1-T4409 — the daemon's boot-time plan read. A task id declared by two plan files is quarantined
 * (with every task that depends on it) instead of thrown, ledgered, and escalated to a human ONCE per
 * duplicated id (escalate's own open-issue dedup covers later boots). Everything else still throws.
 */
export function loadDaemonPlan(
  planPath: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  raise: (escalation: Escalation) => string,
  load: (path: string) => ReturnType<typeof loadPlanQuarantiningDuplicates> = (path) => loadPlanQuarantiningDuplicates(path),
): Plan {
  const { plan, quarantined } = load(planPath);
  reportQuarantined(quarantined, log, raise);
  return plan;
}

const ORIGIN_MAIN_LABEL = "origin/main:";
/** The required acceptance-author-gate refuses a trailerless body with no block (#9005); this test fails while main holds a duplicate. */
const SHARD_REPAIR_ACCEPTANCE =
  "## Acceptance\n- no plan shard on main carries a duplicate key after this repair | unit test: no plan shard on main carries a duplicate key";
type ShardRepairLog = (step: string, extra?: Record<string, unknown>) => void;

/** W1-T5519 — the duplicate-key repair lane's state: `requests/` the loop writes, `opened.json` the plan garden's child writes. */
export function shardRepairDir(stateDir: string): string {
  return join(stateDir, "plan-shard-repair");
}

/** On the daemon loop: a duplicate-key quarantine becomes one small request file — no git, no gh, no repair yet. */
export function shardRepairRequester(stateDir: string, log: ShardRepairLog): (q: QuarantinedTask) => void {
  return (q) => {
    const file = q.files[0] ?? q.id;
    if (!file.startsWith(ORIGIN_MAIN_LABEL)) {
      log("plan.shard_repair_refused", { id: q.id, file, reason: "the shard was not read from origin/main, so there is no blob to repair" });
      return;
    }
    const name = `${createHash("sha256").update(file).digest("hex").slice(0, 16)}.json`;
    writeAtomic(join(shardRepairDir(stateDir), "requests", name), `${JSON.stringify({ id: q.id, file })}\n`);
    log("plan.shard_repair_requested", { id: q.id, file });
  };
}

function shardRepairRequests(stateDir: string): string[] {
  const dir = join(shardRepairDir(stateDir), "requests");
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((n) => n.endsWith(".json")).sort().map((n) => join(dir, n));
}

/** W1-T5618 — a request file: `attempts`, `blob` and `next_at` appear once an attempt has failed. */
type ShardRepairRequest = { id: string; file: string; attempts?: number; blob?: string; next_at?: string };

/** BACKSTOP: the attempts one shard blob gets before its request is abandoned to the standing escalation. */
const SHARD_REPAIR_ATTEMPT_CAP = 3;

/** Whether a request is due at `now`. A request that cannot be read is due, so the pass that consumes it runs. */
function shardRepairRequestDue(path: string, now: number): boolean {
  try {
    const nextAt = (JSON.parse(readFileSync(path, "utf8")) as ShardRepairRequest).next_at;
    return nextAt === undefined || Date.parse(nextAt) <= now;
  } catch {
    // deliberate: a torn or vanished request is "due" — the pass then ledgers it as a pass failure and consumes it.
    return true;
  }
}

/** Whether a repair request is due — the plan garden's due probe, on the loop. A backing-off request is not, so the garden never spins. */
export function shardRepairsPending(stateDir: string, clock: Clock = systemClock): boolean {
  const now = clock.now();
  return shardRepairRequests(stateDir).some((path) => shardRepairRequestDue(path, now));
}

/** The plan garden with the repair lane in front of it: due while a request waits, and a repair failure never skips the garden. */
export function withShardRepairs(stateDir: string, repairs: () => void | Promise<void>, garden: RegisteredGardenPass, log: ShardRepairLog): RegisteredGardenPass {
  return Object.assign(async () => {
    try {
      await repairs();
    } catch (e) {
      log("plan.shard_repair_failed", { stage: "pass", reason: String((e as Error)?.message ?? e) });
    }
    return garden();
  }, { due: () => shardRepairsPending(stateDir) || (garden.due?.() ?? true) });
}

/** `opened.json`'s value per blob: the PR url, or — once a closed-unmerged PR was replaced — the fresh PR and the one it replaced. */
type ShardRepairOpened = string | { pr_url: string; reopened_from: string };

/** What one attempt decided: `done` consumes the request; `retry` keeps it, charged to `blob` when the bytes were read. */
type ShardRepairOutcome = { done: true } | { retry: true; blob?: string };

async function repairRequestedShard(
  request: ShardRepairRequest,
  opts: { stateDir: string; log: ShardRepairLog; readOriginBlob: (rel: string) => string | Promise<string>; land: (rel: string, text: string, pr: { title: string; body: string }) => string | undefined | Promise<string | undefined>; prState: (prUrl: string) => PrState | Promise<PrState> },
): Promise<ShardRepairOutcome> {
  const at = { id: request.id, file: request.file };
  const failure = (stage: string, e: unknown) => ({ ...at, stage, reason: String((e as Error)?.message ?? e) });
  const rel = request.file.slice(ORIGIN_MAIN_LABEL.length);
  let text: string;
  try {
    text = await opts.readOriginBlob(rel);
  } catch (e) {
    opts.log("plan.shard_repair_failed", failure("read", e));
    return { retry: true };
  }
  const blob = gitBlobSha(text);
  const openedPath = join(shardRepairDir(opts.stateDir), "opened.json");
  let opened: Record<string, ShardRepairOpened>;
  try {
    opened = JSON.parse(readFileIfExists(openedPath) ?? "{}") as Record<string, ShardRepairOpened>;
  } catch (e) {
    // An unreadable record cannot say these bytes were never opened: refuse rather than risk a second PR.
    opts.log("plan.shard_repair_failed", failure("opened-record", e));
    return { retry: true, blob };
  }
  const prior = opened[blob];
  let reopenedFrom: string | undefined;
  if (typeof prior === "object") {
    opts.log("plan.shard_repair_skipped", { ...at, blob, pr_url: prior.pr_url, reason: "a repair PR was already reopened once for these bytes; its close is respected" });
    return { done: true };
  }
  if (prior !== undefined) {
    const prState = await opts.prState(prior);
    if (prState === "unknown") {
      opts.log("plan.shard_repair_skipped", { ...at, blob, pr_url: prior, pr_state: prState, reason: "the recorded repair PR's state could not be read; retried rather than risk a duplicate PR" });
      return { retry: true, blob };
    }
    if (prState !== "closed") {
      opts.log("plan.shard_repair_skipped", { ...at, blob, pr_url: prior, pr_state: prState, reason: "a repair PR was already opened for these bytes" });
      return { done: true };
    }
    reopenedFrom = prior;
  }
  const verdict = repairDuplicateKeyShard(text);
  if ("refused" in verdict) {
    opts.log("plan.shard_repair_refused", { ...at, blob, reason: verdict.reason });
    return { done: true };
  }
  const keys = Object.keys(verdict.kept).join(", ");
  const pr = {
    title: `fix(plan): drop the duplicate ${keys} key from a quarantined shard`,
    body:
      `The daemon quarantined \`${rel}\` (blob ${blob}): it fails to parse on a duplicated \`${keys}\` key, the merge race ` +
      `#8877 and #8922 repaired by hand. This keeps ${Object.entries(verdict.kept).map(([k, v]) => `\`${k}: ${v}\``).join(", ")}, the value ` +
      `the record's risk_ruling pin covers, and drops the other line and any backlog-gardener marker it carried.\n\n` +
      `Opened by the duplicate-key repair lane (W1-T5519).\n\n${SHARD_REPAIR_ACCEPTANCE}`,
  };
  let prUrl: string | undefined;
  try {
    prUrl = await opts.land(rel, verdict.text, pr);
  } catch (e) {
    opts.log("plan.shard_repair_failed", failure("land", e));
    return { retry: true, blob };
  }
  if (prUrl === undefined) {
    opts.log("plan.shard_repair_not_landed", { ...at, blob, reason: "the plan-PR preflight refused the repair; plan_pr.preflight_refused names why" });
    return { retry: true, blob };
  }
  const entry: ShardRepairOpened = reopenedFrom === undefined ? prUrl : { pr_url: prUrl, reopened_from: reopenedFrom };
  writeAtomic(openedPath, `${JSON.stringify({ ...opened, [blob]: entry }, null, 2)}\n`);
  opts.log("plan.shard_repair_opened", { ...at, blob, pr_url: prUrl, kept: verdict.kept, ...(reopenedFrom === undefined ? {} : { reopened_from: reopenedFrom }) });
  return { done: true };
}

/** W1-T5618 — a retried request is rewritten with its attempt count and backoff, or abandoned at the cap. Bytes
 *  main changed since the last attempt start their own count: the old bytes' failures say nothing about them. */
function rescheduleShardRepair(path: string, request: ShardRepairRequest, blob: string | undefined, now: number, log: ShardRepairLog): void {
  const charged = blob ?? request.blob;
  const newBytes = blob !== undefined && request.blob !== undefined && blob !== request.blob;
  const attempts = (newBytes ? 0 : (request.attempts ?? 0)) + 1;
  const at = { id: request.id, file: request.file, ...(charged === undefined ? {} : { blob: charged }) };
  if (attempts >= SHARD_REPAIR_ATTEMPT_CAP) {
    rmSync(path, { force: true });
    log("plan.shard_repair_abandoned", { ...at, attempts, reason: `${attempts} repair attempts did not open a PR; the shard's quarantine escalation stands for a hand repair` });
    return;
  }
  const nextAt = new Date(now + GARDEN_FILING_RETRY_BASE_MS * 2 ** (attempts - 1)).toISOString();
  writeAtomic(path, `${JSON.stringify({ id: request.id, file: request.file, attempts, ...(charged === undefined ? {} : { blob: charged }), next_at: nextAt })}\n`);
  log("plan.shard_repair_retry_scheduled", { ...at, attempt: attempts, next_at: nextAt });
}

/**
 * Off the loop, inside the plan garden's child: each due request is repaired from origin/main's blob
 * with {@link repairDuplicateKeyShard} and opened as a plan-only PR through {@link gardenCheckoutAsync} (its
 * W1-T5348 preflight, then `createPlanPrRest`) — once per shard blob, by `opened.json`, unless that PR was
 * closed unmerged, when one fresh PR is opened (W1-T5618). A request is consumed only at an end state — a PR
 * open or merged, a refusal, a request that cannot be read; a not-landed or failed attempt backs off and is
 * retried on a later pass until {@link SHARD_REPAIR_ATTEMPT_CAP} abandons it.
 */
export async function runShardRepairPass(opts: {
  stateDir: string;
  repoDir: string;
  worktreesRoot: string;
  owner: string;
  repo: string;
  log: ShardRepairLog;
  readOriginBlob?: (rel: string) => string | Promise<string>;
  land?: (rel: string, text: string, pr: { title: string; body: string }) => string | undefined | Promise<string | undefined>;
  prState?: (prUrl: string) => PrState | Promise<PrState>;
  openCheckout?: (opts: GardenCheckoutOpts) => Promise<GardenCheckoutAsync>;
  clock?: Clock;
}): Promise<void> {
  const readOriginBlob =
    opts.readOriginBlob ?? (async (rel: string) => (await execFilePromise("git", ["-C", opts.repoDir, "show", `origin/main:${rel}`], { encoding: "utf8", maxBuffer: 1 << 26 })).stdout);
  const land =
    opts.land ??
    (async (rel: string, text: string, pr: { title: string; body: string }) => {
      const checkout = await (opts.openCheckout ?? gardenCheckoutAsync)({ name: "plan", repoDir: opts.repoDir, worktreesRoot: opts.worktreesRoot, owner: opts.owner, repo: opts.repo, log: opts.log, clock: opts.clock });
      try {
        writeFileSync(join(checkout.root, rel), text);
        return await checkout.land({ paths: [rel], ...pr });
      } finally {
        await checkout.dispose();
      }
    });
  const prState = opts.prState ?? ((prUrl: string) => gardenPrState(opts.owner, opts.repo, prUrl, ghJsonAsync));
  const now = (opts.clock ?? systemClock).now();
  for (const path of shardRepairRequests(opts.stateDir)) {
    if (!shardRepairRequestDue(path, now)) continue;
    let request: ShardRepairRequest;
    try {
      request = JSON.parse(readFileSync(path, "utf8")) as ShardRepairRequest;
    } catch (e) {
      opts.log("plan.shard_repair_failed", { request: path, stage: "pass", reason: String((e as Error)?.message ?? e) });
      rmSync(path, { force: true });
      continue;
    }
    const outcome = await repairRequestedShard(request, { stateDir: opts.stateDir, log: opts.log, readOriginBlob, land, prState });
    if ("done" in outcome) rmSync(path, { force: true });
    else rescheduleShardRepair(path, request, outcome.blob, now, opts.log);
  }
}

/** A garden branch whose PR create threw is deleted from origin, unless a PR does sit on it (the
 *  create succeeded server-side but returned nothing) or that cannot be read — then it is kept. */
export function retractGardenBranch(o: {
  branch: string;
  git: (...args: string[]) => string;
  name: string;
  owner: string;
  repo: string;
  fetcher: GhApiFetcher;
  log: (step: string, extra?: Record<string, unknown>) => void;
}): "deleted" | "kept_pr_exists" | "kept_unreadable" | "kept_delete_failed" {
  return runStepsSync(retractGardenBranchSteps(o));
}

export function retractGardenBranchAsync(
  o: Omit<Parameters<typeof retractGardenBranch>[0], "git"> & { git: (...args: string[]) => Promise<string> },
): Promise<ReturnType<typeof retractGardenBranch>> {
  return runStepsAsync(retractGardenBranchSteps(o));
}

function* retractGardenBranchSteps(
  o: Omit<Parameters<typeof retractGardenBranch>[0], "git"> & { git: (...args: string[]) => string | Promise<string> },
): Steps<ReturnType<typeof retractGardenBranch>> {
  let existing: ReturnType<typeof probeExistingPlanPr>;
  try {
    const rows = yield* step(() => o.fetcher(ratifyPrProbeRestArgs(o.owner, o.repo, o.branch)));
    existing = probeExistingPlanPr(() => rows, o.owner, o.repo, o.branch);
  } catch (e) {
    o.log(`${o.name}.garden_branch_kept`, { branch: o.branch, reason: `pr probe failed: ${String((e as Error)?.message ?? e)}` });
    return "kept_unreadable";
  }
  if (existing) {
    o.log(`${o.name}.garden_branch_kept`, { branch: o.branch, reason: `a pr is on it: ${existing.prUrl}` });
    return "kept_pr_exists";
  }
  try {
    yield* step(() => o.git("push", "-q", "origin", "--delete", o.branch));
  } catch (e) {
    o.log(`${o.name}.garden_branch_kept`, { branch: o.branch, reason: `delete failed: ${String((e as Error)?.message ?? e)}` });
    return "kept_delete_failed";
  }
  o.log(`${o.name}.garden_head_deleted`, { branch: o.branch });
  return "deleted";
}

/** A fresh worktree of origin/main a gardener changes and lands as one PR on its own branch. Every
 *  garden PR opens READY FOR REVIEW — never a draft (operator ruling, 2026-09-24: a draft sits like a
 *  stuck PR) — so the sweep reviews and arms it like any other fleet PR (`GARDEN_BRANCH_RE`). */
export function gardenCheckout(opts: GardenCheckoutOpts): GardenCheckout {
  const branch = `${opts.name}-garden-${(opts.clock ?? systemClock).now()}`;
  const root = join(opts.worktreesRoot, branch);
  worktreeAdd(opts.repoDir, root, branch, "origin/main", { log: opts.log });
  const git = (...args: string[]) => execFileSync("git", ["-C", root, ...args], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
  const io: GardenLandIo = {
    git,
    fetcher: opts.fetcher ?? ghJson,
    generate: (script) => execFileSync(process.execPath, [...(script === "generate-capability-snapshot.mjs" ? ["--import", import.meta.resolve("tsx")] : []), join(root, "scripts", script)], { cwd: root, stdio: "pipe" }),
    preflight: opts.preflight ?? ((input) => planPrPreflight(input, { log: opts.log })),
  };
  return {
    root,
    branch,
    land: (landing) => runStepsSync(gardenLandSteps(opts, root, branch, landing, io)),
    dispose: () => worktreeRemove(opts.repoDir, root),
  };
}

export async function gardenCheckoutAsync(opts: GardenCheckoutOpts): Promise<GardenCheckoutAsync> {
  const branch = `${opts.name}-garden-${(opts.clock ?? systemClock).now()}`;
  const root = join(opts.worktreesRoot, branch);
  await worktreeAddAsync(opts.repoDir, root, branch, "origin/main", { log: opts.log });
  const io: GardenLandIo = {
    git: async (...args: string[]) => (await execFilePromise("git", ["-C", root, ...args], { encoding: "utf8" })).stdout,
    fetcher: opts.fetcher ?? ((args) => ghJsonAsync(args)),
    generate: (script) => execFilePromise(process.execPath, [...(script === "generate-capability-snapshot.mjs" ? ["--import", import.meta.resolve("tsx")] : []), join(root, "scripts", script)], { cwd: root }),
    preflight: opts.preflight ?? ((input) => planPrPreflightAsync(input, { log: opts.log })),
  };
  return {
    root,
    branch,
    land: (landing) => runStepsAsync(gardenLandSteps(opts, root, branch, landing, io)),
    dispose: () => worktreeRemoveAsync(opts.repoDir, root),
  };
}

export interface GardenCheckoutOpts {
  name: GardenName;
  repoDir: string;
  worktreesRoot: string;
  owner: string;
  repo: string;
  log: (step: string, extra?: Record<string, unknown>) => void;
  fetcher?: GhApiFetcher;
  clock?: Clock;
  /** W1-T5348: the plan-PR preflight over the committed tree; injected only by a test. */
  preflight?: (input: { cwd: string; title: string; body: string }) => PlanPrPreflightResult;
}

interface GardenLandIo {
  git: (...args: string[]) => string | Promise<string>;
  fetcher: GhApiFetcher;
  generate: (script: "generate-docs-index.mjs" | "generate-capability-snapshot.mjs") => unknown;
  preflight: (input: { cwd: string; title: string; body: string }) => PlanPrPreflightResult | Promise<PlanPrPreflightResult>;
}

function* gardenLandSteps(
  opts: GardenCheckoutOpts,
  root: string,
  branch: string,
  { paths, title, body }: { paths: string[]; title: string; body: string },
  io: GardenLandIo,
): Steps<string | undefined> {
  yield* step(() => io.git("add", "--", ...paths));
  // A garden log under docs/ changes what docs/docs-index.json must say, and docs-index-check
  // refuses a PR whose index is stale — regenerate it with the checkout's own generator.
  if (paths.some((p) => p.startsWith("docs/") && p.endsWith(".md"))) {
    yield* step(() => io.generate("generate-docs-index.mjs"));
    yield* step(() => io.git("add", "--", "docs/docs-index.json"));
  }
  // The gate garden edits REQUIRED; the capability block derives that same list. Commit its
  // checkout-owned regeneration before either preflight or push, with failures left intact.
  if (paths.includes(".github/workflows/ci-gate.yml")) {
    yield* step(() => io.generate("generate-capability-snapshot.mjs"));
    yield* step(() => io.git("add", "--", "MASTER-PLAN.md"));
  }
  // commitlint refuses a header over 100 characters, and a cause name makes a long title: fit
  // the header (prefix kept, cut at a space or hyphen, since a cause is one hyphenated token)
  // for both the commit and the PR, and carry the full title in each body.
  const fitted = fitConventionalTitle(title);
  const fullTitle = fitted.trimmed ? `Full title: ${title}\n\n` : "";
  yield* step(() => io.git("commit", "-q", "-m", `${fitted.header}\n\n${wrapBodyLines(`${fullTitle}Tended by the ${opts.name} gardener.`).join("\n")}`));
  // Both guards run BEFORE the push: a push that lands and a PR that is then refused leaves a
  // branch with no PR — 103 test-run plan-garden-* heads on origin by 2026-09-29.
  assertLiveWriteAllowed("git-push", `pushing the ${opts.name} garden branch ${branch}`);
  assertLiveWriteAllowed("gh-pr-create", `opening a ${opts.name} garden PR against ${opts.owner}/${opts.repo}`);
  // W1-T5348: a tree CI would refuse is never pushed — the lane's not-landed outcome instead of a red PR.
  const verdict = yield* step(() => io.preflight({ cwd: root, title: fitted.header, body: fullTitle + body }));
  if (!planPrPreflightAllows(verdict, { lane: opts.name, branch, log: opts.log })) return undefined;
  yield* step(() => io.git("push", "-q", "origin", `HEAD:refs/heads/${branch}`));
  try {
    const create = { title: fitted.header, body: fullTitle + body, head: branch, base: "main" };
    const row = yield* step(() => io.fetcher(ratifyPrCreateRestArgs(opts.owner, opts.repo, create)));
    return createPlanPrRest(() => row, opts.owner, opts.repo, create).prUrl;
  } catch (e) {
    yield* retractGardenBranchSteps({ branch, git: io.git, name: opts.name, owner: opts.owner, repo: opts.repo, fetcher: io.fetcher, log: opts.log });
    throw e;
  }
}

export function knowledgeGardenWorkspace(opts: KnowledgeGardenWorkspaceOpts): GardenWorkspace {
  const checkout = gardenCheckout({ ...opts, name: "knowledge" });
  return { ...checkout, refreshAssertions: () => refreshKnowledgeAssertions(checkout.root) };
}

export async function knowledgeGardenWorkspaceAsync(opts: KnowledgeGardenWorkspaceOpts): Promise<GardenCheckoutAsync<GardenWorkspace>> {
  const checkout = await gardenCheckoutAsync({ ...opts, name: "knowledge" });
  return { ...checkout, refreshAssertions: () => refreshKnowledgeAssertions(checkout.root) };
}

type KnowledgeGardenWorkspaceOpts = Omit<GardenCheckoutOpts, "name" | "preflight">;

function refreshKnowledgeAssertions(root: string): string[] {
  execFileSync(process.execPath, [join(root, "scripts", "learnings-assert-check.mjs"), "--dir", join(root, "learnings")], { cwd: root, stdio: "pipe" });
  return execFileSync("git", ["-C", root, "status", "--porcelain", "--", "learnings"], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] })
    .split("\n")
    .filter(Boolean)
    .map((line) => line.slice(3));
}

/** What {@link buildRegisteredGarden} builds a garden over: the daemon's own config, repo and ledger writers. */
export type { GardenBuildContext } from "./cli/commands/daemon.js";

export function daemonGardenWorkspace(ctx: Pick<GardenBuildContext, "config" | "repoRoot" | "owner" | "repo" | "log">, name: GardenName): () => Promise<GardenCheckoutAsync> {
  return () => gardenCheckoutAsync({ name, repoDir: ctx.repoRoot, worktreesRoot: worktreesDir(ctx.config), owner: ctx.owner, repo: ctx.repo, log: ctx.log });
}

/** One pass of one garden; it logs its own failure under the garden's own step name and never throws. */
export type RegisteredGardenPass = (() => void | Promise<void>) & { due?: () => boolean | Promise<boolean> };

/** W1-T8864: the issue-revalidation garden's ports that live here: the plan, the reconciler's referent
 *  derivation over the garden's own issue list, and the judge on the escalation judge's mount. Each loads
 *  on first use, never at build time. `seams` stand in for the plan, the reconciler's GitHub reads and the
 *  judge's spawn in tests. */
export function issueRevalidationRunTaskPorts(
  ctx: { owner: string; repo: string; repoRoot: string; stateDir: string; log: (step: string, extra?: Record<string, unknown>) => void },
  seams: {
    loadPlan?: () => Plan;
    reconcile?: Pick<NonNullable<Parameters<typeof buildEscalationReconcileCandidates>[5]>, "github" | "evidenceRootFor" | "creditIo">;
    spawn?: Parameters<typeof issueRevalidationJudgeText>[0]["spawn"];
  } = {},
): Pick<IssueRevalidationPorts, "hasReferent" | "referentVerdicts"> & { judgeText: ReturnType<typeof issueRevalidationJudgeText> } {
  const { owner, repo, repoRoot, stateDir, log } = ctx;
  let plan: Plan | undefined;
  const planNow = (): Plan => (plan ??= (seams.loadPlan ?? (() => loadPlan(resolveRepoLayout(repoRoot).planMonolith)))());
  return {
    hasReferent: (issue) => {
      const taskId = issueTaskId(issue) ?? "";
      return /^PR-\d+$/.test(taskId) || planNow().byId.has(taskId) ||
        prReferentFromIssueText(issue.body) !== undefined || prReferentFromIssueText(issue.title) !== undefined;
    },
    referentVerdicts: async (issues) => {
      const served = issues.map((i) => ({ number: i.number, url: i.url, title: i.title, body: i.body }));
      const candidates = buildEscalationReconcileCandidates(owner, repo, planNow(), join(stateDir, LEDGER_FILENAME), log, {
        ...seams.reconcile,
        issues: { create: () => { throw new Error("issue-revalidation never opens issues"); }, listOpen: () => served },
      });
      return new Map(candidates.filter((c) => c.issueNumber !== undefined).map((c): [number, RevalidationVerdict] => {
        const pr = c.derived.prNumber !== undefined ? `PR #${c.derived.prNumber}` : (c.derived.prUrl ?? "its PR");
        if (c.derived.indeterminate) return [c.issueNumber!, { verdict: "unknown", reason: `the referent of ${c.taskId} could not be derived` }];
        if (c.derived.merged) return [c.issueNumber!, { verdict: "resolved", reason: `${c.taskId} is merged`, citation: `${pr} merged${c.derived.prUrl ? ` (${c.derived.prUrl})` : ""}` }];
        if (c.derived.closed) return [c.issueNumber!, { verdict: "resolved", reason: `${c.taskId}'s PR closed without merging`, citation: `${pr} closed without merging` }];
        return [c.issueNumber!, { verdict: "still-true", reason: `${c.taskId} is still open` }];
      }));
    },
    judgeText: (prompt, issueNumber, observe) => {
      const mounts = loadMounts(mountsPath(repoRoot));
      return issueRevalidationJudgeText({ mount: mounts.escalation_judge ?? resolveRiskJudgeMount(mounts), cwd: repoRoot,
        settingsFile: join(repoRoot, "settings", "worker.json"), spawn: seams.spawn })(prompt, issueNumber, observe);
    },
  };
}

/** W1-T9925: the queue judge's ports that live here: its judge is the escalation judge's tool-less spawn (one per pass,
 *  on the mount the issue-revalidation garden already uses), and its open-PR set is the daemon's persisted board, a file
 *  read with no remote call. `seams` stand in for the spawn and the board read in tests. */
export function queueJudgeRunTaskPorts(
  ctx: { owner: string; repo: string; repoRoot: string; stateDir: string; root: string; log: (step: string, extra?: Record<string, unknown>) => void },
  seams: { spawn?: Parameters<typeof issueRevalidationJudgeText>[0]["spawn"]; openBoard?: typeof readOpenBoardSnapshot } = {},
): Pick<QueueJudgeSources, "judgeText" | "openPrNumbers"> {
  const { owner, repo, repoRoot, stateDir, root, log } = ctx;
  const judge = issueRevalidationRunTaskPorts({ owner, repo, repoRoot, stateDir, log }, { spawn: seams.spawn });
  return {
    judgeText: (prompt) => judge.judgeText(prompt, 0),
    openPrNumbers: () => {
      const open = (seams.openBoard ?? readOpenBoardSnapshot)(root, owner, repo);
      if (!open.ok) throw new Error(`queue judge: the open-PR snapshot is unavailable (${open.reason})`);
      return new Set(open.snapshot.rows.map((row) => row.number));
    },
  };
}

/** W1-T5114: the ONE place each registered garden is built, for the daemon's in-process mode and `rmd garden run`. */

export function buildRegisteredGarden(name: RegisteredGardenName, ctx: GardenBuildContext, opts: { hourly?: boolean } = {}): RegisteredGardenPass | Promise<RegisteredGardenPass> {
  const { config, repoRoot, owner, repo, log, raiseDuplicate } = ctx;
  const stateDir = join(config.root, "state");
  const mintOptions = {
    pollIntervalMs: ctx.pollIntervalMs === undefined ? undefined : () => ctx.pollIntervalMs!,
  };
  const deps = (garden: Parameters<typeof gardenCheckout>[0]["name"], escalate?: (e: Escalation) => string): GardenerDeps => ({
    stateDir,
    repoRoot,
    openWorkspace: daemonGardenWorkspace(ctx, garden),
    prState: (prUrl: string) => gardenPrState(owner, repo, prUrl, ghJson),
    // The daemon's tick persists the open-PR list; reading it and origin/main's ref is two file reads, no gh call.
    pendingSignal: (prUrl: string) => {
      const open = readOpenBoardSnapshot(config.root, owner, repo);
      return gardenPendingSignal(prUrl, open.ok ? open.snapshot.rows : undefined, readOriginMainSha(repoRoot));
    },
    log,
    ...(escalate ? { escalate } : {}),
  });
  const withDue = (pass: () => void | Promise<void>, due: () => boolean | Promise<boolean>): RegisteredGardenPass => Object.assign(pass, { due });
  const gardenPass = <C extends string, I, A extends GardenAction<C>>(spec: GardenSpec<C, I, A, GardenCheckout>, d: GardenerDeps): RegisteredGardenPass => withDue(async () => {
    try {
      await runGardenAsync(spec, d);
    } catch (e) {
      log(`${spec.name}.gardener_failed`, { error: String((e as Error)?.message ?? e) });
    }
  }, () => gardenPassDue(spec, d));
  const noPass: RegisteredGardenPass = () => {};
  switch (name) {
    case "review-replay": {
      const d = deps("review-replay");
      return gardenPass(reviewReplayGardenSpec(d, () => {
        const sha = reviewerHealthRowFields("review.posted", undefined).reviewer_code_sha;
        if (typeof sha !== "string") throw new Error("review replay generator revision is unavailable");
        return sha;
      }), d);
    }
    case "inbox": {
      return withDue(async () => {
        const { scope, ports } = await inboxGardenerRunTaskPorts(ctx);
        const result = await runInboxGardener({ stateDir, scope, mode: inboxGardenerMode(), ports });
        log("inbox.gardener_pass", result);
      }, () => registeredGardenEnabled("inbox", true));
    }
    case "knowledge": {
      // Preserve knowledge's open-PR reuse, review and assertion-refresh ports in the child,
      // rather than reducing it to the generic garden workspace and losing those semantics.
      const d: GardenerDeps<GardenWorkspace> = {
        ...deps("knowledge"),
        openWorkspace: () => knowledgeGardenWorkspaceAsync({ repoDir: repoRoot, worktreesRoot: worktreesDir(config), owner, repo, log }),
      };
      return withDue(async () => {
        try {
          await runKnowledgeGardenPass(d);
        } catch (e) {
          log("knowledge.gardener_failed", { error: String((e as Error)?.message ?? e) });
        }
      }, () => gardenPassDue(knowledgeGardenSpec(d), d));
    }
    case "plan": {
      const d = deps("plan");
      const repairs = { stateDir, repoDir: repoRoot, worktreesRoot: worktreesDir(config), owner, repo, log };
      return withShardRepairs(stateDir, () => runShardRepairPass(repairs), gardenPass(planGardenSpec(d), d), log);
    }
    case "backlog": {
      // A filing streak escalates once (gardener.ts), so a refused change reaches a person rather than looping.
      const d = deps("backlog", raiseDuplicate);
      return gardenPass(backlogGardenSpec(d), d);
    }
    // W1-T9925: the queue judge re-ranks queued tasks by measured cost of delay through its own reviewed plan PR.
    case "queue-judge": {
      const d = deps("queue-judge", raiseDuplicate);
      return gardenPass(queueJudgeGardenSpec(d, queueJudgeRunTaskPorts({ owner, repo, repoRoot, stateDir, root: config.root, log })), d);
    }
    // W1-T5454: the scout looks for work nobody asked for -- a recurring failure-shaped ledger step no task
    // or scorecard covers is filed through the machine-filing path, bounded by the queue and the day's merges.
    case "scout": {
      const d = deps("scout");
      return gardenPass(scoutGardenSpec(d, { mintTaskId: ciLearningTaskIdMinter(repoRoot, log, undefined, mintOptions) }), d);
    }
    // W1-T4116: the gates tighten, refresh and propose demoting themselves from their own
    // measurements. The ratchets are ES modules, so the garden starts once they have loaded.
    case "gate": {
      const d = deps("gate");
      return loadGateProbes(repoRoot).then(
        (probes) => gardenPass(gateGardenSpec(d, probes, { mintTaskId: ciLearningTaskIdMinter(repoRoot, log, undefined, mintOptions) }), d),
        (e: unknown) => {
          log("gate.gardener_failed", { error: String((e as Error)?.message ?? e) });
          return noPass;
        },
      );
    }
    // W1-T4112: the test suite tends itself — a material duration proposal is
    // adopted, a repeat flaker is retiered to the slow tier, and a stale one-way
    // baseline shrinks, all read from scripts/test-tier-manifest.mjs's own
    // functions and the ledger's `test.flake_retry` rows. Same async-probe-load
    // shape as the gate garden just above, since the manifest is also an ES module.
    case "test": {
      const d = deps("test");
      return loadTestManifestProbe(repoRoot).then(
        (probe): RegisteredGardenPass => withDue(async () => {
          try {
            let feed: TestProposalFeed | { status: "failed"; error: string } | undefined;
            if (opts.hourly) {
              try {
                feed = await refreshTestManifestProposalAsync(owner, repo, stateDir);
              } catch (e) {
                feed = { status: "failed", error: String((e as Error)?.message ?? e) };
                log("test.evidence_failed", { error: feed.error });
              }
            }
            const pass = await runGardenAsync(testGardenSpec(d, probe), d);
            if (opts.hourly) {
              log("test.pass", { ran: pass.ran, feed, pr_url: pass.prUrl ?? null, proposal_present: existsSync(testManifestProposalPath(stateDir)) });
            }
          } catch (e) {
            log("test.gardener_failed", { error: String((e as Error)?.message ?? e) });
          }
        }, () => gardenPassDue(testGardenSpec(d, probe), d)),
        (e: unknown) => {
          log("test.gardener_failed", { error: String((e as Error)?.message ?? e) });
          return noPass;
        },
      );
    }
    // W1-T4113: worker configuration tends itself — budgets, mounts and the learnings cap, each a
    // canary it judges and rolls back. The headroom sweep is an ES module, so it starts once loaded.
    case "config": {
      const d = deps("config");
      return tsImport(pathToFileURL(join(repoRoot, "scripts", "mount-headroom-sweep.mjs")).href, import.meta.url).then(
        (): RegisteredGardenPass => {
          const workerEnv = buildWorkerEnv({}, process.env, { allowApiKey: config.overflow === "api_key" });
          // Leave the build seam absent: production must use the heap-bounded measurement worker.
          const mountRecommendations = mountRecommendationSource({ sweepScript: join(repoRoot, "scripts", "mount-headroom-sweep.mjs"), stateDir, mountsFile: mountsPath(repoRoot), billingMode: billingMode(Object.keys(workerEnv)), log });
          return withDue(async () => {
            try {
              await runConfigGarden(configGardenSpec(d, { mountRecommendations }), d, { mountRecommendations });
            } catch (e) {
              log(`${CONFIG_GARDEN_NAME}.gardener_failed`, { error: String((e as Error)?.message ?? e) });
            }
          }, () => configCanariesDue(stateDir) || gardenPassDue(configGardenSpec(d, { mountRecommendations }), d));
        },
        (e: unknown) => {
          log("config.gardener_failed", { error: String((e as Error)?.message ?? e) });
          return noPass;
        },
      );
    }
    // W1-T4117: an export the adoption scan reported unreferenced twice, and that grep
    // finds named nowhere else, is deleted in a small batch.
    case "export": {
      const d = deps("export");
      return gardenPass(exportGardenSpec(d), d);
    }
    // W1-T4435: the fleet prices its own slowest gate. Every extra-head cause (a red
    // required check, main merging in, a merge conflict, a refused fix-lane commit) is
    // priced in PR MINUTES — never fire count — from the ledger union and gate-fire-
    // rate.ts's own measurement (W1-T4115); the costliest cause with no open task is
    // drafted as one, parked for a person.
    case "ci-friction": {
      const d = deps("ci-friction", raiseDuplicate);
      let handFixes: ReturnType<typeof readCiFrictionHandFixes> | undefined;
      const sources: CiFrictionGardenSources = {
        ledgerRecords: () => readCiFrictionLedgerRecords(stateDir),
        handFixes: () => handFixes ??= readCiFrictionHandFixes(repoRoot, stateDir, owner, repo),
        gateFireRates: () => readGateFireRateReport(stateDir),
        planState: () => readCiFrictionPlanState(repoRoot),
        ownerSearch: gitCiFrictionOwnerSearch((args) => execFileSync("git", ["-C", repoRoot, ...args], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 })),
        mintTaskId: ciLearningTaskIdMinter(repoRoot, log, undefined, mintOptions),
      };
      return gardenPass(ciFrictionGardenSpec(d, sources), d);
    }
    case "flow-remedy": {
      const d = deps("flow-remedy", raiseDuplicate);
      const spec = flowGardenSpec(d, {
        owner, repo, mintTaskId: ciLearningTaskIdMinter(repoRoot, log, undefined, mintOptions),
        admission: { owner, repo, settings: config.contributorAdmission },
        escalate: sreOperatorEscalation({ owner, repo, ledgerPath: join(stateDir, LEDGER_FILENAME), log }),
      });
      const pass = gardenPass(spec, d);
      return lowYieldGardenPass(stateDir, "flow-remedy", pass, {
        inputs: () => JSON.stringify([spec.cheapFingerprint(), pass.due!()]),
      });
    }
    // W1-T7421: the fix lane's own defects (operator interventions, unstated or refused rounds, FIXED-but-red heads)
    // are clustered and priced once a UTC day; the top class is drafted as ONE remedy through the flow ladder.
    case "fix-lane": {
      const d = deps("fix-lane", raiseDuplicate);
      return gardenPass(fixLaneGardenSpec(d, {
        owner, repo, mintTaskId: ciLearningTaskIdMinter(repoRoot, log, undefined, mintOptions),
        escalate: sreOperatorEscalation({ owner, repo, ledgerPath: join(stateDir, LEDGER_FILENAME), log }),
      }), d);
    }
    // W1-T4439: aggregate complete coverage-shard shadow records before W1-T4406
    // may narrow CI. A real miss opens a parked task naming the observed edge.
    case "selector-shadow": {
      const d: GardenerDeps = {
        stateDir,
        repoRoot,
        openWorkspace: daemonGardenWorkspace(ctx, "selector-shadow"),
        log,
      };
      return selectorShadowGardenPass(d, owner, repo, ciLearningTaskIdMinter(repoRoot, log, undefined, mintOptions));
    }
    case "flow":
      return flowGardenPass(deps("flow"), owner, repo, ciLearningTaskIdMinter(repoRoot, log, undefined, mintOptions),
        { admission: { owner, repo, settings: config.contributorAdmission } });
    // W1-T8864: every open issue re-checked against current evidence. Shadow until the operator flips
    // `issueRevalidation.mode` to act; the plan and the judge's mount load on the first pass, not here.
    case "issue-revalidation":
      return issueRevalidationGardenPass(stateDir, productionIssueRevalidationPorts({
        owner, repo, stateDir, repoRoot, landingStateRoot: config.root, operatorLogins: config.operatorGithubLogins, log,
        ...issueRevalidationRunTaskPorts({ owner, repo, repoRoot, stateDir, log }),
      }));
    case "evidence-coverage":
      return withDue(() => {
        try {
          runEvidenceCoverageGardener(daemonEvidenceCoverageInput({ stateDir, root: repoRoot, log, landingStateRoot: config.root }));
        } catch (e) {
          log("evidence_coverage.gardener_failed", { reason: "a pass that throws is logged and the next tick tries again", error: String((e as Error)?.message ?? e) });
        }
      }, () => evidenceCoveragePassDue(stateDir));
    // W1-T4802: the overseer watches every gardener -- liveness, the effect of merged changes and
    // churn -- and folds effect back into each class's Beta record. Off: state/GARDENER_OVERSEER_OFF.
    case "overseer":
      return async () => {
        try {
          const pass = runGardenerOverseer(productionGardenerOverseerPorts({ stateDir, repoRoot, owner, repo, fetch: ghJson, log, escalate: raiseDuplicate }));
          if (pass.ran) {
            try { log("improvement_effects.pass", await reconcileManagedImprovementEffects({ stateDir, repoRoot, repository: `${owner}/${repo}`, log })); }
            catch (error) {
              log("improvement_effects.pass_failed", { reason: "Independent improvement follow-up could not be completed.", error: String(error) });
            }
          }
        } catch (e) {
          log("gardener_overseer.overseer_failed", { error: String((e as Error)?.message ?? e) });
        }
      };
    // W1-T4803: the files merge conflicts strand pull requests on, ranked by PR minutes; the
    // costliest one no task restructures is filed as one plan-only proposal.
    case "hot-file": {
      const d = deps("hot-file", raiseDuplicate);
      const sources: HotFileGardenSources = {
        ledgerRecords: () => readCiFrictionLedgerRecords(stateDir),
        mainHistory: (sinceIso) => readMainHistory(repoRoot, sinceIso),
        planOrigins: () => loadPlan(resolveRepoLayout(repoRoot).planMonolith).tasks.map((t) => t.origin).filter((o): o is string => typeof o === "string"),
        mintTaskId: ciLearningTaskIdMinter(repoRoot, log, undefined, mintOptions),
        fileExists: (file) => existsSync(join(repoRoot, file)),
      };
      return gardenPass(hotFileGardenSpec(d, sources), d);
    }
    // Operator ruling 2026-09-29: the LLM judge in the middle of machine-filed work. W1-T5361 moved it off
    // the daemon loop; a pass that throws is still ledgered as machine_judge.failed.
    // Paced (gardenPacingDue): a pass that judged nothing new widens the wait, and a changed plan tree or
    // operator release is due at once.
    case "machine-judge": {
      const ports = productionMachineFilingJudgePorts({ repoRoot, stateDir, worktreesRoot: worktreesDir(config), owner, repo, log });
      const inputs = () => machineJudgeInputsAsync(repoRoot, stateDir, "origin/main");
      return withDue(async () => {
        const seen = await inputs();
        let found = false;
        try {
          found = machineJudgeFoundWork(await runMachineFilingJudge(ports));
        } catch (error) {
          log("machine_judge.failed", { error: String((error as Error)?.message ?? error) });
        }
        recordGardenPacing(stateDir, "machine-judge", found, { inputs: seen });
      }, () => gardenPacingDueAsync(stateDir, "machine-judge", { inputs }));
    }
    // W1-T4804: host disk, swap and inodes are projected to full from the heartbeat history and
    // answered in tiers against each host's own janitor cadence. Off: state/HOST_RESOURCE_OFF.
    case "host-resource": {
      const mintTaskId = ciLearningTaskIdMinter(repoRoot, log, undefined, mintOptions);
      const ports = {
        stateDir,
        log,
        readHeartbeats: gitHeartbeatSource(repoRoot),
        handoff: (h: { id: string; raw: string; origin: string }) => void stageFeedbackCapture(repoRoot, config.root, { id: h.id, raw: h.raw, origin: h.origin as FeedbackOrigin }),
        openIncidentOrigins: () => openIncidentFeedbackOrigins(repoRoot, config.root),
        escalate: raiseDuplicate,
        planOrigins: () => loadPlan(resolveRepoLayout(repoRoot).planMonolith).tasks.map((t) => t.origin).filter((o): o is string => typeof o === "string"),
        fileConsumer: fileConsumerVia(daemonGardenWorkspace(ctx, "host-resource"), mintTaskId, log),
      };
      const paced = lowYieldGardenPass(stateDir, "host-resource", () => runHostResourcePassAsync(ports).then(() => {}), {
        inputs: () => hostResourceInputStamp(repoRoot, stateDir),
      });
      return withDue(async () => {
        try {
          await paced();
        } catch (error) {
          log(`${HOST_RESOURCE}.failed`, { error: String((error as Error)?.message ?? error), reason: "a pass that throws is logged and the next tick tries again" });
        }
      }, paced.due);
    }
  }
}

/** The daemon's garden pass spawn (W1-T5475): a child pass logs through the daemon's ledger `log`, not stderr. */
export function daemonGardenPassSpawn(
  log: (step: string, extra?: Record<string, unknown>) => void,
  injected?: GardenPassSpawn,
  childOpts: Parameters<typeof childGardenPassSpawn>[0] = {},
): GardenPassSpawn {
  return boundedGardenPassSpawn(injected ?? childGardenPassSpawn({ ...childOpts, log }), 2);
}

export function registeredGardenDueProbe(name: RegisteredGardenName, ctx: GardenBuildContext): () => boolean | Promise<boolean> {
  if (!registeredGardenEnabled(name, true)) return () => false;
  let probe: (() => boolean | Promise<boolean>) | undefined;
  Promise.resolve(buildRegisteredGarden(name, ctx)).then(
    (pass) => { probe = pass.due; },
    (e: unknown) => ctx.log(GARDEN_DUE_FAILED_STEP, { name, error: String((e as Error)?.message ?? e) }),
  );
  return () => (probe ? probe() : true);
}

/** Run one garden pass; handled domain failures remain failures at the child-process boundary. */
export function runRegisteredGardenPass(name: RegisteredGardenName, args: readonly string[], ctx: GardenBuildContext, signal: { readonly stopped: boolean } = { stopped: false }): Promise<number> {
  if (signal.stopped) return Promise.resolve(0);
  return withManagedGardenTokenRefresh(name, ctx.log, async () => {
    let failed = false;
    const observed: GardenBuildContext = { ...ctx, log: (step, extra) => {
      const kind = classifyGardenerStep(step)?.kind;
      if (kind === "failed" || kind === "filing_failed" || step === "gardener_overseer.overseer_failed") failed = true;
      ctx.log(step, extra);
    } };
    const run = (pass: RegisteredGardenPass): Promise<number> => Promise.resolve(pass()).then(() => failed ? 1 : 0);
    const built = buildRegisteredGarden(name, observed, { hourly: args.includes(GARDEN_HOURLY_FLAG) });
    return Promise.resolve(built).then((pass) => signal.stopped ? 0 : run(pass));
  }, { refresh: refreshInstallationToken });
}

export const GARDEN_REPLAY_DAYS_FLAG = "--days";
export const GARDEN_REPLAY_STEP_FLAG = "--step-hours";

export interface GardenReplayOptions {
  say?: (line: string) => void;
  clock?: Clock;
  stateDir?: string;
  repoRoot?: string;
}

export function gardenReplayCommand(rest: string[], opts: GardenReplayOptions = {}): number {
  const [name, ...flags] = rest;
  const badArg = unknownArgError("garden", flags, [GARDEN_REPLAY_DAYS_FLAG, GARDEN_REPLAY_STEP_FLAG]);
  const value = (flag: string, fallback: number): number => {
    const i = flags.indexOf(flag);
    const n = i >= 0 ? Number(flags[i + 1]) : fallback;
    return Number.isFinite(n) && n > 0 ? n : NaN;
  };
  const days = value(GARDEN_REPLAY_DAYS_FLAG, 7);
  const stepHours = value(GARDEN_REPLAY_STEP_FLAG, 6);
  if (name !== "ci-friction" || badArg || Number.isNaN(days) || Number.isNaN(stepHours)) {
    console.error(`${badArg ?? "rmd garden: usage: rmd garden replay ci-friction [--days <n>] [--step-hours <h>]"}\n` + USAGE);
    return 2;
  }
  const say = opts.say ?? ((line: string) => console.log(line));
  const root = opts.repoRoot ?? repoRoot;
  const stateDir = opts.stateDir ?? join(loadConfig().root, "state");
  const git: CiFrictionGit = (args) => execFileSync("git", ["-C", root, ...args], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  const toMs = (opts.clock ?? systemClock).now();
  const lines = replayCiFriction({
    records: readCiFrictionLedgerRecords(stateDir),
    tasks: readCiFrictionPlanTimeline(git, relative(root, join(resolveRepoLayout(root).planDir, "tasks.d"))),
    fromMs: toMs - days * 86_400_000,
    toMs,
    stepMs: stepHours * 3_600_000,
    ownerSearch: gitCiFrictionOwnerSearch(git),
  });
  say(renderCiFrictionReplay(lines));
  return 0;
}

/** `rmd garden run <name> [--hourly]` — one pass of one registered garden, the daemon's off-loop child (W1-T5114). */
export async function gardenCommand(rest: string[], source: { repoRoot?: string } = {}): Promise<number> {
  const [sub, name] = rest;
  if (sub === "replay") return gardenReplayCommand(rest.slice(1));
  const badArg = unknownArgError("garden", rest.slice(2), [], [GARDEN_HOURLY_FLAG]);
  if (sub !== "run" || name === undefined || !isRegisteredGardenName(name) || badArg) {
    console.error(`${badArg ?? `rmd garden: usage: ${commandSyntax("garden")} — gardens: ${REGISTERED_GARDEN_NAMES.join(", ")}`}\n` + USAGE);
    return 2;
  }
  const config = loadConfig();
  const ledgerPath = ledgerPathFor(config);
  const self = resolveOwnerRepo();
  const runId = `GARDEN-${name}-${nextLaneEpochMs()}`;
  const log = (step: string, extra: Record<string, unknown> = {}) =>
    appendLedger(ledgerPath, { run_id: runId, task_id: "DAEMON", step, lane: "daemon", ...extra });
  const raiseDuplicate = (e: Escalation): string =>
    escalate({ ...e, runId }, { issues: ghIssueGateway(self.owner, self.repo), ledgerPath, runId });
  return await runRegisteredGardenPass(name, rest.slice(2), { config, repoRoot: source.repoRoot ?? repoRoot, owner: self.owner, repo: self.repo, log, raiseDuplicate });
}

export function sweepPrTerminalRung(github: Pick<GitHub, "prByRef">, ledgerPath: string, runId: string, // W1-T5318
  tickRead?: Pick<TickReadFacts, "closedPrs">): PrTerminalReconcileSummary {
  const lookup = tickRead?.closedPrs ? closedPrLookup(tickRead.closedPrs) : (url: string) => closedPrFromRef(github.prByRef(url));
  return runPrTerminalReconcile(lookup, { ledgerPath, runId });
}

export function applyTickCreditUpdates(facts: Pick<TickReadFacts, "creditUpdates">, ledgerPath: string,
  log: (step: string, extra?: Record<string, unknown>) => void): void {
  if (facts.creditUpdates.length === 0) return;
  const path = defaultCreditStorePath(ledgerPath);
  const current = loadCreditStore(path);
  let changed = false;
  for (const update of facts.creditUpdates) {
    if (JSON.stringify(current[update.id]) !== JSON.stringify(update.before)) {
      log("read_plane.credit_write_conflict", { task_id: update.id });
      continue;
    }
    current[update.id] = update.after;
    changed = true;
  }
  if (changed) saveCreditStore(path, current);
}

/** W1-T4075: the post-fix re-verification rung's two reads, answered from one tick-read generation. */
export function tickReadReverificationDeps(tickRead: Pick<TickReadFacts, "mergedFixPrNumbers" | "postFixCiFailuresByPr">): {
  isMergedByNumber: (prNumber: number) => boolean;
  readCiFailures: (pr: OpenPrView) => CiFailure[] | undefined;
} {
  return {
    isMergedByNumber: (number) => tickRead.mergedFixPrNumbers.includes(number),
    readCiFailures: (pr) => tickRead.postFixCiFailuresByPr.get(pr.prNumber),
  };
}

export function buildDaemonReadRefresher(options: {
  read: (input: { plan: Plan; previousProjection?: Array<[string, StatusProjection]> }) => Promise<ReadGeneration<TickReadFacts>>;
  plan: () => Plan;
  previous: () => Map<string, StatusProjection> | undefined;
  invalidate: () => void;
  publish: (snapshot: ReadGeneration<TickReadFacts>) => void;
  ledgerPath: string;
  statusPath: string;
  log: (step: string, extra?: Record<string, unknown>) => void;
}): (plan?: Plan) => Promise<MergedSet> {
  return async (plan = options.plan()) => {
    options.invalidate();
    const previous = options.previous();
    const snapshot = await options.read({ plan, previousProjection: previous ? [...previous] : undefined });
    applyTickCreditUpdates(snapshot.facts, options.ledgerPath, options.log);
    const stage = `${options.statusPath}.${process.pid}.tmp`;
    mkdirSync(dirname(options.statusPath), { recursive: true });
    writeFileSync(stage, JSON.stringify({ generated_at: new Date().toISOString(),
      note: "Machine-owned projection derived from GitHub. tasks.yaml is never rewritten.",
      tasks: Object.fromEntries(snapshot.facts.projection) }) + "\n");
    renameSync(stage, options.statusPath);
    options.publish(snapshot);
    const merged = new Set(snapshot.facts.projection.filter(([, projection]) => projection.merged).map(([id]) => id));
    return (id) => merged.has(id);
  };
}

/** W1-T5998 — run ids of workers this process spawned and has not reaped. A review takes no
 *  inflight lock, so only this registry tells the orphan sweep its worker is still running. */
const liveWorkerRunIds = new Set<string>();
const reviewWorkerLockId = (runId: string) => `review-worker-${createHash("sha256").update(runId).digest("hex")}`;

export async function whileWorkerRunLive<T>(runId: string, spawn: () => Promise<T>, inflightDir?: string): Promise<T> {
  return whileWorkerRunLiveFromModule(reviewCommandHost(), runId, spawn, inflightDir);
}

/** W1-T5998 — the orphan sweep's `isRunActive`: this daemon's own run id (its fix workers carry
 *  it), a run it spawned and has not reaped, or a live lock's run id or its prefix before
 *  `:fix-claim:`. A previous daemon's id matches none of these, so its strays are still killed. */
export function orphanSweepRunActive(
  ownRunId: string,
  inflightDir: string,
  isPidAlive?: (pid: number) => boolean,
  adoptedRunIds: ReadonlySet<string> = new Set(),
): (runId: string) => boolean {
  const reviewIsLive = (runId: string) => {
    const held = readInflightLock(join(inflightDir, "review-workers"), reviewWorkerLockId(runId));
    return held?.run_id === runId && sameHost(held.host, hostname()) && (isPidAlive ?? defaultIsPidAlive)(held.pid);
  };
  return (runId) =>
    runId === ownRunId ||
    liveWorkerRunIds.has(runId) ||
    adoptedRunIds.has(runId) ||
    reviewIsLive(runId) ||
    liveInflightRuns(inflightDir, isPidAlive).some((r) => r.runId === runId || r.runId.startsWith(`${runId}:fix-claim:`));
}

/** W1-T6782: sample the daemon's live memory and workload on each existing heartbeat. W1-T7092: each
 *  row also carries every worker thread's heap, by creation site, role, thread id and daemon
 *  generation, from request rounds `afterRow` starts once the row is written (never awaited; at most
 *  one unresolved request per thread). `liveThreads` is a test seam. */
export function daemonMemoryTelemetryReader(
  bootHeadSha: string | undefined,
  opts: { generation?: string; liveThreads?: () => readonly TrackedWorker[]; footprint?: DaemonFootprint; clock?: Clock } = {},
): (() => Record<string, unknown>) & { afterRow: () => void } {
  const threadHeaps = workerHeapReadings({
    live: opts.liveThreads ?? workerThreads().live,
    mainHeap: getHeapStatistics,
    ...(opts.generation ? { generation: opts.generation } : {}),
  });
  const read = (): Record<string, unknown> => {
    const memory = sampleDaemonMemory({
      heapStatistics: v8HeapStatistics,
      workload: () => ({ active_workers: activeWorkerCount(), in_flight_reviews: inFlightReviewCount() }),
      bootHeadSha,
      memoSizes: () => ({
        dispatchSelectionLedgerUnion: dispatchSelectionLedgerUnion.size(),
        terminalUnionScans: terminalUnionScans.size(),
        mergeLogEvidenceByRoot: mergeLogEvidenceByRoot.size(),
        dispatchFilingCache: dispatchFilingCache.size(),
        baseReproductionHostCache: baseReproductionHostCache.size(),
      }),
    });
    // The same reading, kept as the daemon's own rolling footprint for the memory budget (daemon-footprint.ts). A
    // failed persist keeps the sample in memory and rides the row.
    const kept = opts.footprint?.record({
      at: (opts.clock ?? systemClock).now(), bytes: memory.rss_bytes + (memory.vm_swap_bytes ?? 0), pid: process.pid,
    });
    return { ...memory, ...threadHeaps.fields(memory), ...(kept && !kept.persisted ? { footprint_persist: `error:${kept.reason}` } : {}) };
  };
  return Object.assign(read, { afterRow: () => threadHeaps.refresh() });
}

export interface RunInChildInput {
  taskId: string;
  config: Config;
  repoDir: string;
  allowStale: boolean;
  options: RunChildSpecOptions;
  planSync: (options: { allowStale?: boolean }) => SyncedPlan | Promise<SyncedPlan>;
  log: (step: string, extra?: Record<string, unknown>) => void;
  /** W1-T10000: the daemon is told while the run waits for its child's admission. */
  onPending?: (pending: RunChildPending) => void;
  /** W1-T10000: asked before the run stays in-process; `false` ends the lane with a {@link TaskAdmissionError}. */
  mayRunInProcess?: (reason: string) => boolean;
}

/** W1-T9085: under `sweep.runChild.mode: on` the run's settling promise from a detached child, else `undefined` (stays in-process; ledgered). */
export async function runInChildWhenOn(
  input: RunInChildInput,
  seams: { readMode?: () => RunChildMode; evidence?: () => RunChildModeEvidence; spawn?: typeof spawnRunChild; ports?: SpawnRunChildPorts } = {},
): Promise<RunChildHandle | undefined> {
  const mode = runChildModeIsOn(seams.readMode, seams.evidence);
  const inProcess = (reason: string): undefined => {
    if (input.mayRunInProcess?.(reason) === false) {
      throw new TaskAdmissionError(`restart decided: task ${input.taskId} was admitted to run as a child, and cannot run in-process (${reason})`);
    }
    return undefined;
  };
  const fallback = (reason: string): undefined => {
    input.log(RUN_CHILD_FALLBACK_STEP, { task_id: input.taskId, reason });
    return inProcess(reason);
  };
  if (mode.unreadable !== undefined) return fallback(`sweep.runChild.mode unreadable: ${mode.unreadable}`);
  if (!mode.on) return inProcess("sweep.runChild.mode is not on");
  if (input.options.skipGitSync) return fallback("an explicit --plan is read literally; the run stays in-process");
  const start = seams.spawn ?? ((spawnInput, spawnPorts) => spawnRunChild(spawnInput, spawnPorts));
  const launched = await start({
    taskId: input.taskId, stateRoot: join(input.config.root, "state"), repoDir: input.repoDir, root: input.config.root,
    log: input.log, options: input.options,
    plan: async () => input.planSync({ allowStale: input.allowStale }),
    ...(input.onPending ? { onPending: input.onPending } : {}),
  }, {
    abort: { teardownMs: () => restartWorkHistory(readRestartHistoryLines(dirname(ledgerPathFor(input.config))), systemClock.now()).yieldCost.ms },
    ...seams.ports,
  });
  if (launched.started) return launched;
  // W1-T10000: an abandoned wait took no claim and wrote no spec; the next daemon dispatches it, never this one in-process.
  if (launched.abandoned) {
    throw new TaskAdmissionError(`task ${input.taskId}'s run child was abandoned after ${launched.waitedMs} ms waiting for memory admission`);
  }
  return inProcess(launched.reason);
}

