/** The reconciler's live close side (fb-1784756088300-6a481e): `gh issue close --comment` via
 *  {@link ghIssueGateway}, built once. Throws if the gateway cannot close, so a phantom close
 *  is never ledgered — the reconciler's per-issue containment catches it as `close-failed`. */
export function buildEscalationCloser(
  owner: string,
  repo: string,
  issues: IssueGateway = ghIssueGateway(owner, repo),
): (url: string, comment: string) => void {
  return (url, comment) => {
    if (!issues.closeWithComment) throw new Error("issue gateway cannot close issues");
    issues.closeWithComment(url, comment);
  };
}

export function buildEscalationCloserAsync(
  owner: string,
  repo: string,
  issues: AsyncIssueGateway = ghIssueGatewayAsync(owner, repo),
): (url: string, comment: string) => Promise<void> {
  return async (url, comment) => {
    if (!issues.closeWithComment) throw new Error("issue gateway cannot close issues");
    await issues.closeWithComment(url, comment);
  };
}

/**
 * The escalation-lifecycle reconciler rung (fb-1784756088300-6a481e), shared verbatim by
 * `rmd sweep` and the daemon's sweep hook: list open needs-human issues, derive each referent's
 * CURRENT state, and close the resolved ones with a citation naming the resolver. Injectable
 * `issues`/`github` for tests. Returns the pass summary; never throws (buildEscalationReconcile-
 * Candidates degrades a failed read to [], runEscalationReconcile contains per-issue throws).
 */
/**
 * W1-T1101: the reconcile summary as THIS caller sees it — `runEscalationReconcile`'s own shape
 * (lib/sweep.ts, untouched by this task) plus the three intake counts `sweepEscalationReconcile`
 * already holds in a local. The widening lives HERE, not on the library type, because the library
 * function never measures these: `buildEscalationReconcileCandidates` does, one statement earlier,
 * in this same file. Putting the fields on the shared type would have moved a run-task.ts
 * measurement into lib/sweep.ts for no reader there.
 */
export interface SweepEscalationReconcileSummary extends EscalationReconcileSummary {
  /**
   * Open issues the read returned, one statement before the candidate loop — see
   * {@link EscalationIntake}. Present iff an intake reached this caller, which happens UNLESS the
   * issue-list read itself failed (the builder's `[]`-on-failure contract never calls its
   * `onIntake` observer) — so `issuesSeen === undefined` is specifically "the read failed", not
   * "nothing was measured".
   */
  issuesSeen?: number;
  /** Dropped for carrying no `**Task:**` trailer — see {@link EscalationIntake}. */
  droppedNoTaskTrailer?: number;
  /** Dropped for naming neither a plan task nor any resolvable PR referent. */
  droppedNoReferent?: number;
}

/**
 * One-line human render of an escalation-reconcile pass, for `rmd sweep`'s console output
 * (W1-T1101). The line this replaces printed `total` (the POST-DROP candidate count) under the
 * label "open needs-human issue(s) checked" — so `total: 0` read identically whether nothing was
 * open, everything open was dropped, or the issue-list read failed outright. This renders
 * `issuesSeen` under that label instead (the count the read actually returned), names an
 * unreadable list as exactly that rather than a bare zero, and — only when a drop shrank
 * `issuesSeen` down to `total` — names the drop reasons, mirroring the ledger row's own
 * healthy-path-stays-small asymmetry (see the `sweep.escalation_reconcile.summary` log call in
 * `runEscalationReconcile`).
 */
export function renderEscalationReconcileSummary(s: SweepEscalationReconcileSummary): string {
  if (s.issuesSeen === undefined) {
    // No intake reached this pass — on `sweepEscalationReconcile`'s own call site (the only
    // production caller), that happens exactly when `buildEscalationReconcileCandidates`' issue-list
    // read threw and returned `[]` under its "do nothing this cycle" contract. `total`/`closed` are
    // both correctly 0 in that case too, so rendering them here would be the identical, ambiguous
    // zero this task exists to remove.
    return "escalation reconcile: issue-list read FAILED this cycle (see sweep.escalation_reconcile.list_failed) — nothing checked, nothing closed";
  }
  const droppedTotal = s.issuesSeen - s.total;
  const droppedNote =
    droppedTotal > 0
      ? ` · ${s.total} became candidate(s), ${droppedTotal} dropped (${s.droppedNoTaskTrailer ?? 0} no-task-trailer, ${s.droppedNoReferent ?? 0} no-referent)`
      : "";
  return `escalation reconcile: ${s.issuesSeen} open needs-human issue(s) checked · ${s.closed} closed${droppedNote}`;
}

export async function sweepEscalationReconcile(
  owner: string,
  repo: string,
  plan: Plan,
  ledgerPath: string,
  runId: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  opts: { dryRun?: boolean; issues?: IssueGateway; github?: GitHub;
    tickRead?: Pick<TickReadFacts, "escalationCandidates" | "escalationIntake"> } = {},
): Promise<SweepEscalationReconcileSummary> {
  let intake: EscalationIntake | undefined;
  const candidates = opts.tickRead?.escalationCandidates ?? await buildEscalationReconcileCandidatesAsync(owner, repo, plan, ledgerPath, log, {
    issues: opts.issues,
    github: opts.github,
    onIntake: (i) => {
      intake = i;
    },
  });
  if (opts.tickRead) intake = opts.tickRead.escalationIntake;
  const summary = await runEscalationReconcile(candidates, {
    intake,
    closeIssue: buildEscalationCloserAsync(owner, repo, opts.issues),
    ledgerPath,
    runId,
    log,
    dryRun: opts.dryRun,
  });
  // W1-T2603: the SEPARATE retirement path for a headroom breach that has recovered — this class
  // carries no task referent, so `buildEscalationReconcileCandidates`/`runEscalationReconcile`
  // above structurally never see it (see that task's rationale). Sharing this rung's own
  // `issues`/`dryRun` rather than a second gateway construction, but a fully independent
  // candidate build and close loop, non-fatal like everything else in this rung — a throw here
  // must never take out the task-referent reconciler's own summary above.
  try {
    await retireRecoveredHeadroomEscalations(ledgerPath, runId, {
      issues: opts.issues ?? ghIssueGatewayAsync(owner, repo),
      log,
      dryRun: opts.dryRun,
    });
  } catch (e) {
    log("sweep.headroom_recovery.failed", { error: String((e as Error)?.message ?? e) });
  }
  // W1-T1101: the SAME counts the ledger row below has carried since #1084, now also riding on the
  // returned summary so `renderEscalationReconcileSummary` (the CLI line) can see them. No new
  // read, no change to what `runEscalationReconcile` measures or logs — the merge happens HERE,
  // in the file that already holds `intake`, rather than widening lib/sweep.ts's shared type.
  return intake
    ? { ...summary, issuesSeen: intake.issuesSeen, droppedNoTaskTrailer: intake.droppedNoTaskTrailer, droppedNoReferent: intake.droppedNoReferent }
    : summary;
}

/** Rejudge only observed open issues, using their recorded subjects and this sweep's referent state. */
export async function sweepEscalationTriage(
  context: { root: string; config: Config; owner: string; repo: string; ledgerPath: string; runId: string },
  openPrs: readonly OpenPrView[],
  log: (step: string, extra?: Record<string, unknown>) => void,
  io: {
    dryRun?: boolean;
    rows?: Record<string, unknown>[];
    /** W1-T9390: the daemon's reader, built once per start; absent (`rmd sweep`), one is built for this call. */
    history?: EscalationTriageHistoryReader;
    issues?: AsyncIssueGateway;
    runtime?: ReturnType<typeof buildEscalationTriageRuntime>;
    clock?: Clock;
    relabel?: (url: string, label: string) => void | Promise<void>;
    execAsync?: GhAsyncExecutor;
  } = {},
): Promise<void> {
  try {
    const { ledgerPath, runId, owner, repo } = context;
    // W1-T9390: this rung runs on the daemon loop, so its ledger read and every GitHub read or write are awaited.
    const history = io.rows ?? (await (io.history ?? createEscalationTriageHistoryReader())(dirname(ledgerPath))).rows;
    const issues = io.issues ?? ghIssueGatewayAsync(owner, repo, { exec: (args) => ghTextAsync(args, {}, io.execAsync) });
    const open = await listRetirableEscalationIssuesAsync(issues);
    const { births, judgedStateKeys } = indexEscalationTriageHistory(history);
    const nowMs = (io.clock ?? systemClock).now();
    const runtime = io.runtime ?? buildEscalationTriageRuntime(context);
    // W1-T9406: the evidence slice is refreshed off the loop before any candidate's evidence is read.
    await runtime.refresh(ledgerPath);
    const deps = { issues, ledgerPath, runId };
    const cfg = runtime(deps);
    // Async transport: this sweep runs on the daemon loop, so the relabel must not block the event loop.
    const relabel = io.relabel ?? (async (url: string, label: string): Promise<void> => {
      assertLiveWriteAllowed("gh-transport", "routing an escalation after triage");
      await ghTextAsync(["issue", "edit", url, "--repo", `${owner}/${repo}`, "--add-label", label,
        "--remove-label", label === "needs-human" ? "fleet-notice" : "needs-human"], {}, io.execAsync);
    });
    const candidates: StaleEscalationRejudgeCandidate[] = [];
    for (const issue of open) {
      const birth = births.get(issue.url);
      if (!birth || typeof birth.ts !== "string" || !Number.isFinite(Date.parse(birth.ts))) continue;
      const subject = birth.triage_subject as Escalation;
      if (!subject || !Array.isArray(subject.options)) continue;
      const pr = openPrs.find((p) => p.taskId === subject.taskId || p.prNumber === prReferentFromIssueText(subject.detail + subject.summary));
      const referentStateNow = pr ? JSON.stringify({ head: pr.headSha, review: pr.reviewState,
        checks: pr.checksState, mergeable: pr.mergeable, mergeableState: pr.mergeableState }) : "referent state unavailable";
      const siblingSummaries = open.filter((sibling) => sibling.url !== issue.url &&
        sibling.body?.includes(`**Task:** ${subject.taskId}\n`)).map((sibling) => sibling.title ?? sibling.url).sort();
      const stateKey = createHash("sha256").update(JSON.stringify([issue.url, issue.body, referentStateNow, siblingSummaries, cfg.mode])).digest("hex");
      candidates.push({ issueUrl: issue.url, issueNumber: issue.number, escalation: subject,
        ageMs: nowMs - Date.parse(birth.ts), referentStateNow, siblingSummaries, stateKey });
    }
    await runStaleEscalationRejudge(candidates, {
      ledgerPath, runId, log, dryRun: io.dryRun,
      alreadyJudgedStateKeys: judgedStateKeys,
      judge: (candidate) => {
        if (candidate.referentStateNow === "referent state unavailable")
          return Promise.resolve({ decision: "deliver", reason: "referent state unavailable" });
        return cfg.judge!({ ...candidate.escalation, detail: buildStaleEscalationRejudgePrompt(candidate) });
      },
      demote: async (url, reason) => { await issues.comment?.(url, reason); await relabel(url, "fleet-notice"); },
      triage: {
        mode: cfg.mode ?? "shadow", evidence: cfg.evidence,
        autoResolve: async (candidate) => {
          try {
            await triageExistingEscalation(candidate.escalation, candidate.issueUrl, { ...deps, triage: cfg }, relabel);
          } catch (err) {
            await relabel(candidate.issueUrl, "needs-human");
            throw err;
          }
        },
      },
    });
  } catch (err) {
    log("sweep.escalation_triage.failed", { reason: String(err) });
  }
}

/**
 * THE W1-T474 CALL SITE for W1-T124's post-fix re-verification rung (`runPostFixReverification`,
 * src/lib/sweep.ts) — built and unit-tested (test/post-fix-reverification.test.ts) but callerless
 * until this task. For every open PR whose recorded failure matches a {@link DEFAULT_FIX_CLASSES}
 * row whose `fixPrNumber` has MERGED and is positively absent from the PR head, mints a fresh head via the SAME `pushEmptyCommit` leaf the
 * ABSENT remedy (`repushAbsent` in {@link buildSweepEffects}) already uses — never a check
 * re-run: W1-T474's rationale (7) measured that the `pull_request` default checkout is the
 * PINNED merge ref, so re-requesting the same check-run replays the identical stale tree. Only a
 * new push (which fires `synchronize` and recomputes `refs/pull/N/merge` against CURRENT main)
 * actually changes what gets tested.
 *
 * `isMergedByNumber` defaults to a real `gh pr view --json state` read (mirrors `ghLiveStateByNumber`'s
 * own shape) so a class's fix is only ever treated as merged off a LIVE read, never an assumption.
 * `openPrs` is the caller's own already-fetched snapshot (never a second `buildOpenPrViews` read)
 * so this rung and `runSweep` observe the identical state for the same pass.
 *
 * MUST be called BEFORE `runSweep` (rationale (10)): the caller is responsible for excluding this
 * pass's `outcome === "redriven"` PRs from the list it hands `runSweep`, so the fix rung never
 * spends a strike deriving a disposition for a PR this rung just acted on in the same pass — a
 * fresh head carries no settled checks/review yet, so no rung should dispose it again until the
 * NEXT poll observes GitHub's own post-push state.
 */
export async function sweepPostFixReverification(
  owner: string,
  repo: string,
  openPrs: OpenPrView[],
  ledgerPath: string,
  runId: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  opts: {
    dryRun?: boolean;
    classes?: readonly FixClass[];
    pushEmptyCommit?: typeof gitPushEmptyCommit;
    fixInHead?: (pr: OpenPrView, cls: FixClass) => boolean | undefined | Promise<boolean | undefined>;
    isMergedByNumber?: (prNumber: number) => boolean;
    readCiFailures?: (pr: OpenPrView) => CiFailure[] | undefined | Promise<CiFailure[] | undefined>;
  } = {},
): Promise<PostFixReverificationSummary> {
  const classes = opts.classes ?? DEFAULT_FIX_CLASSES;
  const pushEmptyCommitImpl = opts.pushEmptyCommit ?? gitPushEmptyCommit;
  const isMergedByNumber = opts.isMergedByNumber ?? ((n) => ghLiveStateByNumber(owner, repo, n) === "MERGED");
  const fixMergeShas = new Map<number, string | undefined>();
  const fixInHead = opts.fixInHead ?? (async (pr: OpenPrView, cls: FixClass): Promise<boolean | undefined> => {
    if (!/^[a-f0-9]{40}$/i.test(pr.headSha ?? "")) return undefined;
    try {
      if (!fixMergeShas.has(cls.fixPrNumber)) {
        const fix = await ghJsonAsync(["pr", "view", String(cls.fixPrNumber), "--repo", `${owner}/${repo}`, "--json", "state,mergeCommit"]) as {
          state?: string; mergeCommit?: { oid?: string };
        };
        const sha = fix.state === "MERGED" ? fix.mergeCommit?.oid : undefined;
        fixMergeShas.set(cls.fixPrNumber, sha && /^[a-f0-9]{40}$/i.test(sha) ? sha : undefined);
      }
      const fixSha = fixMergeShas.get(cls.fixPrNumber);
      if (!fixSha) return undefined;
      const comparison = await ghJsonAsync(["api", `repos/${owner}/${repo}/compare/${fixSha}...${pr.headSha}?per_page=1`]) as {
        status?: string; base_commit?: { sha?: string }; merge_base_commit?: { sha?: string };
      };
      const mergeBase = comparison.merge_base_commit?.sha;
      if (comparison.base_commit?.sha !== fixSha || !mergeBase || !/^[a-f0-9]{40}$/i.test(mergeBase)) return undefined;
      if ((comparison.status === "ahead" || comparison.status === "identical") && mergeBase === fixSha) return true;
      if ((comparison.status === "behind" || comparison.status === "diverged") && mergeBase !== fixSha) return false;
      return undefined;
    } catch (error) {
      log("sweep.post_fix_ancestry_unavailable", { pr_number: pr.prNumber, fix_pr_number: cls.fixPrNumber, error: String(error) });
      return undefined;
    }
  });
  // W1-T977: the rung's own read for a PR still pending — see `PostFixReverificationDeps.
  // readCiFailures`'s own doc (sweep.ts) for why the shared `OpenPrView.ciFailures` snapshot is
  // undefined for exactly this case. Mirrors the `fetchCiFailures` dep already wired below (line
  // ~16332) for the ci-log fix mode: same `gh pr view --json statusCheckRollup` read, same
  // `fetchCiFailures(owner, repo, ...)` leaf, just keyed off this rung's own PR argument instead
  // of a bare `prUrl` string.
  const readCiFailuresImpl =
    opts.readCiFailures ??
    (async (pr: OpenPrView) => {
      const v = ghJson(["pr", "view", pr.prUrl, "--json", "statusCheckRollup"]) as {
        statusCheckRollup?: RollupCheck[];
      };
      return fetchCiFailuresAsync(owner, repo, v.statusCheckRollup);
    });

  const mergedFixPrNumbers = new Set<number>();
  for (const fixPrNumber of new Set(classes.map((c) => c.fixPrNumber))) {
    if (isMergedByNumber(fixPrNumber)) mergedFixPrNumbers.add(fixPrNumber);
  }

  return runPostFixReverification(
    openPrs,
    mergedFixPrNumbers,
    {
      // W1-T474 rationale (8): the effect the ABSENT remedy already ships, reused verbatim rather
      // than a new outward path — an empty commit on the PR's OWN branch (never --force, never a
      // rebase, per src/lib/sweep.ts's own house rule). No settled `fresh` view is returned: a
      // push cannot observe GitHub's own re-derived checks/review synchronously, so (design note
      // ii, sweep.ts) this pass records the redrive and stops — the next ordinary sweep re-derives
      // the disposition once the fresh head's state has actually landed.
      redrive: (pr, cls) => {
        if (!pr.headRefName) return {};
        pushEmptyCommitImpl(
          repoRoot,
          pr.headRefName,
          pr.headSha,
          `chore(ci): re-trigger checks on #${pr.prNumber}\n\n` +
            `${cls.description}\n\nThe fix (#${cls.fixPrNumber}) has merged since this head was tested; this\n` +
            `empty commit mints a fresh head sha so the required checks recompute against CURRENT\n` +
            `main. Automated by the post-fix re-verification rung (W1-T474/W1-T124).`,
        );
        return {};
      },
      fixInHead,
      readCiFailures: readCiFailuresImpl,
      ledgerPath,
      runId,
      log,
      dryRun: opts.dryRun,
    },
    classes,
  );
}

/**
 * W1-T320's PER-POLL rung for the tmp-dir backstop (design clause ii) — rides the daemon's
 * poll cadence the same way `runWorktreeReapRung` (worker.ts) does, so the 26,711-dir ENOSPC
 * backstop (src/lib/tmp.ts's `sweepStaleTempDirs`) actually re-fires on a long-running healthy
 * daemon instead of only once at boot ('removed: 0, kept: 49979' on ten straight boots was the
 * boot-only cadence's failure mode: a healthy daemon between boots never re-ran it at all).
 *
 * `opts.maxAgeMs` is the caller's resolved policy value — the real command threads
 * `policy.values.sweep.tmpMaxAgeMs`, off the SAME repoRoot-scoped `policy` load
 * pollIntervalMs/the headroom curve already use (see `buildSweepHook`'s `tmpMaxAgeMs` param),
 * never a second, independent policy read here (test/config-reader-seams.test.ts's structural
 * check pins every unredirectable `loadPolicy`/`loadDefaultPolicy` call site by name — this rung
 * deliberately stays off that list by taking the value in, not reading it). Omitted ⇒
 * `sweepStaleTempDirs`'s own default (`DEFAULT_TEMP_SWEEP_MAX_AGE_MS`) applies, same as before
 * this task for any caller that predates it.
 *
 * Logs `daemon.tmp_sweep` with removed/kept COUNTS plus the oldest-kept age in ms (design
 * clause iii), so "kept 0 because nothing qualified" reads differently from "kept N and the
 * oldest is already close to the ceiling" — the boot-only line carried neither signal.
 * Best-effort: `sweepStaleTempDirs` itself never throws, but this wrapper still degrades to a
 * logged error rather than ever escaping into the sweep composite around it.
 */
/**
 * THE PER-POLL RUNG FOR THE IN-FLIGHT LOCK SWEEP — the exact shape W1-T320 gave the tmp-dir
 * backstop in {@link runTmpSweepRung} below, applied to the same boot-only cadence bug in
 * `sweepStaleInflightLocks` (lib/inflight-lock.ts).
 *
 * THE HOLE THIS CLOSES. That sweep is wired ONCE, in `daemonCommand`'s boot rung list, and its
 * own doc explains why a stale lock otherwise never clears: a lock is reclaimed by the NEXT
 * acquire of that same task, so a task that is never re-dispatched — circuit-broken, blocked,
 * withdrawn — keeps a dead holder's lock until the daemon happens to restart. The observed case
 * in that doc (`W1-T1.lock`, pid 65304, dead two days) is exactly that population. Riding the
 * daemon's poll cadence means a healthy long-lived daemon clears it without needing a restart,
 * which is the same failure mode W1-T320 recorded for tmp dirs ("a healthy daemon between boots
 * never re-ran it at all").
 *
 * IT MATTERS MORE NOW THAN IT DID. `deriveStatus` reads these locks as its third liveness
 * disjunct (see DeriveDeps.inflightHolder, lib/status.ts). A stale lock is still refused there —
 * the pid probe is what refuses it — but a lock left lying around is a standing invitation for a
 * recycled pid to make a dead run read as live, and `kern.maxproc` is 4000 on this host. Sweeping
 * on the poll cadence shrinks that window from "until the next daemon restart" to one poll.
 *
 * Logs `daemon.inflight_sweep` with reaped/kept COUNTS plus the reaped task ids (bounded), so
 * "kept 0 because nothing was held" reads differently from "kept N live holders". Best-effort:
 * degrades to a logged error rather than escaping into the sweep composite around it, the same
 * discipline as the reap and tmp rungs it sits beside.
 */
export function runInflightLockSweepRung(
  config: Config,
  log: (step: string, extra?: Record<string, unknown>) => void,
): InflightSweepResult {
  try {
    const inflightDir = join(config.root, "state", "inflight");
    const results = [inflightDir, join(inflightDir, "review-workers")]
      .map((dir) => sweepInflightLocksWithReceipts(dir, ledgerPathFor(config)));
    const swept = { reaped: results.flatMap((r) => r.reaped), kept: results.flatMap((r) => r.kept),
      live: results.flatMap((r) => r.live), unverifiableForeignHost: results.flatMap((r) => r.unverifiableForeignHost) };
    // `kept` alone conflates a confirmed-live holder with an unverifiable-foreign-host one
    // (W1-T461) — the per-poll site the boot sweep's own doc calls out as the one that must not
    // stay silent (design clause iii), so `live`/`unverifiable_foreign_host` ride the same line.
    log("daemon.inflight_sweep", {
      reaped: swept.reaped.length,
      kept: swept.kept.length,
      live: swept.live.length,
      unverifiable_foreign_host: swept.unverifiableForeignHost.length,
      reaped_ids: swept.reaped.slice(0, 10),
    });
    return swept;
  } catch (e) {
    log("daemon.inflight_sweep", { error: String((e as Error)?.message ?? e) });
    return { reaped: [], kept: [], live: [], unverifiableForeignHost: [] };
  }
}

export function orphanWorkerKillLedger(ledgerPath: string): OrphanSweepDeps["ledger"] {
  return (line) => {
    appendLedger(ledgerPath, {
      run_id: line.run_id,
      task_id: line.task_id,
      worker_scope: line.worker_scope,
      step: "worker_orphan_killed",
      pid: line.pid,
      cmdline: line.cmdline,
    });
    receiptOrphanedAssignments({ runId: line.run_id, taskId: line.task_id, detectedBy: "orphan-process-sweep" }, ledgerPath);
  };
}

/**
 * W1-T436 — the weekly feedback docket's rung. Gathers the five human-feedback capture
 * surfaces (reframes, operator verdicts/steering notes, rejected-feedback reasons, question
 * answers, operator notes) over a rolling 7-day lookback via {@link buildFeedbackDocket} (the
 * ONE named deterministic gather, no LLM), then {@link synthesizeFeedbackDocketProposal} drafts
 * AT MOST ONE candidate and this rung files it through `updateProposalRegistry` — the SAME
 * W1-T240 single-writer helper, so the SAME NEEDS-ME/APPROVE/REFRAME console path and the SAME
 * `approveCommand` ratification pipeline (branch, plan PR, CI, review, auto-merge arm) every
 * other proposal already rides (design iii): ratified IN-CONSOLE, the plan PR opened and
 * auto-merged by the harness afterwards, the operator never on GitHub.
 *
 * NEVER TWICE PER WEEK: {@link feedbackDocketDue} gates on a rolling-7-day marker
 * (`state/last-feedback-docket.json`) so a 300s poll cadence does not re-fire the gather every
 * tick — the same idempotence discipline `auto-triage.ts`'s marker applies to its own rung.
 * EMPTY WINDOWS FILE NOTHING: `docket.empty` is ledgered and no proposal is filed — "a loop
 * that must emit weekly manufactures drift; the no-op path is first-class" (design). Own
 * try/catch: a read failure here must never take down the sweep composite it rides inside.
 */
/**
 * The two ledger-derived docket surfaces, as the JSON substring their `step` field occupies.
 * `resolveLedgerUnion` greps the WHOLE raw line, so this pre-filters the corpus to candidate rows
 * before anything is parsed — the same shape `rule-efficacy.ts` builds for the same reader.
 */
const DOCKET_LEDGER_STEPS = /"step":"(?:ratify\.reframed|operator_feedback)"/;

/**
 * W1-T1273 — the docket's ledger corpus: EVERY rotation plus the live file, not the live file alone.
 *
 * `rotateLedger` keeps only `MAX_RETAINED_LINES_PER_STEP` newest rows per step in
 * `state/ledger.ndjson` and archives the rest, so the previous `readLedgerLines(ledgerPath)` read
 * a sliver: any `ratify.reframed` or `operator_feedback` row old enough to have rotated was
 * invisible to the weekly gather. Two of the five capture surfaces are fed from here, and
 * `counts_by_source` — the per-surface number an operator reads to decide whether a channel is
 * alive — is produced by this read. A narrow read does not report "narrow"; it reports ZERO,
 * which is indistinguishable from a channel nobody used.
 *
 * DEGRADES TO THE LIVE FILE, NEVER TO ZERO. `resolveLedgerUnion` refuses a corpus it cannot fully
 * enumerate (`requireArchives`, `refuseIncomplete`) — including the honest fresh-host case with no
 * `.gz` at all. Refusing must not be read as "no feedback": on `ok === false` this falls back to
 * exactly the previous behaviour and NAMES the degradation in its own ledger row, so a narrow read
 * is legible as narrow instead of arriving as five zeros. Strictly wider than before on every
 * path; never blank.
 */
export function readDocketLedgerCorpus(
  ledgerPath: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  // W1-T1273: the union reader, injectable and APPENDED LAST so no positional caller shifts. The
  // real `resolveLedgerUnion` is defensive to the point of never throwing for any corpus a test can
  // build on disk — an absent state dir and a state dir that is really a FILE both return
  // `ok: false` rather than raising. The catch arm below is therefore unreachable through the
  // filesystem, and an unreachable catch that swallows a degradation is exactly the arm this repo
  // has shipped uncovered before. This seam exists so ONE test can drive it; every other test runs
  // the real default.
  deps: { resolve?: typeof resolveLedgerUnion } = {},
): Array<Record<string, unknown>> {
  const resolve = deps.resolve ?? resolveLedgerUnion;
  const liveOnly = (reason: string, extra: Record<string, unknown> = {}): Array<Record<string, unknown>> => {
    log("feedback_docket.corpus_degraded", { reason, live_only: true, ...extra });
    return [...readLedgerLines(ledgerPath)];
  };
  let union: ReturnType<typeof resolveLedgerUnion>;
  try {
    union = resolve(dirname(ledgerPath), DOCKET_LEDGER_STEPS);
  } catch (e) {
    // DELIBERATE, AND IT IS THE WHOLE POINT OF THE UNION BEING BEST-EFFORT: an unreadable archive
    // must not cost the docket the rows it CAN see. Degrade to the live sliver and carry the
    // reason, so the caller reports a narrowed corpus rather than an empty one — and never a
    // silently narrowed one, which is the shape this rung was filed to remove.
    return liveOnly(String((e as Error)?.message ?? e));
  }
  if (!union.ok) {
    return liveOnly("union refused this corpus", { archive_count: union.archiveCount, unread: union.unread });
  }
  const rows: Array<Record<string, unknown>> = [];
  let torn = 0;
  for (const raw of union.matches) {
    try {
      rows.push(JSON.parse(raw) as Record<string, unknown>);
    } catch {
      // DELIBERATE: one malformed row is not a malformed corpus. A rotation truncated mid-write
      // leaves exactly one torn line, and throwing here would discard every well-formed row
      // beside it. Counted rather than swallowed — `torn` is reported, so the narrowing stays
      // visible to whoever reads the docket.
      torn++;
    }
  }
  log("feedback_docket.corpus", {
    source: "union",
    archive_count: union.archiveCount,
    live_file_read: union.liveFileRead,
    rows: rows.length,
    torn,
  });
  return rows;
}

export function runFeedbackDocketRung(
  config: Config,
  ledgerPath: string,
  runId: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  deps: { root?: string; noteStore?: OperatorNoteStore; repository?: string; now?: () => Date; synthesize?: typeof synthesizeFeedbackDocketProposal } = {},
): { fired: boolean } {
  const root = deps.root ?? repoRoot;
  const synthesize = deps.synthesize ?? synthesizeFeedbackDocketProposal;
  try {
    const now = deps.now?.() ?? new Date();
    const markerPath = join(config.root, "state", "last-feedback-docket.json");
    const marker = readFeedbackDocketMarker(markerPath);
    if (!feedbackDocketDue(marker, now)) {
      return { fired: false };
    }

    const window = feedbackDocketLookbackWindow(now);
    const ledgerLines = readDocketLedgerCorpus(ledgerPath, log);
    const rejectedFeedback = listFeedback(root, { status: "rejected" }).map((e) => ({ id: e.id, ts: e.ts, raw: e.raw }));
    const questionLines = readQuestionsNdjson(root);
    const noteStore = Object.hasOwn(deps, "noteStore") ? deps.noteStore :
      deps.root && !deps.repository ? root : configuredOperatorNoteStore(config, deps.repository, root);
    const operatorNotes = loadOperatorNoteRows(noteStore)
      .filter((n) => typeof n.note === "string" && typeof n.taskId === "string" && typeof n.ts === "string")
      .map((n) => ({ ts: n.ts as string, taskId: n.taskId as string, note: n.note as string }));

    const docket = buildFeedbackDocket({ ledgerLines, rejectedFeedback, questionLines, operatorNotes, window });
    if (docket.items.length === 0) {
      // Recorded before returning, deliberately — mirrors auto-triage's "record the fire first"
      // discipline while retaining the per-surface counts doctor judges after ledger rotation.
      writeFeedbackDocketMarker(markerPath, feedbackDocketMarkerWithFire(markerPath, now, "feedback_docket.empty", docket));
      log("feedback_docket.empty", { window, counts_by_source: docket.countsBySource });
      return { fired: false };
    }

    const result = synthesize(docket);
    if (result.kind === "empty") {
      writeFeedbackDocketMarker(markerPath, feedbackDocketMarkerWithFire(markerPath, now, "feedback_docket.empty", docket));
      log("feedback_docket.empty", { window, counts_by_source: docket.countsBySource });
      return { fired: false };
    }

    writeFeedbackDocketMarker(markerPath, feedbackDocketMarkerWithFire(markerPath, now, "feedback_docket.published", docket));
    const registryPath = join(config.root, "state", "inbox-proposals.json");
    let filed = false;
    updateProposalRegistry(registryPath, (current) => {
      if (current.some((p) => p.id === result.candidate.id)) return null; // already filed this cycle
      filed = true;
      const proposal: Proposal = {
        id: result.candidate.id,
        summary: result.candidate.summary,
        evidenceAnchors: result.candidate.evidenceAnchors,
      };
      return [...current, proposal];
    });

    log(filed ? "feedback_docket.published" : "feedback_docket.duplicate", {
      run_id: runId,
      proposal_id: result.candidate.id,
      referent: result.referent,
      consumed_count: result.consumed.length,
      window,
    });
    return { fired: filed };
  } catch (e) {
    log("feedback_docket.error", { error: String((e as Error)?.message ?? e) });
    return { fired: false };
  }
}

function readFeedbackDocketMarkerJson(path: string): unknown {
  if (!existsSync(path)) return undefined;
  try {
    return JSON.parse(readFileSync(path, "utf8")) as unknown;
  } catch {
    return undefined;
  }
}

function feedbackDocketMarkerWithFire(
  markerPath: string,
  now: Date,
  step: string,
  docket: FeedbackDocket,
): { lastFireIso: string; recentFires: CaptureSurfaceFireRecord[] } {
  const fire: CaptureSurfaceFireRecord = {
    ts: now.toISOString(),
    step,
    window: docket.window,
    counts_by_source: docket.countsBySource,
  };
  return {
    lastFireIso: now.toISOString(),
    recentFires: appendCaptureSurfaceFireHistory(readFeedbackDocketMarkerJson(markerPath), fire),
  };
}

export const MOUNT_RECOMMENDER_CADENCE_POLICY = {
  kind: "daily-ledger-evidence-accrual",
  intervalMs: 24 * 60 * 60 * 1000,
} as const;

function mountRecommenderCadenceMarkerPath(root: string): string {
  return join(root, "state", "last-mount-recommender.json");
}

function mountRecommenderNextFireMs(marker: ReturnType<typeof readFeedbackDocketMarker>): number | undefined {
  if (!marker) return undefined;
  const last = Date.parse(marker.lastFireIso);
  if (Number.isNaN(last)) return undefined;
  return last + MOUNT_RECOMMENDER_CADENCE_POLICY.intervalMs;
}

/**
 * W1-T2575 — the missing RECOMMENDATION leg (MASTER-PLAN §9, WS-8). `scripts/mount-headroom-
 * sweep.mjs` (W1-T2560, extended W1-T2574) already MEASURES: it groups retained ledger runs into
 * (type, risk, class) cells and, within each, into (provider, served_model, effort) arms — a
 * printed table a human had to read and act on, with nothing that turned it into a decision. This
 * rung is that missing leg: it reads the sweep's own `cells` via a dynamic import (the script
 * sits outside tsconfig's `include`, the SAME "dynamic import at the call site, cast to an
 * explicit shape" discipline `test/a-mount-comparison-across-unmatched-populations-is-not-a-
 * measurement.test.ts` already established for consuming it from typed code), hands them to
 * {@link recommendMounts} (lib/mount-recommender.ts) alongside the CURRENTLY LOADED
 * `.remudero/mounts.yaml` table (so the Tier Invariant, G-17, is checked against what is actually
 * committed), and files every cleared recommendation through `updateProposalRegistry` — the SAME
 * W1-T240 single-writer the feedback-docket rung immediately above uses, idempotent by
 * `mountRecommendationProposalId` so a re-poll before ratification never duplicates. A REFUSAL
 * (the expected, common outcome — see mount-recommender.ts's own header, "refuse more often than
 * recommend") is counted and logged, never filed: it asserts nothing an inbox proposal could
 * ratify. `recommendMounts` and `mountRecommendationProposalCandidate` are BOTH pure (no I/O,
 * mutate no routing table) — every read (the ledger corpus, `mounts.yaml`) and every write (the
 * proposal registry) happens here, in this rung, exactly once. Own try/catch: an empty/missing
 * ledger corpus (`buildMountHeadroomSweep` throws on zero runs) or a malformed `mounts.yaml` must
 * never take down the sweep composite this rides inside, same discipline as every other rung on
 * this cadence.
 */
export async function runMountRecommenderRung(
  config: Config,
  runId: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  deps: {
    root?: string;
    env?: NodeJS.ProcessEnv;
    clock?: Clock;
    buildMountHeadroomSweep?: (stateDir: string) => { cells: MountHeadroomCell[] };
  } = {},
): Promise<{ filed: number; refused: number }> {
  const root = deps.root ?? repoRoot;
  try {
    const now = (deps.clock ?? systemClock).date();
    const stateDir = join(config.root, "state");
    const markerPath = mountRecommenderCadenceMarkerPath(config.root);
    const marker = readFeedbackDocketMarker(markerPath);
    const nextFireMs = mountRecommenderNextFireMs(marker);
    if (nextFireMs !== undefined && now.getTime() < nextFireMs) {
      log("mount_recommendation.skipped", {
        run_id: runId,
        cadence_kind: MOUNT_RECOMMENDER_CADENCE_POLICY.kind,
        interval_ms: MOUNT_RECOMMENDER_CADENCE_POLICY.intervalMs,
        last_fire_iso: marker?.lastFireIso,
        next_fire_iso: new Date(nextFireMs).toISOString(),
      });
      return { filed: 0, refused: 0 };
    }
    writeFeedbackDocketMarker(markerPath, { lastFireIso: now.toISOString() });

    let buildMountHeadroomSweep = deps.buildMountHeadroomSweep;
    if (!buildMountHeadroomSweep) {
      const scriptUrl = pathToFileURL(join(root, "scripts", "mount-headroom-sweep.mjs")).href;
      ({ buildMountHeadroomSweep } = (await import(scriptUrl)) as {
        buildMountHeadroomSweep: (stateDir: string) => { cells: MountHeadroomCell[] };
      });
    }
    const sweep = buildMountHeadroomSweep(stateDir);
    const mounts = loadMounts(mountsPath(root));
    // Derive the objective from the SAME sanctioned environment boundary a real worker crosses:
    // API only when config opts in AND the key is materially present; otherwise subscription.
    // Only key names reach `billingMode`, and neither names nor values are retained below.
    const materialWorkerEnv = buildWorkerEnv({}, deps.env ?? process.env, {
      allowApiKey: config.overflow === "api_key",
    });
    const materialBillingMode = billingMode(Object.keys(materialWorkerEnv));
    let objectiveFallbacks = 0;
    const outcomes = recommendMounts(sweep.cells, mounts, {
      billingMode: materialBillingMode,
      warn: (message) => {
        objectiveFallbacks++;
        log("mount_recommendation.objective_fallback", { run_id: runId, detail: message.slice(0, 500) });
      },
    });

    const registryPath = join(config.root, "state", "inbox-proposals.json");
    let filed = 0;
    let refused = 0;
    for (const outcome of outcomes) {
      if (outcome.kind === "refusal") {
        refused++;
        continue;
      }
      const candidate = mountRecommendationProposalCandidate(outcome);
      updateProposalRegistry(registryPath, (current) => {
        if (current.some((p) => p.id === candidate.id)) return null; // already filed, idempotent
        filed++;
        const proposal: Proposal = { id: candidate.id, summary: candidate.summary, evidenceAnchors: candidate.evidenceAnchors };
        return [...current, proposal];
      });
    }

    log("mount_recommendation.swept", {
      run_id: runId,
      filed,
      refused,
      cells: sweep.cells.length,
      billing_mode: billingMode(Object.keys(materialWorkerEnv)),
      objective_fallbacks: objectiveFallbacks,
    });
    return { filed, refused };
  } catch (e) {
    log("mount_recommendation.error", { error: String((e as Error)?.message ?? e) });
    return { filed: 0, refused: 0 };
  }
}

/**
 * The daemon's per-poll WORKER-TAIL retention rung (W1-T942 design note v) — ages out stale
 * `<config.root>/state/runs/*.tail` files via {@link sweepStaleWorkerTails}, on the SAME
 * per-poll cadence `runWorktreeReapRung`/`runInflightLockSweepRung`/`runTmpSweepRung` already
 * ride (see `buildSweepHook`'s call site). Own try/catch so a sweep hiccup never masks — or is
 * masked by — the rungs around it, the same discipline every sibling rung in this file follows.
 */
export function runWorkerTailSweepRung(config: Config, log: (step: string, extra?: Record<string, unknown>) => void): void {
  try {
    const swept = sweepStaleWorkerTails(config.root);
    if (swept.removed.length > 0) log("daemon.worker_tail_sweep", { removed: swept.removed.length });
  } catch (e) {
    log("daemon.worker_tail_sweep", { error: String((e as Error)?.message ?? e) });
  }
}

export function runTmpSweepRung(
  log: (step: string, extra?: Record<string, unknown>) => void,
  opts: TempSweepOpts = {},
): TempSweepSummary {
  try {
    const swept = sweepStaleTempDirs(opts);
    log("daemon.tmp_sweep", {
      removed: swept.removed.length,
      kept: swept.kept.length,
      oldest_kept_age_ms: swept.oldestKeptAgeMs,
    });
    return swept;
  } catch (e) {
    log("daemon.tmp_sweep", { error: String((e as Error)?.message ?? e) });
    return { removed: [], kept: [], oldestKeptAgeMs: null };
  }
}

/**
 * Automatic remote-branch cleanup for one target repository. The cheap branch-set read happens on
 * every full sweep, while the existing expensive classifier/pruner runs only on first use, a branch
 * set change, or the six-hour bound. This is deliberately on the full sweep path: the write is a
 * remote `git push --delete`, so the light in-flight pass must never reach it.
 *
 * The command remains the one classification authority. This adapter supplies the target checkout,
 * target GitHub owner/repo, daemon run id and quiet output; it never constructs a second delete
 * predicate. An unreadable or empty branch listing is a named refusal, never a healthy zero.
 */
export function runAutomaticBranchReapRung(
  owner: string,
  repo: string,
  config: Config,
  ledgerPath: string,
  runId: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  state: AutomaticBranchReapState,
  opts: {
    prune?: boolean;
    root?: string;
    clock?: Pick<Clock, "now">;
    intervalMs?: number;
    exec?: BranchReapExec;
    plan?: () => Plan | undefined;
  } = {},
): void | Promise<void> {
  const root = opts.root ?? (repo === resolveOwnerRepo().repo ? repoRoot : join(config.root, "repos", repo));
  const key = `${owner}/${repo}\0${root}`;
  if (automaticBranchReapsInFlight.has(key)) return;
  automaticBranchReapsInFlight.add(key);
  try {
    const pass = runStepsEager(automaticBranchReapSteps(owner, repo, config, ledgerPath, runId, log, state, { ...opts, root }));
    if (isPromiseLike(pass)) return Promise.resolve(pass).finally(() => automaticBranchReapsInFlight.delete(key));
  } catch (error) {
    automaticBranchReapsInFlight.delete(key);
    throw error;
  }
  automaticBranchReapsInFlight.delete(key);
}

const automaticBranchReapsInFlight = new Set<string>();

function* automaticBranchReapSteps(
  owner: string,
  repo: string,
  config: Config,
  ledgerPath: string,
  runId: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  state: AutomaticBranchReapState,
  opts: {
    prune?: boolean;
    root?: string;
    clock?: Pick<Clock, "now">;
    intervalMs?: number;
    exec?: BranchReapExec;
    plan?: () => Plan | undefined;
  } = {},
): Steps<void> {
  const checkoutRoot = opts.root ?? (repo === resolveOwnerRepo().repo ? repoRoot : join(config.root, "repos", repo));
  const exec = opts.exec ?? branchReapExec(checkoutRoot);
  let names: string[];
  try {
    names = yield* remoteBranchNamesSteps(exec);
  } catch (e) {
    log("branch_reap.sweep.failed", {
      outcome: "unreadable",
      reason: "remote branch listing failed",
      error: String((e as Error)?.message ?? e),
    });
    return;
  }
  if (names.length === 0) {
    log("branch_reap.sweep.failed", {
      outcome: "unreadable",
      reason: "remote branch listing was empty",
    });
    return;
  }

  const nowMs = (opts.clock ?? systemClock).now();
  const decision = decideAutomaticBranchReap(state, names, nowMs, opts.intervalMs);
  state.lastBranchFingerprint = decision.branchFingerprint;
  if (!decision.fire) return;
  state.lastRunAtMs = nowMs;

  log("branch_reap.sweep.started", {
    mode: opts.prune === false ? "dry-run" : "prune",
    reason: decision.reason,
    branch_count: names.length,
    repository: `${owner}/${repo}`,
  });
  let code = 1;
  let exitReason = "unnamed non-zero exit";
  try {
    code = yield* reapBranchesSteps(opts.prune === false ? [] : ["--prune"], {
      onExitReason: (why) => {
        exitReason = why;
      },
      root: checkoutRoot,
      ownerRepo: { owner, repo },
      exec,
      plan: opts.plan,
      ledgerPath,
      quiet: true,
      runId,
      creditLedgerPath: ledgerPath,
      // W1-T4476 design (iii)/(iv): the cache this state carries in from the LAST pass, and the
      // update this pass hands back — `state` is the one object the caller (buildSweepHook)
      // persists to disk right after this function returns, so the cache and the cadence fields
      // land in the same write.
      mergedHeadShaCache: state.mergedHeadShas ? new Map(Object.entries(state.mergedHeadShas)) : undefined,
      onMergedHeadCacheUpdate: (next) => {
        state.mergedHeadShas = next;
      },
      noPrHeadShaCache: state.noPrHeadShas ? new Map(Object.entries(state.noPrHeadShas)) : undefined,
      onNoPrHeadCacheUpdate: (next) => {
        state.noPrHeadShas = next;
      },
    });
  } catch (e) {
    log("branch_reap.sweep.failed", {
      outcome: "exception",
      reason: decision.reason,
      error: String((e as Error)?.message ?? e),
    });
    return;
  } finally {
    // The prune changed the remote branch set. Refresh the cheap fingerprint so the next ordinary
    // poll does not immediately spend another full REST classification on our own deletion.
    try {
      state.lastBranchFingerprint = branchNamesFingerprint(yield* remoteBranchNamesSteps(exec));
    } catch {
      // Keep the pre-pass fingerprint; a later poll will retry because the remote cannot be proved current.
    }
  }
  // `trigger` is why the pass RAN (the fleet pushes branches all day, so it is nearly always
  // branch-set-changed); `reason` is why it ended as it did — never the trigger read as a failure.
  log("branch_reap.sweep.completed", {
    outcome: code === 0 ? "ok" : "completed_with_drift_or_failure",
    code,
    trigger: decision.reason,
    reason: code === 0 ? "clean" : exitReason,
    repository: `${owner}/${repo}`,
  });
}

// ── WORKER STALL DETECTOR (W1-T943) ─────────────────────────────────────────────────────────
//
// W1-T942 produces `worker.state`; nothing judged it until now — the exact shape W1-T316/
// W1-T317/W1-T916 already paid for (a signal with no reader). LEVEL-TRIGGERED (design note i):
// reads the AGE of the newest `worker.state` row for each LIVE in-flight run (`liveInflightRuns`'s
// own pid-checked lock read — never a second, looser "in flight"), never an event the run itself
// must emit — a wedged, swapped, or dead-socket worker may never emit anything again, so a
// detector waiting for it to announce its own stall cannot fire in exactly the case it exists for.

/** Ledger step a worker-stall verdict rides — appended ONCE per quiet episode (design ii), never
 *  once per tick. */
export const WORKER_STALLED_LEDGER_STEP = "worker.stalled";

/** DEFAULT quiet threshold, mirrored from `plan/policy.yaml`'s `workerStall` row for a caller
 *  with no policy in hand (test fixtures, primarily) — production always threads the real
 *  `policy.values.workerStall` through {@link buildSweepHook} instead of relying on this. See
 *  that row's own comment for why 60 minutes is the default (design note v: comfortably above
 *  the ~16-minute `--ci-parity` suite W1-T463/W1-T465 measured). */
export const DEFAULT_WORKER_STALL_MS = 3_600_000;

/** One live in-flight run whose newest `worker.state` row has aged past the policy `workerStall`
 *  threshold, per {@link findStalledWorkers}. */
export interface WorkerStallCandidate {
  runId: string;
  taskId: string;
  /** ms of quiet since this run's newest `worker.state` transition. */
  quietMs: number;
  /** the run's newest recorded `worker.state` value, when one exists. */
  lastState: string | undefined;
}

/**
 * Pure judgement (design i/ii): which of `liveRuns` have gone quiet past `thresholdMs`, derived
 * from the AGE of each run's own newest `worker.state` ledger row — never a second, event-driven
 * definition of "stalled". A live run with NO `worker.state` row at all is skipped outright:
 * there is nothing whose age this can measure yet (the W1-T942 dependency's own shape — shipping
 * this detector before it would be a guard with no input, W1-T916's class of defect).
 *
 * DEDUP, ONE ROW PER QUIET EPISODE (design ii): a run is excluded when it already carries a
 * `worker.stalled` row NEWER than its own newest `worker.state` row — that quiet episode was
 * already reported and nothing has changed since. The moment the run speaks again (a fresh
 * `worker.state` transition postdating the last `worker.stalled` row), the comparison flips and
 * a LATER quiet stretch re-arms this check — never a per-tick re-fire, and never permanently
 * silenced either.
 *
 * Pure — no fs, no clock read of its own (`nowMs` is a parameter) — so the whole dedup/re-arm
 * shape is unit-testable against synthetic ledger lines with no file on disk at all
 * (test/worker-stall-detector.test.ts).
 */
export function findStalledWorkers(
  liveRuns: readonly Pick<LiveInflightRun, "runId" | "taskId">[],
  ledgerLines: ReadonlyArray<Record<string, unknown>>,
  thresholdMs: number,
  nowMs: number,
): WorkerStallCandidate[] {
  const out: WorkerStallCandidate[] = [];
  for (const run of liveRuns) {
    let lastStateTs: number | undefined;
    let lastState: string | undefined;
    let lastStalledTs: number | undefined;
    for (const line of ledgerLines) {
      if (line.run_id !== run.runId) continue;
      const ts = typeof line.ts === "string" ? Date.parse(line.ts) : NaN;
      if (!Number.isFinite(ts)) continue;
      if (line.step === WORKER_STATE_LEDGER_STEP && (lastStateTs === undefined || ts > lastStateTs)) {
        lastStateTs = ts;
        lastState = typeof line.state === "string" ? line.state : undefined;
      }
      if (line.step === WORKER_STALLED_LEDGER_STEP && (lastStalledTs === undefined || ts > lastStalledTs)) {
        lastStalledTs = ts;
      }
    }
    if (lastStateTs === undefined) continue; // nothing to measure yet (W1-T942 dependency)
    if (lastStalledTs !== undefined && lastStalledTs > lastStateTs) continue; // mid-episode — already reported
    const quietMs = nowMs - lastStateTs;
    if (quietMs < thresholdMs) continue;
    out.push({ runId: run.runId, taskId: run.taskId, quietMs, lastState });
  }
  return out;
}

/** Bound the worker-stall escalation's tail excerpt is capped to AT THE ATTACH SITE (design
 *  note iii: "a 2 MB issue body is its own outage") — deliberately TIGHTER than the tail FILE's
 *  own {@link WORKER_TAIL_MAX_LINES}/{@link WORKER_TAIL_MAX_BYTES} ceiling: an issue body is read
 *  by a human deciding "wedged or just busy", not grepped, and a shorter excerpt is already
 *  enough evidence for that judgment. */
export const WORKER_STALL_TAIL_ATTACH_MAX_LINES = 100;
export const WORKER_STALL_TAIL_ATTACH_MAX_BYTES = 8 * 1024;

/** Best-effort, never-throwing read of a run's live tail for the stall escalation's evidence
 *  attachment — the read-side mirror of {@link writeWorkerTailBestEffort}. An absent/unreadable
 *  tail degrades to an empty array: the escalation still fires — W1-T942's own tail write is
 *  best-effort too, and a missing tail must never block the ONLY thing this detector is allowed
 *  to do (tell someone, design note iv). */
function readWorkerTailBestEffort(tailPath: string): string[] {
  try {
    if (!existsSync(tailPath)) return [];
    return readFileSync(tailPath, "utf8")
      .split("\n")
      .filter((l) => l.length > 0);
  } catch {
    return [];
  }
}

/**
 * The daemon's per-poll WORKER-STALL rung (W1-T943) — appends `worker.stalled` ONCE per quiet
 * episode ({@link findStalledWorkers}) and escalates through the EXISTING §4 machinery
 * ({@link tryEscalate}), never a second one. NEVER acts on the run itself (design iv): no kill,
 * no signal, no dispatch deferral, no strike, no budget change — appending a ledger row and
 * filing/deduping an issue are the only two things this function does, full stop. Rides the SAME
 * per-poll cadence `runWorktreeReapRung`/`runInflightLockSweepRung`/`runWorkerTailSweepRung`
 * already occupy (see `buildSweepHook`'s call site) — own try/catch so a hiccup here never masks,
 * or is masked by, the rungs around it.
 */
export function runWorkerStallDetectorRung(
  owner: string,
  repo: string,
  config: Config,
  ledgerPath: string,
  runId: string,
  thresholdMs: number,
  log: (step: string, extra?: Record<string, unknown>) => void,
  issues?: IssueGateway,
  // Injectable clock (tests) — same discipline as sweepStaleWorkerTails'/DaemonDeps' own `now`,
  // so the age comparison + the episode-boundary re-arm are provable without a real wall-clock
  // wait (Rule 18). Omitted ⇒ the real wall clock, unchanged production behavior.
  now: () => number = Date.now,
): void {
  try {
    const inflightDir = join(config.root, "state", "inflight");
    const liveRuns = liveInflightRuns(inflightDir);
    if (liveRuns.length === 0) return;
    const ledgerLines = readLedgerLines(ledgerPath);
    const stalled = findStalledWorkers(liveRuns, ledgerLines, thresholdMs, now());
    for (const candidate of stalled) {
      const quietMinutes = Math.round(candidate.quietMs / 60_000);
      // Ledgered BEFORE the escalation call, mirroring escalateCircuitBreak/
      // escalateLifetimeCapExceeded's "the dedup marker is written whether or not delivery
      // succeeds" discipline — the row IS the dedup key `findStalledWorkers` reads back next
      // tick, so a `gh` failure below must never leave this episode un-marked and re-firing on
      // the very next poll.
      appendLedger(ledgerPath, {
        run_id: candidate.runId,
        task_id: candidate.taskId,
        step: WORKER_STALLED_LEDGER_STEP,
        quiet_ms: candidate.quietMs,
        last_state: candidate.lastState ?? null,
      });
      const tailPath = join(config.root, "state", "runs", `${candidate.runId}.tail`);
      const tail = capWorkerTailLines(
        readWorkerTailBestEffort(tailPath),
        WORKER_STALL_TAIL_ATTACH_MAX_LINES,
        WORKER_STALL_TAIL_ATTACH_MAX_BYTES,
      ).join("\n");
      const issueUrl = tryEscalate(
        {
          class: "BLOCKED",
          taskId: candidate.taskId,
          // The STALLED run's own id — the evidence an operator needs to act on "stop this run"
          // — never the daemon's own coordinating run id (see EscalateDeps.runId below for that).
          runId: candidate.runId,
          summary: `${candidate.taskId}: worker run ${candidate.runId} has said nothing for ${quietMinutes} min`,
          detail:
            `W1-T943: run ${candidate.runId} (task ${candidate.taskId}) has produced no \`worker.state\` ` +
            `transition for ${quietMinutes} minute(s) — past the policy \`workerStall\` threshold. This can be ` +
            `a genuinely wedged worker OR a long healthy step the fixed threshold misjudged: never auto-killed ` +
            `either way (design note iv) — the operator, or a future paramedic verb, decides. Last recorded ` +
            `state: ${candidate.lastState ?? "unknown"}.\n\n` +
            `Last tail lines from this run:\n\`\`\`\n${tail || "(no tail captured)"}\n\`\`\``,
          options: [
            {
              label: "leave it running",
              detail:
                "Take no action. A long but legitimate step (a full local suite, a slow spawn) can look " +
                "identical to a wedge from the outside — silence alone is not proof.",
            },
            {
              label: "stop this run",
              detail: `Interrupt run ${candidate.runId} yourself and let the fleet redispatch ${candidate.taskId} fresh — this detector never does so itself.`,
            },
          ],
          recommendation: "leave it running",
        },
        // `runId` HERE is the escalating daemon's OWN run — the escalation-machinery dedup/
        // failure-ledger actor, distinct from `e.runId` (the stalled run) immediately above.
        { issues: issues ?? ghIssueGateway(owner, repo), ledgerPath, runId },
      );
      log("daemon.worker_stall", {
        run_id: candidate.runId,
        task_id: candidate.taskId,
        quiet_ms: candidate.quietMs,
        issue_url: issueUrl,
      });
    }
  } catch (e) {
    log("daemon.worker_stall", { error: String((e as Error)?.message ?? e) });
  }
}

/**
 * The daemon's per-iteration sweep hook (acceptance 4: the SAME runSweep the CLI
 * uses). Best-effort by the DaemonDeps.sweep contract — swallows its own errors so
 * a sweep hiccup never halts the scheduler loop.
 *
 * `tmpMaxAgeMs` (W1-T320): the resolved `policy.values.sweep.tmpMaxAgeMs` the real daemon
 * command threads through to {@link runTmpSweepRung} below — optional and trailing so every
 * existing caller (tests included) that predates W1-T320 is unaffected; omitted ⇒
 * `sweepStaleTempDirs`'s own default (`DEFAULT_TEMP_SWEEP_MAX_AGE_MS`) applies.
 */
export function buildSweepHook(
  owner: string,
  repo: string,
  config: Config,
  ledgerPath: string,
  runId: string,
  bootPlan: Plan,
  log: (step: string, extra?: Record<string, unknown>) => void,
  tmpMaxAgeMs?: number,
  // Injectable board gateway — appended LAST so no positional caller shifts, the same convention
  // `buildSweepEffects`' own trailing seams follow. Real callers omit it and get the warm
  // once-per-daemon-start instance built immediately below; a test supplies one with its own
  // `exec`/`ttlMs` so the delta's request count is measurable without shelling out.
  github?: GitHub,
  // W1-T468: paces this poll's three-way burst (this hook's own sweep enumeration plus the board
  // gateway's PR/issue reads below) — trailing and optional so every existing call site (every
  // test included) is unaffected; omitted ⇒ no pacing, exactly the pre-W1-T468 behavior. The
  // daemon's real (non-test) wiring is the only caller that constructs and passes one.
  pacer?: GhCallPacer,
  // W1-T943: the resolved `policy.values.workerStall` the real daemon command threads through to
  // {@link runWorkerStallDetectorRung} below — optional and trailing so every existing caller
  // (tests included) that predates W1-T943 is unaffected; omitted ⇒ {@link DEFAULT_WORKER_STALL_MS}.
  workerStallMs?: number,
  // W1-T2683: main's own rollup observer, supplied only by the real daemon wiring. Trailing and
  // optional so offline callers gain no network I/O. Its own boundary below preserves PR sweep
  // liveness even when a test injection or future implementation accidentally throws.
  mainHealthRung?: () => Promise<void>,
  snapshotCache?: BoardSnapshotCache,
  // W1-T3581 and W1-T3585 independently appended optional positional seams here. Preserve both
  // already-shipped call shapes: a recovery object first (then isMerged/readMainPlan), or the
  // earlier isMerged/readMainPlan pair. The discriminator is structural and fail-closed: a merged
  // resolver is a function, while reviewer provenance is an object.
  reviewerCodeRecoveryOrIsMerged?: SweepDeps["reviewerCodeRecovery"] | MergedResolver,
  isMergedOrReadMainPlan?: MergedResolver | ((root: string) => Plan),
  readMainPlan?: (root: string) => Plan,
  // W1-T448: the daemon already resolved the managed checkout for this exact owner/repo. Keep
  // that path explicit so same-named repositories under different owners cannot reap this repo's
  // origin by accident.
  targetCheckoutRoot?: string,
  planAccessor?: () => Plan,
  // W1-T4471: the owner-reply reader's gateway. Omitted ⇒ that rung is skipped, so a fixture
  // never reaches GitHub; only the daemon's composition root passes the real one.
  escalationAnswerGateway?: EscalationAnswerGateway,
  // W1-T5115: the daemon's git credential socket. Omitted ⇒ fix workers keep the ambient helper.
  gitCredentialSocketPath?: string,
  // W1-T7734: `servedPublishedAtMs` is when the generation these facts came from was published.
  tickReadFor?: () => (TickReadFacts & { servedPublishedAtMs?: number }) | undefined |
    Promise<(TickReadFacts & { servedPublishedAtMs?: number }) | undefined>,
  escalationFeedbackReply?: Pick<PanelGraphDeps, "root" | "inboxRoot" | "feedbackLand">,
): (continueReviewAdmissions?: ReviewAdmissionGate) => Promise<SweepCycleOutcome | void> {
  /* Legacy source-text landmarks; executable wiring lives in cli/commands/sweep.ts (W1-T9338).
  const boardGithub = github ?? buildBatchedGithub(owner, repo, { log, pacer });
  const draftHook = buildInboxDraftHook(owner, repo, config, runId, log);
  const planFilingFileCache = createPlanFilingFileCache();
  return async (continueReviewAdmissions = () => true) => {
    buildOpenPrViewsAsync(owner, repo, ledgerPath, { planFilingFileCache, pacer });
    const creditCandidates = buildCreditCandidates(owner, repo, plan, ledgerPath, log, boardGithub);
    runSweep(projectMergedTaskCandidates(prsForFixRung, creditCandidates), withFullSweepRepairAdmission({
      updatedForWorkflow,
      // W1-T2584: the callback reaches the sweep's review admission.
      continueReviewAdmissions,
    }), DEFAULT_SWEEP_POLICY);
    sweepEscalationReconcile(owner, repo, plan, ledgerPath, runId, log, { github: boardGithub, tickRead });
    runCreditBackfill(creditCandidates, { ledgerPath, runId, log });
    runAutomaticBranchReapRung(owner, repo, config, ledgerPath, runId, log, branchReapState);
  */
  return buildSweepHookFromModule(sweepCommandHost(), owner, repo, config, ledgerPath, runId, bootPlan, log, tmpMaxAgeMs, github, pacer, workerStallMs, mainHealthRung, snapshotCache, reviewerCodeRecoveryOrIsMerged, isMergedOrReadMainPlan, readMainPlan, targetCheckoutRoot, planAccessor, escalationAnswerGateway, gitCredentialSocketPath, tickReadFor, escalationFeedbackReply);
}

/**
 * W1-T254 (the #707 fix) — the daemon's RESTRICTED LIGHT-SWEEP hook, ticked by
 * `DaemonDeps.sweepLight` WHILE `runOne` is in flight (see daemon.ts's doc on
 * that field). Wires the SAME `buildOpenPrViews` + `buildSweepEffects` +
 * `runSweep` the full sweep hook above uses — never a second, independently
 * built reconciler — but passes `actionable: d => d === "post-review"` so
 * ONLY the deterministic, sha-pinned, mutex-serialized re-post can fire here;
 * close/escalate/depReview always stand down (arm: W1-T5922; capacity-gated
 * dispatchFix: W1-T8086, see `lightPassActionable`)
 * ("deferred to full sweep (light pass)") and re-derive on the next FULL
 * sweep instead, preserving the single-threaded reason those lanes exist
 * for. Deliberately excludes the credit-backfill rung and the inbox-draft
 * rung the full hook also runs — both are heavier, not concurrency-safe
 * alongside an in-flight `runOne`, and unrelated to the #707 cadence gap
 * this ticker exists to close. Best-effort, own try/catch: a hiccup here
 * costs one logged tick, never the daemon's liveness (the daemon.ts caller
 * ALSO wraps this call — see `daemon.sweep_light.failed` — this inner catch
 * just names the failure distinctly on this module's own ledger step).
 *
 * W1-T463 — `runSweepLightPass`, NOT `runSweep`, over this pass's whole snapshot. The
 * diagnosis for "a PR sat 21-green and unreviewed for ~15 minutes despite a ticking light
 * sweep": `runSweep`'s own loop is sequential, and `postReview` below runs the REAL
 * `reviewCommand` (worktree materialize + every whitelisted proof), not a cheap status flip —
 * so one slow-to-judge PR used to block every OTHER post-review-eligible PR queued behind it in
 * the SAME tick, and `startInFlightTicker` (daemon.ts) does not schedule its next tick until
 * the whole pass resolves. `runSweepLightPass` (sweep.ts, see its own doc for the full
 * diagnosis) fires one `runSweep` call PER open PR, concurrently, so a fast PR is never starved
 * behind a slow one in the same pass — the SAME dedup/disposition/ledger path per PR, no second
 * lane, no new per-PR mutex (design (ii)/(iv): each PR is handed to exactly one call).
 */
/**
 * W1-T1211 — THE LEDGER STEP A RUN WRITES ONCE WHEN IT STARTS WAITING ON SOMETHING EXTERNAL.
 *
 * Emitted ONCE on entry to each wait loop, never per poll. That is the whole reason it exists
 * rather than reading `ci.polling`: the polling rows fire every fifth iteration for the life of the
 * wait (5,411 of them in the ledger union against 1,205 `fix.dispatch`), and `src/lib/ledger.ts`
 * names them "pure telemetry/polling noise … exactly the high-frequency, no-decision-consequence
 * lines that drove the measured growth". A decision cannot be built on a row the rotator is right
 * to shed, so this task writes a low-frequency one instead — see this task's own design note (i-a).
 */
export const AWAITING_EXTERNAL_LEDGER_STEP = "run.awaiting_external";

/**
 * W1-T1211 — WHAT THE LIGHT PASS MAY ACT ON THIS TICK.
 *
 * `buildSweepLightHook` wires `actionable` while `runOne` is in flight, and every lane except
 * `post-review` stands down as "deferred to full sweep (light pass)". The RESTRICTION's
 * justification is spend-and-capacity — `src/lib/sweep.ts` records 3 dispatch lanes + 3 review
 * lanes against a host measured to fit about four concurrent workers — and of those five lanes
 * ONLY `dispatchFix` spawns a worker. `close`, `escalate`, `depReview` and `arm` are API calls.
 *
 * So the blanket is wider than its reason for exactly one case: a run that is WAITING rather than
 * working. Measured (this task's shard): one lock held 41 minutes wrote 347 light passes and ZERO
 * full sweeps while `fix.dispatch` read zero for twenty-one hours.
 *
 * The other four lanes are DELIBERATELY UNCHANGED (design note iii) — widening the blanket further
 * is a separate argument this task does not make.
 */
export function lightPassActionable(
  disposition: Disposition,
  fixRungAllowed: boolean,
  // W1-T2430 — TRUE ONLY for `buildSweepLightHook`'s SECOND, narrower `runSweepLightPass` call,
  // over the subset `blockedFixableIsRequeueOnly` has already proven can never reach
  // `dispatchFix` (every `ciFailures` entry on that PR names a cancelled required check, so
  // `runSweep`'s own `blocked-fixable` case always breaks at its "cancelled required check(s)"
  // stand-down before it ever gets there — see that case's own comment in `src/lib/sweep.ts`).
  // Admitting here can therefore never widen the spend bound `fixRungAllowed` exists to
  // enforce: the lane's whole action is one `POST actions/jobs/{id}/rerun` (W1-T1223), which
  // spawns no worker. Every EXISTING caller passes 2 args and gets this function's original
  // 3-line shape back, byte-identical (W1-T1211) — this is an ADDITIVE 3rd parameter, not a
  // change to `fixRungAllowed`'s own meaning.
  requeueLaneOnly: boolean = false,
  // W1-T5922 — TRUE only on `buildSweepLightHook`'s ordinary pass. An arm is one GitHub call behind
  // the full sweep's own guards (decideSweepArm, the W1-T5403 risk judge, holds, dedups); it spawns
  // no worker. Default false, so every 2- and 3-argument caller keeps its original shape.
  armAllowed: boolean = false,
  // W1-T8086: the ordinary pass's repair lanes use the existing per-claim fix-capacity admission.
  // 2026-10-14: `conflicted` too, so a merge-conflict round no longer waits for the next full sweep.
  repairFixAllowed: boolean = false,
): boolean {
  // W1-T9558: all three review-lane dispositions; the cheap modes otherwise waited on a full pass.
  if (isReviewLaneDisposition(disposition)) return true;
  if (disposition === "mergeable") return armAllowed;
  // The two dispositions whose ACTION is `dispatchFix` — the only lane that spawns a worker. Both
  // take `runSweep`'s per-claim fix-capacity admission (`claimFixAdmission`, after the per-head
  // `claimFixDispatch` mutex) before they spawn, so on the ordinary pass that claim is the gate, not
  // W1-T1211's "every in-flight run is waiting" blanket. `blocked-fixable` also admits requeues.
  // MEASURED 2026-10-14 on the core ledger: 220 `conflicted` rows read "deferred to full sweep
  // (light pass)" against 7 that acted. Full passes finished a median 18.9 min apart (p90 44.5, max
  // 100), and #11604, #11679, #11689 and #11699 each waited 68-241 min for a conflict round that never
  // came. A refused claim names the capacity; a review-only pass still stands both lanes down.
  if (disposition === "blocked-fixable") return fixRungAllowed || requeueLaneOnly || repairFixAllowed;
  if (disposition === "conflicted") return fixRungAllowed || repairFixAllowed;
  return false;
}

/**
 * W1-T2430 — DOES THIS PR'S ENTIRE RED VERDICT REDUCE TO CANCELLATIONS?
 *
 * TRUE only when {@link isBlockedCi} holds, at least one required check is cancelled
 * ({@link OpenPrView.cancelledRequiredChecks}), and EVERY {@link OpenPrView.ciFailures} entry
 * names one of those cancelled checks — the EXACT SAME fold `runSweep`'s own `blocked-fixable`
 * case performs (`src/lib/sweep.ts`, the `cancelledChecks`/`genuineFailures` pair immediately
 * before its `dispatchFix` call) to decide whether to stand down after re-queueing rather than
 * fall through to a fix dispatch. Recomputed here, read-only, off the SAME {@link OpenPrView}
 * snapshot `runSweep` itself will evaluate (no re-fetch, so no race between this predicate's
 * answer and the switch's own) — a PR this returns `true` for is GUARANTEED to reach that
 * stand-down branch and never `dispatchFix`, which is what lets `buildSweepLightHook` admit it
 * on a light pass without loosening `fixRungAllowed`'s own gate for any other PR.
 *
 * A PR with NO cancelled required check (the common case) always reads FALSE here — never
 * routed to the requeue-only batch, so its ordinary `deferred to full sweep (light pass)`
 * stand-down is entirely unchanged by this predicate's existence.
 */
export function blockedFixableIsRequeueOnly(pr: OpenPrView): boolean {
  if (!isBlockedCi(pr)) return false;
  const cancelledChecks = pr.cancelledRequiredChecks ?? [];
  if (cancelledChecks.length === 0) return false;
  const genuineFailures = (pr.ciFailures ?? []).filter(
    (f) => !cancelledChecks.some((c) => c.name === f.name),
  );
  return genuineFailures.length === 0;
}

/**
 * W1-T1211 — IS THIS RUN DEMONSTRABLY WAITING RATHER THAN SPENDING A WORKER?
 *
 * TRUE only when the task's LATEST RETAINED row is {@link AWAITING_EXTERNAL_LEDGER_STEP}. Reading
 * the latest retained row rather than the latest row of any kind is what makes this survive a
 * rotation: the polling telemetry beside it is shed by design, and a predicate that depended on it
 * would silently invert the moment the rotator ran.
 *
 * DELIBERATELY NOT `liveInflightRuns`: that pid-checks a lock, which is HOST-LOCAL (a pid on
 * another host is unreadable), and it carries W1-T1109's consumer defect — the lock-vs-process arm
 * compares a lock FILENAME's task id against a set of RUN ids, which can never match. Nothing here
 * builds on it (design note ii).
 *
 * FAILS SAFE IN BOTH DIRECTIONS. No rows for the task, or a latest retained row that is any other
 * step, reads FALSE — the fix rung stands down exactly as it does today. And a run that DIED while
 * waiting has no worker either, so treating its stale row as "waiting" reaches the same conclusion
 * by a different route rather than a wrong one.
 *
 * WRITTEN AS A DIRECT `.step ===` COMPARISON ON PURPOSE, like `reviewPostRefusedFor` above:
 * `test/ledger-rotation.test.ts` derives `DECISION_RELEVANT_LEDGER_STEPS` membership by scanning
 * consumer source for exactly that shape, so this makes the dependency VISIBLE to the check that
 * exists to find it. The step is registered in that set by this same change.
 */
export function runIsAwaitingExternal(lines: ReadonlyArray<Record<string, unknown>>, taskId: string): boolean {
  let latestTs = "";
  let awaiting = false;
  for (const line of lines) {
    if (line.task_id !== taskId) continue;
    const rawStep: unknown = line.step;
    const step = typeof rawStep === "string" ? rawStep : "";
    if (!DECISION_RELEVANT_LEDGER_STEPS.has(step)) continue; // the retained core only — see this function's doc
    const ts = typeof line.ts === "string" ? line.ts : "";
    if (ts >= latestTs) {
      latestTs = ts;
      // THE STRING LITERAL, NOT THE CONSTANT, ON PURPOSE. `test/ledger-rotation.test.ts` scans
      // consumer source for a step-equality comparison against a quoted name; comparing against the
      // exported identifier instead would hide this dependency from the very guard that exists to
      // find it, and the predicate would then rest on retention nobody had registered. (The comment
      // itself must not spell that pattern out either — the scanner reads comments too.)
      awaiting = line.step === "run.awaiting_external";
    }
  }
  return awaiting;
}

/**
 * W1-T1211 — MAY THE FIX RUNG ACT ALONGSIDE THE RUNS CURRENTLY IN FLIGHT?
 *
 * TRUE only when EVERY in-flight run is demonstrably waiting. One run still working is enough to
 * stand the rung down, which is the property the restriction genuinely buys (design note iv: never
 * run the fix rung beside a spending worker). An EMPTY in-flight set is vacuously true — there is
 * nothing to be concurrent with.
 */
export function fixRungAllowedBesideInFlight(
  lines: ReadonlyArray<Record<string, unknown>>,
  inFlightTaskIds: readonly string[],
): boolean {
  return inFlightTaskIds.every((taskId) => runIsAwaitingExternal(lines, taskId));
}

/**
 * W1-T1211: the in-flight TASK ids, read from `state/inflight/*.lock` FILENAMES.
 *
 * A directory read, never a pid probe — see {@link runIsAwaitingExternal}'s doc for why
 * `liveInflightRuns` is refused here. The shared directory also holds namespaced fix-branch
 * serialization claims, which are not task runs and therefore never enter the task-phase join.
 * This reads no lock CONTENT, releases nothing, and ages nothing out: W1-T1067's stranded
 * `drain.lock` is the precedent for what a clock-shaped release does when its signal never
 * arrives, and this path has no clock at all.
 */
export function inFlightTaskIdsFrom(inflightDir: string): string[] {
  if (!existsSync(inflightDir)) return [];
  return readdirSync(inflightDir)
    .filter((entry) => entry.endsWith(".lock") && !entry.startsWith(FIX_BRANCH_CLAIM_PREFIX))
    .map((entry) => entry.slice(0, -".lock".length));
}

/** W1-T9569 — what a review-only light pass writes on its rows: its scope, in the stand-down text and in
 * `light_pass_scope`, never the ordinary "deferred to full sweep (light pass)". An ordinary pass gets nothing. */
export function reviewOnlyLightPassDeps(scope?: LightPassScope): Pick<SweepDeps, "lightPassScope" | "standDownReasonFor"> {
  const name = scope?.reviewOnly === true ? scope.scope : undefined;
  return name ? { lightPassScope: name, standDownReasonFor: () => reviewOnlyStandDownReason(name) } : {};
}


interface LightPassReadPorts {
  openPrViews?: () => Promise<OpenPrView[]>;
  effects?: (deps: Parameters<typeof buildSweepEffects>[0]) => SweepDeps;
  readCompare?: (args: string[]) => Promise<unknown>;
  clock?: Pick<Clock, "now">;
}

function createLightPassCompareReader(owner: string, repo: string, read: (args: string[]) => Promise<unknown>) {
  type Facts = { behindBy: number; baseFiles?: BaseChangedFiles };
  const memo = new Map<number, { head: string; main: string | undefined; value: Promise<Facts | undefined> }>();
  const nextDistanceProbe = createDistanceProbeSequence();
  return {
    retain: (prs: readonly OpenPrView[]) => {
      const heads = new Map(prs.map((pr) => [pr.prNumber, pr.headSha]));
      for (const [number, entry] of memo) if (heads.get(number) !== entry.head) memo.delete(number);
    },
    read: async (prs: readonly OpenPrView[], main: string | undefined, timing: LightPassPreReviewTiming) => {
      const behindMainByPr = new Map<number, number>();
      const baseChangedFilesByPr = new Map<number, BaseChangedFiles>();
      await timing.measure("compare", () => Promise.all(distanceRefreshProbeTargets(prs, nextDistanceProbe()).map(async (pr) => {
        const start = timing.clock.now();
        let entry = memo.get(pr.prNumber);
        const cacheHit = main !== undefined && entry?.head === pr.headSha && entry.main === main;
        if (!cacheHit) {
          const value = Promise.resolve().then(async (): Promise<Facts | undefined> => {
            const compare = await read(["api", `repos/${owner}/${repo}/compare/${pr.headSha}...${main ?? "main"}`]) as {
              ahead_by?: unknown; files?: unknown;
            };
            if (typeof compare?.ahead_by !== "number" || !Number.isFinite(compare.ahead_by)) return undefined;
            return { behindBy: compare.ahead_by, ...(Array.isArray(compare.files) ? { baseFiles: {
              files: compare.files.flatMap((f) => typeof f?.filename === "string" ? [f.filename] : []),
              truncated: compare.files.length >= GITHUB_COMPARE_FILES_LISTED,
            } } : {}) };
          });
          entry = { head: pr.headSha, main, value };
          if (main !== undefined) memo.set(pr.prNumber, entry);
        }
        const row: Record<string, unknown> = { pr_number: pr.prNumber, head_sha: pr.headSha, main_sha: main ?? null, cache_hit: cacheHit };
        try {
          const facts = await entry!.value;
          row.outcome = facts ? "read" : "unreadable";
          if (facts) {
            behindMainByPr.set(pr.prNumber, facts.behindBy);
            if (facts.baseFiles) baseChangedFilesByPr.set(pr.prNumber, facts.baseFiles);
          } else if (memo.get(pr.prNumber) === entry) memo.delete(pr.prNumber);
        } catch (error) {
          Object.assign(row, { outcome: "error", error: String(error) });
          if (memo.get(pr.prNumber) === entry) memo.delete(pr.prNumber);
        } finally {
          row.elapsed_ms = timing.clock.now() - start;
          timing.compareReads.push(row);
        }
      })));
      return { behindMainByPr, baseChangedFilesByPr };
    },
  };
}

export function buildSweepLightHook(
  owner: string,
  repo: string,
  config: Config,
  ledgerPath: string,
  runId: string,
  plan: Plan,
  log: (step: string, extra?: Record<string, unknown>) => void,
  // Same compatibility adapter as buildSweepHook: recovery-first is the current daemon shape;
  // isMerged/readMainPlan first remains valid for W1-T3585 callers already on the branch.
  reviewerCodeRecoveryOrIsMerged?: SweepDeps["reviewerCodeRecovery"] | MergedResolver,
  isMergedOrReadMainPlan?: MergedResolver | ((root: string) => Plan),
  readMainPlan?: (root: string) => Plan,
  planAccessor?: () => Plan,
  mainHealthRung?: () => Promise<void>,
  io: LightPassReadPorts = {},
): (scope?: LightPassScope) => Promise<void> {
  return buildSweepLightHookFromModule(sweepCommandHost(), owner, repo, config, ledgerPath, runId, plan, log, reviewerCodeRecoveryOrIsMerged, isMergedOrReadMainPlan, readMainPlan, planAccessor, mainHealthRung, io);
}







export function requestedFixView(pr: OpenPrView): OpenPrView {
  return fixCommandHelpers(fixCommandHost()).requestedFixView(pr);
}

export async function routeFix(
  prState: string | undefined,
  pr: OpenPrView,
  deps: FixDeps,
  policy: SweepPolicy = DEFAULT_SWEEP_POLICY,
): Promise<{ outcome: FixOutcome; reason: string }> {
  return fixCommandHelpers(fixCommandHost()).routeFix(prState, pr, deps, policy);
}

export async function fixCommand(
  rest: string[],
  deps: Parameters<typeof fixCommandFromModule>[1] = {},
): Promise<number> {
  return fixCommandFromModule(rest, deps, fixCommandHost());
}

/**
 * The REAL (default) derivation `wipeTestCommand`'s pre-flight consults (W1-T1252): loads
 * the plan already synced onto `planPath`, selects `taskId` (throws `PlanError` on an
 * unknown id — BEFORE any GitHub read, same ordering `runTaskBody` itself relies on), then
 * projects the plan against a FRESH {@link buildBatchedGithub} gateway scoped to the
 * task's own repo — byte-identical to the construction `runTaskBody`'s own W1-T319
 * already-merged guard uses (`buildBatchedGithub(owner, task.repo)` feeding `projectPlan`).
 * A separate, fresh projection from that guard's own (never shared, never reused): the
 * point of asking here is to decide BEFORE dispatching anything, not to save a GitHub read.
 */
function defaultWipeTestMergedState(taskId: string, planPath: string, config: Config, owner: string): WipeTestMergedState {
  const plan = loadPlan(planPath);
  const task = selectTask(plan, taskId);
  const github = buildBatchedGithub(owner, task.repo);
  const statusPath = join(config.root, "state", "status.json");
  const projection = projectPlan(plan, { ledgerPath: ledgerPathFor(config), github }, statusPath);
  return { merged: projection.get(taskId)?.merged ?? false, prUrl: projection.get(taskId)?.prUrl };
}

/**
 * `rmd wipe-test <task-id> [--factor learnings|recon|rules] [--repo remudero-sandbox]
 * [--allow-non-sandbox]` — the P12 learning-utility A/B harness (W1-T86; see
 * src/lib/wipe-test.ts's module doc for the full design). Runs `<task-id>` TWICE through
 * `runTask`: arm A unmasked, arm B with `--factor`'s factor MASKED (the store itself
 * untouched — see `computeMatchedLearningsForArm` for `learnings`, `opts.maskRecon` above
 * for `recon`, `opts.maskRules` for `rules` (W1-T2761) — the `workerRuleHeadlines.enabled`
 * row itself is never written, only the rendered `rule_headlines` part is forced empty) —
 * then computes + LEDGERS the deltas between them (`wipetest.pair`, now
 * carrying WHICH factor it varied — W1-T2512). SANDBOX-ONLY by default
 * (`resolveWipeTestTarget`): a bare `--repo remudero` (or any non-sandbox name) is REFUSED
 * before either arm ever spawns, for EVERY factor — the guard reads only `--repo`/
 * `--allow-non-sandbox`, never `--factor`. Omitting `--factor` defaults to `"learnings"` —
 * byte-identical to this command's own behaviour before this task.
 *
 * A single pair is an anecdote (the design's own words) — the aggregate over many
 * ledgered pairs of the SAME factor (`aggregateWipeTestPairs`, read back from the ledger
 * and filtered to one factor — it refuses to average two factors together) is what the
 * operator treats as signal; this command runs and ledgers exactly one pair per
 * invocation, by design (repeat it to accumulate pairs).
 *
 * NEVER LEDGERS A PAIR NEITHER ARM MEASURED (W1-T1252), for every factor. A subject the
 * projection already reports merged is refused HERE, up front, naming the reason
 * (`resolveWipeTestPreflight`) — neither arm spawns and no `wipetest.pair` line is written.
 * `ledgerWipeTestPair` itself is the backstop for every OTHER zero-work cause: a pair whose
 * two arms both report zero turns and zero cost is never written, whatever produced it —
 * this backstop reads only turns/cost, never the factor, so it holds for `recon` exactly as
 * it always has for `learnings`.
 */
export async function wipeTestCommand(
  rest: string[],
  deps: {
    config?: Config;
    /** Injectable dispatch — the real (default) is this module's own {@link runTask}. A
     *  behavioral test swaps in a fake returning canned {@link RunResult}s so a `wipe-test`
     *  invocation can be exercised end-to-end WITHOUT spawning two real workers. */
    runTaskFn?: typeof runTask;
    /** Injectable subprocess runner for the non-self clone/fetch step — same seam
     *  `drainCommand`'s `githubFactory` provides for its own network calls. Default: the
     *  real {@link execFileSync}. */
    execFileSyncFn?: typeof execFileSync;
    /**
     * W1-T1252: resolves whether `taskId` is a subject `runTask`'s own W1-T319
     * already-merged guard would refuse — consulted ONCE, BEFORE either arm is
     * dispatched (design note (i)). Default: {@link defaultWipeTestMergedState}, which
     * mirrors `runTaskBody`'s own guard construction exactly (loadPlan + selectTask +
     * projectPlan over a fresh batched GitHub gateway). Injectable (mirrors `runTaskFn`/
     * `execFileSyncFn` above) so a test can drive the merged / not-merged branch without a
     * real plan file on disk or a live GitHub read.
     */
    resolveMergedState?: (taskId: string, planPath: string, config: Config) => WipeTestMergedState;
  } = {},
): Promise<number> {
  const taskId = rest[0];
  const badArg = unknownArgError("wipe-test", rest.slice(1), ["--repo", "--factor"], ["--allow-non-sandbox"]);
  if (!taskId || badArg) {
    if (badArg) console.error(badArg);
    console.error(`usage: ${commandSyntax("wipe-test")}\n` + USAGE);
    return 2;
  }

  // W1-T2512: WHICH FACTOR this pair varies — resolved the SAME way as `--repo` right above
  // (a pure, validated flag lookup), refused loud on an unrecognized value rather than
  // silently falling back to the default. Omitted defaults to "learnings" — see
  // `resolveWipeTestFactor`'s own doc for why that keeps every pre-existing invocation
  // byte-identical.
  const resolvedFactor = resolveWipeTestFactor(rest.slice(1));
  if ("error" in resolvedFactor) {
    console.error(resolvedFactor.error + "\n" + USAGE);
    return 2;
  }
  const { factor } = resolvedFactor;

  const resolvedTarget = resolveWipeTestTarget(rest.slice(1));
  if ("error" in resolvedTarget) {
    console.error(resolvedTarget.error + "\n" + USAGE);
    return 2;
  }

  const config = deps.config ?? loadConfig();
  const runTaskFn = deps.runTaskFn ?? runTask;
  const ablationRunTaskFn: typeof runTask = factor === "rules"
    ? (id, options) => runTaskFn(id, { ...options, workerRuleHeadlinesEnabled: true })
    : runTaskFn;
  const execFileSyncFn = deps.execFileSyncFn ?? execFileSync;
  const self = resolveOwnerRepo();
  const resolveMergedState = deps.resolveMergedState ?? ((tid, pp, cfg) => defaultWipeTestMergedState(tid, pp, cfg, self.owner));

  const result = await runWipeTestPair(
    { id: taskId },
    factor,
    {
      config,
      repoRoot,
      owner: self.owner,
      selfRepo: self.repo,
      targetArgs: rest.slice(1),
      runTaskFn: ablationRunTaskFn,
      execFileSyncFn,
      ledgerPath: ledgerPathFor(config),
      resolveMergedState,
    },
  );
  if (result.status === "refused") {
    console.error(result.reason + (result.target ? "" : "\n" + USAGE));
    return 2;
  }
  console.log("\n" + JSON.stringify({ pair: result.pair, delta: result.delta }, null, 2));
  return 0;
}

/**
 * `rmd sync [--dry-run]` — the sanctioned dedupe-then-pull recipe as one explicit verb
 * (W1-T907). All the classification/preserve/discard/ff logic lives in
 * {@link runOperatorSync} (src/lib/operator-sync.ts), which also does its own
 * printing (say/warn) — this wrapper is arg-validation + exit-code translation only,
 * same shape as every other flags-only subcommand below.
 *
 * `opts.repoDir`/`opts.deps` are injectable (default: the real `repoRoot` + real git) purely so
 * a test can drive the arg-validation branch and the exit-code translation without ever letting
 * runOperatorSync touch THIS process's own checkout — `repoRoot` below is a module-level
 * constant resolved once at import time (no `--repo-root` override reaches here for `sync`
 * today), so an un-injectable version of this function could only be safely exercised via
 * runOperatorSync's own direct unit tests (test/operator-sync.test.ts), never via `main()`.
 */
export function syncCommand(
  rest: string[],
  opts: { repoDir?: string; deps?: OperatorSyncDeps } = {},
): number {
  const badArg = unknownArgError("sync", rest, [], ["--dry-run"]);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const result = runOperatorSync(opts.repoDir ?? repoRoot, { dryRun: rest.includes("--dry-run") }, opts.deps);
  return result.status === "refused" || result.status === "degraded" ? 1 : 0;
}

/**
 * `rmd stop [--reason <text>]` — the fleet control set (W1-T11, MASTER-PLAN §4A/§4B).
 * Writes the STOP flag file. A `rmd drain` already running halts within one tick
 * (checked FIRST, every iteration, ahead of PAUSE); a NEW `rmd drain` refuses to
 * spawn anything until `rmd resume` clears it — same check, same code path.
 */
async function stopCommand(rest: string[]): Promise<number> {
  const config = loadConfig();
  const reason = flagValue(rest, "--reason");
  const ledgerPath = ledgerPathFor(config);

  // STOP is ONE-SHOT: it exists only to halt a RUNNING drain/daemon, which auto-consumes it
  // on termination. With NOTHING running, writing STOP would be a persistent latch that
  // silently blocks the NEXT drain (the reported bug) — so with nothing to stop, warn + no-op.
  // "Active" = the shared drain.lock is held by a live pid (a drain or daemon is running).
  const holder = readDrainLock(join(config.root, "state", "drain.lock"));
  if (!holder || !defaultIsPidAlive(holder.pid)) {
    console.warn(
      `### rmd stop — nothing to stop: no drain/daemon is running. NOT writing a persistent ` +
        `STOP (it is one-shot). For a maintenance hold that survives across runs, use \`rmd pause\`.`,
    );
    appendLedger(ledgerPath, {
      run_id: `FLEET-${Date.now()}`,
      task_id: "FLEET",
      step: "fleet.stop.noop",
      reason: reason ?? null,
    });
    return 0;
  }

  const info = requestStop(config.root, reason);
  appendLedger(ledgerPath, {
    run_id: `FLEET-${Date.now()}`,
    task_id: "FLEET",
    step: "fleet.stop",
    reason: reason ?? null,
    requested_by_pid: info.pid,
    target_pid: holder.pid,
  });
  console.log(
    `### rmd stop — STOP written; the running drain (pid ${holder.pid}) halts within one tick ` +
      `and AUTO-CLEARS STOP as it exits. One-shot: your next \`rmd drain\` starts clean — no \`rmd resume\` needed.`,
  );
  return 0;
}

/**
 * W1-T7727 — the instance a `rmd pause` / `rmd resume` acts on, or a printed refusal. Resolved
 * through the checkout's instance registry and this process's `config.root` (pause-target.ts),
 * never the cwd, the repository, the hostname or a pid. A refusal returns before anything is written.
 */
function pauseTargetOrRefuse(verb: "pause" | "resume", rest: string[], config: Config): PauseTarget | undefined {
  // `RMD_INSTANCE_REGISTRY` is the override the shell readers already honor (install-host-units.sh,
  // host-update.sh, recycle-container.sh); otherwise the checkout's own registry.
  const override = process.env.RMD_INSTANCE_REGISTRY?.trim();
  const registryPath = override ? override : daemonInstanceRegistryPath(repoRoot);
  let registryText: string | undefined;
  try {
    registryText = readFileSync(registryPath, "utf8");
  } catch {
    registryText = undefined; // resolvePauseTarget refuses on an unreadable registry, naming the path.
  }
  const resolution = resolvePauseTarget({
    configRoot: config.root,
    instance: flagValue(rest, "--instance"),
    registryText,
    registryPath,
  });
  if (resolution.ok) return resolution.target;
  console.error(`### rmd ${verb} — REFUSED: ${resolution.refusal}.`);
  return undefined;
}

/**
 * `rmd pause [--instance <name>] [--reason <text>]` — drain-and-hold ONE instance (W1-T11).
 * Writes that instance's PAUSE flag under its own state root. No new spawn after the current
 * tick; an in-flight task ALWAYS runs to completion (verdict + merge).
 *
 * W1-T7727: the default holds ONLY the targeted instance. Core, site and console share a
 * checkout and an origin, so the W1-T1216 push of `refs/rmd-pause/hold` that this verb used to
 * make held all of them (and every other host's daemon). That fleet-wide hold is now its own
 * explicit act, `rmd pause --fleet`, which writes no instance flag.
 */
async function pauseCommand(rest: string[]): Promise<number> {
  const config = loadConfig();
  const runId = `FLEET-${Date.now()}`;
  const reason = flagValue(rest, "--reason");
  if (rest.includes("--fleet")) {
    if (flagValue(rest, "--instance") !== undefined) {
      console.error("### rmd pause — REFUSED: --fleet holds every instance; it cannot be combined with --instance — nothing was changed.");
      return 2;
    }
    const result = requestFleetPause(realDeps().sharedPauseGit, reason);
    appendLedger(ledgerPathFor(config), {
      run_id: runId,
      task_id: "FLEET",
      step: "fleet.pause",
      scope: "fleet",
      pushed: result.pushed,
      reason: reason ?? null,
      session_id: result.sessionId,
      actor_evidence: result.actor_evidence,
      expires_at: result.expiresAt,
      requested_by_pid: process.pid,
    });
    if (!result.pushed) {
      console.error(`### rmd pause --fleet — the push of ${sharedPauseRef()} did not report success; this result does NOT certify the fleet-wide hold state.`);
      return 1;
    }
    console.log(
      `### rmd pause --fleet — FLEET-WIDE hold pushed to ${sharedPauseRef()}: every instance on every host that shares ` +
        "this origin holds new spawns until `rmd resume --fleet`.",
    );
    return 0;
  }
  const target = pauseTargetOrRefuse("pause", rest, config);
  if (!target) return 2;
  const info = requestPause(target.root, reason, undefined, { instance: target.instance });
  appendLedger(ledgerPathFor({ ...config, root: target.root }), {
    run_id: runId,
    task_id: "FLEET",
    step: "fleet.pause",
    scope: "instance",
    instance: target.instance,
    root: target.root,
    resolved_by: target.resolvedBy,
    reason: reason ?? null,
    session_id: info.sessionId ?? null,
    actor_evidence: info.actor_evidence,
    expires_at: info.expiresAt ?? null,
    requested_by_pid: info.pid,
  });
  console.log(
    `### rmd pause — instance '${target.instance}' (${target.root}) is PAUSED (drain-and-hold). Its in-flight task still ` +
      `reaches merge; it spawns nothing new until \`rmd resume --instance ${target.instance}\`. No other instance is held.`,
  );
  return 0;
}

/**
 * `rmd resume [--instance <name>]` — clears ONE instance's STOP and PAUSE flags (W1-T11). Idempotent.
 *
 * W1-T7727: it never deletes the fleet-wide `refs/rmd-pause/hold` — that hold may be another
 * operator's, and only `rmd resume --fleet` clears it. It says so, without a remote read.
 */
async function resumeFleetCommand(rest: string[] = []): Promise<number> {
  const config = loadConfig();
  const runId = `FLEET-${Date.now()}`;
  if (rest.includes("--fleet")) {
    if (flagValue(rest, "--instance") !== undefined) {
      console.error("### rmd resume — REFUSED: --fleet clears the fleet-wide hold only; it cannot be combined with --instance — nothing was changed.");
      return 2;
    }
    const cleared = resumeFleetWide(realDeps().sharedPauseGit);
    appendLedger(ledgerPathFor(config), {
      run_id: runId,
      task_id: "FLEET",
      step: "fleet.resume",
      scope: "fleet",
      cleared_shared_pause: cleared,
      actor_evidence: gatherActorEvidence(),
      session_id: process.env.REMUDERO_SESSION_ID?.trim() || null,
      requested_by_pid: process.pid,
    });
    console.log(`### rmd resume --fleet — ${sharedPauseRef()} ${cleared ? "deleted" : "NOT deleted (the push did not land)"}; no instance flag was touched.`);
    return cleared ? 0 : 1;
  }
  const target = pauseTargetOrRefuse("resume", rest, config);
  if (!target) return 2;
  const result = resumeFleet(target.root);
  appendLedger(ledgerPathFor({ ...config, root: target.root }), {
    run_id: runId,
    task_id: "FLEET",
    step: "fleet.resume",
    scope: "instance",
    instance: target.instance,
    root: target.root,
    resolved_by: target.resolvedBy,
    cleared_stop: result.clearedStop,
    cleared_pause: result.clearedPause,
    actor_evidence: gatherActorEvidence(),
    session_id: process.env.REMUDERO_SESSION_ID?.trim() || null,
    requested_by_pid: process.pid,
  });
  console.log(
    `### rmd resume — instance '${target.instance}' cleared: stop=${result.clearedStop} pause=${result.clearedPause}. ` +
      "No other instance was touched.",
  );
  console.log(
    `### rmd resume — the fleet-wide hold (${sharedPauseRef()}) is NOT cleared by an instance resume; if one stands, ` +
      `'${target.instance}' stays held until \`rmd resume --fleet\` (\`rmd status\` shows it).`,
  );
  return 0;
}

/**
 * `rmd away [on|off]` — set or show the operator presence mode (P34 clause (e), MASTER-PLAN
 * §7B/§4). With no argument, prints the current mode. AWAY batches MANUAL/HARD_STOP escalations
 * into the W1-T163 recap for an async verdict instead of paging in real time; ATTENDED (the
 * default) delivers exactly as today. Presence keys ONLY escalation delivery — it never gates
 * dispatch (escalate.ts's module header names the dead presence×risk matrix this must not
 * resurrect); STOP/PAUSE (above) remain the only real-time-presence waits.
 */
export async function awayCommand(rest: string[]): Promise<number> {
  const config = loadConfig();
  const arg = rest[0];
  if (arg !== undefined && arg !== "on" && arg !== "off") {
    console.error(`usage: ${commandSyntax("away")}`);
    return 2;
  }
  if (arg === undefined) {
    console.log(`### rmd away — presence mode: ${presenceMode(config.root)}`);
    return 0;
  }
  const mode: PresenceMode = arg === "on" ? "away" : "attended";
  setPresenceMode(config.root, mode);
  const ledgerPath = ledgerPathFor(config);
  appendLedger(ledgerPath, {
    run_id: `FLEET-${Date.now()}`,
    task_id: "FLEET",
    step: "fleet.presence",
    mode,
  });
  console.log(
    mode === "away"
      ? "### rmd away on — presence set to AWAY: MANUAL/HARD_STOP escalations now batch into the recap for async verdict instead of paging in real time."
      : "### rmd away off — presence set to ATTENDED: escalations deliver exactly as today.",
  );
  return 0;
}

/**
 * The supported writer for the durable hold state already enforced by every production arm path.
 * Omit `--pr` for a fleet-wide hold; a PR-scoped release after a fleet hold intentionally carves
 * out only that PR, matching automergeHoldFromLedger's existing last-applicable-row semantics.
 */
export function mergeHoldCommand(
  rest: string[],
  deps: {
    config?: Config;
    ledgerPath?: string;
    now?: () => number;
    isInteractive?: () => boolean;
    /** W1-T7721 — where the writer's actor is gathered from. A caller that injects `isInteractive` without a probe
     *  has taken control of the terminal, so it also gets a human-terminal probe rather than this process's own env. */
    actorProbe?: MergeHoldActorProbe;
  } = {},
): number {
  const parsed = parseOperatorMergeHoldArgs(rest);
  if (!parsed.ok) {
    console.error(`rmd merge-hold: ${parsed.error} — usage: ${commandSyntax("merge-hold")}\n` + USAGE);
    return 2;
  }
  if (!(deps.isInteractive ?? (() => process.stdin.isTTY === true))()) {
    console.error(
      `rmd merge-hold: refusing a non-interactive hold writer — use the confirmed console control instead.\n` + USAGE,
    );
    return 2;
  }
  const actor = gatherMergeHoldActor(
    deps.actorProbe ?? (deps.isInteractive ? humanTerminalActorProbe() : realMergeHoldActorProbe()),
  );
  const authorized = authorizeMergeHoldWrite(parsed.input, actor);
  if (!authorized.ok) {
    console.error(`rmd merge-hold: ${authorized.error}`);
    return 2;
  }
  const ledgerPath = deps.ledgerPath ?? ledgerPathFor(deps.config ?? loadConfig());
  const result = applyOperatorMergeHold(ledgerPath, authorized.input, { now: deps.now, actor });
  if (!result.written) {
    console.log(`### rmd merge-hold — ${result.scope} is already released; no ledger row written.`);
    return 0;
  }
  if (authorized.input.authority === "agent-cli") {
    console.log(
      `### rmd merge-hold — AGENT NOTE recorded for ${result.scope}; by ${parsed.input.by}: ${parsed.input.reason}. ` +
        `An agent hold is audit-only (authority agent-cli): it does NOT block auto-merge.`,
    );
    return 0;
  }
  console.log(
    `### rmd merge-hold — ${result.action === "engage" ? "ENGAGED" : "RELEASED"} for ${result.scope}; ` +
      `by ${parsed.input.by}: ${parsed.input.reason}. The append was read back through the production hold reader.`,
  );
  return 0;
}

// flagValue moved to src/lib/cli-args.ts (W1-T2888) — imported below, alongside
// unknownArgError.

/** The repo + plan a `rmd daemon` run targets, resolved from its flags. */
export interface DaemonTarget {
  owner: string;
  repo: string; // scopes the status-derivation GitHub gateway
  planPath: string; // where the plan to schedule is read from
  isSelf: boolean; // repo === the daemon's OWN source repo
  dryRun: boolean;
}

/**
 * Resolve which repo/plan a `rmd daemon` run targets — PURE (no I/O), so the guard is
 * unit-testable. The daemon reads its plan from the CHECKOUT it runs in by default and scoped
 * the status gateway to a hardcoded "remudero"; this makes the target EXPLICIT:
 *   --repo <name>         scope the gateway to THIS checkout's owner/<name> (bare name keeps
 *                          the default owner — unchanged from before W1-T1062)
 *   --repo <owner>/<name> scope the gateway to a FOREIGN owner's <name> — resolved through the
 *                          SAME `resolveReviewTarget` splitter `rmd review --repo` already uses
 *                          (W1-T1062: no parallel parser) — and read the plan from that clone
 *   --plan <path>   read the plan from an explicit file (overrides the derived path)
 *   --allow-self-target  acknowledge draining the daemon's OWN source repo (deliberate self-host)
 *   --dry-run       preview only (harmless — allowed even for self)
 * GUARD (W1-T12d): a bare `rmd daemon` would silently drain the repo that holds the daemon's own
 * source (self) unattended — REFUSED unless --allow-self-target (or --dry-run). Commissioning
 * targets the sandbox explicitly: `rmd daemon --repo remudero-sandbox`.
 * W1-T1062 design (iii): `isSelf` compares BOTH owner and repo — this checkout's OWN repo name
 * under a FOREIGN owner (`--repo other-owner/remudero`) is NOT self, so it can never reach the
 * retro/auto-triage/github-posture hooks `daemonCommand` gates on `target.isSelf`.
 */
export function resolveDaemonTarget(
  env: { selfOwner: string; selfRepo: string; repoRoot: string; reposDir: string },
  rest: string[],
): { target: DaemonTarget } | { error: string } {
  const planFlag = flagValue(rest, "--plan");
  const allowSelf = rest.includes("--allow-self-target");
  const dryRun = rest.includes("--dry-run");
  const { owner, repo } = resolveReviewTarget({ owner: env.selfOwner, repo: env.selfRepo }, rest);
  const isSelf = owner === env.selfOwner && repo === env.selfRepo;
  if (isSelf && !allowSelf && !dryRun) {
    return {
      error:
        `rmd daemon: refusing to drain the daemon's OWN source repo '${repo}' unattended ` +
        `(no silent self-default). For commissioning, target the sandbox: ` +
        `\`rmd daemon --repo remudero-sandbox\`. To self-host deliberately, pass --allow-self-target.`,
    };
  }
  const planPath =
    planFlag ??
    (isSelf ? join(env.repoRoot, "plan", "tasks.yaml") : join(env.reposDir, repo, "plan", "tasks.yaml"));
  // W1-T1062: the RESOLVED owner (bare `--repo <name>` ⇒ env.selfOwner, `--repo <owner>/<name>`
  // ⇒ that owner — see resolveReviewTarget above), never env.selfOwner unconditionally. That one
  // line was the hardcode the task record measured: a foreign-owner target's clone/gateway/PR
  // all silently ran against THIS checkout's own owner instead of the one the operator named.
  return { target: { owner, repo, planPath, isSelf, dryRun } };
}

/** Every `--option "label|detail"` in argv tail, in order given. */
function parseOptionFlags(rest: string[]): EscalationOption[] {
  const options: EscalationOption[] = [];
  for (let i = 0; i < rest.length; i++) {
    if (rest[i] !== "--option") continue;
    const raw = rest[i + 1] ?? "";
    const sep = raw.indexOf("|");
    options.push(sep >= 0 ? { label: raw.slice(0, sep), detail: raw.slice(sep + 1) } : { label: raw, detail: "" });
  }
  return options;
}

const ESCALATION_CLASSES: EscalationClass[] = ["BLOCKED", "MANUAL", "HARD_STOP"];

/**
 * `rmd escalate --class <BLOCKED|MANUAL|HARD_STOP> --task <id> --summary <s>
 *   [--detail <d>] [--recommendation <r>] [--option "label|detail"]...`
 * Opens the `needs-human` labeled issue (escalate.ts) UNCONDITIONALLY. For MANUAL/HARD_STOP
 * ONLY, also fires a real-time iMessage ping (§4: BLOCKED collapses to the digest) — but ONLY
 * when the operator is ATTENDED (escalate.ts's `deliversRealtime`, P34 clause (e)). AWAY mode
 * skips that ping and instead ledgers `escalation.batched_away`: the issue already opened above
 * is picked up by the W1-T163 recap/digest off the SAME marker for an ASYNC verdict, rather than
 * expecting a sync answer right now. ATTENDED behaves EXACTLY as before this flag existed.
 */
export async function escalateCommand(
  rest: string[],
  deps: { issues?: IssueGateway; notifyChannel?: NotifyChannel } = {},
): Promise<number> {
  const cls = flagValue(rest, "--class");
  const taskId = flagValue(rest, "--task");
  const summary = flagValue(rest, "--summary");
  if (!cls || !ESCALATION_CLASSES.includes(cls as EscalationClass) || !taskId || !summary) {
    console.error(`usage: ${commandSyntax("escalate")}`);
    return 2;
  }
  const config = loadConfig();
  const { owner, repo } = resolveOwnerRepo();
  const ledgerPath = ledgerPathFor(config);
  const runId = `ESCALATE-${Date.now()}`;
  const url = escalate(
    {
      class: cls as EscalationClass,
      taskId,
      runId,
      summary,
      detail: flagValue(rest, "--detail") ?? "",
      options: parseOptionFlags(rest),
      recommendation: flagValue(rest, "--recommendation") ?? "",
    },
    { issues: deps.issues ?? ghIssueGateway(owner, repo), ledgerPath, runId },
  );
  console.log(url);
  if (cls === "MANUAL" || cls === "HARD_STOP") {
    if (deliversRealtime(config.root)) {
      // W1-T144: the real-time ping deep-links to the console card alongside the GitHub
      // issue URL, same as the digest's own escalations line (digest.ts's renderDigest).
      // W1-T2696 — SCOPE WIDENING, STATED RATHER THAN SLIPPED IN. This one call site is the
      // fleet's only real-time ping, and it is in run-task.ts, which is NOT in W1-T2696's
      // `files:`. The renderer, the link minting and the answer routes all live inside the
      // declared scope; without this line they would ship inert, which is the "declared but
      // unreachable" class serve.ts's own history has three prior instances of. The scope guard
      // flags this as an overrun (advisory, never blocking) and the PR body names it.
      //
      // A secret that cannot be read degrades to today's text rather than dropping the page:
      // renderEscalationPing takes `secret` as optional for exactly this reason.
      let linkSecret: string | undefined;
      try {
        linkSecret = loadEscalationLinkSecret(config.root);
      } catch (err) {
        console.error(`escalate: answer links unavailable — ${String(err)}`);
      }
      notify(renderEscalationPing(
        {
          cls,
          taskId,
          summary,
          issueUrl: url,
          cardUrl: consoleCardUrl(consoleAppUrl(config), taskId),
          options: parseOptionFlags(rest),
        },
        { secret: linkSecret, baseUrl: consoleUrl(config), nowMs: Date.now() },
      ), {
        channel: deps.notifyChannel ?? imessageChannel(notifyRecipient(config)),
        ledgerPath,
        runId,
        taskId,
      });
    } else {
      // P34 clause (e), AWAY mode: no real-time page. The `escalation.issue_opened` line above
      // already carries this into the recap/digest; this line records that away mode is why no
      // ping fired, so the routing decision itself is auditable.
      appendLedger(ledgerPath, {
        run_id: runId,
        task_id: taskId,
        step: "escalation.batched_away",
        class: cls,
        issue_url: url,
      });
    }
  }
  return 0;
}

/** `rmd notify <message>` — a real-time iMessage ping via osascript (notify.ts). */
async function notifyCommand(rest: string[]): Promise<number> {
  const message = rest.join(" ");
  if (!message) {
    console.error(`usage: ${commandSyntax("notify")}`);
    return 2;
  }
  const config = loadConfig();
  const ledgerPath = ledgerPathFor(config);
  notify(message, {
    channel: imessageChannel(notifyRecipient(config)),
    ledgerPath,
    runId: `NOTIFY-${Date.now()}`,
    taskId: "NOTIFY",
  });
  return 0;
}

/**
 * `rmd feedback <text...> [--attach <path-or-url>]... [--origin cli|ui|issue]` — the durable
 * inbox's async-capture front door (lib/feedback.ts, MASTER-PLAN §7B, W1-T40). Writes one
 * `plan/feedback/<id>.yaml` entry with `status: new` and returns immediately (plain filesystem
 * I/O — no network, no LLM call). Fails loud (exit 2, writes nothing) on a bad flag, an
 * unreadable `--attach` path, or empty text; never falls through to a silent no-op.
 *
 * `repoRoot` here is THIS checkout — the codebase this command is running against, which may
 * be a fork/clone with no relation to rmd's own repo. `captureFeedback` (W1-T397) separately
 * checks `repoRoot`'s own `.remudero/home-repo.json` and, when it names a different repo,
 * routes an upstream PR there in addition to this local write — so an instance working on
 * another codebase files an rmd defect where an rmd maintainer will read it, rather than into
 * that other codebase's own inbox. No pointer configured (the default) leaves this command's
 * behavior unchanged from before W1-T397.
 */
async function feedbackCommand(rest: string[]): Promise<number> {
  const parsed = parseFeedbackAddArgs(rest);
  if ("error" in parsed) {
    console.error(parsed.error);
    return 2;
  }
  try {
    const entry = captureFeedback(repoRoot, parsed);
    console.log(JSON.stringify(entry, null, 2));
    return 0;
  } catch (err) {
    if (err instanceof FeedbackError) {
      console.error(`rmd feedback: ${err.message}`);
      return 1;
    }
    throw err;
  }
}

/** Every value token immediately following a `--root` flag, in argv order — repeats accumulate
 *  (design iv's explicit, multi-root enrolment), unlike {@link flagValue}'s single lookup. */
function parseReconcileRootArgs(rest: string[]): string[] {
  const out: string[] = [];
  for (let i = 0; i < rest.length; i++) if (rest[i] === "--root") out.push(rest[i + 1] ?? "");
  return out;
}

/** The operator-facing render for `rmd feedback-reconcile` — names the mode FIRST (dry run vs
 *  apply), same convention as {@link renderPlanReconcile}, so a preview can never be misread as
 *  having written anything. */
export function renderFeedbackReconcile(result: ReconcileFeedbackLandingResult, apply: boolean): string {
  const { manifest } = result;
  const counts = new Map<string, number>();
  for (const e of manifest.entries) counts.set(e.classification, (counts.get(e.classification) ?? 0) + 1);
  const countLine = [...counts.entries()].map(([k, n]) => `${k}=${n}`).join(" · ") || "nothing to reconcile";
  const lines = [
    `### rmd feedback-reconcile${apply ? " --apply" : " (dry run — nothing written)"}`,
    `scanned: ${manifest.scannedRoots.join(", ")} — ${manifest.recordCount} record(s), ${manifest.byteCount} byte(s)` +
      (manifest.truncated ? " (TRUNCATED — a source held more than the bounded scan cap)" : ""),
    countLine,
    ...manifest.entries.map((e) => {
      const origin = e.originStatus ? `origin=${e.originStatus}` : "origin=<none>";
      const best = e.bestStatus ? `, best=${e.bestStatus}` : "";
      const reason = e.reason ? ` — ${e.reason}` : "";
      return `- ${e.id}: ${e.classification} (found in ${e.foundIn.join(", ")}, ${origin}${best})${reason}`;
    }),
  ];
  if (apply) {
    lines.push(
      result.landed.length > 0
        ? `landed ${result.landed.length} record(s)${result.prUrl ? ` — ${result.prUrl}` : ""}`
        : "nothing landed (already up to date, or every candidate was refused)",
    );
    if (result.refused.length > 0) {
      lines.push(`refused ${result.refused.length} record(s) rather than force a backward move:`);
      lines.push(...result.refused.map((r) => `  - ${r.path}: ${r.reason}`));
    }
  } else if (manifest.entries.some((e) => e.classification !== "present-everywhere")) {
    lines.push("re-run with --apply to re-land the union through the ordinary gated PR path");
  }
  return lines.join("\n");
}

/**
 * `rmd feedback-reconcile --root <name>=<path> [--root <name>=<path> ...] [--checkout <path>]
 *   [--apply]` — the cross-root feedback reconciliation manifest and repair (W1-T3562). Dry-run by
 * default: reports which records an enrolled root or the shared landing branch holds that
 * origin/main does not, or already sits at an earlier §7B position than, and writes nothing.
 * `--apply` re-lands the union through the ordinary gated PR path
 * ({@link reconcileFeedbackLanding}, lib/feedback-reconcile.ts) — this hub does no scanning or
 * classification of its own; it only parses argv and calls the library's one entry point.
 */
export async function feedbackReconcileCommand(rest: string[], configOverride?: Config, gh?: LandFeedbackOpts["gh"]): Promise<number> {
  const badArg = unknownArgError("feedback-reconcile", rest, ["--root", "--checkout"], ["--apply"]);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const rawRoots = parseReconcileRootArgs(rest);
  if (rawRoots.length === 0) {
    console.error(
      "rmd feedback-reconcile: at least one --root <name>=<path> is required — an explicit enrolment, " +
        "never discovered by globbing the host's filesystem (design iv)\n" + USAGE,
    );
    return 2;
  }
  const roots: FeedbackReconcileRoot[] = [];
  for (const raw of rawRoots) {
    const eq = raw.indexOf("=");
    if (eq <= 0) {
      console.error(`rmd feedback-reconcile: malformed --root "${raw}" — expected <name>=<path>`);
      return 2;
    }
    roots.push({ name: raw.slice(0, eq), path: resolve(raw.slice(eq + 1)) });
  }
  const checkoutArg = flagValue(rest, "--checkout");
  const checkoutRoot = checkoutArg !== undefined ? resolve(checkoutArg) : repoRoot;
  const apply = rest.includes("--apply");

  const reconcileConfig = configOverride ?? loadConfig();
  const ledgerPath = ledgerPathFor(reconcileConfig);
  const result = reconcileFeedbackLanding({
    roots,
    checkoutRoot,
    apply,
    gh,
    ledgerLines: () => readLedgerLines(ledgerPath),
    ...(reconcileConfig.contributorAdmission === undefined ? {} : { land: (root: string, relPath: string, content: string, opts: LandFeedbackOpts) =>
      landFeedbackStatusContent(root, relPath, content, { ...opts, publication: { mode: "shadow", record: (step, fields) =>
        appendLedger(ledgerPath, { step, task_id: "CLI", run_id: "feedback-reconcile", ...fields }) } }) }),
  });
  console.log(renderFeedbackReconcile(result, apply));
  if (result.error) {
    console.error(`### rmd feedback-reconcile: ${result.error}`);
    return 1;
  }
  return 0;
}

/**
 * The Architect intake worker's tool allowlist (MASTER-PLAN §7B / `.remudero/skills/feedback.yaml`),
 * minus `AskUserQuestion`: ★ VERIFIED (W1-T42, LEARNINGS.md "AskUserQuestion neither works
 * headlessly nor stalls") it silently auto-resolves with an EMPTY answer with no TTY, and this
 * worker always runs via `spawnWorker` — a subprocess with no TTY BY CONSTRUCTION, regardless of
 * the invoking shell — so an interactive grill is structurally unreachable here, not a fallback
 * choice. The AMBIGUOUS verdict parks the entry at `grilling` AND `triageCommand` below opens a
 * `needs-human` GitHub issue (escalate.ts, MASTER-PLAN §4) carrying options + a recommendation —
 * the grill's one and only mechanism.
 */
// "Edit" is load-bearing (the 2026-07-22 materialization gap): the triage prompt
// (triage.ts) instructs the PROPOSED path to "Edit ONLY plan files", and
// plan/tasks.yaml is ~11k lines — without the Edit tool the worker cannot make a
// surgical change (whole-file Write is not viable at that size), so it emitted
// PROPOSED with an EMPTY diff and decideTriage fail-closed it as inconsistent
// (observed live: feedback 04eac2 + 728bc1, both INCONSISTENT with empty diffs).
// PLAN_WORKER_TOOLS (below) already grants Edit for the same job — this matches it.
// Exported for the behavioral test (test/triage.test.ts) that pins the grant.
export const TRIAGE_WORKER_TOOLS = ["Read", "Write", "Edit", "Grep", "Glob", "WebSearch"];

/**
 * W1-T3749: MEASURED (`cashCanServeToolSurface` over every declared spawn surface in the tree,
 * live squeeze 2026-09-17) — offering TRIAGE_WORKER_TOOLS verbatim to a blocked-auction divert
 * REFUSES ("not implementable by cash"), and dropping WebSearch alone is the ONE change that
 * flips the answer to DIVERTABLE; every other entry is already implemented by the check-runner.
 *
 * THE DECISION (the task's option (b), "triage needs it only sometimes" — not (a) "genuinely
 * needs the network", not (c) "never uses it"): keep WebSearch on the CLAUDE surface above —
 * `LEARNINGS.md` ("`WebSearch`... Grant them to the Architect only") already treats it as an
 * Architect-tier privilege, and triagePrompt's own STEP 2 (lib/triage.ts) already conditions
 * research on "a genuine platform-facts gap", instructing the worker to "skip this step
 * entirely" otherwise — WebSearch was never promised unconditionally, so a run diverted to cash
 * without it degrades on the rare external-fact question rather than breaking. Drop it only from
 * the surface a squeeze diverts to, the same shape `fixRoundGitOwnership`/`FIX_CASH_TOOLS`
 * (lib/fix-fence.ts) already gives the fix rung for its own reason.
 *
 * NOT ADDED TO `OPENWEIGHT_FUNCTIONS` (lib/worker-provider.ts) — the task rules that out by name:
 * triage reads UNTRUSTED INBOUND TEXT (a feedback entry), and W1-T210 bounded the fix rung so an
 * untrusted prompt payload could never reach the network; triage shares that exposure.
 *
 * NOT WIRED THROUGH `DISPATCH_LANE_TOOL_BOUNDS`/`cashDivertSpawnFields` (lib/worker.ts): this
 * task's declared scope is `src/run-task.ts` alone, so the spawn call below passes this list
 * directly as `cashTools` — the same standalone-constant shape `FIX_CASH_TOOLS` already uses,
 * next to the surface it derives from rather than in the shared table.
 */
export const TRIAGE_CASH_TOOLS: readonly string[] = TRIAGE_WORKER_TOOLS.filter((tool) => tool !== "WebSearch");

/**
 * Every path a worker touched in its worktree, measured against `origin/main` — INCLUDING files it
 * CREATED. This is the input `decideTriage` and `decidePlanArchitect` judge a PROPOSED verdict on, so
 * a path missing here is a run that did the work and gets thrown away.
 *
 * SHARED BY BOTH FILING LANES (impl-ER renamed it from `triageChangedFiles` for exactly that reason).
 * The plan lane carried its own tracked-only `git diff` until then; a lane-specific name on a
 * lane-neutral helper is how this repo twice ended up with two implementations of one rule.
 *
 * WHY THE UNION, AND NOT `git diff` ALONE (impl-EO, 2026-08-01). `git diff --name-only origin/main`
 * reports TRACKED paths only; a brand-new file is untracked and is invisible to it. That was
 * harmless while a proposal EDITED the tracked `plan/tasks.yaml` monolith — and became a
 * money-burning failure the moment PR #1060 redirected proposals into a NEW shard at
 * `plan/tasks.d/<id>-<kebab-slug>.yaml`. The worker complied, wrote the shard, and returned
 * PROPOSED; `git diff` saw nothing; `decideTriage` correctly refused the run as inconsistent
 * ("PROPOSED but no plan files were changed", `changed_files: []`) and opened no PR. Two
 * auto-triage fires on `fb-alert-craigoley-remudero-code-scanning-61` failed this way at
 * $1.0547 and $1.0916, and the entry stayed `status: new` — so it would be re-picked as the
 * oldest candidate forever, at ~$1 a fire.
 *
 * `ls-files --others --exclude-standard` is the untracked half, `--exclude-standard` so an
 * ignored build artifact never counts as a plan change. Deduped because the two halves are
 * disjoint by definition and a future third source must not double-report. Detection runs BEFORE
 * the harness's bookkeeping commit, which is exactly why staging cannot be assumed.
 */
/**
 * The MERGE BASE of `origin/main` and this worktree's HEAD — the only base a "what did THIS branch
 * change" question may use.
 *
 * WHY A BARE `origin/main` IS WRONG HERE, and this is MEASURED rather than reasoned: `git diff
 * origin/main` compares the CURRENT TIP to the working tree, so the moment `origin/main` moves it
 * reports every file the incoming commits touched as though this worktree had changed it. #1535
 * fixed the same defect in `scopeGuardOutOfScopeFiles` by moving two-dot to three-dot; this is its
 * third form, and it needs an explicit merge base rather than a dot because there is no three-dot
 * spelling that compares against the WORKING TREE — and the working tree is exactly what
 * {@link worktreeChangedFiles} must see, since detection runs before the bookkeeping commit.
 *
 * AND THE REF MOVES WITHOUT ANYONE MERGING BY HAND. A git worktree shares refs with its parent
 * clone, so ANY fetch anywhere in the checkout moves `origin/main` for every worktree at once — and
 * `refreshOriginMain` (`src/lib/ci-parity.ts`) runs `git fetch origin main` INSIDE the worker's own
 * `preflight --ci-parity`, for the express purpose of refreshing the base. The fleet moves this ref
 * on itself; a human merging merely supplies the commits that fetch then picks up.
 */
function worktreeMergeBase(worktreePath: string): string {
  return hostWorktreeGit(worktreePath, ["merge-base", "origin/main", "HEAD"]).trim();
}

export function worktreeChangedFiles(worktreePath: string): string[] {
  const run = (args: string[]): string[] =>
    hostWorktreeGit(worktreePath, args)
      .split("\n")
      .map((s) => s.trim())
      .filter(Boolean);
  return [
    ...new Set([...run(["diff", "--name-only", worktreeMergeBase(worktreePath)]), ...run(["ls-files", "--others", "--exclude-standard"])]),
  ];
}

/**
 * `rmd triage <feedback-id>` — the Architect intake worker (MASTER-PLAN §7B, W1-T41).
 *
 * GROUND -> RESEARCH -> GRILL-OR-PROPOSE, run by a fresh higher-tier Architect worker
 * (lib/triage.ts's `triagePrompt`) over ONE `plan/feedback/<id>.yaml` entry, in its own worktree
 * (same isolation shape as `rmd retro`). The worker has no Bash — it only grounds/researches/edits
 * plan files; this function OWNS every commit/push/PR/gate step deterministically (same "the
 * harness eats first" split `regenerateOrientation` established for the retro's docs write), so
 * the LLM can never skip the Acceptance:/Remudero-Task: contract or open a PR touching code.
 */
/** Injectable seam (impl-BB) mirroring {@link runTask}'s own `opts` shape exactly — the
 *  same `spawn?: typeof spawnWorker` field, the same `config?: Config`, the same
 *  `?? real` defaulting inside, so this repo has ONE dependency-injection convention and
 *  not two. It exists because every line after the worker spawn in this function was
 *  unreachable from any offline test: with no seam, a test could not get past
 *  `spawnWorker` without paying for a real worker, so diff-coverage reported every added
 *  line here as uncovered whatever it contained. Passing nothing is the production
 *  contract and behaves exactly as before. */
/**
 * `rmd triage <feedback-id>` — acquires the SHARED triage lock, then delegates.
 *
 * ★ WHY THE LOCK IS HERE AND NOT ONLY IN THE DAEMON (impl-DJ). The task id is minted from a
 * SNAPSHOT before the worker runs (lib/triage.ts), so two overlapping triage runs mint the SAME id.
 * Since PR #1060 each writes its own `plan/tasks.d/<id>-<slug>.yaml` — DIFFERENT filenames, so both
 * merge CLEANLY and `loadPlan` then throws duplicate-task-id ON MAIN. Before #1060 that was a loud
 * EOF conflict; now it is a poisoned plan. The daemon loop being single-threaded only ever protected
 * daemon-vs-daemon; nothing stopped a HAND-RUN racing it, and the auto-triage rung makes that far
 * likelier because the operator cannot see the daemon is about to fire. Both paths take the same
 * lock, so whichever is second REFUSES LOUDLY instead of racing.
 */
/**
 * How many task ids `rmd triage` reserves before spawning, mirroring {@link PLAN_MAX_NEW_TASKS}'s
 * shape but scoped to what ONE feedback item plausibly produces rather than an open-ended brief:
 * triage's own prompt has always told a worker filing "MORE than one new task" to continue
 * upward from the minted id, and the overwhelming majority of runs file exactly one. A declared
 * CEILING, not a prediction — every unused id in the block is released in the same `finally` as
 * the used ones, so reserving above the common case costs nothing but a slightly wider (still
 * bounded) remote scan.
 */
export const TRIAGE_MAX_NEW_TASKS = 3;

export async function triageCommand(
  rest: string[],
  opts: { spawn?: typeof spawnWorker; config?: Config; overlap?: OverlapWarningDeps } = {},
): Promise<number> {
  const cfg = opts.config ?? loadConfig();
  const lockPath = triageLockPath(cfg.root);
  let lock: DrainLockHandle;
  try {
    lock = acquireDrainLock(lockPath);
  } catch (e) {
    if (e instanceof DrainLockError) {
      console.error(triageLockRefusalMessage(e.holder.pid, e.holder.startedAt, lockPath));
      return 2;
    }
    throw e;
  }
  try {
    return await triageCommandLocked(rest, { ...opts, config: cfg });
  } finally {
    lock.release();
  }
}

/** The refusal an operator sees when the daemon's rung (or another hand-run) holds the lock. */
export function triageLockRefusalMessage(pid: number, startedAt: string, lockPath: string): string {
  return (
    `rmd triage: REFUSED — another triage run is already in flight (pid ${pid}, started ${startedAt}). ` +
    `Two concurrent runs mint the SAME task id, and since #1060 both merge cleanly and poison the ` +
    `plan on main. Wait for it to finish, or delete ${lockPath} if that process is gone.`
  );
}

async function triageCommandLocked(
  rest: string[],
  opts: { spawn?: typeof spawnWorker; config?: Config; overlap?: OverlapWarningDeps } = {},
): Promise<number> {
  const parsed = parseTriageArgs(rest);
  if ("error" in parsed) {
    console.error(parsed.error + "\n" + USAGE);
    return 2;
  }
  const { feedbackId } = parsed;

  const config = opts.config ?? loadConfig();
  const spawn = opts.spawn ?? ledgeredNonDispatchSpawn("triage");
  const { owner, repo } = resolveOwnerRepo();

  // W1-T2559: triage ships no code and supervises no worker, so G-17's Tier Invariant — which
  // exists to keep a supervisor strictly above what it reviews — does not bind it to plan
  // authorship's tier. It rides its OWN mount (`synthesis.triage`, mounts.yaml), never
  // `architectModel`'s `architect:` row. `assertArchitectAboveWorker` is deliberately NOT called
  // here any more — see the identical note at the retro call site.
  const mountsTable = loadMounts(mountsPath(repoRoot));
  const arch = synthesisModel(mountsTable, "triage");
  const archEffort = synthesisEffort(mountsTable, "triage");
  const wrk = workerModel(config);

  const ledgerPath = ledgerPathFor(config);
  const taskId = `TRIAGE-${feedbackId}`;
  const runId = `${taskId}-${nextLaneEpochMs()}`; // W1-T2528: two same-feedbackId runs can still collide
  const log = (step: string, extra: Record<string, unknown> = {}) =>
    appendLedger(ledgerPath, { run_id: runId, task_id: taskId, step, lane: "triage", ...extra });
  const say = (msg: string) => console.log(`\n### [triage] ${msg}`);
  // W1-T2383 rank 3: the lane's own dispatch row, beside `triage.start` rather than replacing it.
  log("run.start", laneRunStartFields({ lane: "triage", repo, architect: arch, worker: wrk }));
  log("triage.start", { feedback_id: feedbackId, architect: arch, worker: wrk });
  say(`triage ${runId} — architect ${arch} over worker ${wrk} — feedback#${feedbackId}`);

  const settingsFile = renderWorkerSettings({
    templatePath: join(resolveInstallRoot(config), "settings", "worker.json"),
    hooksDir: join(resolveInstallRoot(config), "hooks"),
    outPath: join(config.root, "tmp", `triage-settings-${runId}.json`),
  });
  validateWorkerSettingsFile(settingsFile);

  const repoDir = join(config.root, "repos", repo);
  if (!existsSync(repoDir)) {
    mkdirSync(dirname(repoDir), { recursive: true });
    ghExec(["repo", "clone", `${owner}/${repo}`, repoDir], { stdio: "inherit" });
  }
  const pruned = pruneStaleRuns(repoDir, worktreesDir(config), { graceMs: DEFAULT_PRUNE_GRACE_MS });
  if (pruned.worktrees.length || pruned.branches.length || pruned.skipped.length) log("worktree.prune", { ...pruned });
  const { branch, worktreePath } = await addLaneWorktree(repoDir, worktreesDir(config), runId, log); // W1-T2528

  // W1-T348: the decision-summary rung, resolved ONCE and reused at both sites this run may
  // reach a human/operator — the GRILL escalation below and the proposal write further down.
  // Reuses risk-judge.ts's cheapest-mount scanner (via resolveDecisionSummaryMount, feedback.ts)
  // rather than a new mounts.yaml row, and the SAME cwd/settingsFile/spawn this run already
  // resolved for the Architect worker — no second model-call idiom invented. Constructing this
  // is free (no spawn happens until `.summarize()` is actually called by a grill/propose branch
  // below); a run that ends CLEAR/ALREADY_DECIDED never spends on it.
  const summarizeDeps: SummarizeDeps = {
    summarize: realDecisionSummarizer({
      mount: resolveDecisionSummaryMount(mountsTable),
      cwd: worktreePath,
      settingsFile,
      spawn,
    }),
  };

  // Declared OUTSIDE the try so the finally releases it on EVERY exit — success, throw, or the
  // catch arm's rethrow. A reservation that outlived its run would burn the id permanently, which
  // is the phantom-id class this must not add to (W1-T199/224/247/263 already exist).
  let localIdBlock: TaskIdReservationBlock | undefined;
  // W1-T1132: declared OUTSIDE the try for the SAME reason `localIdBlock` is — the finally must be
  // able to release on EVERY exit, success or throw. Only the anchor matters there: a lane that
  // LOST the claim holds nothing to release.
  let triageClaim: TriageClaimResult | undefined;
  let claimReserver: TriageClaimReserverAsync | undefined;
  // W1-T9488: the remote ids this run holds, what its pushed branch declares, and how it ended —
  // the finally gives back every id the branch does not carry.
  const triageHeld: HeldTaskIdReservation[] = [];
  let triagePushed: LanePushedIds;
  let triageEnding = "ended before a verdict";
  try {
    // Read the entry from the FRESH worktree (origin/main snapshot), not repoRoot, which may be
    // a stale checkout — same discipline retro's next-task read follows.
    let entry;
    try {
      entry = readFeedbackEntry(worktreePath, feedbackId);
    } catch (e) {
      // W1-T243: distinguish "captured locally but the durable-inbox commit bridge hasn't
      // landed it on origin/main yet" from "genuinely no such id" — before this fix both
      // printed the byte-identical "no such feedback entry: <id>", which read as a typo
      // even when the entry was simply mid-flight to its landing PR.
      const existsLocally = existsSync(feedbackEntryPath(repoRoot, feedbackId));
      const landingPrUrl = existsLocally ? findPendingLandingPr() : undefined;
      log("triage.error", {
        error: String((e as Error)?.message ?? e),
        pending_landing: existsLocally,
        landing_pr: landingPrUrl ?? null,
      });
      say(missingFeedbackMessage(feedbackId, { existsLocally, landingPrUrl }));
      worktreeRemove(repoDir, worktreePath);
      return 2;
    }
    if (entry.status !== "new") {
      log("triage.error", { error: `feedback#${feedbackId} is not status:new (already ${entry.status})` });
      say(`feedback#${feedbackId} is already ${entry.status} — refusing to re-triage; nothing to do`);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }
    await observeFeedbackInputs(config.contributorAdmission, entry.contribution ? [entry.contribution] : [], "triage-adoption", log);

    // ── THE CROSS-HOST CLAIM (W1-T1132), TAKEN BEFORE THE ARCHITECT CALL ────────────────────
    // HERE, not before the write: the loser's RESEARCH is the actual cost. Everything below this
    // line — the mint, the reservation, `runRelintLoop`'s spawn — is either cheap and local or the
    // paid Architect call itself, and the two collisions this closes (#2452/#2462, mirror-image
    // verdicts that could not merge) were two lanes that had both already spent by the time either
    // published anything a guard could read. W1-T300's open-PR guard still runs and still refuses
    // an entry whose PR is already open; this refuses the minutes-long window BEFORE that PR
    // exists, which no read of published work can see.
    //
    // AFTER the `status: new` check on purpose: an entry that is already triaged wants no claim
    // taken on it at all, and refusing it there keeps this ref namespace to entries genuinely in
    // flight.
    // `repoDir`, NOT `worktreePath` — MEASURED, not assumed. The worktree is a worktree OF this
    // clone and shares its `origin`, so both reach the same remote; but every refusal arm below
    // calls `worktreeRemove` before returning, and the release in this function's `finally` then
    // ran `git -C <deleted path>` and silently failed to drop the claim it held. The clone
    // outlives the worktree, which is what the release arm actually needs. (Still emphatically
    // not the module-level `repoRoot`: that is the INSTALL root and points at whatever remote the
    // install happened to point at — the trap the id reservation beside this already names.)
    // AWAITED (2026-10-06): this lane runs inside the daemon process, where sync claim git held the loop.
    claimReserver = triageClaimReserverAsyncFor(repoDir);
    // `mergedSubjects` is read LAZILY — only the LOSING lane ever needs it, so the winner pays
    // nothing for the evidence arm's input.
    triageClaim = await claimTriageWithLogging(log, feedbackId, claimReserver, { mergedSubjects: () => mergedTriageSubjects(repoDir) });
    if (!triageClaim.proceed) {
      say(`REFUSED — ${triageClaim.reason}`);
      worktreeRemove(repoDir, worktreePath);
      return 2;
    }

    // ID MINT (the 2/2 collision evidence: W1-T256->257 #770, W1-T260->261 #775; lineage
    // feedback#fb-1784766965325-c7b673; PLUS the W1-T278 fold class: an id filed and later
    // folded away is invisible to every current-tree source, so the mint is also floored by
    // the plan/ git history — see mintNextTaskIdWithHistory). Derived HERE, from the FRESH
    // worktree's plan (monolith + every tasks.d shard + its own git history) plus the ids
    // open plan PRs have already minted, and handed to the worker — which has no Bash tool
    // and so could never have run the grep the prompt used to describe. Ledgered with its
    // provenance so a degraded source is visible, never silent.
    const mint = mintNextTaskIdWithHistory({
      planPath: join(worktreePath, "plan", "tasks.yaml"),
      repoRoot: worktreePath,
      openPrTexts: () => openPrMintTexts(owner, repo),
    });
    // RESERVE the minted id (and TRIAGE_MAX_NEW_TASKS-1 more, as a BLOCK) before spending
    // anything. The mint above is a SNAPSHOT and reserves nothing, so a THIRD caller (the lock
    // #1069 added covers only triage's own two paths — not `rmd plan --mode=create`, not a
    // second machine, not a cross-repo instance filing into this plan) can mint the same number.
    // Contention ADVANCES rather than refusing, so this only ever moves the id upward, never
    // blocks. Taken BEFORE `spawn` on purpose: a reservation that cannot be written throws
    // TaskIdReservationError out of this command, and the paid worker (median $0.96) is never
    // started — a minter that cannot reserve must not spend.
    //
    // A BLOCK, NOT ONE ID (W1-T949 design (i)): triage's own prompt tells a worker filing more
    // than one task to "number them upward" from the minted id — so a single-id reservation left
    // every id past the first unreserved on any store, local or remote (W1-T949 rationale (2)).
    // `rmd plan` already reserves a block LOCALLY for exactly this reason; this makes triage do
    // the same, and closes the remote half `reserveTaskIdBlock`'s own doc names but does not fix.
    localIdBlock = reserveTaskIdBlock(mint.n, TRIAGE_MAX_NEW_TASKS, taskIdReservationsDir(config.root), {
      info: { purpose: `rmd triage ${feedbackId} (run ${runId})` },
    });
    // Built ONCE, here, because the reservation below now happens before the prompt rather than
    // inside the propose branch. A non-throwing runner, not `execFileSync`: a rejected push is a NORMAL
    // outcome (contention), and a throwing runner would make it indistinguishable from an
    // unreachable remote — the conflation `classifyPushFailure` exists to prevent. `worktreePath`,
    // NOT the module-level `repoRoot`: the reservation must be pushed to the SAME `origin` this
    // filing will push its branch to.
    const triageRemoteRefReserver = gatedRemoteRefReserver({ run: gitRunAdapter((args) => hostWorktreeGitResult(worktreePath, args)), lane: "triage", log });
    // W1-T2326: THE REMOTE HALF IS TAKEN HERE, BEFORE THE PROMPT IS BUILT — and that ORDERING is
    // the whole task. It used to be taken 100+ lines below, inside `decision.action === "propose"`,
    // and its result reached nothing but the `triage.id_minted` row: the worker was prompted from
    // `localIdBlock`, which starts at the ADVISORY `mint.n`. So the lane reserved one id and filed
    // under another. MEASURED over 96 `triage.id_minted` rows: 42 carried a reservation differing
    // from the advisory, and `reserved_ids[0]` was later filed 44 times against the advisory's 49 —
    // the lane's own reservation was filed LESS often than the number it did not reserve. On
    // 2026-08-26 a container reserved three ids and filed under two others one second later.
    //
    // `planCommand` below has always done it this way (`const reservedIds =
    // planRemoteIdBlock.taskIds`); this makes triage its sibling rather than its exception.
    //
    // WHAT THIS COSTS, NAMED RATHER THAN HIDDEN — IT RE-OPENS W1-T1011. That task moved this call
    // DOWN because a run that errors or resolves no_task/grill never files, while `refs/rmd-id/<id>`
    // has NO release path: it measured 21 of 64 minted ids burned by runs that filed nothing.
    // RE-MEASURED for W1-T2326: 169 `triage.start` rows against 96 `triage.id_minted`, so 73 of 169
    // runs (43%) never reach propose. At this block width that is up to 219 more permanently-held
    // ids. THE DOCTRINE ONE FILE OVER SETTLES IT — task-id-reservation.ts, in capitals: A HOLE IS
    // NOT A DEFECT; A COLLISION IS. The same doc prices the whole reservation corpus at ~24 KiB.
    // Holes are the cheap side; this buys the expensive one.
    //
    // `localIdBlock` ABOVE IS UNCHANGED AND MUST STAY: it is taken before `spawn`, so an unwritable
    // local store still throws `TaskIdReservationError` and the paid worker (median $0.96) is never
    // started — "a minter that cannot reserve must not spend". It is also the only half with a
    // release path (`localIdBlock?.releaseAll()` in the `finally`), which the remote half
    // deliberately does not have. This call only decides WHICH ids the worker is told about.
    const remoteIdBlock: RemoteReservationBlock = withIdReservationLogging(log, "triage.id_reservation_failed", () =>
      reserveTaskIdBlockRemote(localIdBlock!.ids[0], TRIAGE_MAX_NEW_TASKS, triageRemoteRefReserver),
    );
    // NAMED FOR WHAT IT IS. The old `reservedTaskId` was bound to an advisory-derived value, and
    // that name is most of why this survived review: every reader who checked "does the worker get
    // the reserved id" read it and stopped. These two are derived from the remote block only.
    triageHeld.push(...heldFromBlock(remoteIdBlock, triageRemoteRefReserver));
    const reservedIds = remoteIdBlock.taskIds;
    const reservedHeadTaskId = reservedIds[0];
    say(`next task id: ${describeMintWithHistory(mint)}`);
    if (remoteIdBlock.ids[0] !== mint.n)
      say(`reserved ${reservedHeadTaskId} instead — ${mint.id} is held by a live minter`);

    // impl-FU — THE RELINT LOOP. Spawn, lint what was actually filed with the REAL linter, hand the
    // REAL violations back, bounded. Sits AFTER `decideTriage` inside each round (a CLEAR/GRILL
    // files nothing, so there is nothing to lint and no extra turn is bought) and BEFORE any
    // commit/push/PR — which is the whole point: W1-T286 cost $1.48 and reached a PR that
    // `lint-plan` then rejected with six violations. `decideTriage` itself is UNCHANGED.
    let worker!: WorkerResult;
    // Built ONCE: the envelope's boundary is fresh per call, so a second `feedbackEntryBlock`
    // would fingerprint bytes this worker never saw. See its own doc.
    const triageFeedbackBlock = feedbackEntryBlock(entry);

    // W1-T2700: the SAME per-part fingerprint the implement rung already ledgers (W1-T2297), now on
    // the lane that actually ingests OUTSIDE text. `feedback_raw` is DECLARED external, so its
    // `envelopes` count makes an unwrapped ingestion detectable AFTER THE FACT from the ledger row
    // alone — `unwrappedExternalParts` names exactly the parts that were external, present, and
    // carried zero envelopes. A RECORD, never a gate, on the same terms as the implement call
    // above: nothing reads this to decide a dispatch, a review, or an arm.
    log("prompt.manifest", {
      parts: buildPromptManifest([
        // ONLY the external part. Re-rendering the whole prompt here just to hash it would call
        // `triagePrompt` a second time for no criterion's sake, and a second call is exactly the
        // shape that lets a future non-determinism make the manifest attest bytes nobody received.
        { name: "feedback_raw", value: triageFeedbackBlock, external: true },
      ]),
    });
    const loop = await runRelintLoop({
      lane: "triage",
      filedIds: reservedIds,
      initialPrompt: triagePrompt(entry, runId, reservedHeadTaskId, reservedIds.slice(1), triageFeedbackBlock),
      log,
      run: async (prompt, attempt) => {
        worker = await spawn({
          cwd: worktreePath,
          permissionMode: "bypassPermissions",
          settingsFile,
          model: arch, // W1-T2559: triage's own `synthesis.triage` mount, not the Architect's
          mountProvider: mountsTable.synthesis.triage.provider,
          effort: archEffort, // W1-T2559: this rung's own effort, now actually wired to the spawn
          maxTurns: mountsTable.synthesis.triage.maxTurns, // MOUNT-GOVERNED (§9/W1-T2559) — never a hardcoded literal.
          maxBudgetUsd: DEFAULT_BUDGET_USD,
          config,
          prompt,
          tools: TRIAGE_WORKER_TOOLS,
          // W1-T3749: the surface a BLOCKED auction would divert this run to — TRIAGE_WORKER_TOOLS
          // minus WebSearch, the one entry `cashCanServeToolSurface` refuses. See TRIAGE_CASH_TOOLS.
          cashTools: TRIAGE_CASH_TOOLS,
        });
        log("triage.synthesized", {
          attempt,
          session_id: worker.sessionId,
          cost_usd: worker.costUsd,
          subtype: worker.subtype,
          ...workerLedgerFields(worker),
        });
        // Ground truth: what did the worker ACTUALLY touch (before the harness's own status write)?
        const changedFiles = worktreeChangedFiles(worktreePath);
        const verdict = parseTriageVerdict(workerTranscript(worker));
        const citation = verdict?.kind === "already_decided" ? unresolvedCitationReferents(verdict.citation, worktreeCitationEvidence(worktreePath)) : undefined;
        return { decision: decideTriage({ verdict, changedFiles, citation }), changedFiles };
      },
      filed: (r) => r.decision.action === "propose",
      lint: () =>
        lintFiledTasks(worktreePath, reservedIds, {
          newMonolithIds: newMonolithIdsAgainstBase(worktreePath),
        }),
    });
    const { decision, changedFiles } = loop.decision;
    triageEnding = `verdict ${decision.action}`;
    await observeFeedbackInputs(config.contributorAdmission, entry.contribution ? [entry.contribution] : [],
      `triage-${decision.action}-adoption`, log);

    // W1-T985 — THE RARE-OVERLAP ADVISORY, AT THE POINT THE FILED SHARD IS ON DISK. The advisory
    // shipped 2026-08-16 (W1-T533) and gained its only reader the same day (W1-T917,
    // `nextTaskIdCommand`), so until now it printed ONLY for a human typing `rmd next-task-id`.
    // This lane mints and files without one.
    //
    // AFTER FILING, NEVER AT THE MINT (design (iii)): at mint time the shard does not exist, so the
    // candidate list would be empty and `overlapWarningLinesFor`'s own first statement would return
    // immediately. Reproducing that at three new call sites would ship the same defect three more
    // times.
    //
    // The candidate list is read HERE and handed in explicitly, rather than the helper going
    // looking for the shard (design (iv)) — the three lanes reach their filed shards by three
    // different routes. Nothing below can refuse the filing, change an id, or alter the exit code.
    printLaneOverlapAdvisory(
      declaredFilesForFiledIds(join(worktreePath, "plan", "tasks.yaml"), reservedIds, opts.overlap),
      owner,
      repo,
      join(worktreePath, "plan", "tasks.yaml"),
      opts.overlap,
    );

    // FAIL EARLY, AND SAY WHY. Before this, a violating filing became a PR that opened, burned CI,
    // and reported only "ci failure" — indistinguishable from a flake.
    if (loop.violations.length > 0) {
      const reason = relintRefusalMessage("triage", reservedIds, loop.violations, loop.attempts, loop.stop);
      log("triage.relint_refused", {
        stop: loop.stop,
        attempts: loop.attempts,
        checks: [...new Set(loop.violations.map((v) => v.check))],
        violations: loop.violations.map((v) => v.message),
      });
      say(reason);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }

    if (decision.action === "error") {
      log("triage.error", { error: decision.reason, changed_files: changedFiles, subtype: worker.subtype });
      say(`triage inconsistent — ${decision.reason}; leaving no PR`);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }

    // THE GRILL (W1-T42): the ONLY viable mechanism is the async needs-human issue — ★ VERIFIED
    // AskUserQuestion silently auto-resolves EMPTY with no TTY rather than stalling, and this
    // worker always runs headless via spawnWorker (LEARNINGS.md "AskUserQuestion neither works
    // headlessly nor stalls"; TRIAGE_WORKER_TOOLS above). Opened BEFORE the bookkeeping commit
    // below so the commit/PR body can cite the real issue URL.
    let grillIssueUrl: string | undefined;
    if (decision.action === "grill") {
      // W1-T348: wired at escalation creation via the escalate.ts choke point — the issue opens
      // with a validated decisionSummary when the summarizer succeeds, and degrades to exactly
      // today's raw-body issue (fail-open) on any summarizer failure.
      grillIssueUrl = await escalateWithSummary(buildGrillEscalation({ entry, decision, taskId, runId }), {
        issues: ghIssueGatewayAsync(owner, repo),
        ledgerPath,
        runId,
        ...summarizeDeps,
      });
      log("triage.grill_opened", { issue_url: grillIssueUrl, options: decision.options.length, recommendation: decision.recommendation, cause: decision.cause, unresolved: decision.unresolved });
      say(`grill opened (needs-human, ${decision.options.length} options + a recommendation): ${grillIssueUrl}`);
    }

    // ID-COLLISION GUARD (W1-T236 triple-mint, 2026-07-22): refuse a proposal whose merged plan
    // (monolith + tasks.d shards) does not load — e.g. a minted id a shard already owns — BEFORE
    // any push, with the duplicate named. See lib/triage.ts's assertProposedPlanLoads.
    if (decision.action === "propose") {
      try {
        assertProposedPlanLoads(worktreePath);
      } catch (e) {
        const reason = String((e as Error)?.message ?? e);
        log("triage.error", { error: `proposed plan does not load: ${reason}` });
        say(`triage PROPOSED an unloadable plan — ${reason}; leaving no PR`);
        worktreeRemove(repoDir, worktreePath);
        return 1;
      }
    }

    // W1-T1011 TOOK THE PERMANENT REMOTE RESERVATION HERE; W1-T2326 MOVED IT ABOVE THE PROMPT,
    // because a reservation nothing downstream reads is not a reservation. What stays here is the
    // RECORD and the CHECK: the row still fires only on a PROPOSED verdict, so its meaning ("this
    // run filed under these ids") is unchanged, and the check below is the other half of the
    // mint-and-reserve contract — reserving ids is worthless if nobody verifies the worker used
    // them. Same shape `planCommand` has had all along (`unreservedFiledIds` + `plan.id_check`).
    if (decision.action === "propose") {
      // `triage.id_minted` — the SAME ledger event this lane has always written, still fired once
      // per PROPOSED run.
      log("triage.id_minted", {
        minted_id: remoteIdBlock.taskIds[0],
        reserved_ids: remoteIdBlock.taskIds,
        mint_id: mint.id,
        // THE FALSE FRIEND, KEPT FOR ITS EXISTING READERS AND NO LONGER ALONE. This compares the
        // LOCAL block against the advisory, never RESERVED against advisory, so it read `false`
        // through both degraded rows of 2026-08-26 — anyone auditing the ledger for this defect
        // using the field named after it found nothing, twice. The field beside it answers the
        // question its name implies.
        reserved_above_mint: localIdBlock!.ids[0] !== mint.n,
        reserved_differs_from_advisory: remoteIdBlock.taskIds[0] !== mint.id,
        remote_refs: remoteIdBlock.refs,
        max_seen: mint.maxSeen,
        source_monolith: mint.sources.monolith,
        source_shards: mint.sources.shards,
        source_open_prs: mint.sources.openPrs,
        source_history: mint.historyMax,
        degraded: mint.degraded.map((d) => d.source),
      });
    }

    // Harness-owned deterministic status write (never LLM-authored) — folded into the SAME diff
    // the worker produced, mirroring regenerateOrientation's post-worker deterministic commit.
    setFeedbackStatus(worktreePath, feedbackId, decision.status);
    const commitMessage = triageCommitMessage({ decision, feedbackId, taskId, grillIssueUrl });
    // W1-T1089: route through the SAME shared stage-and-commit function `rmd plan` uses
    // (applyPlanProposalCommit, lib/plan-architect.ts) rather than triage's own inline `git
    // add -A -- plan/`, which never matched MASTER-PLAN.md (a root-level file, not under
    // plan/) — silently discarding any amendment the Architect made even though
    // triagePrompt/decideTriage/nonPlanFilesInDiff all license one. The shared function's
    // `plan/ MASTER-PLAN.md` pathspec stages the amendment; the section index is derived from
    // MASTER-PLAN.md whenever a runtime reader needs it.
    // W1-T4203: a refused commit leaves the entry at `status: new`; the row below is what stops the rung re-picking it.
    await applyPlanProposalCommitAsync(worktreePath, commitMessage, log).catch(error =>
      commitTriageOrRecordRefusal(() => { throw error; }, feedbackId, log));

    // OUTPUT VALIDATION (W1-T2326 Q2) — the PORT of `planCommand`'s `unreservedFiledIds` +
    // `plan.id_check`. Reserving ids is half the mint-and-reserve contract; this is the other half,
    // and triage never had it: did the worker actually file under the ids we hold?
    //
    // PLACED AFTER THE COMMIT, AND A TEST IS WHY. Before it, the worker's shard is UNTRACKED, and
    // `git diff` does not report untracked files — so the check read a clean diff and passed
    // VACUOUSLY on a genuine mismatch. `planCommand` runs its own copy post-commit for exactly this
    // reason. MERGE BASE, not the moving tip (its comment again): a bare `origin/main` here made a
    // shard landed by SOMEONE ELSE's PR read as an id THIS worker filed.
    //
    // REPORT-ONLY BY CONSTRUCTION, matching its sibling's posture: an unreserved id is not
    // necessarily a collision, `lint-plan`'s duplicate-id check already refuses a real one
    // downstream, and this lane must not gain a new refusal — an intake rung that stops on an
    // advisory finding is a worse failure than a rare collision. It decides nothing, refuses
    // nothing and escalates nothing; it makes the divergence legible at the moment it happens,
    // which is exactly what the three collisions of 2026-08-26 lacked.
    if (decision.action === "propose") {
      const triageDiff = hostWorktreeGit(worktreePath, ["diff", worktreeMergeBase(worktreePath), "--", "plan"], { maxBuffer: 64 * 1024 * 1024 });
      const unreserved = unreservedFiledIds(triageDiff, reservedIds);
      log("triage.id_check", { reserved: reservedIds, unreserved, ok: unreserved.length === 0 });
      if (unreserved.length > 0) {
        say(`warning: triage worker filed unreserved id(s): ${unreserved.join(", ")} (reserved: ${reservedIds.join(", ")})`);
      }
    }

    await observeFeedbackPublication(config.contributorAdmission === undefined ? undefined : { mode: "shadow", record: log },
      entry.contribution ? [entry.contribution] : [], `${owner}/${repo}`, "triage-publication");
    triagePushed = "unknown"; // W1-T9488: a push that throws leaves the branch's ids unknowable
    await gitPushRunBranchAsync(worktreePath);
    triagePushed = pushedBranchIds(worktreePath, log);

    // The title is the SAME header string that just went into the commit, split off
    // its first line — never a second computation (W1-T327 design point ii).
    const prCreate = ghPrCreateFillCommand(worktreePath, owner, repo, branch, commitMessage.split("\n")[0], undefined, undefined, { log });
    const prUrl = runGhPrCreate(prCreate, branch, log, say).prUrl;
    if (!prUrl) {
      log("triage.error", { error: "no PR opened" });
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }

    // RUN-OWNERSHIP GUARD (W1-T62 precedent) — before any side effect touches this PR, assert it
    // is actually this triage run's own PR.
    const ownership = checkPrOwnership(prUrl, branch, ghPrHeadGateway(), worker.costUsd, worker.accountLabel);
    if (ownership) {
      log("verdict", ownership.ledger);
      say(`verdict: pr_attribution_failed — claimed PR ${prUrl} is not this triage's own branch (${branch})`);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }
    ensureTaskTrailer(prUrl, taskId, log);

    // Record the proposal_pr back onto the entry for the propose path (chicken-and-egg: the PR
    // URL only exists after the first push) — a second small commit onto the SAME open PR,
    // exactly the pattern retro's post-worker orientation commit already established.
    if (decision.action === "propose") {
      // W1-T348: writes the validated decision summary onto the feedback entry it proposes
      // from, in the SAME write as the `proposed` status transition (never half-written) —
      // fail-open to `summary: null` on any summarizer failure, exactly as before this task.
      await proposeFeedbackWithSummary(worktreePath, feedbackId, summarizeDeps, { proposalPr: prUrl });
      hostWorktreeGit(worktreePath, ["add", "-A", "--", "plan/feedback/"], { stdio: "inherit-stdout" });
      hostWorktreeGit(worktreePath, ["commit", "-m", `chore(triage): record proposal_pr for feedback#${feedbackId}`], { stdio: "inherit-stdout" });
      await gitPushRunBranchAsync(worktreePath);
    }

    // DETERMINISTIC GUARD: a triage PR is PLAN-ONLY. Fail closed if the diff touches anything
    // outside plan/ (lib/triage.ts's `nonPlanFilesInDiff`, the same shape as retro's guard).
    const diff = ghExec(["pr", "diff", prUrl], { encoding: "utf8", maxBuffer: 1 << 26 });
    const strayFiles = nonPlanFilesInDiff(diff);
    if (strayFiles.length > 0) {
      log("triage.error", { error: "triage PR is NOT plan-only", stray_files: strayFiles });
      say(`triage PR touched non-plan file(s) (${strayFiles.join(", ")}) — leaving PR OPEN for inspection`);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }
    if (decision.action === "propose" && !diffCitesFeedback(diff, feedbackId)) {
      log("triage.error", { error: "proposed diff missing feedback# provenance" });
      say(`triage PROPOSED but the diff never cites feedback#${feedbackId} — leaving PR OPEN for inspection`);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }
    log("pr.opened", { pr_url: prUrl, plan_only: true, action: decision.action });
    say(`triage PR (plan-only, ${decision.action}): ${prUrl}`);

    // Gate: ci green -> post remudero-review -> arm auto-merge (identical shape to every other
    // Architect skill's output — "PROPOSES anything, MERGES nothing" until the gate clears it).
    const ci = ciGateState(await waitForCiGreen(prUrl, (s, extra) => log(s, extra)));
    if (ci !== "green") {
      say(`ci ${ci} — PR left OPEN: ${prUrl}`);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }

    // W1-T963 (empty-diff-triage-merge incident: #2075/#2077/#2078 merged and passed review
    // despite changing nothing). `diff` above is `gh pr diff` — frozen against THIS branch's own
    // fork point, so it stays non-empty even once a SIBLING triage PR for the SAME feedback entry
    // has already landed the identical change on `origin/main`. Re-diff the declared scope (the
    // feedback entry this decision writes) against a FRESH fetch of the LIVE default branch tip
    // instead — `no_task`/`grill` only: a `propose` decision's entire contribution is never just
    // this one file (it also adds a new plan/tasks.d/ shard), so this narrower scope would refuse
    // a genuinely-new proposal whose feedback-file edit happens to look identical to a sibling's.
    if (decision.action !== "propose") {
      const scopeFiles = triageDeclaredScope(feedbackId);
      let liveDiffFiles: string[] | undefined;
      try {
        hostWorktreeGit(worktreePath, ["fetch", "origin", "main"], { stdio: "inherit-stdout" });
        liveDiffFiles = hostWorktreeGit(worktreePath, ["diff", "--name-only", "origin/main", "HEAD", "--", ...scopeFiles])
          .split("\n")
          .map((l) => l.trim())
          .filter(Boolean);
      } catch (e) {
        // Fail OPEN, never a false positive (mirrors buildBaseProofDir's own "unresolvable base ⇒
        // no staleness signal"): an unreadable/unfetchable live tip is never treated as "already done".
        log("triage.live_scope_check_error", { error: String((e as Error)?.message ?? e) });
      }
      const disposition = liveDiffFiles !== undefined ? triageEmptyScopeDisposition(liveDiffFiles, scopeFiles) : undefined;
      if (disposition?.action === "close") {
        log("triage.already_done", { scope: scopeFiles });
        say(
          `triage PR's declared scope (${scopeFiles.join(", ")}) is EMPTY against the LIVE origin/main — ` +
            `a sibling triage PR already landed this change; closing rather than merging: ${prUrl}`,
        );
        ghExec(["pr", "close", prUrl, "--comment", disposition.comment!], { stdio: "inherit" });
        worktreeRemove(repoDir, worktreePath);
        return 0; // terminal, deliberate — the work is already done, not a failure (design (v))
      }
    }

    const prNum = prUrl.match(/\/pull\/(\d+)/)?.[1] ?? prUrl;
    const reviewCode = await reviewCommand(prNum);
    // W1-T230: reviewCommand resolved this PR's task id off its own
    // `Remudero-Task: <taskId>` trailer (ensureTaskTrailer above), so its
    // review.posted ledger line is keyed to the SAME `taskId` armAutoMerge
    // must pass to find it.
    // W1-T2258: this lane holds no headSha variable of its own — `readHeadShaRest(prUrl)` is
    // the SAME live REST read `reviewCommand` (just above) already made to post its own
    // `review.posted` line, best-effort here too: a failed read leaves the row unjoinable,
    // exactly as it is today, never blocking the arm itself.
    let armHeadSha: string | undefined;
    try {
      armHeadSha = readHeadShaRest(prUrl);
    } catch {
      /* best-effort — see the comment above */
    }
    const armOutcome = armAndLogOutcome(prUrl, taskId, log, undefined, undefined, armHeadSha);
    worktreeRemove(repoDir, worktreePath);
    // W1-T968: the PR — not merely this call — is what the console line answers about; a
    // review-lane arm already ledgered moments earlier on this SAME head must still read as armed.
    const priorArm = priorArmOnHead(readLedgerLines(ledgerPath), prUrl, armHeadSha);
    say(`triage PR gated — ${armReportPhrase(armOutcome, priorArm)} (review ${reviewCode === 0 ? "success" : "failure"}): ${prUrl}`);
    return reviewCode;
  } catch (e) {
    log("triage.error", { error: String((e as Error)?.message ?? e) });
    triageEnding = `errored: ${String((e as Error)?.message ?? e).slice(0, 160)}`;
    try {
      worktreeRemove(repoDir, worktreePath);
    } catch {
      /* best-effort */
    }
    throw e;
  } finally {
    removeRunLock(worktreePath); // terminal ⇒ drop the liveness token
    // W1-T9488: the REMOTE half is given back too — every reserved id the pushed branch does not declare.
    releaseUnfiledReservations(triageHeld, triagePushed, {
      run: gitRunAdapter((args) => hostWorktreeGitResult(repoDir, args)), lane: "triage", log,
      reason: laneReleaseReason(`triage ${feedbackId}`, triageEnding, triagePushed),
    });
    // Every LOCAL id is now either ON an open PR (where the mint's openPrs source sees it) or
    // unused and free to reissue. Either way holding the file longer protects nothing — release
    // the WHOLE block, used or not, exactly as `rmd plan`'s block does (a hole is not a defect;
    // see task-id-reservation.ts's own doctrine). The REMOTE half is released just above
    // (W1-T9488), for every id the pushed branch does not declare.
    localIdBlock?.releaseAll();
    // W1-T1132 RELEASE ARM 1 (HOLDER): explicit, on completion, success or throw — never a timer.
    // Guarded on the ANCHOR rather than on `triageClaim` being set: a lane that refused because
    // the claim was already taken holds nothing, and calling the release there would ask the
    // decision a question it has already answered on the contention path.
    if (triageClaim?.anchor !== undefined && claimReserver !== undefined)
      await releaseTriageClaimWithLogging(log, feedbackId, claimReserver, triageClaim.anchor);
  }
}

/**
 * The unified PLAN Architect worker's tool allowlist (`.remudero/skills/plan.yaml`), minus
 * `AskUserQuestion` and `Bash`: same deferral `TRIAGE_WORKER_TOOLS` already documents — v1
 * never grills interactively (LEARNINGS "no live operator in a headless worker"; the actual
 * grill delivery is W1-T42's job, which W1-T45 does not depend on), and the harness — never
 * the LLM — owns every git/gh step.
 */
const PLAN_WORKER_TOOLS = ["Read", "Write", "Edit", "Grep", "Glob", "WebSearch", "WebFetch"];

/**
 * `rmd plan --mode=create|clarify|expand [<brief>...]` — the unified Architect PLAN skill
 * (MASTER-PLAN §5B, W1-T45): ONE code path (lib/plan-architect.ts's `planArchitectPrompt` /
 * `parsePlanVerdict` / `decidePlanArchitect` — each a single definition, no per-mode copy)
 * shared by all three modes, run by a fresh higher-tier Architect worker in its own worktree
 * (same isolation shape as `rmd triage`/`rmd retro`). The worker has no Bash — it only
 * grounds/researches/edits plan-scope files; this function OWNS every commit/push/PR/gate step
 * deterministically, so the LLM can never skip the Acceptance:/Remudero-Task: contract or open
 * a PR touching code. CLEAR and GRILL verdicts touch nothing and open no PR — there is no
 * per-item status file to update here (unlike triage's feedback entry), so only a PROPOSED
 * verdict reaches the commit/push/PR/gate machinery below.
 */
/** Injectable seam (impl-BB) mirroring {@link runTask}'s own `opts` shape exactly — the
 *  same `spawn?: typeof spawnWorker` field, the same `config?: Config`, the same
 *  `?? real` defaulting inside, so this repo has ONE dependency-injection convention and
 *  not two. It exists because every line after the worker spawn in this function was
 *  unreachable from any offline test: with no seam, a test could not get past
 *  `spawnWorker` without paying for a real worker, so diff-coverage reported every added
 *  line here as uncovered whatever it contained. Passing nothing is the production
 *  contract and behaves exactly as before. */
/**
 * How many task ids `rmd plan` reserves before spawning.
 *
 * The lane files "one or more" tasks and the count is unknowable until the worker runs, so this is a
 * declared CEILING rather than a prediction: the worker is told it may file at most this many, and
 * every unused id is released in the same `finally` as the used ones. Five is chosen to be larger
 * than any plan run this repo has produced (the largest single filing to date is the 8-task session
 * harvest, which was a HAND filing, not a `rmd plan` run) while staying small enough that a crashed
 * run holds a trivial slice of the id space until the next acquirer reclaims it lazily.
 */
export const PLAN_MAX_NEW_TASKS = 5;

export async function planCommand(
  rest: string[],
  opts: { spawn?: typeof spawnWorker; config?: Config; overlap?: OverlapWarningDeps } = {},
): Promise<number> {
  const parsed = parsePlanArgs(rest);
  if ("error" in parsed) {
    console.error(parsed.error + "\n" + USAGE);
    return 2;
  }
  const { mode, brief } = parsed;

  const config = opts.config ?? loadConfig();
  const spawn = opts.spawn ?? ledgeredNonDispatchSpawn("plan");
  const { owner, repo } = resolveOwnerRepo();

  // G-17 Tier Invariant: the plan Architect MUST outrank implement workers.
  const mountsTable = loadMounts(mountsPath(repoRoot));
  const arch = architectModel(config, mountsTable);
  const wrk = workerModel(config);
  assertArchitectAboveWorker(arch, wrk); // throws (fail-closed) on violation

  const ledgerPath = ledgerPathFor(config);
  const taskId = `PLAN-${mode}`;
  const runId = `${taskId}-${nextLaneEpochMs()}`; // W1-T2528: two same-mode runs can still collide
  const log = (step: string, extra: Record<string, unknown> = {}) =>
    appendLedger(ledgerPath, { run_id: runId, task_id: taskId, step, lane: "plan", ...extra });
  const say = (msg: string) => console.log(`\n### [plan] ${msg}`);
  log("plan.start", { mode, brief, architect: arch, effort: mountsTable.architect.effort, worker: wrk });
  say(`plan ${runId} — mode=${mode} — architect ${arch} over worker ${wrk}`);

  const settingsFile = renderWorkerSettings({
    templatePath: join(resolveInstallRoot(config), "settings", "worker.json"),
    hooksDir: join(resolveInstallRoot(config), "hooks"),
    outPath: join(config.root, "tmp", `plan-settings-${runId}.json`),
  });
  validateWorkerSettingsFile(settingsFile);

  const repoDir = join(config.root, "repos", repo);
  if (!existsSync(repoDir)) {
    mkdirSync(dirname(repoDir), { recursive: true });
    ghExec(["repo", "clone", `${owner}/${repo}`, repoDir], { stdio: "inherit" });
  }
  const pruned = pruneStaleRuns(repoDir, worktreesDir(config), { graceMs: DEFAULT_PRUNE_GRACE_MS });
  if (pruned.worktrees.length || pruned.branches.length || pruned.skipped.length) log("worktree.prune", { ...pruned });
  const { branch, worktreePath } = await addLaneWorktree(repoDir, worktreesDir(config), runId, log); // W1-T2528

  let planIdBlock: TaskIdReservationBlock | undefined;
  // W1-T9488: see the triage lane's twin — the remote ids held, what the pushed branch declares, how it ended.
  const planHeld: HeldTaskIdReservation[] = [];
  let planPushed: LanePushedIds;
  let planEnding = "ended before a verdict";

  try {
    // ID MINT + BLOCK RESERVATION (impl-DV), the SAME ordering triage uses at :10222-:10240: mint
    // from the FRESH worktree's plan, reserve BEFORE spawning, hand the worker ids it cannot
    // collide on. Until now this lane minted NOTHING — `planArchitectPrompt` received no id, so its
    // worker chose one by reading the plan files, and nothing could reserve what was never minted.
    //
    // A BLOCK, NOT ONE ID, because this lane files "one or more" tasks (plan-architect.ts's PROPOSED
    // wording in every mode) and the count is unknowable until the worker has run. Reserving a
    // bounded block up front is the only ordering that both refuses cheaply on collision and leaves
    // no id stranded — every id, used or not, is released in the `finally` below.
    const mint = mintNextTaskIdWithHistory({
      planPath: join(worktreePath, "plan", "tasks.yaml"),
      repoRoot: worktreePath,
      openPrTexts: () => openPrMintTexts(owner, repo),
    });
    planIdBlock = reserveTaskIdBlock(mint.n, PLAN_MAX_NEW_TASKS, taskIdReservationsDir(config.root), {
      info: { purpose: `rmd plan --mode=${mode} (run ${runId})` },
    });
    // W1-T949: AND RESERVE THE SAME BLOCK WHERE EVERY OTHER WRITER CAN SEE IT — the local block
    // above resolves under this process's own `config.root`, a worker-sandbox path discarded on
    // exit; two writers on two hosts never observe each other there. `reserveTaskIdBlockRemote`
    // is the remote-substrate twin of `reserveTaskIdBlock`, one ref pushed per reserved id. An
    // unreachable origin THROWS (caught below, a durable ledger event, never just a stringified
    // message) rather than falling through — the paid worker is still unstarted when it does.
    // Same closure-narrowing reason as the triage lane above.
    const planReserveFrom = planIdBlock.ids[0];
    // Same non-throwing runner over `worktreePath` triage's own remote reserve uses — a
    // rejected push is NORMAL here (contention), so a throwing runner would make it
    // indistinguishable from an unreachable remote.
    const planRemoteReserver = gatedRemoteRefReserver({
      lane: "plan", log,
      run: gitRunAdapter((args) => hostWorktreeGitResult(worktreePath, args)),
    });
    const planRemoteIdBlock: RemoteReservationBlock = withIdReservationLogging(log, "plan.id_reservation_failed", () =>
      reserveTaskIdBlockRemote(planReserveFrom, PLAN_MAX_NEW_TASKS, planRemoteReserver),
    );
    planHeld.push(...heldFromBlock(planRemoteIdBlock, planRemoteReserver));
    const reservedIds = planRemoteIdBlock.taskIds;
    log("plan.id_minted", {
      reserved: reservedIds,
      mint_id: mint.id,
      reserved_above_mint: planIdBlock.ids[0] !== mint.n,
      remote_refs: planRemoteIdBlock.refs,
      max_seen: mint.maxSeen,
      degraded: mint.degraded.map((d) => d.source),
    });
    say(`reserved ${reservedIds.length} task id(s): ${reservedIds.join(", ")}`);

    // impl-FU — THE RELINT LOOP, the same shared runner the triage lane and the inbox draft rung
    // use. This lane has NEVER EXECUTED, so it has never paid for the class this prevents — but its
    // prompt drifted from `monolith-filing` for a fortnight, and the next drift will be found the
    // same way unless the linter itself is in the loop. `decidePlanArchitect` is UNCHANGED.
    let worker!: WorkerResult;
    const loop = await runRelintLoop({
      lane: "plan",
      filedIds: reservedIds,
      initialPrompt: planArchitectPrompt(mode, brief, runId, reservedIds),
      log,
      run: async (prompt, attempt) => {
        worker = await spawn({
          cwd: worktreePath,
          permissionMode: "bypassPermissions",
          settingsFile,
          model: arch, // the Architect tier
          effort: mountsTable.architect.effort,
          maxTurns: mountsTable.architect.maxTurns, // MOUNT-GOVERNED (§9) — never a hardcoded literal.
          maxBudgetUsd: DEFAULT_BUDGET_USD,
          config,
          prompt,
          tools: PLAN_WORKER_TOOLS,
        });
        log("plan.synthesized", {
          attempt,
          session_id: worker.sessionId,
          cost_usd: worker.costUsd,
          subtype: worker.subtype,
          ...workerLedgerFields(worker),
        });
        const changed = worktreeChangedFiles(worktreePath);
        return { decision: decidePlanArchitect({ verdict: parsePlanVerdict(workerTranscript(worker)), changedFiles: changed }), changedFiles: changed };
      },
      filed: (r) => r.decision.action === "propose",
      // Only the ids THIS run reserved — the plan carries 193 tasks that already fail the linter.
      lint: () => lintFiledTasks(worktreePath, reservedIds, { newMonolithIds: newMonolithIdsAgainstBase(worktreePath) }),
    });

    // Ground truth: what did the worker ACTUALLY touch, INCLUDING files it CREATED (impl-ER).
    // This lane carried the tracked-only `git diff` that PR #1100 replaced in the triage lane, and it
    // is the same defect: a plan worker that files a NEW shard under `plan/tasks.d/` writes an
    // UNTRACKED path, `git diff` reports nothing, and `decidePlanArchitect` refuses a correct run as
    // "PROPOSED but no plan files were changed". `.remudero/skills/plan.yaml`'s own PROPOSED wording
    // directs the worker to add tasks, and PR #1074's monolith-filing rule pushes those into shards —
    // so the created-file case is the NORMAL one here, not an edge.
    const { decision, changedFiles } = loop.decision;
    planEnding = `verdict ${decision.action}`;

    // W1-T985 — THE RARE-OVERLAP ADVISORY, AT THE POINT THE FILED SHARD IS ON DISK. The advisory
    // shipped 2026-08-16 (W1-T533) and gained its only reader the same day (W1-T917,
    // `nextTaskIdCommand`), so until now it printed ONLY for a human typing `rmd next-task-id`.
    // This lane mints and files without one.
    //
    // AFTER FILING, NEVER AT THE MINT (design (iii)): at mint time the shard does not exist, so the
    // candidate list would be empty and `overlapWarningLinesFor`'s own first statement would return
    // immediately. Reproducing that at three new call sites would ship the same defect three more
    // times.
    //
    // The candidate list is read HERE and handed in explicitly, rather than the helper going
    // looking for the shard (design (iv)) — the three lanes reach their filed shards by three
    // different routes. Nothing below can refuse the filing, change an id, or alter the exit code.
    printLaneOverlapAdvisory(
      declaredFilesForFiledIds(join(worktreePath, "plan", "tasks.yaml"), reservedIds, opts.overlap),
      owner,
      repo,
      join(worktreePath, "plan", "tasks.yaml"),
      opts.overlap,
    );

    // FAIL EARLY, AND SAY WHY — see the triage lane's twin of this block.
    if (loop.violations.length > 0) {
      const reason = relintRefusalMessage("plan", reservedIds, loop.violations, loop.attempts, loop.stop);
      log("plan.relint_refused", {
        stop: loop.stop,
        attempts: loop.attempts,
        checks: [...new Set(loop.violations.map((v) => v.check))],
        violations: loop.violations.map((v) => v.message),
      });
      say(reason);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }

    // OUTPUT VALIDATION (impl-DV): did the worker actually FILE under the ids we reserved? Reserving
    // is half a contract; this is the other half. Report-only on purpose — see `unreservedFiledIds`.
    if (decision.action === "propose") {
      // MERGE BASE, not the moving tip — see `worktreeMergeBase`. A bare `origin/main` here made a
      // plan shard landed by SOMEONE ELSE's PR read as an id THIS worker filed, so the unreserved-id
      // warning named ids the run never touched.
      const planDiff = hostWorktreeGit(worktreePath, ["diff", worktreeMergeBase(worktreePath), "--", "plan"], { maxBuffer: 64 * 1024 * 1024 });
      const unreserved = unreservedFiledIds(planDiff, reservedIds);
      log("plan.id_check", { reserved: reservedIds, unreserved, ok: unreserved.length === 0 });
      if (unreserved.length > 0) {
        say(`warning: plan worker filed unreserved id(s): ${unreserved.join(", ")} (reserved: ${reservedIds.join(", ")})`);
      }
    }

    if (decision.action === "error") {
      log("plan.error", { error: decision.reason, changed_files: changedFiles, subtype: worker.subtype });
      say(`plan inconsistent — ${decision.reason}; leaving no PR`);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }

    if (decision.action === "no_action") {
      log("plan.verdict", { action: "no_action", detail: decision.detail });
      say(formatPlanVerdictLine(mode, decision));
      worktreeRemove(repoDir, worktreePath);
      return 0;
    }

    if (decision.action === "grill") {
      // THE GRILL (W1-T42/W1-T354): the ledger line above is written UNCONDITIONALLY, before any
      // escalation attempt, so a delivery failure below degrades to exactly today's behavior
      // (ledger + console line + clean exit) rather than losing the record — see this task's
      // twin, triageCommand's THE GRILL block a few hundred lines up.
      log("plan.verdict", { action: "grill", detail: decision.detail });
      say(formatPlanVerdictLine(mode, decision));
      try {
        const issueUrl = await escalateWithSummary(buildPlanGrillEscalation({ decision, mode, brief, taskId, runId }), {
          issues: ghIssueGatewayAsync(owner, repo),
          ledgerPath,
          runId,
          summarize: realDecisionSummarizer({
            mount: resolveDecisionSummaryMount(mountsTable),
            cwd: worktreePath,
            settingsFile,
            spawn,
          }),
        });
        log("plan.grill_opened", { issue_url: issueUrl });
        say(`grill opened (needs-human): ${issueUrl}`);
      } catch (err) {
        // FAIL-OPEN (tryEscalate's discipline, inlined here since escalateWithSummary is async
        // and tryEscalate is not): a failed delivery never turns the grill into a crash — the
        // plan.verdict ledger line above already recorded the outcome, so this is a missed
        // issue, not a missed record.
        appendLedger(ledgerPath, {
          run_id: runId,
          task_id: taskId,
          step: "escalation.failed",
          class: "GRILL",
          error: String((err as Error)?.message ?? err),
        });
      }
      worktreeRemove(repoDir, worktreePath);
      return 0;
    }

    // propose
    log("plan.verdict", { action: "propose", detail: decision.detail, files: decision.files });
    say(formatPlanVerdictLine(mode, decision));
    const commitMessage = planCommitMessage({ decision, mode, brief });
    applyPlanProposalCommit(worktreePath, commitMessage, log);
    // Build the body only AFTER the shared commit writer has staged the plan sources. The
    // changed-files block is an assertion about the actual commit, not the worker's pre-harness
    // advisory list; constructing it before regeneration would immediately make the PR contradict
    // its own diff whenever the index changes.
    const planPrFiles = hostWorktreeGit(worktreePath, ["diff", "--name-only", worktreeMergeBase(worktreePath), "HEAD"], { maxBuffer: 64 * 1024 * 1024 })
      .split("\n")
      .map((line) => line.trim())
      .filter(Boolean);
    const planPrBody = buildPlanPrBody({
      intro: `rmd plan --mode=${mode} proposed plan-only changes.\n\nOperator brief\n\n${brief || "(none — whole-plan scope)"}`,
      criteria: filingAcceptanceCriteria(reservedIds, planPrFiles),
      changedFiles: planPrFiles,
      proofCwd: worktreePath,
    });
    planPushed = "unknown"; // W1-T9488: a push that throws leaves the branch's ids unknowable
    await gitPushRunBranchAsync(worktreePath);
    planPushed = pushedBranchIds(worktreePath, log);

    // The title is the SAME header string that just went into the commit, split off
    // its first line — never a second computation (W1-T327 design point ii).
    const prCreate = ghPrCreateFillCommand(worktreePath, owner, repo, branch, commitMessage.split("\n")[0], planPrBody, undefined, { log });
    const prUrl = runGhPrCreate(prCreate, branch, log, say).prUrl;
    if (!prUrl) {
      log("plan.error", { error: "no PR opened" });
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }

    // RUN-OWNERSHIP GUARD (W1-T62 precedent) — before any side effect touches this PR, assert it
    // is actually this plan run's own PR.
    const ownership = checkPrOwnership(prUrl, branch, ghPrHeadGateway(), worker.costUsd, worker.accountLabel);
    if (ownership) {
      log("verdict", ownership.ledger);
      say(`verdict: pr_attribution_failed — claimed PR ${prUrl} is not this plan run's own branch (${branch})`);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }
    // DETERMINISTIC GUARDS: a plan PR is PLAN-ONLY (plan/** or MASTER-PLAN.md), and an EXPAND
    // proposal must cite a research source (lib/plan-architect.ts's `outOfPlanScopeFilesInDiff`
    // / `diffCitesResearchSource`, the same shape as triage's plan-only + provenance guards).
    const diff = ghExec(["pr", "diff", prUrl], { encoding: "utf8", maxBuffer: 1 << 26 });
    const strayFiles = outOfPlanScopeFilesInDiff(diff);
    if (strayFiles.length > 0) {
      log("plan.error", { error: "plan PR is NOT plan-only", stray_files: strayFiles });
      say(`plan PR touched file(s) outside plan scope (${strayFiles.join(", ")}) — leaving PR OPEN for inspection`);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }
    if (mode === "expand" && !diffCitesResearchSource(diff)) {
      log("plan.error", { error: "expand diff missing a research-source citation" });
      say(`plan --mode=expand PROPOSED but the diff cites no research source (URL) — leaving PR OPEN for inspection`);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }
    log("pr.opened", { pr_url: prUrl, plan_only: true, mode });
    say(`plan PR (plan-only, --mode=${mode}): ${prUrl}`);

    // Gate: ci green -> post remudero-review -> arm auto-merge (identical shape to every other
    // Architect skill's output — "PROPOSES anything, MERGES nothing" until the gate clears it).
    const ci = ciGateState(await waitForCiGreen(prUrl, (s, extra) => log(s, extra)));
    if (ci !== "green") {
      say(`ci ${ci} — PR left OPEN: ${prUrl}`);
      worktreeRemove(repoDir, worktreePath);
      return 1;
    }
    const prNum = prUrl.match(/\/pull\/(\d+)/)?.[1] ?? prUrl;
    const reviewCode = await reviewCommand(prNum);
    // W1-T230: reviewCommand resolved this PR's task id off its own
    // `Remudero-Task: <taskId>` trailer (ensureTaskTrailer above), so its
    // review.posted ledger line is keyed to the SAME `taskId` armAutoMerge
    // must pass to find it.
    // W1-T2258: this lane holds no headSha variable of its own — `readHeadShaRest(prUrl)` is
    // the SAME live REST read `reviewCommand` (just above) already made to post its own
    // `review.posted` line, best-effort here too: a failed read leaves the row unjoinable,
    // exactly as it is today, never blocking the arm itself.
    let armHeadSha: string | undefined;
    try {
      armHeadSha = readHeadShaRest(prUrl);
    } catch {
      /* best-effort — see the comment above */
    }
    const armOutcome = armAndLogOutcome(prUrl, taskId, log, undefined, undefined, armHeadSha);
    worktreeRemove(repoDir, worktreePath);
    // W1-T968: the PR — not merely this call — is what the console line answers about; a
    // review-lane arm already ledgered moments earlier on this SAME head must still read as armed.
    const priorArm = priorArmOnHead(readLedgerLines(ledgerPath), prUrl, armHeadSha);
    say(`plan PR gated — ${armReportPhrase(armOutcome, priorArm)} (review ${reviewCode === 0 ? "success" : "failure"}): ${prUrl}`);
    return reviewCode;
  } catch (e) {
    log("plan.error", { error: String((e as Error)?.message ?? e) });
    planEnding = `errored: ${String((e as Error)?.message ?? e).slice(0, 160)}`;
    try {
      worktreeRemove(repoDir, worktreePath);
    } catch {
      /* best-effort */
    }
    throw e;
  } finally {
    removeRunLock(worktreePath); // terminal ⇒ drop the liveness token
    // W1-T9488: the REMOTE half is given back too — every reserved id the pushed branch does not declare.
    releaseUnfiledReservations(planHeld, planPushed, {
      run: gitRunAdapter((args) => hostWorktreeGitResult(repoDir, args)), lane: "plan", log,
      reason: laneReleaseReason("plan", planEnding, planPushed),
    });
      // Release EVERY reserved id — the ones the worker filed AND the ones it declined. Once the
      // PR exists the mint sees those ids via openPrMintTexts, so holding them longer would only
      // punch holes in the id space (the phantom-id trap: W1-T199/224/247/263).
      planIdBlock?.releaseAll();
  }
}

/** The bounded inbox-draft Architect worker's tool allowlist: Read/Grep/Glob ONLY — no
 *  Write/Edit/Bash. Drafting is TEXT the harness parses/caches state-side (never
 *  committed), so unlike `rmd triage`/`rmd plan` this worker never touches a file. */
const INBOX_DRAFT_WORKER_TOOLS = ["Read", "Grep", "Glob"];

/**
 * Build the one inbox-draft worker request from its resolved mount.  Keeping this as a pure
 * boundary makes the mount affinity observable without creating a worktree or attempting a
 * paid spawn; {@link draftProposalBatch} remains the only production caller.
 */
export function buildInboxDraftSpawnArgs(args: {
  cwd: string;
  settingsFile: string;
  prompt: string;
  mount: Mount;
  config: Config;
  disallowedTools: readonly string[];
  proposalId?: string;
  proposal?: Proposal;
  currentPlanText?: string;
  draftRoutingLog?: (step: string, extra?: Record<string, unknown>) => void;
  draftRoutingReadStats?: () => DraftStats;
  avoidModels?: readonly string[];
}): SpawnWorkerArgs {
  const registryIntent = selectedRegistryIntentForConfig(args.config), registryRecord = args.draftRoutingLog;
  return {
    // The one worktree below is shared by every draft lane, so enforce the read-only tool
    // surface at the spawn boundary rather than asking the worker to respect prose.
    ...buildInboxDraftWorkerArgs({ ...args, maxBudgetUsd: DEFAULT_BUDGET_USD, tools: INBOX_DRAFT_WORKER_TOOLS }),
    onSelectionAssignment: (assignment) => ledgerNonDispatchAssignment("inbox-draft", assignment, args.config),
    ...(registryRecord && args.proposalId ? { draftRouting: {
      lane: "inbox-draft",
      proposalId: args.proposalId,
      log: registryRecord,
      readStats: args.draftRoutingReadStats,
      evaluate: (worker: WorkerResult) => withSelectedRegistryContextSync(selectedRegistryObserverFromIntent(registryIntent, registryRecord), () => {
        const parsed = parseDraftedCandidate(workerTranscript(worker), args.proposal, args.currentPlanText);
        const facts = checkoutRepoFacts(args.cwd);
        return { contractFailed: parsed === null,
          clean: parsed !== null && (parsed.releaseTaskId !== undefined || lintDraftedFragment(parsed.fragmentYaml,
            args.proposalId!, parsed.stampLine, undefined, facts.moduleExists, facts.readGrepProofFile,
            facts.pathIsDirectory, facts.pathExistsAtBase).length === 0) };
      }),
    } } : {}),
  };
}

/** A cash draft's one Sonnet rescue, admitted against the live subscription reserve before the explicit Claude mount. */
export async function spawnEscalatedInboxDraft(
  args: Parameters<typeof buildInboxDraftSpawnArgs>[0],
  rawSpawn: typeof spawnWorker = spawnWorker,
  readCapacity: (config: Config) => Promise<ProviderCapacity> = (config) => readClaudeProviderCapacity(config, { forceRefresh: true }),
): Promise<WorkerResult | undefined> {
  const policy = resolveProviderRoutingPolicy(args.config.root, args.config);
  if (!policy.routableProviders.includes("claude")) return undefined;
  const capacity = await readCapacity(args.config);
  if (!providerEligibility(capacity, policy.reservePercent).eligible) return undefined;
  return rawSpawn({
    ...buildInboxDraftSpawnArgs({
      ...args,
      mount: { ...args.mount, model: "sonnet", provider: "claude", effort: "medium" },
    }),
    onSelectionAssignment: undefined,
  });
}

/**
 * Materialize ONE worktree and draft EVERY proposal in `toDraft` against it — the shared
 * harness-owned glue {@link runDraftRung}'s pure core (lib/inbox.ts) needs: a real
 * `spawnWorker` inside a real worktree. Both `inboxCommand` (CLI, `rmd inbox`) and
 * {@link buildInboxDraftHook} (the daemon's per-poll rung, W1-T192) call this SAME function,
 * so the two paths can never diverge on HOW a proposal gets drafted — only on WHICH
 * proposals are due (`rmd inbox` uses {@link proposalsNeedingDraft} unthrottled;
 * the daemon uses {@link draftsDueOnDaemon}'s idempotence throttle on top of it) and what
 * happens with the resulting {@link DraftRungOutcome}s. `toDraft.length === 0` short-circuits
 * before any clone/worktree — no spend for the common "nothing to draft" case.
 */
/**
 * Materialize the daemon lane's per-attempt worktree — extracted from `draftProposalBatch`
 * (its one call site) purely so this exact sequence is directly unit-testable against a real
 * repo, the same rationale `createFixRungWorktree` (above) already documents for its own
 * extraction (W1-T1129).
 *
 * W1-T2493. `runId` here is `buildInboxDraftHook`'s daemon-lifetime run id — built ONCE at
 * daemon boot and passed to `draftProposalBatch` UNCHANGED on every poll that has proposals
 * due. Before this function existed, `draftProposalBatch` minted its branch as the bare
 * `run-${runId}`, so the SECOND poll in one boot asked `worktreeAdd` for the identical branch
 * the FIRST poll already created and died on `fatal: a branch named '...' already exists` —
 * see {@link uniqueRunBranch}'s own doc (lib/worker.ts) for the full mechanism and why a
 * leftover branch is the expected case, not an edge one. `pruneStaleRuns` still runs FIRST
 * (unchanged position/args), so the ordinary case — a truly orphaned branch from a worktree
 * that already finished or was reaped — gets reclaimed and this function hands `worktreeAdd`
 * back the plain, unsuffixed name; `uniqueRunBranch` is what covers every case pruning does
 * not (a leftover branch whose worktree is still ON DISK when this runs again, or a prune
 * hiccup) without ever forcing or reusing a branch.
 *
 * A worktreeAdd failure is ledgered (`worktree.add_failed`, naming the branch it tried) and
 * RETHROWN — never swallowed here — so a genuine two-lane collision (a race `uniqueRunBranch`
 * could not have observed) is still visible on the SAME ledger this whole rung already writes
 * to, not only as inherited git stderr in a separate log file.
 */
export async function createDaemonLaneWorktree(
  repoDir: string,
  worktreesRoot: string,
  runId: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
): Promise<{ branch: string; worktreePath: string }> {
  const pruned = pruneStaleRuns(repoDir, worktreesRoot, { graceMs: DEFAULT_PRUNE_GRACE_MS });
  if (pruned.worktrees.length || pruned.branches.length || pruned.skipped.length) log("worktree.prune", { ...pruned });
  // W1-T5284: the add is awaited, so a second lane from the same boot-long run id can pick a name while the first
  // add has not created its branch yet. The sync add closed that window by blocking; the reservation holds it now.
  const reserved = laneBranchesBeingAdded.get(repoDir) ?? new Set<string>();
  laneBranchesBeingAdded.set(repoDir, reserved);
  const branch = uniqueRunBranch(repoDir, runId, reserved);
  reserved.add(branch);
  const worktreePath = join(worktreesRoot, branch);
  try {
    // W1-T2621: see addLaneWorktree's identical note, above — worktreeAdd itself emits
    // worktree.add now, given a ledger to emit it through.
    await addLockedRunWorktreeAsync(repoDir, worktreePath, branch, "origin/main", runId, log);
  } catch (e) {
    log("worktree.add_failed", { branch, error: String((e as Error)?.message ?? e) });
    throw e;
  } finally {
    reserved.delete(branch);
  }
  return { branch, worktreePath };
}

/** W1-T5284: per repo, the `run-*` branches a {@link createDaemonLaneWorktree} add in this process has picked and not
 *  yet created. */
const laneBranchesBeingAdded = new Map<string, Set<string>>();

export async function draftProposalBatch(
  toDraft: Proposal[],
  config: Config,
  owner: string,
  repo: string,
  runId: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  rawSpawn: typeof spawnWorker = spawnWorker,
): Promise<DraftRungOutcome[]> {
  if (toDraft.length === 0) return [];
  const causalScope = { repository: `${owner}/${repo}` };
  toDraft = toDraft.map(proposal => captureInboxDraftSnapshot(proposal, causalScope).proposal);
  const registryIntent = selectedRegistryIntentForConfig(config);

  // W1-T2559: the inbox-draft rung ships no code and supervises no worker, so G-17's Tier
  // Invariant — which exists to keep a supervisor strictly above what it reviews — does not bind
  // it to plan authorship's tier. It rides its OWN mount (`synthesis.inbox_draft`, mounts.yaml),
  // never `architectModel`'s `architect:` row. `assertArchitectAboveWorker` is deliberately NOT
  // called here any more — see the identical note at the retro call site.
  const mountsTable = loadMounts(mountsPath(repoRoot));
  const inboxDraftMount = mountsTable.synthesis.inbox_draft;
  const routingStats = createDraftStatsSession(join(config.root, "state"), "inbox-draft", log);

  const settingsFile = renderWorkerSettings({
    templatePath: join(resolveInstallRoot(config), "settings", "worker.json"),
    hooksDir: join(resolveInstallRoot(config), "hooks"),
    outPath: join(config.root, "tmp", `inbox-settings-${runId}.json`),
  });
  validateWorkerSettingsFile(settingsFile);

  const repoDir = join(config.root, "repos", repo);
  if (!existsSync(repoDir)) {
    mkdirSync(dirname(repoDir), { recursive: true });
    ghExec(["repo", "clone", `${owner}/${repo}`, repoDir], { stdio: "inherit" });
  }
  const { branch, worktreePath } = await createDaemonLaneWorktree(repoDir, worktreesDir(config), runId, log);

  try {
    const planText = stringifyYaml(loadPlan(join(worktreePath, "plan", "tasks.yaml")).tasks);
    return await withSelectedRegistryContext(selectedRegistryObserverFromIntent(registryIntent, log), () => runDraftRung(
      toDraft,
      planText,
      {
        repoFacts: checkoutRepoFacts(worktreePath),
        causalScope,
        spawn: (proposal, prompt, ctx) =>
          benchmarkNonDispatchSpawn("inbox-draft", rawSpawn)({ ...buildInboxDraftSpawnArgs({
            cwd: worktreePath,
            settingsFile,
            mount: inboxDraftMount,
            config,
            prompt,
            proposalId: proposal.id,
            proposal,
            currentPlanText: planText,
            draftRoutingLog: routingStats.log,
            draftRoutingReadStats: routingStats.readStats,
            avoidModels: ctx?.avoidModels,
            // Keep the enforced list at the shared-worktree spawn site. The companion invariant
            // test reads this body so a later extraction cannot silently turn the guarantee into
            // a helper-level convention.
            disallowedTools: INBOX_DRAFT_DISALLOWED_TOOLS,
          }), onSelectionAssignment: undefined }),
        ...(inboxDraftMount.provider === "cash" ? {
          escalate: (proposal: Proposal, prompt: string) => spawnEscalatedInboxDraft({
            cwd: worktreePath,
            settingsFile,
            mount: inboxDraftMount,
            config,
            prompt,
            proposal,
            currentPlanText: planText,
            disallowedTools: INBOX_DRAFT_DISALLOWED_TOOLS,
          }, benchmarkNonDispatchSpawn("inbox-draft", rawSpawn)),
        } : {}),
        log,
      },
      runId,
    ));
  } finally {
    worktreeRemove(repoDir, worktreePath);
    removeRunLock(worktreePath);
  }
}

/** How many real proposals `rmd inbox-bakeoff` replays through every candidate unless `--sample` says otherwise. */
const INBOX_BAKEOFF_DEFAULT_SAMPLE = 8;

/**
 * `rmd inbox-bakeoff [--sample <n>]` (W1-T4907) — replay a fixed sample of the real open inbox proposals (the first
 * `n` by id, so two runs see the same ones) through each candidate lane on the PRODUCTION draft path, then print the
 * ranking by lint-clean drafts per cash dollar. It spends real cash and subscription capacity, which is why it is a
 * verb the operator runs and never a rung the daemon does. It writes `inbox.bakeoff` rows only; the production
 * `inbox.drafted` rows, the draft cache and routing are untouched, so the table cannot move the lead by itself.
 */
export async function inboxBakeoffCommand(
  rest: string[],
  rawSpawn: typeof spawnWorker = spawnWorker,
  replay: typeof runInboxBakeoff = runInboxBakeoff,
  repoClone: (args: string[]) => void = (args) => { ghExec(args, { stdio: "inherit" }); },
): Promise<number> {
  const badArg = unknownArgError("inbox-bakeoff", rest, ["--sample"], []);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const sampleRaw = flagValue(rest, "--sample");
  const sample = sampleRaw === undefined ? INBOX_BAKEOFF_DEFAULT_SAMPLE : Number(sampleRaw);
  if (!Number.isInteger(sample) || sample < 1) {
    console.error(`inbox-bakeoff: --sample must be a positive integer, got ${sampleRaw}\n${USAGE}`);
    return 2;
  }
  const config = loadConfig();
  const registryPath = join(config.root, "state", "inbox-proposals.json");
  const proposals = parseProposalRegistry(readFileIfExists(registryPath))
    .sort((a, b) => a.id.localeCompare(b.id, "en", { numeric: true }))
    .slice(0, sample);
  if (proposals.length === 0) {
    console.error("inbox-bakeoff: no open inbox proposals to replay");
    return 1;
  }
  const { owner, repo } = resolveOwnerRepo();
  const runId = `BAKEOFF-${Date.now()}`;
  const ledgerPath = ledgerPathFor(config);
  const log = (step: string, extra: Record<string, unknown> = {}) =>
    appendLedger(ledgerPath, { run_id: runId, task_id: "inbox-bakeoff", step, lane: "inbox-bakeoff", ...extra });

  const settingsFile = renderWorkerSettings({
    templatePath: join(resolveInstallRoot(config), "settings", "worker.json"),
    hooksDir: join(resolveInstallRoot(config), "hooks"),
    outPath: join(config.root, "tmp", `inbox-bakeoff-settings-${runId}.json`),
  });
  validateWorkerSettingsFile(settingsFile);
  const repoDir = join(config.root, "repos", repo);
  if (!existsSync(repoDir)) {
    mkdirSync(dirname(repoDir), { recursive: true });
    repoClone(["repo", "clone", `${owner}/${repo}`, repoDir]);
  }
  const baseMount = loadMounts(mountsPath(repoRoot)).synthesis.inbox_draft;
  const { branch, worktreePath } = await createDaemonLaneWorktree(repoDir, worktreesDir(config), runId, log);
  try {
    // Match the production draft rung: a monolith-only sample silently omits shard dependencies.
    const planText = stringifyYaml(loadPlan(join(worktreePath, "plan", "tasks.yaml")).tasks);
    const spawnFor = (candidate: BakeoffCandidate) => async (_proposal: Proposal, prompt: string) => {
      const cash = candidate.billing === "cash";
      // A cash candidate is pinned by restricting the cash ladder to its one deployment; the subscription candidate
      // by giving the spawn a Claude mount. Neither writes a selection assignment — this is a measurement, not a route.
      const args = buildInboxDraftSpawnArgs({
        cwd: worktreePath,
        settingsFile,
        prompt,
        config,
        mount: cash ? { ...baseMount, model: candidate.mountModel ?? baseMount.model }
          : { ...baseMount, model: "sonnet", provider: "claude" },
        disallowedTools: INBOX_DRAFT_DISALLOWED_TOOLS,
      });
      return await rawSpawn({
        ...args,
        ...(candidate.effort === undefined ? {} : { effort: candidate.effort }),
        onSelectionAssignment: undefined,
        ...(cash ? { routingTrial: { id: "inbox-bakeoff", arm: "cash", reason: `bake-off candidate ${candidate.id}`, models: [candidate.model] } } : {}),
        ...(candidate.tools ? {} : { tools: [] }),
      });
    };
    const rows = await replay({ proposals, planText, spawnFor, log, runId });
    console.log(`inbox-bakeoff: ${proposals.length} proposals (${proposals.map((p) => p.id).join(", ")}) on branch ${branch}\n`);
    console.log(renderBakeoff(rows));
    return 0;
  } finally {
    worktreeRemove(repoDir, worktreePath);
    removeRunLock(worktreePath);
  }
}

/**
 * The daemon's per-poll DRAFT rung (W1-T192, ratifies P25's autonomous half). Reachable from
 * the daemon's OWN `deps.sweep()` seam (daemon.ts:274) — wired into {@link buildSweepHook}
 * below, riding the SAME slot the W1-T150 credit-backfill rung already occupies, never a
 * second, separately-scheduled loop. Selects candidates via {@link draftsDueOnDaemon}: the
 * SAME {@link proposalsNeedingDraft} predicate `rmd inbox` classifies against, further
 * throttled so a 300s poll cadence never re-spawns the Architect for the SAME cause (one
 * invalidation ⇒ one attempt — see lib/inbox.ts's `draftAttemptKey` doc). Every attempted
 * proposal's key is recorded in `state/inbox-draft-attempts.json` regardless of outcome —
 * a FAILED attempt is also throttled, or a stuck cause would re-spawn every poll forever
 * (the exact spend leak W1-T177 exists to prevent). Wrapped in its own try/catch so a
 * registry-read hiccup or a worktree failure is logged (`inbox.draft_rung.error`) and
 * skipped, never thrown up into the sweep/daemon loop — an un-drafted proposal is the status
 * quo, not a regression; `rmd inbox` remains available to force a draft on demand in the
 * meantime.
 */
// Exported, with `draftBatch` an injectable seam defaulting to the real draftProposalBatch
// (logic UNCHANGED — same mirrors runTask's opts.github escape hatch, drainCommand's
// githubFactory, etc.): draftProposalBatch itself clones a real worktree and spawns a real
// Architect worker, so a behavioral test of THIS hook's own inflight-file write/clear
// discipline (W1-T193) needs a seam to stand in for it without paying that cost.
export function buildInboxDraftHook(
  owner: string,
  repo: string,
  config: Config,
  runId: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  draftBatch: (
    toDraft: Proposal[],
    config: Config,
    owner: string,
    repo: string,
    runId: string,
    log: (step: string, extra?: Record<string, unknown>) => void,
  ) => Promise<DraftRungOutcome[]> = draftProposalBatch,
  grepAnchor?: (ref: string, anchor: EvidenceAnchor) => boolean,
  mainSha: () => string | undefined = () => readOriginMainSha(repoRoot),
  grepAnchorAsync?: (ref: string, anchor: EvidenceAnchor) => Promise<boolean>,
  legacyGrepAnchorAsync?: (ref: string, anchor: EvidenceAnchor) => Promise<boolean>,
  onlyProposalId?: string,
  planningStore?: { root: string; ledgerPath: string },
): (tickRead?: TickReadFacts) => Promise<void> {
  // 2026-10-06: the sync `git grep` behind each anchor held the daemon loop up to 29 s a spawn. The
  // readiness pass stays sync, so every anchor is warmed into the cache OFF the loop first. A test
  // that injects only the sync seam warms through that same seam, so its answers are unchanged.
  const grepAnchorSync = grepAnchor ?? ((ref: string, anchor: EvidenceAnchor) => gitGrepAnchorTrue(repoRoot, ref, anchor));
  const grepAnchorWarm =
    legacyGrepAnchorAsync ??
    grepAnchorAsync ??
    (grepAnchor
      ? async (ref: string, anchor: EvidenceAnchor) => grepAnchor(ref, anchor)
      : (ref: string, anchor: EvidenceAnchor) => gitGrepAnchorTrueAsync(repoRoot, ref, anchor));
  // W1-T2564: see the migration block below — this is the once-per-daemon-start scope it needs.
  let attemptsMigrated = false;
  const anchorGrepCache = createAnchorGrepCache();
  // W1-T9443: the orphan prune's shard population, held for this daemon's life like the anchor cache above, so a
  // full sweep reads, off the loop, only the shard files that changed since the one before.
  const inboxRoot = planningStore?.root ?? config.root;
  const shardReader = createProposalShardReader(proposalShardDir(join(inboxRoot, "state", "inbox-proposals.json")), { log });
  return async () => {
    try {
      const registryPath = join(inboxRoot, "state", "inbox-proposals.json");
      const causalScope = { repository: `${owner}/${repo}` };
      commitInboxDraftOutcomes({ stateDir: join(inboxRoot, "state"), scope: causalScope, snapshots: [], outcomes: [], log });
      const proposals: Proposal[] = parseProposalRegistry(readFileIfExists(registryPath));
      if (proposals.length === 0) return; // no active proposals — no spend
      const ledgerPath = planningStore?.ledgerPath ?? ledgerPathFor(config);

      const draftsPath = join(inboxRoot, "state", "inbox-drafts.json");
      const pruned = await pruneOrphanedDraftsAsync(draftsPath, registryPath, shardReader);
      if (pruned && pruned.count > 0) log("inbox.drafts_pruned", { count: pruned.count, bytes_before: pruned.bytesBefore, bytes_after: pruned.bytesAfter });
      const drafts: DraftCache = parseDraftCache(readFileIfExists(draftsPath));
      const attemptsPath = join(inboxRoot, "state", "inbox-draft-attempts.json");
      const attempts: DraftAttemptCache = parseDraftAttemptCache(readFileIfExists(attemptsPath));

      // W1-T2564 MIGRATION, ONCE PER DAEMON START, BEFORE `due` IS COMPUTED. Not writing a key for
      // a refusal fixes the write path forward and repairs nothing already on disk: 267 of 353
      // proposals were keyed with no cached draft and, their key being the literal `::0`, could
      // never become due again.
      //
      // ⚠ WHY ONCE PER PROCESS RATHER THAN EVERY POLL — A TEST CAUGHT THE NAIVE FORM. Run per poll
      // it also evicts the key W1-T192 had just written for a GENUINE failure in that same poll,
      // re-opening it forever: an unbounded retry loop wearing a migration's clothes, and the exact
      // opposite of the bounded one-off this is meant to be (test/run-task.test.ts's "an ORDINARY
      // failure still writes its attempt key" reddened on precisely that). Once per daemon start
      // keeps the property that matters — a fresh host recovers with no operator step, because
      // every boot runs it — while bounding a re-opened genuine failure to ONE extra attempt per
      // daemon start rather than one per poll. `buildInboxDraftHook` is constructed once per daemon
      // start (see its own doc), so this closure flag is that scope.
      // W1-T2566: THE CLOSURE FLAG STAYS — it is what keeps this off the per-poll path, and the
      // comment above records the test that caught the naive form. What it CANNOT do is survive a
      // restart, which is precisely what resets it: at a MEASURED median daemon lifetime of 50.5
      // minutes (479 processes, 32% under 30 min) a proposal that fails genuinely and repeatedly
      // never acquires a cached draft, satisfies the eviction predicate on every boot, and is
      // re-opened ~29 times a day at an $8.52 draft mean. The PERSISTED per-id marker below is the
      // bound that survives the restart; the flag and the marker do different jobs.
      if (!attemptsMigrated) {
        attemptsMigrated = true;
        const reopenedPath = join(inboxRoot, "state", "inbox-reopened-keys.json");
        const reopened = parseReopenedKeysCache(readFileIfExists(reopenedPath));
        // KEYED ON PROPOSAL ID, never a global "migration done" flag: an id never seen before is
        // still re-opened on FIRST SIGHT, so a freshly-provisioned host recovers with no operator
        // step — the property W1-T2564 chose a closure flag to get, preserved rather than traded.
        const evicted = evictRefusalPoisonedKeys(attempts, drafts, new Set(proposals.map((p) => p.id)), new Set(Object.keys(reopened)));
        if (evicted.length > 0) {
          writeDraftAttemptPair(draftsPath, attemptsPath, drafts, attempts);
          // Written AFTER the pair commits. A marker recorded for an eviction that never landed
          // would silently retire a proposal the caches still consider due — the failure direction
          // that costs work rather than one extra attempt.
          writeReopenedKeys(reopenedPath, markReopened(reopened, evicted, new Date().toISOString()));
          log("inbox.draft_attempts_reopened", { evicted: evicted.length, evicted_ids: evicted.slice(0, 20), refused_this_batch: 0 });
        }
      }

      const lifecycleContext = inboxRetirementContext(join(config.root, "state"), { instance: process.env.RMD_INSTANCE_NAME ?? "core", repository: `${owner}/${repo}`, root: config.root });
      let draftSelection: DraftSelectionContext = { retirement: lifecycleContext, isRatified: () => false,
        grepAnchorTrue: () => true, openProposalIds: new Set(proposals.map(p => p.id)) };
      try {
        const ledgerLines = readLedgerLines(ledgerPath);
        const sha = mainSha();
        const anchors = proposals.flatMap((p) => p.evidenceAnchors);
        const grepFailures = await warmAnchorGrepCache(anchorGrepCache, sha, anchors, grepAnchorWarm);
        draftSelection = {
          retirement: lifecycleContext,
          grepAnchorTrue: (a: EvidenceAnchor) => warmedAnchorGrep(anchorGrepCache, sha, grepFailures, a, grepAnchorSync),
          openProposalIds: new Set(proposals.map((p) => p.id)),
          isRatified: (id) => isRatifiedInLedger(ledgerLines, id),
          isDeclined: declinedWithReceipts(ledgerLines, join(inboxRoot, "state")),
        };
      } catch (e) {
        log("inbox.draft_readiness_unavailable", { error: String((e as Error)?.message ?? e) });
      }

      const draftLane = resolvedInboxDraftLane(repoRoot);
      // Explicit saved-conversation drafting narrows selection; every cadence, retry, ownership and spend guard stays the same.
      // The ordinary cadence never selects a saved improvement: only its daemon-owned handoff names it here.
      const population = onlyProposalId === undefined ? proposals.filter(proposal => !isImprovementBoundProposal(proposal))
        : proposals.filter(proposal => proposal.id === onlyProposalId);
      const due = draftsDueOnDaemon(population, drafts, attempts, DAEMON_DRAFT_BATCH_CAP, draftSelection, draftLane);
      if (due.length === 0) return;

      // W1-T2561: NAME THE DEFERRAL, NEVER CAP SILENTLY. `draftsDueOnDaemon` now returns at most
      // DAEMON_DRAFT_BATCH_CAP proposals per poll, so on a large registry `due` is a SLICE and the
      // rest are still due. A cap that shows up nowhere is the "tested, inert" shape this repo has
      // shipped before: the queue would drain at a bounded rate with no way to see the backlog or
      // tell a paced drain from a wedged one. This is a pure observation — a count of a set already
      // computed above, spawning nothing — and `deferred: 0` on an uncapped poll is a real reading,
      // not silence, so the row is written unconditionally.
      const eligible = draftsDueOnDaemon(population, drafts, attempts, 0, draftSelection, draftLane);
      log("inbox.draft_batch", {
        eligible: eligible.length,
        drafting: due.length,
        deferred: eligible.length - due.length,
        cap: DAEMON_DRAFT_BATCH_CAP,
      });

      // W1-T193: the console must render a proposal as DRAFTING (with its spawn time) for the
      // whole window an Architect worker is actually running for it — "never lies about its
      // own state", the same bar W1-T156 set for liveness. Written BEFORE the batch spawns and
      // cleared in the `finally` below regardless of outcome, so a crash mid-draft is the only
      // way this file can go stale (self-corrects: a stuck entry is overwritten the next time
      // ANY draft batch runs, since this rung always writes its own full `due` set, never
      // merges onto a stale one).
      // ── W1-T2569: THE RE-ENTRANCY GUARD ───────────────────────────────────────────────────
      // THE BOUND STOPS AWAITING; IT DOES NOT CANCEL. `DEFAULT_SWEEP_WALL_CLOCK_BOUND_MS`
      // (559_000, lib/daemon.ts) abandons `await deps.sweep()` at 9.3 minutes, but the sweep — and
      // this rung inside it — KEEPS RUNNING DETACHED. A draft batch is 3 sequential drafts at a
      // measured 316s median, ~948s end to end, so it is un-awaited EVERY time and the next loop
      // iteration starts a fresh sweep carrying a fresh batch.
      //
      // MEASURED 2026-09-01, six consecutive cycles, perfect alternation:
      //   batch 17:38:13 -> abandoned 17:46:45 (+512s) -> batch 17:53:01 -> abandoned 18:01:15 ...
      // with `daemon.sweep.abandoned` carrying `elapsed_ms: 559000, bound_ms: 559000` exactly.
      // Cost: 16 Architect spawns across 5 distinct proposals, $123.30, drafts cache frozen at 62.
      //
      // THIS IS WHY `buildInboxDraftHook`'s OWN DOC WAS WRONG to say the hook is "awaited to
      // completion by the daemon's serial sweep tick" — corrected at that doc; see it for the
      // wider class, which is NOT confined to this rung.
      //
      // O_EXCL + reclaimStaleLock, REUSED not reinvented: `acquireDrainLock` is already
      // path-parameterised and already applies the pid+host staleness rule (`isHolderStale`) that
      // W1-T1067 settled for `drain.lock`. A SECOND staleness rule here would be a second thing to
      // drift. The staleness bound is load-bearing in the other direction too: without it a killed
      // daemon strands the lock and this rung never runs again — the exact W1-T1067 failure, one
      // file over.
      // ── W1-T2590: DO NOT RETRY INTO A SHUT DOOR ───────────────────────────────────────────
      // Checked FIRST — before the lock, before the registry is even consulted — so a deferred
      // poll costs nothing: no lock churn, no `deps.spawn`, no Architect. The instant comes from
      // the provider's OWN refusal text (`detectUsageLimitRefusal`, lib/classify.ts), which on the
      // measured real string was more accurate than the headroom governor's belief at that moment.
      //
      // THIS IS WHAT MAKES RAISING `DAEMON_DRAFT_BATCH_CAP` SAFE LATER. W1-T2564 correctly stopped
      // a refusal from writing an attempt key, so a refused draft now stays due and retries next
      // poll; that left the cap as the ONLY bound on a retry storm during a live outage — the exact
      // condition that produced 494 refusals in seven hours. Bounding the retry by the account's
      // own stated window is the prerequisite, not a nicety.
      // A repository-specific planning store cannot bypass either provider refusal window.
      const deferralPath = join(config.root, "state", "inbox-draft-deferred-until.json");
      const deferralPaths = [...new Set([deferralPath, join(inboxRoot, "state", "inbox-draft-deferred-until.json")])];
      for (const path of deferralPaths) {
        const deferral = decideDraftDeferral(parseDraftDeferralCache(readFileIfExists(path)), Date.now());
        if (deferral.defer) {
          log("inbox.draft_batch.deferred", {
            until: new Date(deferral.untilMs).toISOString(), remaining_ms: deferral.remainingMs, matched: deferral.matched,
          });
          return;
        }
      }

      const draftLockPath = join(config.root, "state", "inbox-draft.lock");
      let draftLock: DrainLockHandle;
      try {
        draftLock = acquireDrainLock(draftLockPath);
      } catch (e) {
        // A LIVE holder is the expected, healthy outcome of an abandoned-but-still-running batch —
        // it is a SKIP, never an error. Ledgered so a stuck lock is visible rather than looking
        // like a rung that quietly stopped firing.
        log("inbox.draft_batch.skipped", {
          reason: "another draft batch holds the lock",
          detail: String((e as Error)?.message ?? e),
        });
        return;
      }
      try {
      // Hold the fleet lock first, then the selected store's native lock. A live holder of
      // either keeps its slot; failure to acquire the second releases only our first lock.
      let storeLock: DrainLockHandle | undefined;
      const storeLockPath = join(inboxRoot, "state", "inbox-draft.lock");
      if (resolve(storeLockPath) !== resolve(draftLockPath)) {
        try { storeLock = acquireDrainLock(storeLockPath); }
        catch (error) { log("inbox.draft_batch.skipped", { reason: "another draft batch holds the repository lock", detail: String(error) }); return; }
      }
      try {
      const inflightPath = join(inboxRoot, "state", "inbox-draft-inflight.json");
      const spawnedAt = new Date().toISOString();
      writeFileSync(inflightPath, JSON.stringify(Object.fromEntries(due.map((p) => [p.id, spawnedAt])), null, 2), "utf8");

      let outcomes: DraftRungOutcome[];
      const snapshots = due.map(proposal => captureInboxDraftSnapshot(proposal, causalScope));
      try {
        outcomes = await draftBatch(due, config, owner, repo, runId, log);
      } finally {
        // ⚠ W1-T2569 CORRECTION — THIS CLAIM WAS FALSE AND COST $123.30. It used to read "Only one
        // draft rung runs at a time (this hook is awaited to completion by the daemon's own serial
        // sweep tick before the next one can start)". The sweep tick does NOT await to completion:
        // `DEFAULT_SWEEP_WALL_CLOCK_BOUND_MS` (559_000, lib/daemon.ts) stops AWAITING at 9.3
        // minutes and does not CANCEL, so a ~948s draft batch keeps running detached while the next
        // iteration starts a fresh one. MEASURED: six consecutive batch/abandon alternations.
        //
        // Clearing the whole file is safe now for a DIFFERENT reason — the lock acquired above
        // means this really is the only batch running. It was never safe because of serialization.
        writeFileSync(inflightPath, JSON.stringify({}, null, 2), "utf8");
      }

      // W1-T2564: ids left unkeyed because the account refused them — ledgered below so a refusal
      // storm is visible as itself rather than as a run of malformed-output errors.
      const refusedThisBatch: string[] = [];
      for (const outcome of outcomes) {
        const proposal = due.find((p) => p.id === outcome.proposalId);
        if (!proposal) continue; // unreachable — outcomes are 1:1 with `due`
        // IDEMPOTENCE (W1-T192): mark this cause ATTEMPTED whether it succeeded or failed —
        // see this function's own doc for why a failed attempt must be throttled too.
        //
        // W1-T2564: EXCEPT A REFUSAL, WHICH IS NOT AN ATTEMPT. W1-T192's argument is that a cause
        // which was TRIED and failed must not be retried every poll. A run the account turned away
        // was never tried, so keying it does not throttle a failure — it retires work that never
        // ran, permanently, because a routed follow-up's key is the literal `::0` and can never
        // change. This is the ONLY arm that skips the write; an ordinary failure still keys, so
        // W1-T192's throttle is untouched (its own test pins that).
        if (!outcome.ok && outcome.refused) {
          refusedThisBatch.push(outcome.proposalId);
        }
      }
      // ATOMIC PAIR (W1-T241): see lib/inbox.ts's `writeDraftAttemptPair` doc for the
      // torn-file/wedged-idempotence hazard this closes and why drafts commits before
      // attempts.
      if (refusedThisBatch.length > 0) {
        log("inbox.draft_attempts_reopened", { evicted: 0, refused_this_batch: refusedThisBatch.length });
      }
      // W1-T2590: record the window the account itself stated, so the NEXT poll waits it out
      // instead of spending against a door that is still shut. `deferralFromOutcomes` returns
      // nothing when no refusal carried a usable instant — a zone-less refusal must not stop the
      // rung on a window whose end nobody stated (see its own doc), so that case falls through to
      // today's behaviour: retry next poll, bounded by the batch cap.
      const nextDeferral = deferralFromOutcomes(outcomes);
      if (nextDeferral) {
        for (const path of deferralPaths) writeFileSync(path, JSON.stringify(nextDeferral, null, 2), "utf8");
        log("inbox.draft_deferral_recorded", {
          until: new Date(nextDeferral.deferredUntilMs).toISOString(),
          matched: nextDeferral.matched,
        });
      }
      // Re-read under the shared registry lock, adopt only this batch's unchanged generations,
      // and persist completion before publication. Never spread an old whole-cache snapshot
      // over unrelated writes or mark newer direction attempted when an older worker finishes.
      commitInboxDraftOutcomes({ stateDir: join(inboxRoot, "state"), scope: causalScope, snapshots, outcomes, lane: draftLane, log });
      } finally { storeLock?.release(); }
      } finally {
        draftLock.release();
      }
    } catch (e) {
      log("inbox.draft_rung.error", { error: String((e as Error)?.message ?? e) });
    }
  };
}

/**
 * W1-T510: the CLI's `isMerged` + `depsUnobservable` pair for {@link ReadinessContext} —
 * shared by `rmd inbox` ({@link inboxCommand}) and the `rmd approve`/`rmd reframe`
 * re-classify helper ({@link loadProposalForRatify}) so both derive the SAME third value
 * the SAME way, never diverging. `deriveStatus(t, deriveDeps)` is memoized PER TASK ID
 * (`projectionOf`) so a dependency named by both `isMerged` and `depsUnobservable` —
 * the common case, since {@link unmetOutsideDeps} in lib/inbox.ts calls `isMerged` first
 * and only consults `depsUnobservable` for the ids it reports unmerged — is derived ONCE,
 * never twice: no new GitHub reads over what this CLI already made pre-W1-T510.
 */
/** EXPORTED for its own coverage: the memoising seam W1-T510's readiness split rests on. Its
 *  body is reachable from no other test — both `inboxCommand` call sites need a live plan and
 *  a real GitHub gateway, which is why these lines arrived uncovered. */
/** W1-T4565: the resequence CLOSE's resolver; `indeterminate` reads as met (DO NOT ACT), so doubt only withholds a close. */
export function resequenceMergedResolver(projection: () => Map<string, StatusProjection> | undefined): MergedResolver {
  return (t) => {
    const p = projection()?.get(t.id);
    return p?.merged === true || p?.indeterminate === true;
  };
}

export function buildDepsReadinessAccessors(plan: Plan, deriveDeps: DeriveDeps): { isMerged: MergedResolver; depsUnobservable: (taskId: string) => GhFailureReason | undefined } {
  const projectionOf = new Map<string, StatusProjection>();
  const derive = (t: Task): StatusProjection => {
    const cached = projectionOf.get(t.id);
    if (cached) return cached;
    const projection = deriveStatus(t, deriveDeps);
    projectionOf.set(t.id, projection);
    return projection;
  };
  const isMerged: MergedResolver = (t) => derive(t).merged;
  const depsUnobservable = (taskId: string): GhFailureReason | undefined => {
    const t = plan.byId.get(taskId);
    if (!t) return undefined; // not in the plan at all — unmetDependencies' own `!d` branch handles this, never isMerged
    const projection = derive(t);
    return projection.indeterminate ? (projection.unavailableReason ?? "unknown") : undefined;
  };
  return { isMerged, depsUnobservable };
}

/** W1-T4075: {@link buildDepsReadinessAccessors}' two answers, read from a tick-read generation's
 *  projection of the same plan instead of re-deriving each task. A task absent from it is absent
 *  from the plan, so it answers `undefined` exactly as the deriving accessor does. */
export function projectionReadinessAccessors(projection: ReadonlyMap<string, StatusProjection>): ReturnType<typeof buildDepsReadinessAccessors> {
  return {
    isMerged: (t) => projection.get(t.id)?.merged ?? false,
    depsUnobservable: (taskId) => {
      const row = projection.get(taskId);
      return row?.indeterminate ? (row.unavailableReason ?? "unknown") : undefined;
    },
  };
}

/**
 * `rmd inbox [--dry-run]` — the ratification inbox's deterministic core, wired live
 * (MASTER-PLAN P25(i), W1-T110). The actual readiness predicate ({@link
 * classifyProposal}) is a PURE function, unit-tested exhaustively over fixtures
 * (test/inbox.test.ts) with the LLM stubbed out entirely — this command is the thin,
 * real-world GLUE around it, in the same "pure core / harness-owned I/O" split as
 * `rmd dep-review`/`rmd triage`/`rmd plan`:
 *
 *   1. Read the ACTIVE-proposal registry (`<config.root>/state/inbox-proposals.json`
 *      — state-side, never a repo path; population of this registry — e.g. from
 *      MASTER-PLAN.md's proposal list — is a separate, later concern). Zero
 *      proposals ⇒ print "no active proposals" and return immediately (no clone, no
 *      spend) — the common case on a fresh checkout.
 *   2. For every proposal {@link proposalsNeedingDraft} names (NOT deferred-by-trigger,
 *      cached draft missing or stale) — UNTHROTTLED, unlike the daemon's own rung below,
 *      because this is the operator's MANUAL FORCE (W1-T192: `rmd inbox` is demoted from
 *      the only trigger to a manual one, never removed as a trigger) — spawn ONE bounded
 *      Architect worker per proposal ({@link draftProposalBatch}) and cache the result.
 *      Skipped entirely under `--dry-run` (classify against whatever is already cached,
 *      spend nothing).
 *   3. Classify every proposal with REAL facts: dependency-merge state via
 *      `deriveStatus` (GitHub-derived, corrections-supreme — never the decorative
 *      yaml `status:` field), evidence-anchor truth via a real `git grep` against
 *      `origin/main` ({@link gitGrepAnchorTrue}), and lint-cleanliness via the SAME
 *      `rmd lint-plan` checks every other plan PR is gated by (inside
 *      classifyProposal itself).
 *   4. Print {@link renderInbox} and ledger-log one `inbox.classified` line per
 *      proposal (traceable via `rmd trace`).
 *
 * NOTE (W1-T192): the daemon's OWN per-poll draft rung ({@link buildInboxDraftHook}) is what
 * makes a draft exist without this command ever being invoked — see that function's doc.
 */
export function improvementNativeFilingReceipt(ledgerPath: string, proposalId: string, repository: string, clock: Clock = systemClock): ImprovementPlanReceipt | undefined {
  const rows = readLedgerLines(ledgerPath);
  const receipt = rows.filter(row => row.task_id === proposalId && row.step === "ratify.approved").at(-1);
  if (!receipt || typeof receipt.pr_url !== "string" || !receipt.pr_url.startsWith(`https://github.com/${repository}/pull/`) ||
      !/\/pull\/[1-9][0-9]*$/.test(receipt.pr_url) || typeof receipt.branch !== "string" || typeof receipt.run_id !== "string" ||
      typeof receipt.ts !== "string" || !Number.isFinite(Date.parse(receipt.ts)) || Date.parse(receipt.ts) > clock.now()) return undefined;
  const materialized = rows.filter(row => row.run_id === receipt.run_id && row.step === "approve.id_materialized" && row.proposal_id === proposalId).at(-1);
  const taskIds = Array.isArray(materialized?.ids) && materialized.ids.every(id => typeof id === "string" && /^[A-Za-z0-9-]{1,128}$/.test(id)) ? materialized.ids as string[] : [];
  return { state: "plan_pr_opened", prUrl: receipt.pr_url, branch: receipt.branch, taskIds, taskIdsState: taskIds.length ? "observed" : "unavailable", recordedAt: receipt.ts,
    nativeReceiptId: `${receipt.run_id}|${receipt.step}|${String(receipt.ts)}` };
}

const IMPROVEMENT_ACTION_RUNTIME = { readConfig: loadConfig, clock: systemClock, draftHook: buildInboxDraftHook,
  approve: approveCommandMirrored, isDaemonOwned: daemonOwnedProcess };

/** Only a saved, authenticated decision can reach the existing bounded draft and governed approve paths. */
export async function improvementActionCommand(rest: string[], deps: Partial<typeof IMPROVEMENT_ACTION_RUNTIME> = {}): Promise<number> {
  const bad = unknownArgError("improvement-action", rest.slice(1), ["--state-dir"], []), operationId = rest[0];
  if (bad || !operationId || !/^[a-f0-9]{64}$/.test(operationId)) { console.error("rmd improvement-action: use a saved action identity and its fleet state directory"); return 2; }
  const runtime = { ...IMPROVEMENT_ACTION_RUNTIME, ...deps };
  if (!runtime.isDaemonOwned()) { console.error("rmd improvement-action: saved actions run only through the daemon's admitted workflow"); return 1; }
  const config = runtime.readConfig(), stateDir = flagValue(rest, "--state-dir");
  if (!stateDir || resolve(stateDir) !== resolve(config.root, "state")) { console.error("rmd improvement-action: the request store must belong to this configured fleet"); return 2; }
  const identity = resolveOwnerRepo(), repository = `${identity.owner}/${identity.repo}`.toLowerCase();
  const checkTarget = (target: { repository: string; repoRoot: string }) => {
    if (target.repository !== repository || resolve(target.repoRoot) !== resolve(repoRoot)) throw new Error("The saved action does not belong to the selected repository checkout.");
  };
  const draft: Parameters<typeof runImprovementAction>[2] = async target => {
    checkTarget(target);
    const planningStore = { root: target.controlRoot, ledgerPath: target.ledgerPath }, runId = `IMPROVEMENT-DRAFT-${operationId}`;
    const log = (step: string, extra: Record<string, unknown> = {}) => appendLedger(target.ledgerPath, { run_id: runId, task_id: target.proposalId, step, ...extra });
    await runtime.draftHook(identity.owner, identity.repo, config, runId, log, undefined, undefined, undefined, undefined, undefined, target.proposalId, planningStore)();
  };
  const file: Parameters<typeof runImprovementAction>[3] = async target => {
    checkTarget(target);
    await runtime.approve([target.proposalId], { config, inboxRoot: target.controlRoot, inboxLedgerPath: target.ledgerPath, root: target.controlRoot, planPath: target.planPath,
      reviewedImprovement: { goalDigest: target.goalDigest, draftDigest: target.draftDigest } });
    return improvementNativeFilingReceipt(target.ledgerPath, target.proposalId, repository, runtime.clock);
  };
  const result = await runImprovementAction(operationId, { stateDir, actorId: "owned-improvement-cli", clock: runtime.clock }, draft, file,
    target => improvementNativeFilingReceipt(target.ledgerPath, target.proposalId, repository, runtime.clock));
  console.log(JSON.stringify(result));
  return "kind" in result && ["completed", "waiting"].includes(result.state) ? 0 : 1;
}

export async function inboxCommand(rest: string[], deps: { config?: Config; github?: GitHub; draftBatch?: typeof draftProposalBatch } = {}): Promise<number> {
  const badArg = unknownArgError("inbox", rest, [], ["--dry-run"]);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const dryRun = rest.includes("--dry-run");

  const config = deps.config ?? loadConfig();
  const plan = loadPlan(join(repoRoot, "plan", "tasks.yaml"));
  const ledgerPath = ledgerPathFor(config);
  const { owner, repo } = resolveOwnerRepo();

  const registryPath = join(config.root, "state", "inbox-proposals.json");
  const proposals: Proposal[] = parseProposalRegistry(readFileIfExists(registryPath));
  if (proposals.length === 0) {
    console.log(renderInbox([]));
    return 0;
  }

  const draftsPath = join(config.root, "state", "inbox-drafts.json");
  const drafts: DraftCache = parseDraftCache(readFileIfExists(draftsPath));

  // UNTHROTTLED (see this command's doc) — `rmd inbox` is the manual FORCE, so it always
  // attempts every proposal `proposalsNeedingDraft` names, never consulting the daemon-only
  // DraftAttemptCache.
  const lifecycleContext = inboxRetirementContext(join(config.root, "state"), { instance: process.env.RMD_INSTANCE_NAME ?? "core", repository: `${owner}/${repo}`, root: config.root });
  // Manual force retains its existing conflict behavior while observing lifecycle uncertainty. A saved
  // improvement drafts only through its daemon-owned handoff, never this manual force.
  const needsDraft = proposalsNeedingDraft(proposals.filter(proposal => !isImprovementBoundProposal(proposal)), drafts, { retirement: lifecycleContext,
    isRatified: () => false, grepAnchorTrue: () => true, openProposalIds: new Set() });

  const runId = `INBOX-${Date.now()}`;
  const log = (step: string, extra: Record<string, unknown> = {}) => appendLedger(ledgerPath, { run_id: runId, task_id: "inbox", step, lane: "inbox", ...extra });

  if (!dryRun) commitInboxDraftOutcomes({ stateDir: join(config.root, "state"), scope: { repository: `${owner}/${repo}` }, snapshots: [], outcomes: [], log });

  if (needsDraft.length > 0 && !dryRun) {
    const causalScope = { repository: `${owner}/${repo}` };
    const snapshots = needsDraft.map(proposal => captureInboxDraftSnapshot(proposal, causalScope));
    const outcomes = deps.draftBatch ? await deps.draftBatch(needsDraft, config, owner, repo, runId, log)
      : await draftProposalBatch(needsDraft, config, owner, repo, runId, log);
    commitInboxDraftOutcomes({ stateDir: join(config.root, "state"), scope: causalScope, snapshots, outcomes, log });
    Object.assign(drafts, parseDraftCache(readFileIfExists(draftsPath)));
  }

  const deriveDeps: DeriveDeps = { ledgerPath, github: deps.github ?? buildBatchedGithub(owner, repo) };
  const { isMerged, depsUnobservable } = buildDepsReadinessAccessors(plan, deriveDeps);
  const openProposalIds = new Set(proposals.map((p) => p.id));
  // W1-T190: re-derive "already ratified" from the ledger on every `rmd inbox` pass, never
  // from the registry's own state — a proposal ratify.approved already fired for is reported
  // ratified even if the registry entry itself drifted (the P19 incident).
  const ledgerLinesForRatify = readLedgerLines(ledgerPath);

  const classifications = proposals.map((p) =>
    classifyProposal(p, drafts[p.id], {
      retirement: lifecycleContext,
      plan,
      isMerged,
      depsUnobservable,
      grepAnchorTrue: (a: EvidenceAnchor) => gitGrepAnchorTrue(repoRoot, "origin/main", a),
      openProposalIds,
      isRatified: (id) => isRatifiedInLedger(ledgerLinesForRatify, id),
      isDeclined: declinedWithReceipts(ledgerLinesForRatify, join(config.root, "state")),
    }),
  );
  for (const c of classifications) log("inbox.classified", { proposal_id: c.proposalId, state: c.state, reasons: c.reasons });
  // W1-T112: one `inbox.polled` snapshot per invocation — digest.ts reads the LATEST such
  // line inside its window and folds it into the daily pulse's soft-composed "inbox: N
  // ready" line (see lib/inbox.ts's InboxPollSummary doc). Logged unconditionally, same as
  // the `inbox.classified` lines just above — `rmd inbox --dry-run` already always
  // classifies+ledgers (it only skips the draft-synthesis SPAWN), unlike `rmd ops`/`rmd
  // issues`, whose dry-run skips their own poll-summary line because THEIR poll has real
  // side effects (escalate/capture) a preview must leave no trace of; classification here
  // has none.
  log("inbox.polled", { inbox: summarizeInboxPoll(classifications) });

  // W1-T190 (round 2): a proposal classified "ratified" here is DETECTED off the ledger,
  // never trusted from the registry's own (possibly drifted) copy — but detection alone
  // still leaves the drifted row sitting in state/inbox-proposals.json forever. Heal it:
  // any proposal the ledger already ratified is pruned from the registry on THIS pass, the
  // same way approveCommand prunes the common (non-drifted) case, so the correction lands
  // on disk, not just in this run's in-memory classification.
  const { prunedIds } = pruneRatifiedProposals(proposals, classifications);
  if (prunedIds.length > 0) {
    // W1-T240: reapply the (already-derived, ledger-sourced) prunedIds set against a
    // FRESH read of the registry, under lock — never blind-write the `proposals` array
    // this function read at the top, which a concurrent `rmd approve`/`rmd reframe`/the
    // daemon's own `GET /v1/inbox` heal could have changed in the meantime. See
    // lib/inbox.ts's `updateProposalRegistry` doc for the lost-update/torn-file hazard
    // this guards against.
    const prunedIdSet = new Set(prunedIds);
    updateProposalRegistry(registryPath, (current) => {
      const fresh = current.filter((p) => !prunedIdSet.has(p.id));
      return fresh.length === current.length ? null : fresh;
    });
    for (const id of prunedIds) log("inbox.registry_healed", { proposal_id: id });
  }

  const rendered = renderInbox(classifications);
  console.log(rendered);
  return 0;
}

/** Load the ACTIVE-proposal registry + draft cache and classify ONE proposal against REAL
 *  facts (deriveStatus-derived merge state, real `git grep`, the whole registry as the
 *  conflict set) — the SAME readiness context `inboxCommand` classifies every proposal
 *  with, factored out so `rmd approve`/`rmd reframe` never diverge from what `rmd inbox`
 *  showed the operator. Returns `undefined` proposal when `proposalId` is not in the
 *  registry — the caller turns that into a fail-loud usage error. */
function loadProposalForRatify(
  proposalId: string,
  plan: Plan,
  ledgerPath: string,
  owner: string,
  repo: string,
  config: Config,
  inboxRoot = config.root,
): { proposal: Proposal | undefined; proposals: Proposal[]; drafts: DraftCache; draftsPath: string; classification?: InboxClassification } {
  const registryPath = join(inboxRoot, "state", "inbox-proposals.json");
  const proposals: Proposal[] = parseProposalRegistry(readFileIfExists(registryPath));
  const proposal = proposals.find((p) => p.id === proposalId);

  const draftsPath = join(inboxRoot, "state", "inbox-drafts.json");
  const drafts: DraftCache = parseDraftCache(readFileIfExists(draftsPath));

  if (!proposal) return { proposal: undefined, proposals, drafts, draftsPath };

  const deriveDeps: DeriveDeps = { ledgerPath, github: ghGateway(owner, repo) };
  const { isMerged, depsUnobservable } = buildDepsReadinessAccessors(plan, deriveDeps);
  // W1-T190: read the ledger ONCE here and cross-check it, never the registry's own copy of
  // "is this ratified" (there isn't one) — a proposal the ledger already carries
  // ratify.approved for is `ratified`, no matter what stale/drifted state the registry entry
  // itself is still in (the P19 incident this task fixes).
  const ledgerLines = readLedgerLines(ledgerPath);
  const ctx: ReadinessContext = {
    plan,
    isMerged,
    depsUnobservable,
    grepAnchorTrue: (a: EvidenceAnchor) => gitGrepAnchorTrue(repoRoot, "origin/main", a),
    retirement: inboxRetirementContext(join(inboxRoot, "state"), { instance: process.env.RMD_INSTANCE_NAME ?? "core", repository: `${owner}/${repo}`, root: inboxRoot }),
    openProposalIds: new Set(proposals.map((p) => p.id)),
    isRatified: (id) => isRatifiedInLedger(ledgerLines, id),
    isDeclined: declinedWithReceipts(ledgerLines, join(inboxRoot, "state")),
  };
  const classification = classifyProposal(proposal, drafts[proposal.id], ctx);
  return { proposal, proposals, drafts, draftsPath, classification };
}

/**
 * W1-T2471: the N-proposal counterpart of {@link loadProposalForRatify} — builds the SAME
 * {@link ReadinessContext} ONCE (one ledger read, one registry/draft-cache read) and classifies
 * every named id against it, rather than re-deriving that context once per id the way N
 * sequential `loadProposalForRatify` calls would. `proposalIds` is the EXPLICIT, ORDERED set
 * the operator named (Q4) — an id absent from the ACTIVE registry is reported in `unknown`
 * rather than silently dropped, so the caller can refuse the whole invocation on a typo instead
 * of quietly ratifying a smaller batch than the operator asked for. Every KNOWN id is
 * classified individually and returned in the SAME order it was named, whatever its state —
 * readiness triage (skip-unready-never-abort) is {@link planRatificationBatch}'s job, not this
 * loader's. */
function loadProposalsForRatify(
  proposalIds: string[],
  plan: Plan,
  ledgerPath: string,
  owner: string,
  repo: string,
  config: Config,
): { found: { id: string; proposal: Proposal; classification: InboxClassification }[]; unknown: string[] } {
  const registryPath = join(config.root, "state", "inbox-proposals.json");
  const proposals: Proposal[] = parseProposalRegistry(readFileIfExists(registryPath));
  const draftsPath = join(config.root, "state", "inbox-drafts.json");
  const drafts: DraftCache = parseDraftCache(readFileIfExists(draftsPath));

  const deriveDeps: DeriveDeps = { ledgerPath, github: ghGateway(owner, repo) };
  const { isMerged, depsUnobservable } = buildDepsReadinessAccessors(plan, deriveDeps);
  const ledgerLines = readLedgerLines(ledgerPath);
  const ctx: ReadinessContext = {
    plan,
    isMerged,
    depsUnobservable,
    grepAnchorTrue: (a: EvidenceAnchor) => gitGrepAnchorTrue(repoRoot, "origin/main", a),
    retirement: inboxRetirementContext(join(config.root, "state"), { instance: process.env.RMD_INSTANCE_NAME ?? "core", repository: `${owner}/${repo}`, root: config.root }),
    openProposalIds: new Set(proposals.map((p) => p.id)),
    isRatified: (id) => isRatifiedInLedger(ledgerLines, id),
    isDeclined: declinedWithReceipts(ledgerLines, join(config.root, "state")),
  };

  const found: { id: string; proposal: Proposal; classification: InboxClassification }[] = [];
  const unknown: string[] = [];
  for (const id of proposalIds) {
    const proposal = proposals.find((p) => p.id === id);
    if (!proposal) {
      unknown.push(id);
      continue;
    }
    found.push({ id, proposal, classification: classifyProposal(proposal, drafts[proposal.id], ctx) });
  }
  return { found, unknown };
}

export function skillLifecycleActionStillApproved(worktreeRoot: string, action: SkillLifecycleAction): boolean {
  if (action.kind !== "skill-retirement") return false;
  if (action.skillPath !== `.claude/skills/${action.skillName}/SKILL.md`) return false;
  return loadInjectableSkills(join(worktreeRoot, ".claude", "skills")).some((skill) => skill.name === action.skillName);
}

export function applySkillLifecycleRemoval(
  worktreeRoot: string,
  action: SkillLifecycleAction,
  deps: {
    approved?: (root: string, action: SkillLifecycleAction) => boolean;
    exists?: (path: string) => boolean;
    remove?: (path: string) => void;
  } = {},
): { ok: true; removedPath: string } | { ok: false; reason: string } {
  const approved = deps.approved ?? skillLifecycleActionStillApproved;
  if (!approved(worktreeRoot, action)) {
    return { ok: false, reason: `${action.skillName} is not an approved opted-in skill at ${action.skillPath}` };
  }
  const target = join(worktreeRoot, action.skillPath);
  if (!(deps.exists ?? existsSync)(target)) {
    return { ok: false, reason: `missing ${action.skillPath}` };
  }
  (deps.remove ?? unlinkSync)(target);
  return { ok: true, removedPath: action.skillPath };
}

export function skillLifecycleApproveCommitMessage(action: SkillLifecycleAction, proposalId: string): string {
  return [
    "chore(skill): retire approved skill via rmd approve",
    "",
    ...wrapBodyLines(
      [
        `Proposal ${proposalId} carried measured negative lifecycle evidence for ${action.skillName}.`,
        `Evidence fingerprint: ${action.evidenceFingerprint}`,
        "",
        "The operator's one-bit approve initiated this PR; staging the proposal did not alter the " +
          "approved skill tree. This commit removes exactly the approved SKILL.md named by the action.",
      ].join("\n"),
    ),
  ].join("\n");
}

/** W1-T4338: the commit that writes an approved skill draft. Carries NO `Remudero-Task:` trailer — it files a skill,
 *  it implements no task. */
export function skillFileApproveCommitMessage(proposalId: string, relPath: string): string {
  return [
    "chore(skill): add approved skill via rmd approve",
    "",
    ...wrapBodyLines(
      [
        `Proposal ${proposalId} staged a skill-workshop draft; the operator's one-bit approve writes it.`,
        `This commit adds exactly ${relPath}, verbatim from the staged draft.`,
      ].join("\n"),
    ),
  ].join("\n");
}

/** W1-T4338: the PR body for an approved skill draft — an executable Acceptance proof on the file this PR adds. */
export function skillFileApprovePrBody(
  proposalId: string,
  name: string,
  relPath: string,
  proofContext: Pick<PlanPrBodyOpts, "baseRef" | "proofCheck" | "proofCwd"> = {},
): string {
  const filedPaths = [relPath];
  return buildPlanPrBody({
    intro: [
      `Proposal ${proposalId} adds approved skill \`${name}\`.`,
      "",
      "The operator's one-bit approve initiated this PR. The gate still reviews it; nothing",
      "auto-merges without that review.",
    ].join("\n"),
    criteria: [{ claim: `${relPath} is the approved skill draft ${name}`, proof: `grep: name: ${name} in ${relPath}` }],
    changedFiles: filedPaths,
    ...proofContext,
  });
}

export function skillLifecyclePrBody(action: SkillLifecycleAction, proposalId: string): string {
  return [
    `Proposal ${proposalId} retires approved skill \`${action.skillName}\`.`,
    "",
    "The operator's one-bit approve initiated this PR. The gate still reviews it; nothing",
    "auto-merges without that review.",
    "",
    "## Acceptance",
    `- Removes exactly \`${action.skillPath}\`.`,
    `- Evidence fingerprint: \`${action.evidenceFingerprint}\`.`,
    "- No other approved skill file is changed by this lifecycle action.",
  ].join("\n");
}

// ── The verify-human judge's production call site (W1-T3188) ──────────────────────────────────
//
// W1-T349 built a complete, tested judge that nothing called for fourteen months. lint-plan
// refused THIS shard for the same omission until it carried a call-site criterion. So the call
// site ships in the same change as the judge, and the shard's acceptance greps for it here.

export function shadowedVerifyHumanJudge(opts: {
  mounts: Mounts;
  config: Config;
  cwd: string;
  settingsFile: string;
  log: (step: string, fields: Record<string, unknown>) => void;
  spawns?: { primary: typeof spawnWorker; shadow: typeof spawnWorker };
}): (shard: ShardUnderJudgement) => Promise<VerifyHumanVerdict> {
  let primaryServedModel: string | null = null;
  const primarySpawn = opts.spawns?.primary ?? ledgeredNonDispatchSpawn("verify-human-judge");
  const shadowSpawn = opts.spawns?.shadow ?? ledgeredNonDispatchSpawn("verify-human-shadow");
  const primary = realVerifyHumanJudge({
    ...opts,
    spawn: async (args) => {
      const result = await primarySpawn(args);
      primaryServedModel = result.servedModel ?? result.routedModel ?? null;
      return result;
    },
  });
  const primaryMount = resolveVerifyHumanJudgeMount(opts.mounts, opts.config);
  return async (shard) => {
    primaryServedModel = null;
    const verdict = await primary(shard);
    if (verdict.judgeFailed) return verdict;
    await runShadowJudge({
      surface: "verify-human", key: observedStateKey(shard),
      primaryMount, primaryDecision: verdict.decision,
      primaryServedModel,
      mounts: () => [primaryMount, resolveMount(opts.mounts, "reviewer", "low")],
      log: opts.log,
      judge: async (mount) => {
        const shadow = await spawnVerifyHumanJudgeWorker({
          shard, mount, cwd: opts.cwd, settingsFile: opts.settingsFile,
          spawn: (args) => shadowSpawn({
            ...args, maxTurns: Math.min(args.maxTurns ?? 4, 4),
            maxBudgetUsd: SHADOW_JUDGE_MAX_BUDGET_USD,
            clockBound: { boundMs: 60_000 },
          }),
        });
        const parsed = parseVerifyHumanVerdict(shadow.text);
        if (parsed.judgeFailed) throw new Error("shadow verify-human verdict unavailable");
        return { decision: parsed.decision, servedModel: shadow.servedModel ?? shadow.routedModel ?? null };
      },
    });
    return verdict;
  };
}

/** {@link routeVerifyHumanBacklog}'s effects, every one injectable — so the fail-open path and
 *  the never-writes-the-plan invariant are provable without a repo, a spawn or a network. */
export interface VerifyHumanRouteDeps {
  judge: (shard: ShardUnderJudgement) => Promise<VerifyHumanVerdict>;
  /** Verdicts already recorded, keyed by {@link observedStateKey}. */
  priorVerdicts: ReadonlyMap<string, VerifyHumanVerdict>;
  /** Optional caller-selected batch size; omitted preserves the historical unlimited pass. */
  maxJudged?: number;
  /** Stages a needs_operator or automate shard as an inbox proposal. Called ONLY on those arms. */
  stageProposal: (proposal: Proposal) => void;
  /** Writes the {@link VERIFY_HUMAN_JUDGED_STEP} row. Called on BOTH arms, always. */
  appendRow: (row: LedgerLine) => void;
  runId: string;
  /** The continue arm — see verify-human-judge.ts's release section. Absent ⇒ prior behaviour. */
  release?: VerifyHumanReleaseHook;
  releasedIds?: ReadonlySet<string>;
  releaseEscalatedKeys?: ReadonlySet<string>;
}

/** What one pass did. `skipped` are settled states; `deferred` are still due for a later pass. */
export interface VerifyHumanRouteResult {
  judged: number;
  needsOperator: string[];
  automated: string[];
  backlog: string[];
  skipped: string[];
  deferred: string[];
  /** Released to the fleet this pass (automate + risk-judge proceed). Absent reads as none. */
  released?: string[];
}

/** Production inputs for the adaptive lifetime-pressure follow-up. The route owns no plan or PR
 * mutation: it only records the judge result and stages the same idempotent inbox proposal used by
 * `verify-human-sweep`. Keeping this as a separate adapter lets the drain/daemon paths share the
 * judge without making a pressure signal a hidden blocking gate. */
type AdaptiveLifetimePressureRoute = Pick<VerifyHumanRouteDeps, "runId"> & {
  plan: Plan;
  root: string;
  config: Config;
  ledgerPath: string;
  runId: string;
  shadowJudgeSpawns?: { primary: typeof spawnWorker; shadow: typeof spawnWorker };
  clock?: Clock;
  filingHistory?: FilingHistoryOptions;
};

function lifetimeShardAge(
  taskId: string,
  nowMs: number,
  rows: readonly Record<string, unknown>[],
  filingHistory: TaskFilingHistoryInvocation,
): Pick<ShardUnderJudgement, "ageDays" | "ageUnknownReason"> {
  const fromGit = shardAgeDays(taskId, nowMs, filingHistory);
  if (fromGit.ageDays !== null) return fromGit;
  let first: number | undefined;
  for (const row of rows) {
    if (row.task_id !== taskId && row.task !== taskId) continue;
    const t = typeof row.ts === "string" ? Date.parse(row.ts) : NaN;
    if (!Number.isNaN(t) && (first === undefined || t < first)) first = t;
  }
  if (first === undefined) return fromGit;
  return { ageDays: Math.max(0, Math.floor((nowMs - first) / 86400000)) };
}

function latestLifetimeOperatorRuling(note: string | undefined): { date: string; decision: "automate" | "needs_operator" } | undefined {
  if (!note) return undefined;
  let latest: { date: string; decision: "automate" | "needs_operator" } | undefined;
  for (const match of note.matchAll(/^OPERATOR RULING (\d{4}-\d{2}-\d{2}): (automate|needs_operator)\b/gm)) {
    const date = match[1]!;
    if (!latest || date >= latest.date) latest = { date, decision: match[2] as "automate" | "needs_operator" };
  }
  return latest;
}

/** Route repeated attributable dispatch pressure through the existing three-way LLM judge. */
export async function routeAdaptiveLifetimePressure(
  tasks: readonly Task[],
  deps: AdaptiveLifetimePressureRoute,
): Promise<VerifyHumanRouteResult> {
  const rows = readLedgerLines(deps.ledgerPath) as unknown as Record<string, unknown>[];
  const nowMs = (deps.clock ?? systemClock).now();
  const filingHistory = createTaskFilingHistoryInvocation(deps.root, tasks.map(task => task.id), deps.filingHistory);
  const shards: ShardUnderJudgement[] = [];
  const infraOnly: string[] = [];
  const rulings = new Map<string, VerifyHumanVerdict>();
  for (const task of tasks) {
    const taskRows = rows.filter((row) => row.task_id === task.id || row.task === task.id);
    const attributableDispatches = taskAttributableLifetimeDispatches(rows, task.id);
    const capacityRefusals = taskRows.filter((row) => row.step === "daemon.spawn_infra_blocked").length;
    const openPrEvidence = taskRows.filter((row) => row.step === "pr.opened").length;
    const mergeEvidence = taskRows.filter((row) => row.step === "verdict.merged" || (row.step === "verdict" && row.verdict === "merged")).length;
    const terminalRows = taskRows.filter((row) => row.step === "verdict");
    const lastTerminal = terminalRows.at(-1);
    const lastVerdict = typeof lastTerminal?.verdict === "string" ? lastTerminal.verdict : "unavailable";
    const attributableHistory = terminalRows
      .filter((row) => streakRefusal(row) === undefined)
      .map((row) => `${String(row.verdict ?? "unavailable")}: ${String(row.reason ?? row.stage ?? "no reason recorded")}`);
    const ruling = latestLifetimeOperatorRuling(task.note);
    const key = `${task.id}:adaptive-lifetime=${attributableDispatches}:capacity=${capacityRefusals}:` +
      `open=${openPrEvidence}:merged=${mergeEvidence}:last=verdict:${lastVerdict}:${terminalRows.length}` +
      (ruling ? `:ruling=${ruling.date}:${ruling.decision}` : "");
    if (attributableDispatches === 0) {
      infraOnly.push(task.id);
      if (!rows.some((row) => row.step === "dispatch.lifetime_pressure.infra_only" && row.task_id === task.id && row.observed_state === key)) {
        appendLedger(deps.ledgerPath, { run_id: deps.runId, task_id: task.id,
          step: "dispatch.lifetime_pressure.infra_only", observed_state: key } as LedgerLine);
      }
      continue;
    }
    const evidence =
      `adaptive lifetime pressure: attributable dispatches=${attributableDispatches}; ` +
      `capacity refusals=${capacityRefusals}; open PR evidence=${openPrEvidence}; ` +
      `merge evidence=${mergeEvidence}; last terminal verdict=${lastVerdict}; ` +
      `attributable terminal-verdict history=${attributableHistory.join(" | ") || "none"}`;
    const shard: ShardUnderJudgement = {
      id: task.id,
      title: task.title ?? task.id,
      rationale: "Decide whether BUILDING the task needs the operator. Runtime operator confirmation " +
        "inside the feature is not a build-time need. Judge why attributable attempts keep failing; " +
        "choose automate, backlog, or needs_operator for the build process.",
      acceptance: (task.acceptance ?? []).map((criterion) => criterion.claim),
      route: "lifetime-pressure",
      attributableDispatches,
      ...lifetimeShardAge(task.id, nowMs, rows, filingHistory),
      depsAllMerged: (task.depends_on ?? []).every((id) => planTaskLanded(deps.plan.byId.get(id))),
      citedInSrc: idCitedInSrc(task.id, deps.root),
      evidence,
      observationKey: key,
    };
    shards.push(shard);
    if (ruling) rulings.set(key, { decision: ruling.decision, reason: `Operator ruling ${ruling.date}: ${ruling.decision}` });
  }
  const judge = shadowedVerifyHumanJudge({
      mounts: loadMounts(mountsPath(deps.root)),
      config: deps.config,
      cwd: deps.root,
      settingsFile: join(deps.root, "settings", "worker.json"),
      log: (step, fields) => appendLedger(deps.ledgerPath, { run_id: deps.runId, step, ...fields } as LedgerLine),
      spawns: deps.shadowJudgeSpawns,
    });
  const result = await routeVerifyHumanBacklog(shards, {
    judge: async (shard) => rulings.get(observedStateKey(shard)) ?? judge(shard),
    priorVerdicts: priorVerifyHumanVerdicts(rowsWithArchivedVerifyHumanVerdicts(deps.ledgerPath, rows)),
    maxJudged: tasks.length,
    stageProposal: (proposal) =>
      void stageInboxProposalOnce(join(deps.config.root, "state", "inbox-proposals.json"), proposal),
    appendRow: (row) => appendLedger(deps.ledgerPath, row as LedgerLine),
    runId: deps.runId,
  });
  result.skipped.push(...infraOnly);
  return result;
}

/**
 * The production `onLifetimePressure` hook, EXTRACTED so its body is reachable from a test.
 *
 * Inline in `drainCommand`/`daemonCommand` the surrounding deps object IS covered — both commands
 * are driven by real tests with `runDaemon`/`runDrain` stubbed — but an `async (tasks) => { … }`
 * body only runs when real pressure occurs, so `diff-coverage` named exactly those body lines.
 * Lifting the body out leaves one expression per call site that runs at CONSTRUCTION. Same
 * extraction-and-injection remedy {@link resolveEventPath} documents in this file.
 *
 * `plan` is a THUNK, not a value: the daemon re-projects its active plan every tick, so the hook
 * must read it when it FIRES. Capturing `activePlanRef.current` eagerly would pin the first tick's
 * projection for the life of the process.
 */
type ProductionLifetimePressureHookInputs = {
  plan: () => Plan;
  root: string;
  config: Config;
  ledgerPath: string;
  runId: string;
};

export function productionLifetimePressureHook(
  deps: ProductionLifetimePressureHookInputs,
): (tasks: readonly Task[]) => Promise<void> {
  return async (tasks) => {
    await routeAdaptiveLifetimePressure(tasks, {
      plan: deps.plan(),
      root: deps.root,
      config: deps.config,
      ledgerPath: deps.ledgerPath,
      runId: deps.runId,
    });
  };
}

/**
 * Judge the parked `verify: human` population and route the verdicts.
 *
 * THE PLAN IS NEVER WRITTEN HERE, and there is no code path that could: this function's only
 * effects are `deps.appendRow` and `deps.stageProposal`. No fs write, no plan load, no
 * `verify:` edit. Design clause (ii) is a signature, not a promise.
 *
 * A SETTLED SHARD IS NOT RE-ASKED (design iv): 56 shards times every poll is a token event, not
 * a sweep. A FAILED verdict is never settled, so a judge outage self-heals on the next pass
 * instead of pinning the whole population to the ask list.
 */
export async function routeVerifyHumanBacklog(
  shards: readonly ShardUnderJudgement[],
  deps: VerifyHumanRouteDeps,
): Promise<VerifyHumanRouteResult> {
  const releasedIds = deps.releasedIds ?? new Set<string>();
  // A released task is the fleet's now: never re-judged, never re-released.
  const due = shardsNeedingJudgement(shards, deps.priorVerdicts).filter((s) => !releasedIds.has(s.id));
  // W1-T3921: failed verdict remains eligible for the next batch
  const dueIds = new Set(due.map((s) => s.id));
  // W1-T3921: --limit <n> applies only to due observed states
  const toJudge = deps.maxJudged === undefined ? due : due.slice(0, deps.maxJudged);
  const result: VerifyHumanRouteResult = {
    judged: 0,
    needsOperator: [],
    automated: [],
    backlog: [],
    skipped: shards.filter((s) => !dueIds.has(s.id)).map((s) => s.id),
    // W1-T3921: deferred due work remains due for the next pass
    deferred: due.slice(toJudge.length).map((s) => s.id),
    released: [],
  };
  const automateHooks = {
    release: deps.release,
    stageProposal: deps.stageProposal,
    appendRow: (row: Record<string, unknown>) => deps.appendRow(row as LedgerLine),
    runId: deps.runId,
  };
  const bucketOf = (bucket: "released" | "needsOperator" | "automated"): string[] =>
    bucket === "released" ? (result.released ??= []) : bucket === "needsOperator" ? result.needsOperator : result.automated;
  // THE BACKFILL — the same rule the daemon cadence applies: a shard settled as automate before the
  // release arm existed is otherwise never revisited.
  if (deps.release) {
    for (const shard of awaitingRelease(shards, deps.priorVerdicts, releasedIds, deps.releaseEscalatedKeys ?? new Set())) {
      const prior = deps.priorVerdicts.get(observedStateKey(shard));
      if (!prior) continue;
      bucketOf(await applyAutomateVerdict(shard, prior, automateHooks)).push(shard.id);
    }
  }
  for (const shard of toJudge) {
    const verdict = await judgeVerifyHumanShard(shard, { judge: deps.judge });
    // UNCONDITIONAL, and BEFORE either arm: a crash between the verdict and its effect leaves
    // the verdict readable rather than leaving a silent gap.
    deps.appendRow(verifyHumanVerdictRow(shard, verdict, deps.runId) as LedgerLine);
    result.judged += 1;
    if (verdict.decision === "needs_operator") {
      deps.stageProposal(proposalFromJudgedShard(shard, verdict));
      result.needsOperator.push(shard.id);
      continue;
    }
    if (verdict.decision === "automate") {
      bucketOf(await applyAutomateVerdict(shard, verdict, automateHooks)).push(shard.id);
      continue;
    }
    result.backlog.push(shard.id);
  }
  return result;
}

/**
 * W1-T10077: the live ledger's rows with every archived `verify_human.judged` row ahead of them, so a settled shard
 * whose row rotated out of the carry-capped live file is not judged again. The live rows come last and win a key.
 * An archive that cannot be read whole contributes what it did read: a missing row only ever costs one more judge call.
 */
export function rowsWithArchivedVerifyHumanVerdicts(ledgerPath: string, live: readonly Record<string, unknown>[]): Record<string, unknown>[] {
  const archived = readLedgerUnionRecordsSync(dirname(ledgerPath), { step: [VERIFY_HUMAN_JUDGED_STEP] });
  return [...archived.rows, ...live];
}

/** Verdicts already on the ledger, keyed by the observed state they were taken against —
 *  {@link routeVerifyHumanBacklog}'s `priorVerdicts`. A row with no `observed_state` predates
 *  the key and is ignored rather than guessed at. */
export function priorVerifyHumanVerdicts(rows: readonly Record<string, unknown>[]): Map<string, VerifyHumanVerdict> {
  const out = new Map<string, VerifyHumanVerdict>();
  for (const row of rows) {
    if (row?.step !== VERIFY_HUMAN_JUDGED_STEP) continue;
    const key = row.observed_state;
    const decision = row.judge_decision;
    if (typeof key !== "string" || !key) continue;
    if (decision !== "needs_operator" && decision !== "automate" && decision !== "backlog") continue;
    out.set(key, {
      decision,
      reason: typeof row.judge_reason === "string" ? row.judge_reason : "",
      ...(row.judge_failed === true ? { judgeFailed: true as const } : {}),
    });
  }
  return out;
}

/**
 * `rmd verify-human-sweep` — W1-T3188's REAL entry point, and the reason
 * {@link realVerifyHumanJudge} is not another imported-but-uncalled factory. Judges the parked
 * `verify: human` population once and routes the verdicts: `needs_operator` shards become inbox
 * proposals, the rest stay in the visible backlog.
 *
 * TOUCHES NO PLAN FILE. It reads the plan, writes ledger rows and stages proposals. `--dry-run`
 * judges nothing and spends nothing; it reports which shards a real pass WOULD ask about.
 */
/** The daemon's machine-filing judge (operator ruling 2026-09-29) over this checkout's plan, mounts
 *  and policy. The risk judge is built on first use, as {@link productionVerifyHumanRelease}'s is. */
/**
 * W1-T10371: the operator's four mechanical rulings' ports, wired from the ledger union and the gardeners' own windows.
 * A symptom has a reader only for the families whose history the ledger holds: a scout record's own step (rows across
 * {@link SCOUT_WINDOW_MS}) and a ci-friction record's cause key (rounds across {@link CI_FRICTION_HALF_LIFE_MS}). Every
 * other family reads as undefined, which the rules treat as undecided, so it keeps the judge path it had.
 * A release goes through {@link approveParkedTask}, whose every guard stands.
 */
export function productionMechanicalPort(opts: {
  repoRoot: string;
  stateDir: string;
  clock?: Clock;
  /** Test seams: the union reader and the ci-friction ledger records. */
  reader?: typeof readLedgerUnionRecordsSync;
  ciFrictionRecords?: () => LedgerRecord[];
}): MechanicalPort {
  const clock = opts.clock ?? systemClock;
  const ledgerPath = join(opts.stateDir, LEDGER_FILENAME);
  const reader = opts.reader ?? readLedgerUnionRecordsSync;
  return {
    read: (tasks) => {
      const nowMs = clock.now();
      const scoutSteps = [...new Set(tasks.flatMap((t) => (t.origin?.startsWith("scout:") ? [t.origin.slice("scout:".length)] : [])))];
      let scoutRows: readonly Record<string, unknown>[] | undefined;
      let ciRounds: ReturnType<typeof ciFrictionRoundsFromLedger> | undefined;
      // ledger-read-intent: live — a decline or restore the receipts store has not retained yet.
      const declinedOf = declinedWithReceipts(readLedgerLines(ledgerPath) as unknown as Record<string, unknown>[], opts.stateDir);
      return {
        symptom: (task): SymptomReading | undefined => {
          const origin = task.origin ?? "";
          if (origin.startsWith("scout:")) {
            if (scoutRows === undefined) {
              const read = reader(opts.stateDir, { sinceTs: new Date(nowMs - SCOUT_WINDOW_MS).toISOString(), step: scoutSteps, refuseIncomplete: true });
              if (!read.ok) throw new Error(`incomplete ledger union: ${read.unread.join(", ")}`);
              scoutRows = read.rows;
            }
            const step = origin.slice("scout:".length);
            const filing = filingEvidenceOf(task, SCOUT_WINDOW_MS);
            return { ...countStepRows(scoutRows, step, nowMs, SCOUT_WINDOW_MS), ...(filing ? { filing } : {}) };
          }
          const cause = parseCiFrictionOrigin(origin);
          if (cause === undefined) return undefined;
          ciRounds ??= ciFrictionRoundsFromLedger((opts.ciFrictionRecords ?? (() => readCiFrictionLedgerRecords(opts.stateDir)))());
          const filing = filingEvidenceOf(task, CI_FRICTION_HALF_LIFE_MS);
          const matches = (r: { cause: Parameters<typeof ciFrictionCauseKey>[0]; pr: number; evidence?: Parameters<typeof ciFrictionRoundMatchesCause>[0]["evidence"] }): boolean =>
            ciFrictionRoundMatchesCause({ pr: r.pr, causeKey: ciFrictionCauseKey(r.cause), ...(r.evidence ? { evidence: r.evidence } : {}) }, cause.key);
          return { ...countRounds(ciRounds, matches, nowMs, CI_FRICTION_HALF_LIFE_MS), ...(filing ? { filing } : {}) };
        },
        declined: (task) => declinedOf(`machine-judge:${task.id}`) !== undefined || declinedOf(`verify-human:${task.id}`) !== undefined,
      };
    },
    release: (task, provenance) => approveParkedTask(task.id, {
      plan: { tasks: [task], byId: new Map([[task.id, task]]) },
      ledgerPath,
      runId: `machine-judge-mechanical-${nextLaneEpochMs()}`,
      riskPolicy: readRiskPolicy(policyPath(opts.repoRoot)),
      provenance: { ...provenance },
    }),
  };
}

export function productionMachineFilingJudgePorts(opts: {
  repoRoot: string;
  stateDir: string;
  worktreesRoot: string;
  owner: string;
  repo: string;
  log: (step: string, extra?: Record<string, unknown>) => void;
  spawn?: typeof spawnWorker;
  fetcher?: GhApiFetcher;
  clock?: Clock;
  /** Test files main's CI failed at a sha (W1-T9694). Absent: read from GitHub, as the flake-incident gardener does. */
  mainFailures?: SelectorShadowMainFailures;
}): MachineJudgePorts {
  let mount: Mount | undefined;
  const fetcher = opts.fetcher ?? ghJson;
  return {
    mechanical: productionMechanicalPort({ repoRoot: opts.repoRoot, stateDir: opts.stateDir, clock: opts.clock }),
    flakeEvidence: flakeJudgeEvidencePort({
      stateDir: opts.stateDir, log: opts.log, clock: opts.clock ?? systemClock,
      mainFailures: opts.mainFailures ?? selectorShadowMainFailures(opts.owner, opts.repo),
      // ledger-read-intent: live — the main.repair rows the main-health rung itself reads.
      repairs: () => [...mainRepairRecordsFromLedger(readLedgerLines(join(opts.stateDir, LEDGER_FILENAME))).values()],
    }),
    stateDir: opts.stateDir,
    plan: async () => {
      const mainSha = await mainTipViaGit(opts.repoRoot);
      const committed = await loadPlanAtRefAsync(opts.repoRoot, relative(opts.repoRoot, resolveRepoLayout(opts.repoRoot).planMonolith), mainSha);
      // The judge uses sourcePath to address the corresponding record in its fresh landing
      // checkout. Keep those paths anchored here while every record's bytes come from mainSha.
      const tasks = committed.tasks.map(task => ({
        ...task, sourcePath: join(opts.repoRoot, task.sourcePath!.slice(mainSha.length + 1)),
      }));
      return { tasks, byId: new Map(tasks.map(task => [task.id, task])) };
    },
    riskJudge: (input) => {
      if (!mount) {
        const mounts = loadMounts(mountsPath(opts.repoRoot));
        mount = mounts.machine_filing_judge ?? resolveRiskJudgeMount(mounts);
      }
      // Per-judgment receipts precede parse retries; symbol-only identity preserves router inputs.
      const identity = { runId: `machine-judge-${nextLaneEpochMs()}`, taskId: input.planContext.taskId ?? "RISK-JUDGE" };
      const spawn = opts.spawn ?? ledgeredNonDispatchSpawn("risk-judge");
      const record = (result: WorkerResult | undefined, assignmentId: string | undefined): void => {
        try {
          let resources: ReturnType<typeof benchmarkWorkerAttemptResources> | undefined;
          try { if (result) resources = benchmarkWorkerAttemptResources(result); }
          catch { /* unavailable accounting is unknown, never a replacement judgment */ }
          const { billing_mode = "unknown" } = resources ?? {};
          const price = resources?.total_cost_usd, notional = resources?.notional_cost_usd;
          const priced = typeof price === "number" && Number.isFinite(price) && price >= 0;
          opts.log("machine_judge.attempt_spend", {
            run_id: identity.runId, task_id: identity.taskId,
            ...attemptAssignmentJoin(assignmentId, result === undefined),
            attempt_state: result ? "result" : assignmentId ? "failed" : "not-started",
            accounting_source: "worker-result-estimate-not-invoice",
            provider: result?.provider === "claude" || result?.provider === "codex" || result?.provider === "cash" ? result.provider : "unknown",
            billing_mode,
            price_state: priced ? "reported" : "unknown",
            ...(priced ? { total_cost_usd: price } : {}),
            ...(typeof notional === "number" && Number.isFinite(notional) && notional >= 0 ? { notional_cost_usd: notional } : {}),
          });
        } catch { /* a telemetry failure must not change the ruling, retries or provider result */ }
      };
      return realRiskJudge({ mount, cwd: opts.repoRoot, settingsFile: join(opts.repoRoot, "settings", "worker.json"),
        spawn: async (args) => {
          let assignmentId: string | undefined;
          const recorded = new Set<string>();
          const recordedResults = new WeakSet<WorkerResult>();
          const recordAttempt = (result: WorkerResult | undefined, id: string | undefined): void => {
            // A fallback observer and final return can carry the same result object without IDs.
            if (result !== undefined && recordedResults.has(result) || id !== undefined && recorded.has(id)) return;
            record(result, id);
            if (result !== undefined) recordedResults.add(result);
            if (id !== undefined) recorded.add(id);
          };
          try {
            const result = await spawn(withReceiptIdentity({ ...args,
              onSelectionAssignment: (assignment) => { assignmentId = assignment.id; args.onSelectionAssignment?.(assignment); },
              onModelFallbackAttempt: (attempt) => {
                recordAttempt(attempt.result, attempt.selectionAssignmentId);
                args.onModelFallbackAttempt?.(attempt);
              },
            }, identity));
            recordAttempt(result, result.selectionAssignmentId ?? assignmentId);
            return result;
          } catch (error) {
            recordAttempt(undefined, assignmentId);
            throw error;
          }
        } })(input);
    },
    riskPolicy: () => readRiskPolicy(policyPath(opts.repoRoot)),
    gardenRecord: (family) => gardenFamilyRecord(opts.stateDir, family),
    operatorReleases: () => readOperatorReleaseRecords(opts.stateDir),
    releaseLedgerLines: () => readReleaseLedgerLines(join(opts.stateDir, LEDGER_FILENAME)),
    // W1-T9043: a ledgered release, `rmd release`, or an `rmd note` on a parked escalation is a ruling that stops its withdrawal.
    operatorRulings: () => {
      // ledger-read-intent: live — `dispatch.breaker_released` is in the retention set, and `rmd approve` is durable in operator-releases.json.
      const ledgered = operatorRulingTimes(readLedgerLines(join(opts.stateDir, LEDGER_FILENAME)) as unknown as Record<string, unknown>[]);
      return (taskId) => {
        const store = operatorNoteStore({ stateDir: opts.stateDir, repository: `${opts.owner}/${opts.repo}`, legacyRoot: opts.repoRoot });
        const times = [ledgered.get(taskId), loadOperatorNotesForTask(store, taskId).at(-1)?.ts].filter((t): t is string => t !== undefined);
        return times.sort((a, b) => Date.parse(a) - Date.parse(b)).at(-1);
      };
    },
    openWorkspace: () => gardenCheckoutAsync({ name: "machine-judge", repoDir: opts.repoRoot, worktreesRoot: opts.worktreesRoot, owner: opts.owner, repo: opts.repo, log: opts.log, fetcher, clock: opts.clock }),
    prState: (prUrl) => gardenPrState(opts.owner, opts.repo, prUrl, fetcher),
    stageProposal: (proposal) => void stageInboxProposalOnce(join(opts.stateDir, "inbox-proposals.json"), proposal),
    log: opts.log,
    clock: opts.clock ?? systemClock,
  };
}

/**
 * The PRODUCTION continue arm, shared by the daemon cadence and `rmd verify-human-sweep`. See
 * lib/verify-human-release.ts for the contract: a filing-time risk judge must say PROCEED, and the
 * release is the `ratify.approved` row `rmd approve` already writes — now carrying a machine author.
 *
 * THE RISK JUDGE IS BUILT LAZILY, on the first release attempt. Resolving a mount can throw, and an
 * eager build inside the cadence's try-block would turn a missing mount into a refused rung for
 * every shard — including the ones that only needed a needs_operator proposal.
 */
export function productionVerifyHumanRelease(
  plan: Plan,
  checkoutRoot: string,
  ledgerPath: string,
  runId: string,
  options: {
    riskJudge?: (input: RiskJudgeInput) => Promise<RiskJudgeVerdict>;
    /** Live policy reader. The production callers pass plan/policy.yaml; omitted keeps old tests and callers byte-safe. */
    riskPolicy?: () => RiskPolicy;
    /** Forwarded to realRiskJudge, so a test drives the REAL construction (mount resolution and
     *  parsing included) without a model call. */
    spawn?: typeof spawnWorker;
  } = {},
): VerifyHumanReleaseHook {
  let judge = options.riskJudge;
  const readCurrentRiskPolicy = options.riskPolicy ?? (() => {
    try {
      return readRiskPolicy(policyPath(checkoutRoot));
    } catch (e) {
      // Tests and older callers may provide a synthetic checkout with no policy file; preserve
      // their pre-policy behavior. Malformed or unreadable policy files still fail closed below.
      if ((e as NodeJS.ErrnoException)?.code === "ENOENT") return DEFAULT_RISK_POLICY;
      throw e;
    }
  });
  const riskJudge = (input: RiskJudgeInput): Promise<RiskJudgeVerdict> => {
    judge ??= realRiskJudge({ mount: resolveRiskJudgeMount(loadMounts(mountsPath(checkoutRoot))), cwd: checkoutRoot, settingsFile: join(checkoutRoot, "settings", "worker.json"), spawn: options.spawn ?? ledgeredNonDispatchSpawn("risk-judge") });
    return judge(input);
  };
  return async (shard, verdict) => {
    let riskPolicy: RiskPolicy;
    try {
      riskPolicy = readCurrentRiskPolicy();
    } catch (e) {
      return { kind: "unavailable", reason: `risk policy unavailable: ${String((e as Error)?.message ?? e)}` };
    }
    return releaseAutomatedShard(shard, verdict, {
      task: (id) => plan.byId.get(id),
      riskJudge,
      riskPolicy,
      writeRelease: (taskId, provenance, resolvedPolicy) =>
        approveParkedTask(taskId, {
          plan,
          ledgerPath,
          runId,
          riskPolicy: resolvedPolicy,
          provenance: { ...provenance },
        }),
    });
  };
}

export async function verifyHumanSweepCommand(
  rest: string[],
  deps: {
    root?: string;
    route?: typeof routeVerifyHumanBacklog;
    clock?: Clock;
    /** The fourth seam, and the one that makes the rest of this function reachable: `loadConfig()`
     *  shells `which claude`, which no CI runner has (W1-T2 / PR #18). Omitted, byte-identical. */
    config?: Config;
  } = {},
): Promise<number> {
  const root = deps.root ?? repoRoot;
  const dryRun = rest.includes("--dry-run");
  const badArg = unknownArgError("verify-human-sweep", rest, ["--limit"], ["--dry-run"]);
  if (badArg) {
    console.error(`${badArg}\n` + USAGE);
    return 2;
  }
  const limitProvided = rest.includes("--limit");
  const limitText = flagValue(rest, "--limit");
  const limit = limitProvided && limitText !== undefined && /^[1-9]\d*$/.test(limitText) ? Number(limitText) : undefined;
  // W1-T3921: invalid batch limits refuse before any sweep side effect
  if (limitProvided && (limit === undefined || !Number.isSafeInteger(limit))) {
    console.error("rmd verify-human-sweep: --limit must be a positive safe integer");
    return 2;
  }

  const config = deps.config ?? loadConfig();
  const plan = loadPlan(join(root, "plan", "tasks.yaml"));
  const ledgerPath = ledgerPathFor(config);
  // status.ts's reader, which already parses and already skips an unreadable line — no second
  // JSON pass, and one bad line never hides the verdicts around it.
  const rows = readLedgerLines(ledgerPath) as unknown as Record<string, unknown>[];
  const shards = withWhyMeJudgmentInput(parkedVerifyHumanShards(plan, root, deps.clock ?? systemClock, readMergeCreditedTaskIds(ledgerPath).credited), join(config.root, "state"), readPersistedInbox(join(config.root, "state")), (deps.clock ?? systemClock).now(), { repository: githubRepoSlugOfCheckout(root), instance: process.env.RMD_INSTANCE_NAME });
  const priorVerdicts = priorVerifyHumanVerdicts(rowsWithArchivedVerifyHumanVerdicts(ledgerPath, rows));

  if (dryRun) {
    const due = shardsNeedingJudgement(shards, priorVerdicts);
    const selected = limit === undefined ? due : due.slice(0, limit);
    const deferred = due.length - selected.length;
    console.log(`verify-human-sweep --dry-run: ${shards.length} parked shard(s), ${selected.length} would be judged, ${shards.length - due.length} already settled, ${deferred} deferred due. Nothing spent.`);
    for (const d of selected) console.log(`  would judge ${d.id} (${observedStateKey(d)})`);
    const pending = awaitingRelease(shards, priorVerdicts, resolveReleasedIds(releaseReadersFor(ledgerPath), plan), releaseEscalatedKeys(rows));
    console.log(`verify-human-sweep --dry-run: ${pending.length} earlier automate verdict(s) would be put to the risk judge for release.`);
    for (const d of pending) console.log(`  would release-check ${d.id}`);
    return 0;
  }

  // The STATE root, never the checkout: `ledgerPathFor(config)` resolves under `config.root`, and
  // a decision whose ledger row and whose proposal land in different directories is half-recorded.
  const registryPath = join(config.root, "state", "inbox-proposals.json");
  const sweepRunId = `VHSWEEP-${(deps.clock ?? systemClock).iso()}`;
  const result = await (deps.route ?? routeVerifyHumanBacklog)(shards, {
    judge: shadowedVerifyHumanJudge({
      mounts: loadMounts(mountsPath(root)),
      config,
      cwd: root,
      settingsFile: join(root, "settings", "worker.json"),
      log: (step, fields) => appendLedger(ledgerPath, { run_id: sweepRunId, step, ...fields } as LedgerLine),
    }),
    priorVerdicts,
    maxJudged: limit,
    stageProposal: (proposal) =>
      void updateProposalRegistry(registryPath, (current) =>
        current.some((existing) => existing.id === proposal.id) ? null : [...current, proposal],
      ),
    appendRow: (row) => appendLedger(ledgerPath, row),
    runId: sweepRunId,
    release: productionVerifyHumanRelease(plan, root, ledgerPath, sweepRunId),
    releasedIds: resolveReleasedIds(releaseReadersFor(ledgerPath), plan),
    releaseEscalatedKeys: releaseEscalatedKeys(rows),
  });

  const deferred = result.deferred ?? [];
  // Keep the reporting boundary tolerant of older/injected route seams. A missing collection
  // means no entries, never a crash after the sweep has already written its ledger/proposals.
  const needsOperator = result.needsOperator ?? [];
  const automated = result.automated ?? [];
  console.log(`verify-human-sweep: judged ${result.judged}, ${needsOperator.length} need you, ${automated.length} entered self-improvement, ${result.backlog.length} stay in the backlog, ${result.skipped.length} already settled, ${deferred.length} deferred due.`);
  for (const id of needsOperator) console.log(`  NEEDS YOU: ${id} — staged as verify-human:${id} in the inbox`);
  for (const id of automated) console.log(`  AUTOMATE: ${id} — staged as verify-human-automate:${id} in the inbox`);
  for (const id of result.released ?? []) console.log(`  RELEASED: ${id} — risk judge said proceed; dispatch-eligible now`);
  return 0;
}

/** Has this plan task LANDED, by the credit `deriveStatus` honours rather than the decorative yaml `status:`?
 *  `merged` or `done` status, an explicit `pr:` number (precedence source (b)), or a ledger merge credit. */
export function planTaskLanded(task: Task | undefined, ledgerCredited?: ReadonlySet<string>): boolean {
  if (!task) return false;
  return task.status === "merged" || task.status === "done" || typeof task.pr === "number" || ledgerCredited?.has(task.id) === true;
}

/** The parked population, as {@link ShardUnderJudgement} — the ONE place plan records become
 *  judgeable input. Reads the plan and greps src/; writes nothing. */
export function parkedVerifyHumanShards(plan: Plan, root: string, clock: Clock, ledgerCredited?: ReadonlySet<string>, filingHistoryOptions: FilingHistoryOptions = {}): ShardUnderJudgement[] {
  const nowMs = clock.now();
  const out: ShardUnderJudgement[] = [];
  const candidates = plan.tasks.filter(task => {
    // The machine-filing judge routes AND releases every machine record and every operator record that
    // is not ruling-shaped (operator ruling 2026-09-29); only rulings stay on this operator-facing sweep.
    // W1-T4860: "queued" and "landed" read the credit the dispatcher and board use, not the raw yaml `status:` —
    // a ruling already executed and credited (`pr:`, `done`, ledger merge credit) is settled, never judged again.
    // W1-T9043: a machine record the judge ESCALATED to a person is admitted too, so it rides the 14/30/60-day
    // age-band re-asks a person already reads; an unjudged machine record stays the machine-filing judge's alone.
    const heldForAPerson = task.author_class === "machine" ? parkedEscalation(task) : isRulingShaped(task);
    return task.verify === "human" && task.status === "queued" && !planTaskLanded(task, ledgerCredited) && heldForAPerson;
  });
  const filingHistory = createTaskFilingHistoryInvocation(root, candidates.map(task => task.id), filingHistoryOptions);
  for (const task of candidates) {
    const deps = task.depends_on ?? [];
    out.push({
      id: task.id,
      title: task.title ?? task.id,
      rationale: (task as { rationale?: string }).rationale ?? "",
      acceptance: (task.acceptance ?? []).map((c) => c.claim),
      ...shardAgeDays(task.id, nowMs, filingHistory),
      depsAllMerged: deps.every((d) => planTaskLanded(plan.byId.get(d), ledgerCredited)),
      citedInSrc: idCitedInSrc(task.id, root),
      ...(() => {
        const evidence = shardEvidence(task);
        return evidence ? { evidence } : {};
      })(),
    });
  }
  return out;
}

/**
 * The evidence a shard's OWN RECORD carries, summarised for {@link ShardUnderJudgement.evidence}.
 *
 * WHY: `rationale` was the only free text passed, and NONE of the 42 machine-filed CI-learning
 * shards has one — while ALL 42 carry `ci_learning_prs`. The judge saw a title claiming "36 PULL
 * REQUESTS" and no pull requests, and refused it saying so. Right on its input.
 *
 * BOUNDED: one `note` here lists a hundred-plus paths from a single repair, so the corpus goes as
 * a count plus head sample and the note as its leading sentence — enough to identify the gate, not
 * a transcript. `undefined` when there is nothing to say, never "", so a shard with no evidence
 * reads differently from one whose evidence was withheld.
 */
export function shardEvidence(task: Task): string | undefined {
  const rec = task as unknown as Record<string, unknown>;
  const parts: string[] = [];

  const prs = rec.ci_learning_prs;
  if (Array.isArray(prs) && prs.length > 0) {
    const head = prs.slice(0, 12).join(", ");
    parts.push(
      `corpus: ${prs.length} pull request(s) — ${head}${prs.length > 12 ? `, … (${prs.length - 12} more)` : ""}`,
    );
  }
  if (typeof rec.origin === "string" && rec.origin) parts.push(`origin: ${rec.origin}`);
  if (Array.isArray(task.files) && task.files.length > 0) parts.push(`declared files: ${task.files.join(", ")}`);
  if (typeof rec.note === "string" && rec.note) {
    // The leading sentence only — these notes run to thousands of characters of path lists.
    const lead = rec.note.split(/(?<=\.)\s/)[0]?.trim() ?? "";
    if (lead) parts.push(`note: ${lead.slice(0, 300)}`);
  }
  return parts.length > 0 ? parts.join("\n") : undefined;
}

/** Days since the exact task record was introduced in qualified Git history, or `null` with the reason it could
 *  not be read — never 0, which reads as "filed today" (#7911). Age is CONTEXT for the judge,
 *  never a threshold — nothing here decides anything from it. */
function shardAgeDays(taskId: string, nowMs: number, invocation: TaskFilingHistoryInvocation): Pick<ShardUnderJudgement, "ageDays" | "ageUnknownReason"> {
  const history = resolveTaskFilingHistory(taskId, invocation);
  if (history.state === "unknown") return { ageDays: null, ageUnknownReason: history.reason };
  return { ageDays: Math.max(0, Math.floor((nowMs - history.committerSeconds * 1000) / 86400000)) };
}

/** Whether anything under src/ cites this id — evidence the work may already have landed under
 *  another shard. `git grep` exits 1 on no match, which is an ANSWER, not a failure. */
function idCitedInSrc(taskId: string, root: string): boolean {
  const r = spawnSync("git", ["-C", root, "grep", "-l", "-F", "--", taskId, "--", "src"], { encoding: "utf8" });
  return r.status === 0 && r.stdout.trim().length > 0;
}

// ── The ruling judge's production call site (W1-T3212) ────────────────────────────────────────
//
// W1-T349 built a complete, tested escalation judge that had ZERO production callers until
// W1-T3166 wired it fourteen months later. That is this pattern's documented failure mode, so
// this judge's call site ships in the same change as the judge, and the shard's own acceptance
// greps for it here rather than trusting that someone will come back for it.

/** `routeRuling`'s outward effects, every one injectable — so the fail-closed paths this
 *  function exists for are provable at the CALL SITE without a repo, a spawn or a network.
 *  `standingDecisions` is the decision record's current text, READ BY THE CALLER: keeping the
 *  file read out here is what lets the contradiction check be unit-tested. */
export interface RouteRulingDeps {
  judge: (r: AgentRuling) => Promise<RulingJudgeVerdict>;
  standingDecisions: string;
  /** Lands the recorded entry. Called ONLY on the `record` arm. */
  land: (relPath: string, content: string) => void;
  /** Stages the refused ruling as an inbox proposal. Called ONLY on the `escalate` arm. */
  stageProposal: (proposal: Proposal) => void;
  /** Writes the {@link RULING_JUDGED_STEP} row. Called on BOTH arms, always. Typed as a
   *  {@link LedgerLine} rather than a loose record so a row missing `step`/`task_id`/`run_id` —
   *  the three fields every reader of this row joins on — cannot compile. */
  appendRow: (row: LedgerLine) => void;
  /** The Clock PORT, never a bespoke `now`-shaped field: clock-signature-census.test.ts
   *  ratchets exactly that declaration shape per file, because four incompatible ones had already
   *  accumulated across this repo before the port existed. */
  clock: Clock;
}

/** What one routed ruling did: the verdict, and which arm it actually took. */
export interface RouteRulingResult {
  decision: RulingJudgeVerdict["decision"];
  reason: string;
  /** Set only when the ruling was RECORDED. */
  landedPath?: string;
  /** Set only when the ruling was ESCALATED. */
  proposalId?: string;
}

/**
 * Route ONE agent-authored ruling: judge it, ledger the verdict, and take exactly one arm.
 *
 * THE LEDGER WRITE IS UNCONDITIONAL AND HAPPENS BEFORE EITHER ARM, so a crash between the
 * verdict and its effect leaves the verdict readable rather than leaving a silent gap — the
 * exact residue that made proving the escalation judge had never run take three reads.
 *
 * THE ARMS ARE EXCLUSIVE BY CONSTRUCTION: there is one `if` and it returns. Nothing lands on
 * the escalate arm, and nothing is staged on the record arm; the suite asserts both directions,
 * because "records AND also asks" would quietly re-create the duplicated audit trail design
 * clause (iii) exists to prevent.
 */
export async function routeRuling(ruling: AgentRuling, deps: RouteRulingDeps): Promise<RouteRulingResult> {
  const verdict = await judgeRulingRisk(ruling, { judge: deps.judge, standingDecisions: deps.standingDecisions });
  deps.appendRow({
    step: RULING_JUDGED_STEP,
    task_id: ruling.taskId,
    run_id: ruling.runId,
    author: ruling.author,
    judge_decision: verdict.decision,
    judge_reason: verdict.reason,
  });
  if (verdict.decision === "record") {
    const relPath = rulingRecordRelPath(ruling.taskId, ruling.runId);
    deps.land(relPath, rulingRecordContent(ruling, verdict, deps.clock.iso()));
    return { decision: verdict.decision, reason: verdict.reason, landedPath: relPath };
  }
  const proposal = proposalFromRefusedRuling(ruling, verdict);
  deps.stageProposal(proposal);
  return { decision: verdict.decision, reason: verdict.reason, proposalId: proposal.id };
}

/** Everything the decision record currently says, as ONE string for the contradiction check:
 *  `DECISIONS.md` plus every landed `plan/decisions.d/**` shard, since a record that landed
 *  through the bridge but has not been folded into the root file is no less standing. An
 *  unreadable path contributes nothing rather than throwing — and contributing nothing is the
 *  SAFE direction here only because an unresolvable `supersedes` escalates anyway. */
export function readStandingDecisions(root: string): string {
  const parts: string[] = [];
  try {
    parts.push(readFileSync(join(root, "DECISIONS.md"), "utf8"));
  } catch {
    // no root decision file in this checkout — the shards below are still consulted
  }
  const dir = join(root, "plan", "decisions.d");
  let entries: string[] = [];
  try {
    entries = readdirSync(dir);
  } catch {
    // no plan/decisions.d in this checkout — DECISIONS.md alone is the whole standing record here,
    // which is a real state (a fresh clone before the first landing), not a read failure to report
    return parts.join("\n");
  }
  for (const name of entries) {
    if (!name.endsWith(".md")) continue;
    try {
      parts.push(readFileSync(join(dir, name), "utf8"));
    } catch {
      // one unreadable shard never hides the rest
    }
  }
  return parts.join("\n");
}

/**
 * `rmd rule` — an agent records a ruling, behind the judge (W1-T3212, operator ruling
 * 2026-09-08). The thin real-world glue around {@link routeRuling}, mirroring
 * `approveCommand`/`inboxCommand`'s split: every seam below is the REAL one, and the pure
 * routing above is what the suite drives.
 *
 * EVERY FIELD IS REQUIRED and the usage error names the missing one. That is design clause (iv)
 * at the CLI: there is no invocation of this verb that produces an entry a reader cannot
 * attribute, chase or undo.
 */
export async function ruleCommand(
  rest: string[],
  deps: { root?: string; route?: typeof routeRuling; clock?: Clock; config?: Config } = {},
): Promise<number> {
  const root = deps.root ?? repoRoot;
  const flag = (name: string): string | undefined => {
    const i = rest.indexOf(`--${name}`);
    return i === -1 ? undefined : rest[i + 1];
  };
  const evidence = rest.flatMap((t, i) => (t === "--evidence" && rest[i + 1] ? [rest[i + 1]!] : []));
  const supersedes = rest.flatMap((t, i) => (t === "--supersedes" && rest[i + 1] ? [rest[i + 1]!] : []));
  const ruling: AgentRuling = {
    taskId: flag("task") ?? "",
    runId: flag("run") ?? `RULE-${flag("task") ?? "unknown"}`,
    title: flag("title") ?? "",
    ruling: flag("ruling") ?? "",
    evidence,
    rollback: flag("rollback") ?? "",
    author: flag("author") ?? "",
    ...(supersedes.length > 0 ? { supersedes } : {}),
  };
  if (!ruling.taskId) {
    console.error(`rmd rule: --task <W#-T#> is required — usage: ${commandSyntax("rule")}\n` + USAGE);
    return 2;
  }

  const route = deps.route ?? routeRuling;
  // BOTH PATHS COME FROM THE CONFIG. The first draft got all three parts wrong: it wrote to
  // `ledger.jsonl` (the real filename is `ledger.ndjson`, owned by `ledgerPathFor` — hardcoding it
  // means a rename silently writes to a file nothing reads), under `root` (the CHECKOUT) rather
  // than `config.root` (the daemon's STATE root), so a ruling's ledger row and its inbox proposal
  // landed in different directories from each other and from every other consumer. MEASURED on the
  // sibling verify-human sweep, 2026-09-09: 56 ledger rows in the state root, 56 proposals in a
  // lane, nothing reaching the inbox an operator reads.
  const config = deps.config ?? loadConfig();
  const ledgerPath = ledgerPathFor(config);
  const registryPath = join(config.root, "state", "inbox-proposals.json");
  const result = await route(ruling, {
    judge: realRulingJudge({
      mounts: loadMounts(mountsPath(root)),
      cwd: root,
      settingsFile: join(root, "settings", "worker.json"),
    }),
    standingDecisions: readStandingDecisions(root),
    land: (relPath, content) => void recordRuling(root, relPath, content),
    stageProposal: (proposal) =>
      void updateProposalRegistry(registryPath, (current) =>
        current.some((existing) => existing.id === proposal.id) ? null : [...current, proposal],
      ),
    appendRow: (row) => appendLedger(ledgerPath, row),
    clock: deps.clock ?? systemClock,
  });

  if (result.decision === "record") {
    console.log(`recorded: ${result.landedPath} — ${result.reason}`);
    return 0;
  }
  console.log(`escalated to the inbox as ${result.proposalId} — ${result.reason}`);
  console.log(`the operator ratifies it with: rmd approve ${result.proposalId}`);
  return 0;
}

/**
 * `rmd approve <P##>` — the operator's ONE BIT (MASTER-PLAN P25 ii, W1-T111). Refuses
 * anything not currently READY (re-classified live, against the SAME facts `rmd inbox`
 * would show right now — never a stale cached verdict), naming the state; a READY
 * proposal's cached draft is shipped VERBATIM into a plan PR that rides the full gate
 * (ci-gate + remudero-review) before auto-merge is armed — rule 15: the bit INITIATES,
 * it never merges anything itself. The pure decision + gateway-call-counting live in
 * {@link approveProposal}; this command is the thin real-world glue (mirrors
 * `inboxCommand`/`planCommand`'s split).
 */
/** W1-T3216 — SHAPE ONLY: does this token name a TASK rather than a proposal? `W1-T1041` takes
 *  the release path, `P7` the proposal path. Deliberately not an EXISTENCE test: a well-formed
 *  but unknown id is refused BY NAME one step later, which reads better than "unknown proposal". */
export function namesATask(token: string): boolean {
  return /^W\d+-T[0-9A-Za-z]+$/.test(token);
}

/** W1-T4050 — the proposal `approveParkedTask` stages when `risk.verifyHumanReleaseEnabled` is
 *  `false`, rather than writing the release row directly. Derived from `taskId` alone, so
 *  naming the same parked task twice while the switch stays off stages one proposal, not two
 *  (mirrors `verifyHumanProposalId`'s dedup discipline in lib/verify-human-judge.ts). */
export function verifyHumanReleaseProposalId(taskId: string): string {
  return `verify-human-release:${taskId}`;
}

/** W1-T4050 — an ordinary inbox {@link Proposal} standing in for the direct release the policy
 *  switch just refused. `evidenceAnchors` is EMPTY on purpose, the same reason
 *  `proposalFromJudgedShard` leaves it empty: this proposal depends on nothing landing, and
 *  ratifying it goes through the reviewed proposal/PR path rather than tiering READY off a grep. */
export function verifyHumanReleaseProposal(taskId: string, task: Task): Proposal {
  return {
    id: verifyHumanReleaseProposalId(taskId),
    summary:
      `${taskId} (${task.title}) is a parked \`verify: human\` task an operator asked to release ` +
      `via \`rmd approve ${taskId}\`, but \`plan/policy.yaml\`'s \`risk.verifyHumanReleaseEnabled\` ` +
      `is currently \`false\` — the direct release arm is disabled by policy. Ratifying this ` +
      `proposal routes the SAME release through the reviewed proposal/PR path instead of the ` +
      `one-bit ledger write.`,
    evidenceAnchors: [],
  };
}

/**
 * W1-T3216 — RATIFY A PARKED `verify: human` TASK through the pipeline proposals already use.
 *
 * Writes the SAME `ratify.approved` row a proposal ratification writes, which `releasedTaskIds`
 * (plan.ts) reads back and `resolveReleasedIds` (drain.ts) turns into dispatch eligibility — so
 * the plan record is NEVER edited and the decision is auditable on the one ledger step that
 * already means "the operator spent his bit".
 *
 * REFUSES, NAMING THE STATE, WITH ZERO SIDE EFFECTS: an unknown id, a task that is not
 * `verify: human` (it needs no release), one that is blocked or retired, and one ALREADY
 * released — that last returns 0 and writes NO second row, because a second bit is not a second
 * release.
 *
 * W1-T4050 — THE VERIFY-HUMAN RELEASE ARM IS NOW RUNTIME POLICY: `deps.riskPolicy` (default
 * {@link DEFAULT_RISK_POLICY}, `verifyHumanReleaseEnabled: true` — today's behaviour, absent
 * risk section or absent caller both reproduce it exactly) gates the direct ledger write below.
 * `false` stops the release and stages {@link verifyHumanReleaseProposal} through
 * `deps.stageProposal` instead — the operator's bit is still recorded, just routed through the
 * same reviewed proposal/PR path every other release already goes through, rather than the
 * one-bit ledger write this function otherwise performs.
 */
export function approveParkedTask(
  taskId: string,
  deps: {
    plan: Plan;
    ledgerPath: string;
    runId: string;
    ledgerLines?: readonly string[];
    append?: typeof appendLedger;
    riskPolicy?: RiskPolicy;
    stageProposal?: (proposal: Proposal) => void;
    /** A MACHINE-written release carries who decided it and why (Law 5: the author class rides
     *  the record). Both classes carry the exact release contract pin. */
    provenance?: Record<string, unknown>;
    /** The operator's own release, kept where rotation cannot shed it until the machine-filing
     *  judge pins it on the record (operator ruling 2026-09-29). */
    recordDurableRelease?: (task: Task) => void;
    readDurableReleaseEvidence?: () => ReleaseEvidence;
    /** W1-T9252: told of the release row once it is written, so the release lands on every open ask about the
     *  task; a failure here never fails the release. */
    recordThreadRow?: (row: Record<string, unknown>) => void;
  },
): { code: number; message: string; released?: boolean } {
  const task = deps.plan.byId.get(taskId);
  if (!task) return { code: 2, message: `rmd approve: unknown task '${taskId}' — not in the plan` };
  if (task.verify !== "human") {
    return {
      code: 2,
      message: `rmd approve: ${taskId} is verify:${task.verify} — it needs no release; only a verify:human task is parked`,
    };
  }
  if (task.status !== "queued") {
    return { code: 2, message: `rmd approve: ${taskId} is status:${task.status} — only a queued task can be released` };
  }
  // The writer is the last authority boundary: callers other than the cadence helper may supply
  // machine provenance. Neither a stale release nor a low model verdict can lift a plan hold or
  // downgrade a task the plan itself calls high-risk. A human can still release high-risk work.
  if (task.dispatch_hold === true) {
    return { code: 2, message: `rmd approve: ${taskId} has an explicit dispatch hold — resolve it in the plan before release` };
  }
  if (deps.provenance !== undefined && task.risk === "high") {
    return { code: 2, message: `rmd approve: ${taskId} is high-risk in the plan — a machine cannot release its human verification` };
  }
  const releaseEvidence = qualifyReleaseEvidence(deps.ledgerLines ?? readReleaseLedgerLines(deps.ledgerPath),
    deps.readDurableReleaseEvidence?.() ?? readOperatorReleaseRecords(dirname(deps.ledgerPath)), releaseContractPins(deps.plan.tasks));
  if (deps.provenance && releaseEvidence.unknownHistory) return { code: 2, message: `rmd approve: ${taskId} operator release history is unreadable: malformed ledger record` };
  if (deps.provenance && (releaseEvidence.reapproval.has(taskId) || operatorReleaseContractChanged(task))) return { code: 2,
    message: `rmd approve: ${taskId} requires explicit operator reapproval of its current contract` };
  const already = new Set(releaseEvidence.authors.keys());
  if (already.has(taskId)) {
    if (!deps.provenance) deps.recordDurableRelease?.(task);
    return { code: 0, released: true, message: `rmd approve: ${taskId} is already released — no second row written` };
  }
  const riskPolicy = deps.riskPolicy ?? DEFAULT_RISK_POLICY;
  if (!riskPolicy.verifyHumanReleaseEnabled) {
    const proposal = verifyHumanReleaseProposal(taskId, task);
    (deps.stageProposal ?? (() => {}))(proposal);
    return {
      code: 0,
      released: false,
      message:
        `rmd approve: verify-human release is DISABLED by policy (risk.verifyHumanReleaseEnabled: ` +
        `false) — staged ${proposal.id} as a proposal instead of releasing ${taskId} directly`,
    };
  }
  const releaseRow = {
    run_id: deps.runId,
    task_id: taskId,
    step: RELEASE_LEDGER_STEP,
    released: "verify-human",
    ...(deps.provenance ?? {}),
    release_pin: operatorReleasePin(task),
  };
  (deps.append ?? appendLedger)(deps.ledgerPath, releaseRow);
  deps.recordThreadRow?.(releaseRow);
  if (!deps.provenance) deps.recordDurableRelease?.(task);
  return { code: 0, released: true, message: `rmd approve: ${taskId} RELEASED — a verify:human task is now dispatch-eligible` };
}

/** W1-T10348: the two release records beside a ledger, for the shared resolver (drain.ts `resolveReleases`). */
export function releaseReadersFor(ledgerPath: string): ReleaseReaders {
  return { readLedgerLines: () => readReleaseLedgerLines(ledgerPath), readDurableReleases: () => readOperatorReleaseRecords(dirname(ledgerPath)) };
}

/** The ledger's RAW lines. `releasedTaskIds` parses them itself (it rejects on a cheap substring
 *  before spending a JSON.parse), so handing it pre-parsed rows would parse every line twice.
 *  An unreadable ledger yields NO releases — the safe direction: the wall stands. */
export function readLedgerRawLines(path: string): readonly string[] {
  try {
    return readFileSync(path, "utf8").split("\n").filter(Boolean);
  } catch {
    // no ledger yet (a fresh checkout) or unreadable — releases nothing, never throws into dispatch
    return [];
  }
}

export async function inboxActionCliCommand(name: InboxVerbName, rest: string[], config: Config = loadConfig(), deps?: PanelGraphDeps): Promise<number> {
  const { owner, repo } = deps ? { owner: "", repo: "" } : resolveOwnerRepo();
  const causalScope = deps?.inboxSourceIdentity ?? deps?.inboxAuditScope ?? reframeCausalScope(config, true);
  const actions = buildInboxVerbActions(deps ?? {
    root: repoRoot, inboxRoot: config.root, planPath: join(repoRoot, "plan", "tasks.yaml"), ledgerPath: ledgerPathFor(config),
    github: ghTraceGateway(owner, repo), statusGithub: ghGateway(owner, repo),
    ratify: ratifyCliGateway(repoRoot, join(config.root, "logs")),
  }, causalScope);
  return inboxVerbCommand(name, rest, actions);
}

export function proposalVerdictCliCommand(kind: ProposalVerdictKind, rest: string[], config: Config = loadConfig()): number {
  const plan = loadPlan(join(repoRoot, "plan", "tasks.yaml"));
  const ledgerPath = ledgerPathFor(config);
  const { owner, repo } = resolveOwnerRepo();
  const summaries = new Map<string, string>();
  return proposalVerdictCommand(
    kind,
    rest,
    (id) => {
      const { proposal, classification } = loadProposalForRatify(id, plan, ledgerPath, owner, repo, config);
      if (proposal) summaries.set(id, proposal.summary);
      return { exists: proposal !== undefined, classification };
    },
    (step, id, reason) => {
      // W1-T10077: a decline of a verify-human proposal records the state it was given on.
      const observedState = step === "panel.proposal_declined" ? observedStateOfProposalSummary(summaries.get(id) ?? "") : undefined;
      const row = appendPanelLedger(ledgerPath, step, id, "rmd-cli", { reason, ...(observedState ? { observed_state: observedState } : {}) });
      // W1-T9252: the action also lands on the item's thread; a store fault never fails the verb.
      recordRowThreadEvents({ ...row, task_id: id, origin: "rmd-cli", reason }, [{ id }], { threadStorePath: inboxThreadStorePath(config.root) },
        (failed, extra) => console.error(`rmd ${row.step}: ${failed} ${JSON.stringify(extra)}`));
    },
  );
}

/**
 * W1-T4688: the exit of an approve whose PR is open but whose CI gate did not go green. A CI
 * timeout or a freshness yield leaves the PR for the sweep — a HAND-OFF, reported with the retro's
 * named hand-off code (3) — while a red CI stays 1. Same mapping {@link retroExitAfterPrOpened}
 * gives the retro, so the two lanes cannot drift.
 */
export function approveExitWhenCiNotGreen(ci: "red" | "timeout" | "freshness_handoff"): number {
  return retroExitAfterPrOpened(ci);
}

/**
 * W1-T4688: the shared tail of an approve whose CI gate did not go green (single and batch paths).
 * Returns undefined for a green CI (the caller proceeds to review); otherwise reports the PR left
 * open, releases the worktree and returns the exit code. One helper so both paths are covered by
 * the same behavioural test.
 */
export function approveCiNotGreenExit(
  ci: "green" | "red" | "timeout" | "freshness_handoff",
  prUrl: string,
  release: () => void,
): number | undefined {
  if (ci === "green") return undefined;
  console.log(`ci ${ci} — PR left OPEN: ${prUrl}`);
  release();
  return approveExitWhenCiNotGreen(ci);
}

/**
 * W1-T4688: `approve.skill_written` records that the skill is COMMITTED, so it is ledgered only
 * after `commit` returns; a commit that throws (a commitlint refusal) ledgers nothing.
 */
export function commitThenLedgerSkillWrite(commit: () => void, ledger: () => void): void {
  commit();
  ledger();
}

/**
 * `rmd approve`. W1-T9252: whatever the run ledgered for the proposals it named (approved, filed, refused) is
 * also mirrored onto each proposal's thread, once the run ends — the ledger rows stay the record, and the
 * mirror is keyed on them, so the daemon's live tail and boot backfill add nothing a second time.
 */
export async function approveCommandMirrored(rest: string[], deps: NonNullable<Parameters<typeof approveCommand>[1]> = {}): Promise<number> {
  const startedAt = (deps.clock ?? systemClock).now();
  const code = await approveCommand(rest, deps);
  const ids = rest.filter((token) => !token.startsWith("--") && !namesATask(token));
  if (ids.length === 0) return code;
  try {
    const config = deps.config ?? loadConfig();
    const inboxRoot = deps.inboxRoot ?? config.root;
    const proposals = parseProposalRegistry(readFileIfExists(join(inboxRoot, "state", "inbox-proposals.json")));
    const named = new Set(ids);
    for (const row of readLedgerLines(deps.inboxLedgerPath ?? ledgerPathFor(config))) {
      const rowIds = [row.task_id, row.proposal_id, ...(Array.isArray(row.proposal_ids) ? row.proposal_ids : [])];
      if (typeof row.ts !== "string" || Date.parse(row.ts) < startedAt || !rowIds.some((id) => typeof id === "string" && named.has(id))) continue;
      recordRowThreadEvents(row, proposals, { threadStorePath: inboxThreadStorePath(inboxRoot) }, (step, extra) =>
        console.error(`rmd approve: ${step} ${JSON.stringify(extra)}`));
    }
  } catch (error) {
    // deliberate: the thread mirror is a courtesy of the verb; the daemon's live tail mirrors what this missed.
    console.error(`rmd approve: could not mirror the run onto its thread: ${String((error as Error)?.message ?? error)}`);
  }
  return code;
}

export async function approveCommand(
  rest: string[],
  // W1-T3351 appended `root`/`clock`/`log` LAST, all optional: the `--note` chain needs a store
  // root and a clock a test can pin, and no existing caller passes either. `clock` is the shared
  // {@link Clock} port, not a bespoke `now`-shaped field — see recordCliOperatorNote's own doc.
  deps: {
    config?: Config;
    gateway?: RatifyGateway;
    batchGateway?: RatifyBatchGateway;
    overlap?: OverlapWarningDeps;
    root?: string;
    clock?: Clock;
    log?: (step: string, extra?: Record<string, unknown>) => void;
    /** The plan both branches read: the checkout's own, never `config.root` (a state root holds no plan). */
    planPath?: string;
    /** Metadata location only; provider, reservation, and workspace guards keep config.root. */
    inboxRoot?: string;
    inboxLedgerPath?: string;
    reviewedImprovement?: { goalDigest: string; draftDigest: string };
  } = {},
): Promise<number> {
  const proposalId = rest[0];
  if (rest.some(id => id.startsWith("improvement:")) && (rest.length !== 1 || deps.reviewedImprovement === undefined)) {
    console.error("rmd approve: review and file this improvement's exact completed draft through its saved conversation");
    return 1;
  }
  const planPath = deps.planPath ?? join(repoRoot, "plan", "tasks.yaml");
  // W1-T3216: a TASK id takes the release path. Taken BEFORE the proposal registry is consulted,
  // so the proposal path below is byte-for-byte unchanged, and keyed on SHAPE so an unknown but
  // well-formed task id is refused as a task rather than as a missing proposal.
  // W1-T3351: `--note` may ride the TASK-release path too. The guard still requires exactly ONE
  // bare id — it is the flag tokens, not the id count, that widened.
  const bareTokens = rest.filter((t, i) => !t.startsWith("--") && !(i > 0 && rest[i - 1] === "--note"));
  if (proposalId && bareTokens.length === 1 && namesATask(proposalId)) {
    const config = deps.config ?? loadConfig();
    const outcome = approveParkedTask(proposalId, {
      plan: loadPlan(planPath),
      ledgerPath: ledgerPathFor(config),
      // Clock-free BY CONSTRUCTION — and the comment may not NAME the shape it avoids, because
      // clock-signature-census.test.ts counts by SOURCE TEXT, comments included. The row is already
      // unique per task, so keying it on the task id is deterministic AND makes the
      // row findable by the very thing it releases.
      runId: `APPROVE-${proposalId}`,
      // W1-T4050: LIVE read, same as the risk-judge call site — never memoized, so a merged
      // `plan/policy.yaml` edit governs the very next `rmd approve` with no daemon restart.
      riskPolicy: readRiskPolicy(policyPath(repoRoot)),
      stageProposal: (proposal) =>
        void stageInboxProposalOnce(join(config.root, "state", "inbox-proposals.json"), proposal),
      recordDurableRelease: (task) => recordOperatorRelease(join(config.root, "state"), task, (deps.clock ?? systemClock).iso()),
      recordThreadRow: (row) =>
        void recordRowThreadEvents(
          // The row as the ledger stamped it: the event's key is the stored row's `ts`, which this call never chose.
          readLedgerLines(ledgerPathFor(config)).filter((line) => line.step === row.step && line.run_id === row.run_id && line.task_id === row.task_id).at(-1) ?? row,
          parseProposalRegistry(readFileIfExists(join(config.root, "state", "inbox-proposals.json"))),
          { threadStorePath: inboxThreadStorePath(config.root) },
          (step, extra) => console.error(`rmd approve: ${step} ${JSON.stringify(extra)}`),
        ),
    });
    console.log(outcome.message);
    // CHAINED ONLY ON SUCCESS: guidance attached to a refused release would describe a state the
    // plan was never in.
    if (outcome.code === 0) approveNoteChain(rest, proposalId, config, deps);
    return outcome.code;
  }
  const badArg = unknownArgError("approve", rest.slice(1), ["--note"], []);
  // W1-T2471: more than one bare id named (e.g. `rmd approve P1 P2 P3`) is what the SINGLE-id
  // parse above already flags as a bad arg — every token after the first is "unexpected".
  // Reinterpreted here, and ONLY here, as an EXPLICIT batch (Q4: never an implicit "approve
  // everything ready" — the operator must NAME every id): every token in `rest` is a bare
  // proposal id, none a `--flag`. Any OTHER malformed shape (a stray `--flag` anywhere) falls
  // straight through to the single-path usage error below, UNCHANGED — this branch changes
  // NOTHING about the single-proposal path's own parsing or behaviour.
  if (badArg && rest.length >= 2 && rest.every((t) => !t.startsWith("--"))) {
    return approveBatchCommand(rest, deps);
  }
  if (!proposalId || badArg) {
    console.error((badArg ?? `rmd approve: <P##> is required — usage: ${commandSyntax("approve")}`) + "\n" + USAGE);
    return 2;
  }

  const config = deps.config ?? loadConfig();
  const plan = loadPlan(planPath);
  const inboxRoot = deps.inboxRoot ?? config.root;
  const ledgerPath = deps.inboxLedgerPath ?? ledgerPathFor(config);
  const registryPath = join(inboxRoot, "state", "inbox-proposals.json");
  const { owner, repo } = resolveOwnerRepo();
  const registryIntent = selectedRegistryIntentForConfig(config);

  const { proposal, classification } = loadProposalForRatify(proposalId, plan, ledgerPath, owner, repo, config, inboxRoot);
  if (!proposal || !classification) {
    console.error(`rmd approve: unknown proposal '${proposalId}' — not in the ACTIVE registry (state/inbox-proposals.json)`);
    return 2;
  }

  if (proposal.improvement && !isReviewedImprovementDraft(proposal, parseDraftCache(readFileIfExists(join(inboxRoot, "state", "inbox-drafts.json")))[proposal.id], deps.reviewedImprovement)) {
    console.error("rmd approve: this improvement requires an explicit review of its current completed draft; use the saved conversation's Review and file action");
    return 1;
  }

  if (classification.state === "ready" && classification.releaseTaskId) {
    const code = await approveCommand([classification.releaseTaskId], deps);
    if (code === 0 && releasedTaskIds(readLedgerRawLines(ledgerPath), loadPlan(planPath)).has(classification.releaseTaskId)) {
      appendLedger(ledgerPath, { run_id: `APPROVE-${proposalId}`, task_id: proposalId,
        step: "ratify.approved", release_task_id: classification.releaseTaskId });
      approveNoteChain(rest, proposalId, config, deps);
    }
    return code;
  }

  const runId = `APPROVE-${proposalId}-${Date.now()}`;
  const log = (step: string, extra: Record<string, unknown> = {}) => appendLedger(ledgerPath, { run_id: runId, task_id: proposalId, step, lane: "approve", ...extra });

  let repoDir: string | undefined;
  let worktreePath: string | undefined;
  // W1-T9153: the worktree this run may tear down, recorded only once ITS add returned. Both are set by
  // `addApproveWorktree` below and never before the add: a run whose add threw or was refused never owned what lives at
  // that path, which may be another live approve's tree, so its teardown removes nothing.
  let addedWorktreePath: string | undefined;
  // The shard path(s) this ratification wrote, captured beside `filedTaskIds` and for the same
  // reason: `openPlanPr` runs after the branch call and must name what was ACTUALLY written rather
  // than a path it assumes. Empty on the adopt/resume paths, which write nothing.
  let shardRelPaths: string[] = [];
  // Filed task id(s), captured by whichever of createRatificationBranch/completeRatificationBranch
  // ran (approveProposal calls exactly one of them, always before openPlanPr — see inbox.ts's
  // own doc) for openPlanPr's Acceptance-criteria auto-authorship below — the closure approach
  // lets openPlanPr's signature (part of the RatifyGateway interface other tests fake) stay
  // unchanged. Stays empty for an ADOPTED PR (openPlanPr never runs on that path at all).
  let filedTaskIds: string[] = [];
  let filedStampLine = ""; // W1-T4706: the materialized stamp, for a joined PR's rebuilt body
  // W1-T311: the block {@link materializeDraftTaskIds} reserves for this approve's placeholder
  // ids — held until the PR actually exists (released below, once `result.ok`), so a
  // console-initiated or second-machine approve overlapping this CLI one cannot mint the same
  // ids. Released on any failure path too (the catch around `approveProposal` below) — every
  // reserved id, used or not, must come back, or it is a phantom-id hole (W1-T199/224/247/263).
  let idBlock: TaskIdReservationBlock | undefined;
  // The remote claims behind idBlock: given back when the filing fails before its branch is pushed.
  const approveClaims: Array<{ run: (args: string[]) => { status: number; stdout: string; stderr: string }; held: HeldTaskIdReservation }> = [];
  let approvePushStarted = false;
  const releaseApproveClaims = (reason: string): void => {
    for (const c of approveClaims.splice(0)) releaseTaskIdReservation(c.run, c.held, { reason: `rmd approve ${proposalId}: ${reason}`, lane: "approve", log });
  };
  // W1-T903: shared by findPushedBranch (resume evidence) and createRatificationBranch (fresh
  // PROCEED) — both need the same clone, and only one of the two ever runs per approve call.
  const ensureRepoDir = (): string => {
    repoDir = repoDir ?? join(config.root, "repos", repo);
    if (!existsSync(repoDir)) {
      mkdirSync(dirname(repoDir), { recursive: true });
      ghExec(["repo", "clone", `${owner}/${repo}`, repoDir], { stdio: "inherit" });
    }
    return repoDir;
  };
  const addApproveWorktree = (dir: string, path: string, branch: string, base: string): string => {
    addLockedRunWorktree(dir, path, branch, base, runId, log); // W1-T5356: lock before add
    return (addedWorktreePath = path);
  };
  // W1-T9161: a join or a resume cuts THIS run's own tree on this run's own branch from `base`, so no two approves
  // ever claim one path or create one local branch.
  const addOwnTreeAt = (dir: string, base: string): string => {
    const own = approveRunBranch(runId);
    return addApproveWorktree(dir, join(worktreesDir(config), own), own, base);
  };
  // W1-T9161: the tree a lost join added, with its never-pushed local branch, so the fallback can cut the same name.
  const dropOwnTree = (dir: string, path: string): void => {
    worktreeRemove(dir, path);
    removeRunLock(path);
    hostWorktreeGit(dir, ["branch", "-D", approveRunBranch(runId)]);
    addedWorktreePath = worktreePath = undefined;
  };
  // A fresh, locked worktree on this run's branch at origin/main — shared by the two skill paths (W1-T4338's write,
  // the lifecycle retirement), which write under .claude/skills/ rather than filing plan shards.
  const freshSkillApproveWorktree = (): { branch: string; path: string } => {
    const dir = ensureRepoDir();
    const pruned = pruneStaleRuns(dir, worktreesDir(config), { graceMs: DEFAULT_PRUNE_GRACE_MS });
    if (pruned.worktrees.length || pruned.branches.length || pruned.skipped.length) log("worktree.prune", { ...pruned });
    const branch = approveRunBranch(runId);
    const path = (worktreePath = addApproveWorktree(dir, join(worktreesDir(config), branch), branch, "origin/main"));
    return { branch, path };
  };
  // W1-T4437: the mint/write/commit steps `createRatificationBranch` and `joinRatificationBranch`
  // BOTH run once the worktree exists — the only difference between the two gateway methods is
  // which ref that worktree was checked out AT (a fresh `origin/main` vs. an already-open PR's own
  // tip) and whether the result is pushed as a NEW branch or a new commit on an existing one.
  // Shared here so the mint/shard/stamp/advisory sequence can never drift between the two.
  // W1-T9161: `filingBranch` is the branch the shards land on, which a join's own local branch is not: the remote
  // reservation names it, so the reserved ids match the PR that files them.
  const materializeAndCommitApproveFragment = (
    worktreePath: string, payload: RatificationPayload, purposeLabel: string, filingBranch: string,
  ): void => {
    const subjectId = deriveTaskReferent(payload.proposalId);
    const subject = subjectId === undefined ? undefined : loadPlan(join(worktreePath, "plan", "tasks.yaml")).byId.get(subjectId);
    if (subject?.status === "blocked" && subject.retirement) {
      throw new Error(`rmd approve: refusing to ratify ${payload.proposalId} — task ${subjectId} is ${subject.retirement} in the worktree plan`);
    }
    // W1-T311: MINT + RESERVE the drafted fragment's placeholder (`NEW-<n>`) ids from the
    // worktree's OWN plan, AFTER it is checked out and BEFORE anything is written — the same
    // ordering `rmd triage`/`rmd plan` already use (:11831,:12159), calling the ONE shared
    // derivation rather than re-deriving ids locally here. A degraded mint source or a
    // reservation failure REFUSES (throws) before any write, so no partial union ever reaches
    // the worktree.
    const materialized = materializeDraftTaskIds(
      { fragmentYaml: payload.fragmentYaml, stampLine: payload.stampLine },
      {
        mint: () =>
          mintNextTaskIdWithHistory({
            planPath: join(worktreePath, "plan", "tasks.yaml"),
            repoRoot: worktreePath,
            openPrTexts: () => openPrMintTexts(owner, repo),
          }),
        reserveBlock: (startId, count) => {
          idBlock = reserveTaskIdBlock(startId, count, taskIdReservationsDir(config.root), {
            info: { purpose: `rmd approve ${payload.proposalId} (${purposeLabel})` },
          });
          // Same closure-narrowing reason as the triage and plan lanes.
          const approveReserveFrom = idBlock.ids[0];
          // W1-T949: AND RESERVE THE SAME BLOCK REMOTELY — this closure is the ONLY thing
          // `materializeDraftTaskIds` (lib/inbox.ts) sees; `reserveBlock` there is an INJECTED
          // callback (`DraftTaskIdMintDeps.reserveBlock`), so the remote half threads through
          // it right here without inbox.ts needing to know the local store even exists. Caught
          // and re-thrown here (rather than left to inbox.ts's own catch, which folds ANY
          // reservation failure into a free-text `reason` string) so a genuine
          // `TaskIdReservationError` still leaves a durable, structured ledger event before
          // `materializeDraftTaskIds` reduces it to prose.
          const approveRun = (args: string[]) => {
            const r = spawnSync("git", ["-C", worktreePath, ...args], { encoding: "utf8" });
            return { status: r.status ?? 1, stdout: r.stdout ?? "", stderr: r.stderr ?? "" };
          };
          const approveReserver = gatedRemoteRefReserver({ lane: "approve", log, filingBranch, run: approveRun });
          const remote = withIdReservationLogging(
            log,
            "approve.id_reservation_failed",
            () => reserveTaskIdBlockRemote(approveReserveFrom, count, approveReserver),
            { proposal_id: payload.proposalId },
          );
          for (const h of remote.handles) {
            approveClaims.push({ run: approveRun, held: { taskId: h.taskId, sha: approveReserver.wonAnchor?.(h.taskId) ?? h.anchor } });
          }
          return { ids: remote.ids };
        },
      },
    );
    if (!materialized.ok) {
      throw new Error(`rmd approve: refusing to materialize task id(s) for ${payload.proposalId} — ${materialized.reason}`);
    }
    log("approve.id_materialized", { proposal_id: payload.proposalId, ids: materialized.ids });

    // ONE SHARD PER DRAFTED TASK, never a monolith append (`monolith-filing`). W1-T4700: re-linted
    // WITH the stamp first, refusing before any write; returns only the paths it changed.
    shardRelPaths = fileRatificationDraft(
      worktreePath,
      { fragmentYaml: materialized.fragmentYaml, proposalId: payload.proposalId, stampLine: materialized.stampLine },
      { mkdirSync, writeFileSync, readFileSync },
      join,
    );
    log("approve.shards_written", { proposal_id: payload.proposalId, paths: shardRelPaths });

    // materialized.fragmentYaml carries only REAL ids now (materializeDraftTaskIds already
    // rewrote every placeholder) — same per-line `- id: <id>` regex the pre-W1-T311 code used,
    // just over the rewritten text rather than payload.fragmentYaml verbatim.
    filedTaskIds = [...materialized.fragmentYaml.matchAll(/^- id:\s*(\S+)/gm)].map((m) => m[1]);
    filedStampLine = materialized.stampLine;

    // W1-T985 — the rare-overlap advisory for the shards this ratification just wrote. Same
    // reader `nextTaskIdCommand` has had since W1-T917, reached here because this lane files
    // without a human at a terminal; see the triage lane's twin of this block for the full
    // reasoning. `filedTaskIds` is read one line above from the SAME materialised fragment the
    // shards were written from, so the ids and the shards on disk cannot disagree.
    printLaneOverlapAdvisory(
      declaredFilesForFiledIds(join(worktreePath, "plan", "tasks.yaml"), filedTaskIds, deps.overlap),
      owner,
      repo,
      join(worktreePath, "plan", "tasks.yaml"),
      deps.overlap,
    );

    execFileSync("git", ["-C", worktreePath, "add", "--", ...shardRelPaths], { stdio: "inherit" });
    execFileSync("git", ["-C", worktreePath, "commit", "-m", approveCommitMessage(payload)], { stdio: "inherit" });
  };
  // W1-T5348: the committed shards and the title are preflighted before the push. The body is authored later by
  // buildPlanPrBody, which already refuses a proof that does not discriminate, so it is not re-checked here.
  const preflightApprovePush = (path: string, branch: string, id: string): void =>
    refuseRedPlanPr(planPrPreflight({ cwd: path, title: approvePrTitle(id), body: "" }, { log }), { lane: "approve", branch, log });
  const branchFiledTaskIds = (path: string): string[] =>
    execFileSync("git", ["-C", path, "diff", "origin/main...HEAD", "--", "plan/tasks.yaml", "plan/tasks.d"], { encoding: "utf8" })
      .split("\n")
      .map((line) => /^\+- id:\s*(\S+)/.exec(line)?.[1])
      .filter((id): id is string => id !== undefined);
  const gateway: RatifyGateway = deps.gateway ?? {
    // W1-T903 design (iii): evidence (ledger) + a real remote read — never guessed. A cheap
    // ledger-only miss (the overwhelming majority of approve calls: no prior run at all) never
    // touches git or clones anything.
    findPushedBranch(id) {
      const candidate = priorApproveRunBranch(readLedgerLines(ledgerPath), id);
      if (!candidate) return undefined;
      const dir = ensureRepoDir();
      const remote = execFileSync("git", ["-C", dir, "ls-remote", "--heads", "origin", candidate], { encoding: "utf8" });
      return remote.trim().length > 0 ? candidate : undefined;
    },
    // W1-T903 design (ii): the SAME REST surface fetchOpenPrsRest (open-prs-rest.ts) reads,
    // never `gh pr list` — a probe issues no GraphQL call at all.
    findExistingPr(branch) {
      return probeExistingPlanPr(ghJson, owner, repo, branch);
    },
    // W1-T4437 design (i)/(ii): the OPEN plan PR of a DIFFERENT approve run of this same pass, if
    // one is safe to join. The ledger names the CANDIDATE (evidence only, cheap, no network);
    // everything after that is a live confirmation, since only GitHub can say whether it is still
    // open and not already queued to merge. Fails closed on every uncertainty — a merged/closed
    // candidate, or a head sha this cannot read, answers "not joinable" and this approval opens its
    // own PR exactly as it always has, never risking a commit on a PR already on its way to main.
    findJoinablePr() {
      const candidate = mostRecentApprovePr(readLedgerLines(ledgerPath));
      if (!candidate) return undefined;
      // W1-T9161: the approve that wrote this row may still be in its CI wait, about to merge the PR or arm it. A pid is
      // only a process on the host that wrote it; a dead pid, another host's, or a row naming none keeps the join.
      if (candidate.actorPid !== undefined && sameHost(candidate.host, hostname()) && defaultIsPidAlive(candidate.actorPid)) {
        log("approve.join_skipped", { pr_url: candidate.prUrl, branch: candidate.branch, reason: "approving_pid_alive", actor_pid: candidate.actorPid });
        return undefined;
      }
      const open = probeExistingPlanPr(ghJson, owner, repo, candidate.branch);
      if (!open) return undefined;
      let headSha: string | undefined;
      try {
        headSha = readHeadShaRest(open.prUrl);
      } catch {
        return undefined; // unreadable head — cannot confirm it is safe to join
      }
      if (priorArmOnHead(readLedgerLines(ledgerPath), open.prUrl, headSha)) return undefined; // already queued to merge
      return { branch: candidate.branch, prUrl: open.prUrl, prNumber: open.prNumber };
    },
    // W1-T903 design (iii)/(vi): COMPLETE an already-pushed branch — check it out (no `-b` onto
    // a fresh commit, the branch's OWN remote tip), and read filed task ids back from what is
    // ALREADY COMMITTED, never re-mint. No write, no commit, no push.
    completeRatificationBranch(branch) {
      const dir = ensureRepoDir();
      const pruned = pruneStaleRuns(dir, worktreesDir(config), { graceMs: DEFAULT_PRUNE_GRACE_MS });
      if (pruned.worktrees.length || pruned.branches.length || pruned.skipped.length) log("worktree.prune", { ...pruned });
      // W1-T2621: thread this call's own ledger through — worktreeAdd now emits worktree.add
      // (and, on the currency check's fail-open, worktree.base_uncheckable) itself.
      // W1-T9161: this run's OWN tree and local branch, cut from the resumed branch's remote tip. Nothing is pushed.
      worktreePath = addOwnTreeAt(dir, `origin/${branch}`);
      // The merge-base diff isolates ONLY what this branch added to plan/tasks.yaml, unaffected
      // by anything origin/main gained afterward (a plain two-dot diff would not be) — same
      // `- id: <id>` per-line shape the fresh-mint path below extracts, just over the diff's
      // ADDED lines rather than the freshly-materialized fragment text.
      // BOTH FILING SHAPES, because a resumed branch may predate the shard write: one pushed
      // before it carries its ids in plan/tasks.yaml, one pushed after carries them in
      // plan/tasks.d/. Scoping this diff to the monolith alone would read ZERO ids off every
      // shard-filed branch and hand `openPlanPr` an empty list — a resumed ratification silently
      // losing the very ids it filed.
      filedTaskIds = branchFiledTaskIds(worktreePath);
      return branch;
    },
    createRatificationBranch(payload) {
      const dir = ensureRepoDir();
      const pruned = pruneStaleRuns(dir, worktreesDir(config), { graceMs: DEFAULT_PRUNE_GRACE_MS });
      if (pruned.worktrees.length || pruned.branches.length || pruned.skipped.length) log("worktree.prune", { ...pruned });
      // THE BRANCH-NAME BOUNDARY. `runId` is `APPROVE-<proposalId>-<ms>` and a board-review
      // proposal id carries colons, which git refuses in a ref — so the bare `run-${runId}` that
      // stood here died in `worktreeAdd` with `fatal: ... is not a valid branch name` and no
      // proposal has ever been ratified. {@link approveRunBranch} (lib/inbox.ts) sanitises HERE,
      // never the id itself (a registry key and a ledger value), and the SAME call fixes the
      // WORKTREE DIRECTORY on the next line, which is derived from this string.
      const branch = approveRunBranch(runId);
      // W1-T2621: see completeRatificationBranch's identical note, above.
      worktreePath = addApproveWorktree(dir, join(worktreesDir(config), branch), branch, "origin/main");
      materializeAndCommitApproveFragment(worktreePath, payload, `run ${runId}`, branch);
      preflightApprovePush(worktreePath, branch, payload.proposalId);
      approvePushStarted = true;
      gitPushRunBranch(worktreePath);
      return branch;
    },
    // W1-T4437 design (i)/(ii): add ONE more proposal's shard(s) as a NEW COMMIT on an
    // ALREADY-PUSHED, still-open plan PR from a DIFFERENT approve run of this same pass — never a
    // new branch, never a new PR. Checked out at the branch's OWN remote tip (never `origin/main`),
    // the same base `completeRatificationBranch` above uses, so the mint below sees every id
    // already filed on it and never re-mints one.
    joinRatificationBranch(branch, payload, prUrl) {
      const dir = ensureRepoDir();
      const pruned = pruneStaleRuns(dir, worktreesDir(config), { graceMs: DEFAULT_PRUNE_GRACE_MS });
      if (pruned.worktrees.length || pruned.branches.length || pruned.skipped.length) log("worktree.prune", { ...pruned });
      // W1-T9161: this run's OWN tree and local branch, cut from the PR's remote tip, never `-b <the PR's branch>` at
      // `worktrees/<the PR's branch>`: that path and branch belong to whichever run created or last held them.
      const ownTree = (worktreePath = addOwnTreeAt(dir, `origin/${branch}`));
      materializeAndCommitApproveFragment(ownTree, payload, `joined ${branch}`, branch);
      preflightApprovePush(ownTree, branch, payload.proposalId);
      approvePushStarted = true;
      try {
        gitPushRunBranch(ownTree, { destination: branch });
      } catch (e) {
        if (!isNonFastForwardRejection(e)) throw e;
        // Another approve moved the PR's tip first. Release the ids, drop this tree and its unpushed branch, and let
        // approveProposal file through createRatificationBranch: a fresh origin/main tree and its own PR.
        log("approve.join_lost", { proposal_id: payload.proposalId, branch, released_ids: idBlock?.ids ?? [] });
        idBlock?.releaseAll();
        idBlock = undefined;
        approvePushStarted = false;
        releaseApproveClaims(`the join push onto ${branch} was rejected as non-fast-forward`);
        dropOwnTree(dir, ownTree);
        return undefined;
      }
      log("approve.joined", { proposal_id: payload.proposalId, branch });
      // W1-T4706: the open PR's body is rebuilt over every proposal on the branch, never left as the first approve's.
      try {
        const live = ghJson(["api", `repos/${owner}/${repo}/pulls/${prUrl.match(/\/pull\/(\d+)/)?.[1]}`]) as { body?: string | null };
        const paths = execFileSync("git", ["-C", worktreePath, "diff", "--name-only", worktreeMergeBase(worktreePath), "HEAD"], { encoding: "utf8" }).split("\n").filter(Boolean);
        const body = joinedRatificationPrBody(live.body ?? "", filedStampLine, branchFiledTaskIds(worktreePath), paths, { proofCwd: worktreePath });
        writePrBodyRest(prUrl, body);
        log("approve.join_body_refreshed", { pr_url: prUrl, paths });
      } catch (e) {
        // The commit is already pushed: throwing would leave it unrecorded, so the stale body is ledgered instead.
        log("approve.join_body_stale", { pr_url: prUrl, error: String((e as Error)?.message ?? e) });
      }
      return branch;
    },
    // W1-T4338: the skill-draft twin of createRatificationBranch — one SKILL.md, verbatim, on a fresh branch.
    writeSkillFile(id, skillFile) {
      const { branch, path } = freshSkillApproveWorktree();
      const relPath = writeApprovedSkillFile(path, skillFile, { mkdirSync, writeFileSync, existsSync }, join);
      commitThenLedgerSkillWrite(
        () => {
          execFileSync("git", ["-C", path, "add", "--", relPath], { stdio: "inherit" });
          execFileSync("git", ["-C", path, "commit", "-m", skillFileApproveCommitMessage(id, relPath)], { stdio: "inherit" });
        },
        () => log("approve.skill_written", { proposal_id: id, path: relPath }),
      );
      gitPushRunBranch(path);
      return branch;
    },
    openPlanPr(branch, id) {
      const skillRelPath = classification.skillFile ? approvedSkillRelPath(classification.skillFile.name) : null;
      if (classification.skillFile && skillRelPath) {
        assertLiveWriteAllowed("gh-pr-create", `opening a skill PR against ${owner}/${repo}`);
        return createPlanPrRest(ghJson, owner, repo, {
          title: `chore(skill): add approved skill ${classification.skillFile.name} via rmd approve`,
          body: skillFileApprovePrBody(id, classification.skillFile.name, skillRelPath, { proofCwd: worktreePath }),
          head: branch,
          base: "main",
        }).prUrl;
      }
      // W1-T136 (#387 class): an ALWAYS-judgeable Acceptance block about the filing itself, and
      // NO Remudero-Task trailer. W1-T4700: Changed files are the paths the commit wrote.
      const ids = filedTaskIds.length > 0 ? filedTaskIds : [id];
      const body = ratificationPrBody(classification.draft?.stampLine ?? "", ids, shardRelPaths, { proofCwd: worktreePath });
      assertLiveWriteAllowed("gh-pr-create", `opening a PR against ${owner}/${repo}`);
      // W1-T903 design (i): REST, not `gh pr create` (GraphQL) — a pure transport swap, since
      // title/body are already fully authored above (no `--fill` autofill to replace).
      const created = createPlanPrRest(ghJson, owner, repo, {
        title: approvePrTitle(id),
        body,
        head: branch,
        base: "main",
      });
      return created.prUrl;
    },
  };

  const createSkillLifecycleBranch = (action: SkillLifecycleAction): string => {
    const { branch, path } = freshSkillApproveWorktree();
    const removed = applySkillLifecycleRemoval(path, action);
    if (!removed.ok) throw new Error(`rmd approve: refusing lifecycle action for ${proposalId} — ${removed.reason}`);
    execFileSync("git", ["-C", path, "add", "-A", "--", action.skillPath], { stdio: "inherit" });
    execFileSync("git", ["-C", path, "commit", "-m", skillLifecycleApproveCommitMessage(action, proposalId)], { stdio: "inherit" });
    gitPushRunBranch(path);
    return branch;
  };

  const openSkillLifecyclePr = (branch: string, action: SkillLifecycleAction): string => {
    assertLiveWriteAllowed("gh-pr-create", `opening a skill lifecycle PR against ${owner}/${repo}`);
    const created = createPlanPrRest(ghJson, owner, repo, {
      title: "chore(skill): retire approved skill via rmd approve",
      body: skillLifecyclePrBody(action, proposalId),
      head: branch,
      base: "main",
    });
    return created.prUrl;
  };

  const duplicateCorpus = filedShardSlugCorpus(repoRoot);

  let result: ReturnType<typeof approveProposal>;
  try {
    if (proposal.lifecycleAction) {
      if (classification.state !== "ready" || !classification.lifecycleAction) {
        const refusal = refusalReason(classification);
        appendLedger(ledgerPath, {
          run_id: runId,
          task_id: proposalId,
          step: "ratify.approve_refused",
          state: classification.state,
          reason: refusal,
        });
        console.error(`rmd approve: ${refusal}`);
        return 1;
      }
      // The proposal carries the evidence as it stood at staging. Re-judged now, a stale one is withdrawn rather
      // than allowed to delete a skill the ledger no longer condemns; an unreadable ledger refuses and keeps it.
      const recheck = recheckSkillRetirement(dirname(ledgerPathFor(config)), classification.lifecycleAction);
      if (recheck.verdict !== "qualifies") {
        const withdrawn = recheck.verdict === "stale" && withdrawSkillLifecycleProposal(registryPath, proposalId);
        appendLedger(ledgerPath, {
          run_id: runId,
          task_id: proposalId,
          step: "ratify.approve_refused",
          state: `evidence_${recheck.verdict}`,
          reason: recheck.reason,
          withdrawn,
        });
        console.error(`rmd approve: ${recheck.reason}${withdrawn ? `; withdrew ${proposalId} from the inbox` : ""}`);
        return 1;
      }
      const branch = createSkillLifecycleBranch(classification.lifecycleAction);
      const prUrl = openSkillLifecyclePr(branch, classification.lifecycleAction);
      const prNumber = Number(prUrl.match(/\/pull\/(\d+)/)?.[1]);
      appendLedger(ledgerPath, {
        run_id: runId,
        task_id: proposalId,
        step: "ratify.approved",
        pr_url: prUrl,
        pr_number: Number.isFinite(prNumber) ? prNumber : undefined,
        branch,
        lifecycle_action: classification.lifecycleAction.kind,
      });
      result = {
        ok: true,
        proposalId,
        branch,
        prUrl,
        prNumber: Number.isFinite(prNumber) ? prNumber : undefined,
        payload: { proposalId, fragmentYaml: "", stampLine: "" },
      };
    } else {
      result = withSelectedRegistryContextSync(selectedRegistryObserverFromIntent(registryIntent, log), () =>
        approveProposal(classification, gateway, { ledgerPath, runId, duplicateCorpus }));
    }
  } catch (e) {
    // W1-T311: createRatificationBranch REFUSED (a degraded mint or a failed reservation) —
    // or any other failure inside either gateway call. approveProposal never reached its own
    // ledger append on this path, so NOTHING was ratified: no PR opened, the registry entry
    // below is never touched (this proposal stays READY), and every id this run reserved
    // (if any) comes back rather than punching a phantom-id hole.
    log("approve.error", { error: String((e as Error)?.message ?? e) });
    idBlock?.releaseAll();
    if (!approvePushStarted) releaseApproveClaims(`failed before its branch was pushed: ${String((e as Error)?.message ?? e)}`);
    // W1-T9153: only a worktree this run's add returned. A refused or failed add left nothing of its own here.
    if (repoDir && addedWorktreePath) {
      try {
        worktreeRemove(repoDir, addedWorktreePath);
      } catch {
        /* best-effort */
      }
      try {
        removeRunLock(addedWorktreePath);
      } catch {
        /* best-effort */
      }
    }
    throw e;
  }
  if (!result.ok) {
    console.error(`rmd approve: ${result.refusal}`);
    return 1;
  }

  // W1-T311: both gateway calls above succeeded — the PR already exists, so the mint now sees
  // this run's ids via openPrMintTexts. Release the reservation here rather than holding it
  // through the CI wait below: holding longer only punches holes in the id space (the
  // phantom-id trap: W1-T199/224/247/263), the same reasoning `rmd plan`'s own release carries.
  idBlock?.releaseAll();

  // W1-T190: `ratify.approved` above just ledgered this proposal's ratification, but the
  // ledger and the registry are two different sources of truth — `rmd inbox`/the console's
  // `/v1/inbox` route (buildInboxRoute) classify strictly off state/inbox-proposals.json,
  // never the ledger, so leaving this entry in place kept recommending an already-ratified
  // proposal as READY indefinitely. Mirrors reframeCommand's registry write below (5646+ in
  // this file): this proposal is no longer ACTIVE (see the Proposal interface's doc comment
  // in lib/inbox.ts), so it is removed rather than rewritten in place.
  // W1-T240: drop `proposalId` from a FRESH read of the registry under lock, never a
  // stale in-memory array — a concurrent `rmd reframe`/the daemon's own heal write could
  // have changed the file since `loadProposalForRatify` read it above. See
  // lib/inbox.ts's `updateProposalRegistry` doc for the lost-update/torn-file hazard
  // this guards against.
  updateProposalRegistry(registryPath, (current) => {
    const next = current.filter((p) => p.id !== proposalId || p.retainAfterRatification);
    return next.length === current.length ? null : next;
  });

  // W1-T903: an ADOPTED PR (result.adopted) never called createRatificationBranch or
  // completeRatificationBranch at all (design iii's "open NOTHING") — repoDir/worktreePath
  // legitimately stay unset on that one path. Every OTHER success path still sets both before
  // returning a branch, so the guard below still fires loud on a genuine gateway contract
  // violation rather than silently skipping cleanup/gate.
  if (!result.adopted && (!repoDir || !worktreePath)) {
    throw new Error("rmd approve: gateway reported success but never created a ratification branch");
  }
  const ownedRepoDir = repoDir;
  const ownedWorktreePath = addedWorktreePath; // W1-T9153: the one this run's add returned
  const removeApproveWorktree = () => {
    if (ownedRepoDir && ownedWorktreePath) worktreeRemove(ownedRepoDir, ownedWorktreePath);
  };

  try {
    // RUN-OWNERSHIP GUARD (W1-T62 precedent) — never trailer/gate/arm a PR that is not
    // actually this run's own branch.
    const ownership = checkPrOwnership(result.prUrl, result.branch, ghPrHeadGateway(), 0);
    if (ownership) {
      log("verdict", ownership.ledger);
      console.error(`rmd approve: claimed PR ${result.prUrl} is not this run's own branch (${result.branch})`);
      removeApproveWorktree();
      return 1;
    }
    // W1-T136 (#387 correctness rule): NO `ensureTaskTrailer` call here — a ratification
    // branch is a plan-FILING PR (it introduces the ratified task(s), it does not
    // implement them). `ensureTaskTrailer(result.prUrl, proposalId)` used to stamp a
    // `Remudero-Task: <proposalId>` trailer post-hoc, undoing the no-trailer contract
    // approveCommitMessage/openPlanPr's body now enforce (findMergedByTrailer would
    // credit that trailer's id as DONE on merge — see lib/plan-pr-emitter.ts's doc
    // comment). proposalId (e.g. "P19") never collides with a real task id's W1-Txxx
    // shape, but a filing PR carries NO Remudero-Task trailer at all, full stop.
    log("pr.opened", { pr_url: result.prUrl, branch: result.branch, adopted: result.adopted === true, joined: result.joined === true });
    console.log(
      `rmd approve: ${proposalId} — plan PR ${result.adopted ? "adopted" : result.joined ? "joined" : "opened"}: ${result.prUrl}`,
    );

    const ci = ciGateState(await waitForCiGreen(result.prUrl, (s, extra) => log(s, extra)));
    const notGreenExit = approveCiNotGreenExit(ci, result.prUrl, removeApproveWorktree);
    if (notGreenExit !== undefined) return notGreenExit;
    const prNum = result.prUrl.match(/\/pull\/(\d+)/)?.[1] ?? result.prUrl;
    const reviewCode = await reviewCommand(prNum);
    // W1-T230: a ratification PR carries NO Remudero-Task trailer by design
    // (see the no-trailer comment above) — reviewCommand's own taskId resolve
    // therefore falls back to `PR-${view.number}` and its review.posted ledger
    // line is keyed to that same fallback, not `proposalId`.
    // W1-T2258: this lane holds no headSha variable of its own — `readHeadShaRest(result.prUrl)`
    // is the SAME live REST read `reviewCommand` (just above) already made to post its own
    // `review.posted` line, best-effort here too: a failed read leaves the row unjoinable,
    // exactly as it is today, never blocking the arm itself.
    let armHeadSha: string | undefined;
    try {
      armHeadSha = readHeadShaRest(result.prUrl);
    } catch {
      /* best-effort — see the comment above */
    }
    const armOutcome = armAndLogOutcome(result.prUrl, `PR-${prNum}`, log, undefined, undefined, armHeadSha);
    removeApproveWorktree();
    // W1-T968: the PR — not merely this call — is what the console line answers about; a
    // review-lane arm already ledgered moments earlier on this SAME head must still read as armed.
    const priorArm = priorArmOnHead(readLedgerLines(ledgerPath), result.prUrl, armHeadSha);
    console.log(`rmd approve: ${proposalId} gated — ${armReportPhrase(armOutcome, priorArm)} (review ${reviewCode === 0 ? "success" : "failure"}): ${result.prUrl}`);
    // CHAINED AFTER THE RATIFICATION LANDED, never before: the note describes work that is now
    // really in the plan. Scoped to the proposal id — the docket gathers notes across ALL tasks,
    // so an id that is not a task id still reaches the weekly gather (the task scoping applies to
    // prompt injection only).
    approveNoteChain(rest, proposalId, config, deps);
    return reviewCode;
  } catch (e) {
    log("approve.error", { error: String((e as Error)?.message ?? e) });
    try {
      removeApproveWorktree();
    } catch {
      /* best-effort */
    }
    throw e;
  } finally {
    if (ownedWorktreePath) removeRunLock(ownedWorktreePath);
  }
}

/**
 * `rmd approve <P##> <P##> ...` (N >= 2) — the EXPLICIT-BATCH counterpart of
 * {@link approveCommand} (W1-T2471): ships every READY member of a batch of NAMED proposals
 * into ONE branch, ONE commit, ONE folded MASTER-PLAN.md block and ONE plan PR, instead of one
 * full PR lifecycle (+ one advisory reviewer spawn) per proposal. Reached ONLY when the
 * operator names two or more bare ids to `rmd approve` — never an implicit "approve every
 * READY proposal" (Q4): an id absent from the ACTIVE registry refuses the WHOLE invocation
 * before anything is touched, exactly like the single-path's own "unknown proposal" refusal.
 *
 * The pure decision (skip-unready-never-abort, within-batch duplicate growth, shard-collision
 * refusal, the sequential stamp fold) lives in {@link approveBatch}/{@link planRatificationBatch}
 * (lib/inbox.ts); this is the thin real-world glue, mirroring {@link approveCommand}'s own
 * split — `createRatificationBranch` runs the mint/reserve/write loop once PER ACCEPTED
 * MEMBER inside the SAME worktree (Q3: the shard writer is per-fragment and composes with no
 * shared state) but commits and pushes exactly ONCE for the whole set.
 */
async function approveBatchCommand(
  rest: string[],
  deps: { config?: Config; gateway?: RatifyGateway; batchGateway?: RatifyBatchGateway } = {},
): Promise<number> {
  const proposalIds = rest;
  const config = deps.config ?? loadConfig();
  const registryIntent = selectedRegistryIntentForConfig(config);
  const plan = loadPlan(join(repoRoot, "plan", "tasks.yaml"));
  const ledgerPath = ledgerPathFor(config);
  const registryPath = join(config.root, "state", "inbox-proposals.json");
  const { owner, repo } = resolveOwnerRepo();

  const { found, unknown } = loadProposalsForRatify(proposalIds, plan, ledgerPath, owner, repo, config);
  if (found.some(row => row.proposal.improvement !== undefined)) {
    console.error("rmd approve: improvement drafts must be reviewed and filed individually through their bound saved conversation");
    return 1;
  }
  if (unknown.length > 0) {
    console.error(
      `rmd approve: unknown proposal(s) ${unknown.join(", ")} — not in the ACTIVE registry (state/inbox-proposals.json); ` +
        "the batch names ONLY ids that already exist there, nothing is ratified",
    );
    return 2;
  }

  const runId = `APPROVE-BATCH-${Date.now()}`;
  const log = (step: string, extra: Record<string, unknown> = {}) =>
    appendLedger(ledgerPath, { run_id: runId, task_id: "BATCH", step, lane: "approve", ...extra });

  let repoDir: string | undefined;
  let worktreePath: string | undefined;
  let allWrittenPaths: string[] = [];
  let allFiledTaskIds: string[] = [];
  const idBlocks: TaskIdReservationBlock[] = [];
  // W1-T9488: the remote claims behind idBlocks, and what the pushed batch branch declares. The batch gives back
  // every member's id that branch does not carry, on every way out.
  const batchHeld: HeldTaskIdReservation[] = [];
  let batchPushed: LanePushedIds;
  const releaseBatchUnfiled = (ending: string): void => {
    if (batchHeld.length === 0 || repoDir === undefined) return;
    const cloneDir = repoDir;
    releaseUnfiledReservations(batchHeld, batchPushed, {
      run: gitRunAdapter((args) => hostWorktreeGitResult(cloneDir, args)), lane: "approve-batch", log,
      reason: laneReleaseReason(`rmd approve batch ${runId}`, ending, batchPushed),
    });
  };
  const ensureRepoDir = (): string => {
    repoDir = repoDir ?? join(config.root, "repos", repo);
    if (!existsSync(repoDir)) {
      mkdirSync(dirname(repoDir), { recursive: true });
      ghExec(["repo", "clone", `${owner}/${repo}`, repoDir], { stdio: "inherit" });
    }
    return repoDir;
  };

  const gateway: RatifyBatchGateway = deps.batchGateway ?? {
    createRatificationBranch(payloads) {
      const dir = ensureRepoDir();
      const pruned = pruneStaleRuns(dir, worktreesDir(config), { graceMs: DEFAULT_PRUNE_GRACE_MS });
      if (pruned.worktrees.length || pruned.branches.length || pruned.skipped.length) log("worktree.prune", { ...pruned });
      const branch = approveRunBranch(runId);
      worktreePath = join(worktreesDir(config), branch);
      // W1-T2621: see the single-approve gateway's identical note (createRatificationBranch,
      // above) — this ledger is the batch lane's own.
      addLockedRunWorktree(dir, worktreePath, branch, "origin/main", runId, log); // W1-T5356: lock before add

      // Q3: ONE mint/reserve/write pass PER ACCEPTED PAYLOAD, sequentially, in the SAME
      // worktree — each iteration's shard write lands on disk before the NEXT payload's own
      // mint runs, so `mintNextTaskIdWithHistory`'s shard-directory scan (its `sources.shards`
      // term) sees every id minted so far and never re-mints one. W1-T4706: through
      // fileRatificationBatch, so each member gets the single lane's refusal and written-paths list,
      // and every member's stamp folds over this worktree's own MASTER-PLAN.md in order (Q2).
      const batchWorktree = worktreePath;
      const filed = fileRatificationBatch(
        batchWorktree,
        payloads,
        (payload) => {
          const materialized = materializeDraftTaskIds(
            { fragmentYaml: payload.fragmentYaml, stampLine: payload.stampLine },
            {
              mint: () =>
                mintNextTaskIdWithHistory({
                  planPath: join(batchWorktree, "plan", "tasks.yaml"),
                  repoRoot: batchWorktree,
                  openPrTexts: () => openPrMintTexts(owner, repo),
                }),
              reserveBlock: (startId, count) => {
                const block = reserveTaskIdBlock(startId, count, taskIdReservationsDir(config.root), {
                  info: { purpose: `rmd approve ${payload.proposalId} (batch run ${runId})` },
                });
                idBlocks.push(block);
                const reserveFrom = block.ids[0];
                const batchReserver = gatedRemoteRefReserver({
                  lane: "approve-batch", log,
                  run: (args) => {
                    const r = spawnSync("git", ["-C", batchWorktree, ...args], { encoding: "utf8" });
                    return { status: r.status ?? 1, stdout: r.stdout ?? "", stderr: r.stderr ?? "" };
                  },
                });
                const remote = withIdReservationLogging(
                  log,
                  "approve.id_reservation_failed",
                  () => reserveTaskIdBlockRemote(reserveFrom, count, batchReserver),
                  { proposal_id: payload.proposalId },
                );
                batchHeld.push(...heldFromBlock(remote, batchReserver));
                return { ids: remote.ids };
              },
            },
          );
          if (!materialized.ok) {
            throw new Error(`rmd approve: refusing to materialize task id(s) for ${payload.proposalId} — ${materialized.reason}`);
          }
          log("approve.id_materialized", { proposal_id: payload.proposalId, ids: materialized.ids });
          return { proposalId: payload.proposalId, fragmentYaml: materialized.fragmentYaml, stampLine: materialized.stampLine };
        },
        { mkdirSync, writeFileSync, readFileSync },
        join,
      );
      allWrittenPaths = filed.writtenPaths;
      allFiledTaskIds = filed.filedIds;
      log("approve.shards_written", { proposal_ids: payloads.map((p) => p.proposalId), paths: allWrittenPaths });

      execFileSync("git", ["-C", batchWorktree, "add", "--", ...allWrittenPaths], { stdio: "inherit" });
      execFileSync("git", ["-C", worktreePath, "commit", "-m", approveBatchCommitMessage(payloads)], { stdio: "inherit" });
      batchPushed = "unknown"; // W1-T9488: a push that throws leaves the branch's ids unknowable
      gitPushRunBranch(worktreePath);
      batchPushed = pushedBranchIds(worktreePath, log);
      return branch;
    },
    openPlanPr(branch, ids) {
      const intro = [
        `Batch ratification of ${ids.length} explicitly-named proposals: ${ids.join(", ")}.`,
        "",
        "The operator's one-bit approve initiated this PR (MASTER-PLAN P25 ii, W1-T111). The",
        "gate still reviews (ci + remudero-review); nothing auto-merges without it.",
      ].join("\n");
      const filedIds = allFiledTaskIds.length > 0 ? allFiledTaskIds : ids;
      // W1-T2550: one local list feeds both the filing-acceptance evidence and the rendered
      // changed-files block. W1-T4706: it is what the batch actually wrote, never an assumed file.
      const filedPaths = [...allWrittenPaths];
      const body = buildPlanPrBody({
        intro,
        criteria: filingAcceptanceCriteria(filedIds, filedPaths),
        changedFiles: filedPaths,
        proofCwd: worktreePath,
      });
      assertLiveWriteAllowed("gh-pr-create", `opening a PR against ${owner}/${repo}`);
      const created = createPlanPrRest(ghJson, owner, repo, {
        title: `chore(plan): ratify ${ids.length} proposals via rmd approve`,
        body,
        head: branch,
        base: "main",
      });
      return created.prUrl;
    },
  };

  let result: BatchApproveResult;
  try {
    result = withSelectedRegistryContextSync(selectedRegistryObserverFromIntent(registryIntent, log), () => approveBatch(
      found.map((f) => f.classification),
      // Unused by the real gateway above — it reads/folds MASTER-PLAN.md itself, inside the
      // worktree it just created off a FRESH `git fetch` (worktreeAdd), which is the only base
      // that can never drift from what actually gets committed. See the comment inside
      // `createRatificationBranch` above.
      "",
      gateway,
      { ledgerPath, runId, duplicateCorpus: filedShardSlugCorpus(repoRoot) },
    ));
  } catch (e) {
    log("approve.error", { error: String((e as Error)?.message ?? e) });
    idBlocks.forEach((b) => b.releaseAll());
    releaseBatchUnfiled(`errored: ${String((e as Error)?.message ?? e).slice(0, 160)}`);
    if (repoDir && worktreePath) {
      try {
        worktreeRemove(repoDir, worktreePath);
      } catch {
        /* best-effort */
      }
      try {
        removeRunLock(worktreePath);
      } catch {
        /* best-effort */
      }
    }
    throw e;
  }

  if (!result.ok) {
    console.error(`rmd approve: ${result.refusal}`);
    for (const s of result.skipped) console.error(`  skipped ${s.proposalId}: ${s.reason}`);
    releaseBatchUnfiled(`refused: ${result.refusal.slice(0, 160)}`);
    return 1;
  }
  for (const s of result.skipped) console.log(`rmd approve: skipped ${s.proposalId} — ${s.reason}`);

  idBlocks.forEach((b) => b.releaseAll());
  releaseBatchUnfiled("ratified");

  updateProposalRegistry(registryPath, (current) => {
    const acceptedIds = new Set(result.accepted.map((p) => p.proposalId));
    const next = current.filter((p) => !acceptedIds.has(p.id));
    return next.length === current.length ? null : next;
  });

  if (!repoDir || !worktreePath) {
    throw new Error("rmd approve: batch gateway reported success but never created a ratification branch");
  }
  const ownedRepoDir = repoDir;
  const ownedWorktreePath = worktreePath;
  const removeApproveWorktree = () => worktreeRemove(ownedRepoDir, ownedWorktreePath);

  try {
    const ownership = checkPrOwnership(result.prUrl, result.branch, ghPrHeadGateway(), 0);
    if (ownership) {
      log("verdict", ownership.ledger);
      console.error(`rmd approve: claimed PR ${result.prUrl} is not this run's own branch (${result.branch})`);
      removeApproveWorktree();
      return 1;
    }
    log("pr.opened", { pr_url: result.prUrl, branch: result.branch, accepted: result.accepted.map((p) => p.proposalId) });
    console.log(`rmd approve: batch of ${result.accepted.length} — plan PR opened: ${result.prUrl}`);

    const ci = ciGateState(await waitForCiGreen(result.prUrl, (s, extra) => log(s, extra)));
    const notGreenExit = approveCiNotGreenExit(ci, result.prUrl, removeApproveWorktree);
    if (notGreenExit !== undefined) return notGreenExit;
    const prNum = result.prUrl.match(/\/pull\/(\d+)/)?.[1] ?? result.prUrl;
    const reviewCode = await reviewCommand(prNum);
    let armHeadSha: string | undefined;
    try {
      armHeadSha = readHeadShaRest(result.prUrl);
    } catch {
      /* best-effort — see the single-path comment above */
    }
    const armOutcome = armAndLogOutcome(result.prUrl, `PR-${prNum}`, log, undefined, undefined, armHeadSha);
    removeApproveWorktree();
    // W1-T968: the PR — not merely this call — is what the console line answers about; a
    // review-lane arm already ledgered moments earlier on this SAME head must still read as armed.
    const priorArm = priorArmOnHead(readLedgerLines(ledgerPath), result.prUrl, armHeadSha);
    console.log(
      `rmd approve: batch of ${result.accepted.length} gated — ${armReportPhrase(armOutcome, priorArm)} ` +
        `(review ${reviewCode === 0 ? "success" : "failure"}): ${result.prUrl}`,
    );
    return reviewCode;
  } catch (e) {
    log("approve.error", { error: String((e as Error)?.message ?? e) });
    try {
      removeApproveWorktree();
    } catch {
      /* best-effort */
    }
    throw e;
  } finally {
    if (ownedWorktreePath) removeRunLock(ownedWorktreePath);
  }
}

/**
 * `rmd reframe <P##> --feedback "<text>" [--supersedes <rounds>]` — the operator's
 * OBJECTION path (MASTER-PLAN P25 iii, W1-T111): captures the feedback verbatim, ledgers
 * `ratify.reframed`, and invalidates the proposal's cached draft so the NEXT `rmd inbox`
 * pass redrafts WITH the feedback in the Architect prompt ({@link inboxDraftPrompt}). Valid
 * for ANY proposal already in the registry, whatever its current classification — reframe
 * is feedback, never a ratification, and opens no PR. State-side only (registry + draft
 * cache + ledger); no clone, no worktree, no `gh` call.
 *
 * `--supersedes` (W1-T194) is the EXPLICIT retraction surface the composer's own
 * "address EVERY round" header otherwise leaves nothing to countermand: a round number, a
 * comma list, a range, or `ALL` ({@link parseSupersedesExpr}), naming EXISTING rounds this
 * round supersedes. Retraction never deletes — the retracted rounds stay in
 * `reframeHistory` and their original ledger lines are untouched — it only stops
 * {@link inboxDraftPrompt} from carrying their text into the NEXT redraft. An invalid
 * expression (out of range, unparseable) is a usage error; nothing is written.
 */

/** The one author string a CLI-written note carries. `operator-notes.ts` states this deployment
 *  has no per-human identity, so inventing a `--author` flag would offer precision the system
 *  cannot back — the note's accountability is the SURFACE it arrived on, recorded in its own
 *  ledger step (`operator_note.added` for the CLI, `panel.operator_note_added` for the console). */
const CLI_OPERATOR_NOTE_AUTHOR = "operator";

export function configuredOperatorNoteStore(config: Config, repository?: string, legacyRoot = repoRoot): OperatorNoteStore | undefined {
  let target = repository;
  if (target === undefined) {
    const self = resolveOwnerRepo();
    target = `${self.owner}/${self.repo}`;
  }
  return operatorNoteStore({ stateDir: join(config.root, "state"), repository: target, legacyRoot });
}

/**
 * W1-T3351 — write ONE stamped operator note, from the CLI, to the docket's fifth capture surface.
 *
 * Shared by `rmd note` and `rmd approve --note` so the two cannot drift: one stamp, one store, one
 * ledger step. `appendOperatorNote` REFUSES an unstamped entry and never throws, so a filesystem
 * failure is a `false` the caller reports rather than a crash mid-ratification.
 *
 * The time source is the shared {@link Clock} port, never a bespoke `now`-shaped field:
 * clock-signature-census.test.ts tracks every new bare `() => Date` signature added to this file
 * as legacy-shape growth, and this is new code with no legacy caller to stay compatible with.
 */
export function recordCliOperatorNote(
  root: string | OperatorNoteStore | undefined,
  taskId: string,
  text: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  clock: Clock,
): boolean {
  const note = text.trim().replace(/\s+/g, " ");
  const entry = { ts: clock.iso(), taskId, author: CLI_OPERATOR_NOTE_AUTHOR, note };
  const written = appendOperatorNote(root, entry);
  log(written ? "operator_note.added" : "operator_note.refused", {
    task_id: taskId,
    author: CLI_OPERATOR_NOTE_AUTHOR,
    chars: note.length,
  });
  return written;
}


/** `rmd approve <id> --note "<text>"` — the optional half. Absent `--note` is a NO-OP, so the
 *  one-bit ratification `approve` documents stays exactly one bit unless the operator chose to
 *  say more. Never called before the approve succeeded. */
function approveNoteChain(
  rest: string[],
  scopeId: string,
  config: Config,
  deps: { root?: string; clock?: Clock; log?: (step: string, extra?: Record<string, unknown>) => void },
): void {
  const text = flagValue(rest, "--note");
  if (text === undefined || text.trim().length === 0) return;
  const log =
    deps.log ??
    ((step: string, extra: Record<string, unknown> = {}) =>
      appendLedger(ledgerPathFor(config), { run_id: `APPROVE-${scopeId}`, task_id: scopeId, step, ...extra }));
  const written = recordCliOperatorNote(deps.root ?? configuredOperatorNoteStore(config), scopeId, text, log, deps.clock ?? systemClock);
  console.log(
    written
      ? `rmd approve: note recorded for ${scopeId} — it enters the next weekly feedback docket.`
      : `rmd approve: the note store refused this entry — the ratification stands, the note was NOT recorded.`,
  );
}

/**
 * `rmd note <id> <text...>` — the operator's own words, into the surface the weekly feedback docket
 * already gathers across ALL tasks.
 *
 * THE TEXT IS POSITIONAL, DELIBERATELY. `rmd reframe` already captures operator words verbatim into
 * `ratify.reframed` — the docket's FIRST surface, fully wired — behind a required
 * `--feedback "<text>"` flag, and that step reads ZERO across the entire ledger union. A capture
 * path that costs a flag is a capture path that does not get used. This one costs an id and the
 * sentence you were going to type anyway.
 */
export async function noteCommand(
  rest: string[],
  deps: { root?: string; noteStore?: OperatorNoteStore; repository?: string; clock?: Clock; log?: (step: string, extra?: Record<string, unknown>) => void; config?: Config } = {},
): Promise<number> {
  const taskId = rest[0];
  const text = rest.slice(1).join(" ");
  if (!taskId || taskId.startsWith("--") || text.trim().length === 0) {
    console.error(
      `rmd note: <id> and <text...> are both required — usage: ${commandSyntax("note")}\n` + USAGE,
    );
    return 2;
  }
  const root = deps.root ?? repoRoot;
  const log =
    deps.log ??
    ((step: string, extra: Record<string, unknown> = {}) => appendLedger(ledgerPathFor(deps.config ?? loadConfig()), { run_id: `NOTE-${taskId}`, task_id: taskId, step, ...extra }));
  const store = Object.hasOwn(deps, "noteStore") ? deps.noteStore :
    deps.root ? root : configuredOperatorNoteStore(deps.config ?? loadConfig(), deps.repository);
  const written = recordCliOperatorNote(store, taskId, text, log, deps.clock ?? systemClock);
  if (!written) {
    console.error(`rmd note: the note store refused this entry (unwritable ${join(root, "plan", "operator-notes.ndjson")}?) — nothing was recorded`);
    return 1;
  }
  console.log(`rmd note: recorded for ${taskId} — it enters the next weekly feedback docket.`);
  return 0;
}

/** A forwarded input requires the configured instance's existing root binding. A direct local
 * command may instead use its explicit checkout context; no account-selected repository is read. */
function explicitReframeTarget(instance: string) {
  const registryPath = process.env.RMD_INSTANCE_REGISTRY?.trim() || daemonInstanceRegistryPath(repoRoot);
  let registryText: string | undefined;
  try { registryText = readFileSync(registryPath, "utf8"); }
  catch { return { ok: false as const, refusal: "instance registry is unreadable; forwarded input scope is unverified" }; }
  return resolvePauseTarget({ configRoot: "", instance, registryText, registryPath });
}

function reframeCausalScope(config: Pick<Config, "root">, forwarded: boolean): InboxCausalScope | undefined {
  const registryPath = process.env.RMD_INSTANCE_REGISTRY?.trim() || daemonInstanceRegistryPath(repoRoot);
  let registryText: string | undefined;
  try { registryText = readFileSync(registryPath, "utf8"); }
  catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
      console.error("rmd reframe: instance registry is unreadable; repository scope is unverified");
      return undefined;
    }
    registryText = undefined;
  }
  const bound = resolvePauseTarget({ configRoot: config.root, registryText, registryPath });
  if (bound.ok && registryText) {
    const instance = parseInstanceRegistry(registryText).instances.find(instance => instance.name === bound.target.instance && instance.live);
    return instance ? { repository: instance.repo, instance: instance.name } : undefined;
  }
  if (forwarded) return undefined;
  const { owner, repo } = resolveOwnerRepo();
  return { repository: `${owner}/${repo}` };
}

export async function reframeCommand(rest: string[], deps: { config?: Config } = {}): Promise<number> {
  const proposalId = rest[0];
  const badArg = unknownArgError("reframe", rest.slice(1), ["--feedback", "--supersedes", "--input-id", "--instance"], []);
  if (!proposalId || badArg) {
    console.error((badArg ?? `rmd reframe: <P##> is required — usage: ${commandSyntax("reframe")}`) + "\n" + USAGE);
    return 2;
  }
  const feedback = flagValue(rest, "--feedback");
  if (!feedback) {
    console.error(`rmd reframe: --feedback "<text>" is required — usage: ${commandSyntax("reframe")}\n` + USAGE);
    return 2;
  }

  const inputId = flagValue(rest, "--input-id");
  const instance = flagValue(rest, "--instance");
  if ((inputId === undefined) !== (instance === undefined)) {
    console.error("rmd reframe: a forwarded input requires both --instance and --input-id — nothing was changed");
    return 2;
  }
  let explicitRoot: string | undefined;
  if (instance !== undefined) {
    const selected = explicitReframeTarget(instance);
    if (!selected.ok) { console.error(`rmd reframe: ${selected.refusal}`); return 2; }
    explicitRoot = selected.target.root;
  }
  // Forwarded, state-only work uses the declared source. It neither opens the account config
  // nor loads provider credentials, and cannot select an arbitrary path or repository label.
  const config: Pick<Config, "root"> = explicitRoot !== undefined ? { root: explicitRoot } : deps.config ?? loadConfig();
  const causalScope = reframeCausalScope(config, inputId !== undefined);
  if (!causalScope || inputId !== undefined && !/^[A-Za-z0-9._:-]{1,256}$/.test(inputId)) {
    console.error("rmd reframe: repository/input scope is unverified — nothing was changed");
    return 2;
  }
  let input: InboxInputReference | undefined;
  if (inputId !== undefined) {
    const captured = readThread(inboxThreadId(proposalId), { threadStorePath: inboxThreadStorePath(config.root) });
    const matches = captured.status === "ok" ? captured.messages.filter(message => message.role === "reply" && !hasThreadEvent(message.extra) && message.extra?.input?.id === inputId) : [];
    const capturedInput = matches[0]?.extra?.input;
    if (matches.length !== 1 || matches[0]!.body !== feedback || capturedInput === undefined || verifiedInboxInput(capturedInput, causalScope, proposalId, feedback) === false) {
      console.error("rmd reframe: input is missing, ambiguous, foreign or changed — nothing was changed");
      return 2;
    }
    input = capturedInput;
  }
  const ledgerPath = ledgerPathFor(config);

  const registryPath = join(config.root, "state", "inbox-proposals.json");
  const proposal = parseProposalRegistry(readFileIfExists(registryPath)).find(proposal => proposal.id === proposalId);
  const draftsPath = join(config.root, "state", "inbox-drafts.json");
  if (!proposal) {
    console.error(`rmd reframe: unknown proposal '${proposalId}' — not in the ACTIVE registry (${registryPath})`);
    return 2;
  }

  const supersedesExpr = flagValue(rest, "--supersedes");
  let supersedes: number[] | undefined;
  if (supersedesExpr !== undefined) {
    const historyLength = (proposal.reframeHistory ?? []).length;
    const parsed = parseSupersedesExpr(supersedesExpr, historyLength);
    if (!parsed) {
      console.error(
        `rmd reframe: --supersedes '${supersedesExpr}' is not a valid round expression for ${proposalId} ` +
          `(${historyLength} round${historyLength === 1 ? "" : "s"} on record) — expected round numbers, a ` +
          `range (e.g. "2-3"), or ALL. Usage: ${commandSyntax("reframe")}\n${USAGE}`,
      );
      return 2;
    }
    supersedes = parsed;
  }

  const runId = `REFRAME-${proposalId}-${Date.now()}`;
  // W1-T240: apply the reframe against a FRESH read of the registry, under lock — never
  // the `proposal` `loadProposalForRatify` read above, which a concurrent `rmd approve`/
  // another `rmd reframe`/the daemon's own heal write could have changed (or removed)
  // since. See lib/inbox.ts's `updateProposalRegistry` doc for the lost-update/torn-file
  // hazard this guards against.
  let reframed: ReframeResult | undefined;
  updateProposalRegistry(registryPath, (current) => {
    const freshProposal = current.find((p) => p.id === proposalId);
    if (!freshProposal) return null; // vanished concurrently — nothing left to reframe
    const freshDrafts = parseDraftCache(readFileIfExists(draftsPath));
    reframed = reframeProposal(freshProposal, feedback, freshDrafts, { ledgerPath, runId, threadStorePath: inboxThreadStorePath(config.root), causalScope, ...(input ? { input } : {}) }, supersedes);
    writeAtomic(draftsPath, JSON.stringify(reframed.drafts, null, 2));
    return current.map((p) => (p.id === proposalId ? reframed!.proposal : p));
  });
  if (!reframed) {
    console.error(`rmd reframe: ${proposalId} was removed from the registry by a concurrent update — nothing to reframe`);
    return 2;
  }

  console.log(
    supersedes && supersedes.length > 0
      ? `rmd reframe: ${proposalId} — feedback ledgered, round${supersedes.length > 1 ? "s" : ""} ${supersedes.join(", ")} ` +
          "retracted, draft invalidated; the next `rmd inbox` pass will redraft with it."
      : `rmd reframe: ${proposalId} — feedback ledgered, draft invalidated; the next \`rmd inbox\` pass will redraft with it.`,
  );
  return 0;
}

/**
 * `rmd digest [--since <iso>] [--dry-run]` — roll up the ledger since `--since` into one message
 * (digest.ts) and send it over iMessage; `--dry-run` prints the text without sending.
 *
 * W1-T163 (MARKER-AWARE by default): with NO `--since`, the window is the operator's own
 * `lib/last-seen.ts` marker — the SAME per-token marker the console's `GET /v1/status` recap
 * advances on a board view (lib/board.ts) — keyed off the write token's id (the write token is
 * the operator's real credential; a read-only caller never sends this digest). A first-ever send
 * (no marker yet) falls back to the pre-existing 24h-ago default. Sending (never `--dry-run`,
 * which previews without any side effect) then ADVANCES that same marker to now, so "push and
 * pull tell one story": whichever of a digest send or a console view happens next only reports
 * what's left since THIS send, never re-reporting what it already covered.
 *
 * An EXPLICIT `--since` is an operator-directed override/inspection tool — it builds/sends
 * exactly that window (old behavior, unchanged) and deliberately never touches the marker, so a
 * one-off "show me since <date>" never resets the shared push/pull window out from under it.
 */
// digestCommand moved to src/lib/report-commands.ts (W1-T2888) — imported/re-exported below.

/**
 * `rmd ops [--dry-run]` — alert intake v0+v1 (W1-T55/W1-T56, MASTER-PLAN §5D lane 2, §7B): poll
 * code-scanning/Dependabot/secret-scanning alerts for THIS repo via `gh api` (lib/ops.ts), fold
 * OPEN counts+ages into the next `rmd digest`, escalate every NEW critical/high alert exactly
 * once via the SHIPPED escalate() path, and capture a `plan/feedback/<id>.yaml` entry (origin:
 * `alert#<source>-<id>`) for every open alert not already captured, ANY severity, for `rmd
 * triage` (W1-T41) to ground and propose a corrective task from. Escalation dedup is
 * ledger-keyed (escalation.issue_opened task ids); feedback-capture dedup is id-keyed (a
 * deterministic `fb-alert-<owner>-<repo>-<source>-<id>` id) — a re-poll of the SAME open alerts
 * escalates and captures nothing new. --dry-run previews the counts + which alerts WOULD
 * escalate; it opens no issues, captures no feedback, and writes no ledger line.
 */
export async function opsCommand(
  rest: string[],
  // W1-T462: APPENDED LAST AND FULLY DEFAULTED, so no positional caller shifts. Exists because the
  // union-reading `readLedger` below is otherwise unreachable from a test — this function builds its
  // own config, gateways and ledger path, so without a seam the one line that fixes the dedupe could
  // only be asserted by grepping source, which is what let its predecessor ship half-wired.
  deps: { pollAlerts?: typeof pollAlerts; loadConfig?: typeof loadConfig; resolveOwnerRepo?: typeof resolveOwnerRepo } = {},
): Promise<number> {
  const badArg = unknownArgError("ops", rest, [], ["--dry-run"]);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const dryRun = rest.includes("--dry-run");
  const config = (deps.loadConfig ?? loadConfig)();
  const ledgerPath = ledgerPathFor(config);
  const { owner, repo } = (deps.resolveOwnerRepo ?? resolveOwnerRepo)();
  const runId = `OPS-${Date.now()}`;
  const result = await (deps.pollAlerts ?? pollAlerts)(owner, repo, {
    // W1-T462: THE DEDUPE READS THE UNION, NOT ONE FILE. `pollAlerts` defaults `readLedger` to
    // `readLedgerLines`, which opens EXACTLY ONE path — and its dedupe key,
    // `escalation.issue_opened`, is capped by rotation at `MAX_RETAINED_LINES_PER_STEP` (200).
    // MEASURED on this host at 2026-08-13: the live file exposes 107 distinct escalated ids while
    // the union holds 207 — SO 100 ALREADY-ESCALATED ALERTS WERE INVISIBLE TO THE DEDUPE, and
    // re-polling would have opened a duplicate issue for every one of them.
    //
    // THAT IS WHY THIS LINE SHIPS WITH THE CADENCE RATHER THAN AFTER IT. A cadence is precisely
    // what turns a latent one-file read into repeated duplicate escalations — the same shape as the
    // credit treadmill #1710 fixed, where `hasMergeCredit` read one file against the same 200-row
    // cap and re-credited 185 tasks forever. Scheduling the poll without this would have shipped
    // the amplifier and called it a feature.
    //
    // The fix is at the CALLER because `readLedger` is already injectable — `lib/ops.ts` is
    // untouched, which is what W1-T462's design (iii) requires ("do not build a new poller").
    // NO `satisfied` PREDICATE, DELIBERATELY. `readLedgerUnionBounded`'s early stop is keyed on
    // STEPS SEEN, which answers "is this step present anywhere" — and the live file almost always
    // has one `escalation.issue_opened`, so a step predicate stops before opening a single
    // rotation and reproduces the exact one-file blindness this injection exists to fix. A dedupe
    // needs the whole SET, not the newest row, so it reads to the rotation cap.
    readLedger: (path) => readLedgerUnionBounded(path),
    alerts: ghAlertGateway(),
    issues: ghIssueGateway(owner, repo),
    ledgerPath,
    runId,
    root: repoRoot,
    dryRun,
    capture: captureFeedback,
  });
  console.log(`### rmd ops${dryRun ? " --dry-run" : ""} — ${owner}/${repo}\nalerts: ${renderAlertsSummary(result.summary)}`);
  if (dryRun) {
    console.log(
      result.newCritical.length
        ? `would escalate ${result.newCritical.length} new critical/high alert(s): ${result.newCritical
            .map((a) => `${a.source}#${a.id} [${a.severity}]`)
            .join(", ")}`
        : "no new critical/high alerts to escalate",
    );
  } else if (result.escalated.length > 0) {
    console.log(`escalated ${result.escalated.length} new critical/high alert(s):`);
    for (const e of result.escalated) console.log(`  ${e.alert.source}#${e.alert.id} [${e.alert.severity}] -> ${e.issueUrl}`);
  } else {
    console.log("no new critical/high alerts to escalate");
  }
  if (!dryRun) {
    if (result.feedbackCreated.length > 0) {
      console.log(`captured ${result.feedbackCreated.length} new feedback entr${result.feedbackCreated.length === 1 ? "y" : "ies"}:`);
      for (const e of result.feedbackCreated) console.log(`  ${e.origin} -> plan/feedback/${e.id}.yaml`);
    } else {
      console.log("no new alerts to capture as feedback");
    }
  }
  return 0;
}

/**
 * The ephemeral fix-run worker's prompt (W1-T90) — mirrors the retro/triage prompts' own
 * "harness eats first" split: the WORKER only fixes the alert and opens its own PR through the
 * normal contract (`Acceptance:`/`Remudero-Task:` trailer, `PR_URL:` REPORT line); this command
 * owns the worktree/spawn/teardown mechanics deterministically, so an LLM can never skip the
 * contract or scope-creep past the one named alert.
 *
 * W1-T8625: its Acceptance block is taught by {@link PR_BODY_ACCEPTANCE_GRAMMAR}, the shared PR-body grammar. The bare
 * "`- <claim> | <proof>` bullets" line it replaced named no dialect, so a worker wrote prose and the reviewer capped it.
 */
export function alertFixPrompt(alert: AlertLaneAlert, taskId: string, harnessOwned?: { bodyFile: string }): string {
  return [
    "You are a REMUDERO fix worker dispatched by the alert-fix lane (W1-T90, MASTER-PLAN P20, §5D lane 2).",
    "Fix EXACTLY ONE thing: the alert named below. Do not scope-creep into unrelated changes.",
    "",
    `Alert: ${alert.source} #${alert.id} [${alert.severity}]`,
    `Summary: ${alert.summary}`,
    alert.url ? `Link: ${alert.url}` : undefined,
    alert.path ? `Path: ${alert.path}` : undefined,
    "",
    "This alert was matched by policy (plan/alert-policy.yaml) as safe to auto-fix: severity is",
    "medium or low, AND outside the gate/containment-critical path set. Make the minimal, correct fix.",
    "",
    ...(harnessOwned ? [
    `THE PR BODY IS ALREADY WRITTEN, by the dispatcher, at: ${harnessOwned.bodyFile}`,
    "It lives outside your checkout: never copy it in and never commit it. Its `origin:` line and its",
    `trailer \`Remudero-Task: ${taskId}\` are the dispatcher's; leave them as written.`,
    `Replace ONLY the line \`${MAIN_REPAIR_PROSE_PLACEHOLDER}\` with your prose, and the line`,
    `\`${MAIN_REPAIR_ACCEPTANCE_PLACEHOLDER}\` with ONE executable bullet per claim, in this grammar:`,
    ...PR_BODY_ACCEPTANCE_GRAMMAR,
    "",
    "Then, from the working directory:",
    ...harnessOwnedRepairSteps(),
    ] : [
    "Then, from the working directory:",
    "- git add the changed files && commit;",
    // The commit/PR contracts every other worker prompt carries: this lane's PR failed commitlint
    // AFTER it existed, because the prompt said only "commit with a concise message".
    ...commitMessageContractLines(),
    "- `git push origin HEAD` (NOT -u);",
    "- open a PR with an EXPLICIT title: `gh pr create --title \"type(scope): subject\" --fill --base main`.",
    "  PR TITLE: a conventional-commit subject of <= 100 characters, written by you — never the",
    "  title `--fill` derives from the commit or the branch name.",
    ...bodyVsDiffContractLines(),
    "  The PR body MUST include:",
    "  - an `Acceptance:` block covering the fix, written to the ACCEPTANCE PROOFS rules below;",
    `  - \`origin: alert#${alertOriginId(alert)}\` naming this alert's provenance;`,
    `  - as the LAST body line: \`Remudero-Task: ${taskId}\`.`,
    ...PR_BODY_ACCEPTANCE_GRAMMAR,
    "- End your REPORT with exactly: PR_URL: <the pull request url>",
    ]),
  ]
    .filter((l): l is string => l !== undefined)
    .join("\n");
}

/**
 * The effectful collaborators {@link dispatchAlertFixRun} calls through — real defaults below,
 * injectable so a unit test can drive every branch (success/no-PR/error) without ever shelling
 * `git worktree`, reading `mounts.yaml`, or spawning the Agent SDK for real (the SAME
 * fake-the-boundary shape {@link withMaterializedWorktree}'s injected `remove` and
 * `defaultReconRunLens`'s injected `spawn`/`probeExec` already use in this file).
 */
export interface AlertFixDispatchDeps {
  /** W1-T2621: the optional 5th positional matches `worktreeAdd`'s own (lib/worker.ts) — this
   *  lane threads its `log` through it below so the fail-open's `worktree.base_uncheckable`
   *  and the `worktree.add` three-way base reading land on the SAME ledger every other row
   *  this lane writes goes to, not nowhere. */
  worktreeAdd: (
    repoDir: string,
    worktreePath: string,
    branch: string,
    startPoint: string,
    deps?: { log?: (step: string, extra?: Record<string, unknown>) => void },
  ) => void | Promise<void>;
  worktreeRemove: (repoDir: string, worktreePath: string) => void;
  renderWorkerSettings: typeof renderWorkerSettings;
  loadMounts: typeof loadMounts;
  resolveMount: typeof resolveMount;
  spawn: (args: SpawnWorkerArgs) => Promise<WorkerResult>;
  /** W1-T2435: takes the SAME `log` the rest of this dispatch already writes through, so a
   *  swallowed read/write failure lands a `trailer_stamp.failed` row on this lane too, not just
   *  the four `runTaskBody`-family call sites. */
  ensureTaskTrailer: (prUrl: string, taskId: string, log: (step: string, extra?: Record<string, unknown>) => void) => void;
  /** W1-T952 design (ii): the author-time acceptance check, applied to the just-opened PR before
   *  CI/review would pay for a round trip to discover the same defect. Injectable so a test can
   *  drive both the refusal and the positive-control branch without a real `gh` call — see the
   *  real binding ({@link checkAlertFixAcceptance}) and `PR_AUTHORING_PATHS`'s "alert-fix" row
   *  (lib/review.ts) for why THIS lane, specifically, cannot fall back to a plan-side lookup. */
  checkAcceptance: AlertFixAcceptanceCheck;
  /** W1-T8625: the opened PR's body, which the dispatcher parses ITSELF for inert proofs — `checkAcceptance`'s trailer
   *  arm returns `ok` before it reads the block, and every alert-fix body carries a trailer. Optional so the dispatch
   *  fakes that predate it keep driving only what they drove; omitted, the inert-proof count does not run (no real
   *  `gh` default fires under a fake). The real binding is {@link readAlertFixPrBody}. W1-T9698: the dispatch reads it
   *  ONCE, awaited, and hands that body to `checkAcceptance`. */
  readPrBody?: AlertFixBodyRead;
  /** W1-T8572: the main-repair fix dispatch's no-test-file open (that lane reuses this seam rather than declaring
   *  another): the REST PR create, the pushed branch's diff against origin/main and its head subject. Optional, so a
   *  fake that omits them gets the real reads; the alert-fix lane never calls them. */
  fetch?: GhApiFetcher;
  readDiff?: (worktreePath: string) => string | undefined;
  readHeadSubject?: (worktreePath: string) => string;
  pushBranch?: (worktreePath: string, expectedHeadSha: string) => Promise<unknown>; // W1-T9667: the host push of a harness commit
  readRemoteBranchHead?: (worktreePath: string, branch: string) => Promise<string | undefined>; // W1-T9667: `git ls-remote`
}

export { alertFixBodyDeps, checkAlertFixAcceptance, readAlertFixPrBody } from "./lib/alert-fix-body.js";

const REAL_ALERT_FIX_DISPATCH_DEPS: AlertFixDispatchDeps = {
  worktreeAdd: worktreeAddAsync,
  worktreeRemove,
  renderWorkerSettings,
  loadMounts,
  resolveMount,
  spawn: ledgeredNonDispatchSpawn("alert-fix"),
  ensureTaskTrailer,
  ...alertFixBodyDeps(),
};

/**
 * The real `deps.dispatch` effect {@link runAlertLane} calls for an "act" disposition (W1-T90) —
 * a MINIMAL analog of `buildSweepEffects`'s `dispatchFix` (~line 5546): a fresh branch off
 * `origin/main`, a fresh worker settings file, ONE `spawnWorker` call, teardown. Deliberately
 * NOT `dispatchFix`'s full machinery (no existing task/PR/branch to reuse, no fix-rung strikes —
 * this is a BRAND NEW ephemeral run, never a fix on an existing task's branch): the worker owns
 * its own commit/push/PR-open steps (mirrors the retro/triage workers' prompts) via
 * {@link alertFixPrompt}; this function only spawns it and tears the worktree down after.
 */
export async function dispatchAlertFixRun(
  owner: string,
  repo: string,
  config: Config,
  alert: AlertLaneAlert,
  ledgerPath: string,
  runId: string,
  deps: AlertFixDispatchDeps = REAL_ALERT_FIX_DISPATCH_DEPS,
): Promise<void> {
  const originId = alertOriginId(alert);
  const taskId = alertTaskId(alert);
  const log = (step: string, extra: Record<string, unknown> = {}) =>
    appendLedger(ledgerPath, { run_id: runId, task_id: taskId, step, lane: "alert-fix", ...extra });

  const repoDir = repo === resolveOwnerRepo().repo ? repoRoot : join(config.root, "repos", repo);
  const branch = `alert-fix-${originId}-${Date.now()}`;
  const worktreePath = join(worktreesDir(config), branch);
  const bodyFile = join(config.root, "tmp", `alert-fix-body-${taskId}-${systemClock.now()}.md`);
  try {
    await deps.worktreeAdd(repoDir, worktreePath, branch, "origin/main", { log });
    mkdirSync(dirname(bodyFile), { recursive: true });
    writeFileSync(bodyFile, alertFixBody(alert, taskId));
    const settingsFile = deps.renderWorkerSettings({
      templatePath: join(resolveInstallRoot(config), "settings", "worker.json"),
      hooksDir: join(resolveInstallRoot(config), "hooks"),
      outPath: join(config.root, "tmp", `alert-fix-settings-${taskId}-${Date.now()}.json`),
    });
    const mountsTable = deps.loadMounts(mountsPath(repoRoot));
    // W1-T90 rides the SAME "fix" task_type mounts.yaml already routes (§9) — this ephemeral run
    // is scoped down to a single-alert fix, the same shape a fix-rung strike already is. Risk
    // band is pinned at "medium": policy already confined this dispatch to a non-critical-path,
    // medium/low-severity alert (decideAlertDisposition), so a "low"/"high" spend band would
    // either under- or over-provision every dispatch identically — "medium" is the accurate
    // single band for the whole act-eligible severity range this lane ever dispatches.
    const fixMount: Mount = deps.resolveMount(mountsTable, "fix", "medium");

    log("alert-fix.dispatching", { branch, mount: fixMount.model });
    // W1-T3616: an alert fix commits and pushes, so it takes the fix lane's own list rather than
    // a narrower second copy.
    const toolBound = [...resolveDispatchLaneToolBound("alert_fix", fixMount.provider ?? "claude")];
    const worker = await deps.spawn({
      cwd: worktreePath,
      permissionMode: "bypassPermissions",
      tools: toolBound,
      settingsFile,
      model: fixMount.model,
      mountProvider: fixMount.provider,
      effort: fixMount.effort,
      maxTurns: fixMount.maxTurns,
      maxBudgetUsd: DEFAULT_BUDGET_USD,
      config,
      prompt: alertFixPrompt(alert, taskId, repairHarnessOwnsGit({ provider: fixMount.provider, tools: toolBound }) ? { bodyFile } : undefined),
    });
    log("alert-fix.dispatched_worker", {
      session_id: worker.sessionId,
      subtype: worker.subtype,
      ...workerLedgerFields(worker),
    });

    const workerReport = parseReport(workerTranscript(worker));
    const owned = (workerReport?.prUrl ?? "") === "" && repairHarnessOwnsGit({ provider: worker.provider, tools: toolBound, harnessCommit: workerHarnessCommit(worker) });
    const landed = owned ? await landHarnessCommit("alert-fix", worker, branch, worktreePath, log, deps) : undefined;
    const report = landed === undefined ? workerReport : { prUrl: await openCheckedRepairPr(owner, repo, "alert-fix", { branch, base: "main", worktreePath,
      bodyFile, pushedHead: landed, prose: `Fixes ${alert.source} alert #${alert.id} [${alert.severity}]: ${alert.summary}`, fallbackTitle: `fix(alert): ${alert.source} #${alert.id}` }, log, deps) };
    if (report?.prUrl) {
      deps.ensureTaskTrailer(report.prUrl, taskId, log);
      log("alert-fix.pr_opened", { pr_url: report.prUrl, origin: `alert#${originId}` });
      // W1-T952 design (ii): the diagnostics call, at the one point this lane already reads the
      // PR back — before CI/review would pay a full cycle to discover the same thing (rationale
      // (2)). Best-effort: an unreadable PR (a `gh` hiccup) must never fail this lane over a
      // diagnostic read, so only the check itself is guarded, not `ensureTaskTrailer`/`pr_opened`
      // above. W1-T9698: one awaited body read serves the check and the inert-proof count (W1-T8625);
      // the mutation check (test/acceptance-block-diagnostics.test.ts) targets its call in lib/alert-fix-body.ts.
      await judgeOpenedAlertFixBody(report.prUrl, deps.checkAcceptance, deps.readPrBody, log);
    } else if (!owned || landed !== undefined) {
      log("alert-fix.no_pr", { subtype: worker.subtype });
    }
  } catch (e) {
    log("alert-fix.error", { error: String((e as Error)?.message ?? e) });
  } finally {
    rmSync(bodyFile, { force: true });
    try {
      deps.worktreeRemove(repoDir, worktreePath);
    } catch {
      /* best-effort cleanup */
    }
  }
}

/** W1-T6403 — a red-main fix PR's synthetic task id, one per offending merge; W1-T9583 cuts each lane's head `run-<its id>-<epochMs>`. */
export function mainRepairTaskId(offendingSha: string): string {
  return `main-repair-${offendingSha.slice(0, 12)}`;
}
export const mainRepairRevertTaskId = (offendingSha: string): string => `main-repair-revert-${offendingSha.slice(0, 12)}`;

/**
 * W1-T8572 — THE DISPATCHER WRITES A MAIN-REPAIR PR'S ACCEPTANCE BLOCK. Paths with a named failing-test witness
 * qualify for whole-file proofs through {@link mainRepairUsesFileProofs}; reported paths alone remain context.
 * The harness spells the file proof so a model's spelling never sits between a red main and its repair
 * (#11096's prose proofs). Rendered through {@link renderAcceptanceBlock}, so it round-trips
 * through `parseAcceptanceBlock` or throws; it throws on an empty list too, which the no-test-file path never reaches.
 */
export function mainRepairAcceptanceCriteria(request: Pick<MainRepairFixRequest, "testFiles">): string {
  return renderAcceptanceBlock(request.testFiles.map((path) => ({ claim: `${path} passes again on the repaired head`, proof: `unit test: ${path}` })));
}

/** W1-T8572 — the line of the dispatcher-written body the fix worker replaces with its own prose, and nothing else. */
export const MAIN_REPAIR_PROSE_PLACEHOLDER = "WORKER-PROSE: replace this one line with what broke on main and how this change repairs it.";
/** W1-T8572 — the no-test-file body's one line under `Acceptance:` that the worker replaces with its bullets. */
export const MAIN_REPAIR_ACCEPTANCE_PLACEHOLDER = "WORKER-ACCEPTANCE: replace this one line with your `- <claim> | <proof>` bullets.";

// Gate reports can name suites that pass normally; paths alone are not a failing-test witness.
function mainRepairUsesFileProofs(request: Pick<MainRepairFixRequest, "testFiles" | "failingTestTitles">): boolean {
  return request.testFiles.length > 0 && request.failingTestTitles.some((title) => title.trim().length > 0);
}

/** W1-T8572 — the body the dispatcher writes BEFORE the fix worker spawns: the prose placeholder, the Acceptance
 *  block (rendered here when test files are known, a placeholder line for the worker's bullets when not), the
 *  `origin:` line and the `Remudero-Task:` trailer last. */
export function mainRepairFixBody(request: MainRepairFixRequest): string {
  const block = mainRepairUsesFileProofs(request) ? mainRepairAcceptanceCriteria(request) : `Acceptance:\n${MAIN_REPAIR_ACCEPTANCE_PLACEHOLDER}`;
  return [
    MAIN_REPAIR_PROSE_PLACEHOLDER,
    "",
    block,
    "",
    `origin: main-repair#${request.offendingSha}`,
    "",
    `Remudero-Task: ${mainRepairTaskId(request.offendingSha)}`,
    "",
  ].join("\n");
}

/** W1-T6403 — the priority fix worker's prompt: repair main, never revert. W1-T8572: the PR body is the dispatcher's
 *  file at `bodyFile`. With failing test files known, the worker opens the PR with `--body-file` and writes only its
 *  prose; with none, it writes its bullets under {@link PR_BODY_ACCEPTANCE_GRAMMAR} into that file, pushes, and leaves
 *  the open to the dispatcher, which checks those proofs first. */
export function mainRepairFixPrompt(request: MainRepairFixRequest, bodyFile: string, harnessOwnsGit = false): string {
  const pr = request.offendingPr !== undefined ? `PR #${request.offendingPr}` : "an unnamed PR";
  const known = mainRepairUsesFileProofs(request);
  const merges = mainRepairMergesBrief(request);
  return [
    "You are a REMUDERO red-main fix worker dispatched by the main-health rung (W1-T6403).",
    `The default branch \`${request.branch}\` is RED at \`${request.headSha}\`. Every open PR's CI fails until it is green.`,
    `The first red merge is \`${request.offendingSha}\` (${pr}). Its diff stat:`,
    request.diffStat,
    "",
    ...merges.lines,
    "",
    `Failing check(s): ${request.failingChecks.join(", ") || "(none named)"}`,
    `Failing test title(s): ${request.failingTestTitles.join("; ") || "(none parsed from the log)"}`,
    `${known ? "Failing test file(s)" : "Reported test path(s), not established whole-file failures"}: ${request.testFiles.join(", ") || "(none parsed from the log)"}`,
    `Why main reads red: ${request.reason}`,
    "Log excerpt of the failing check(s):",
    "```",
    request.logExcerpt || "(no log was read)",
    "```",
    "",
    merges.fixLine,
    "Do NOT revert that merge — a revert PR is this lane's separate, later step. Do not scope-creep.",
    known ? "Reproduce the failing test file(s) above first, then make the minimal correct change."
      : "Reproduce the red check's actual failing experiment first: reported paths may pass at the ordinary clock. Then make the minimal correct change.",
    "",
    `THE PR BODY IS ALREADY WRITTEN, by the dispatcher, at: ${bodyFile}`,
    "It lives outside your checkout: never copy it in and never commit it. Its `origin:` line and its",
    `trailer \`Remudero-Task: ${mainRepairTaskId(request.offendingSha)}\` are the dispatcher's; leave them as written.`,
    `Replace ONLY the line \`${MAIN_REPAIR_PROSE_PLACEHOLDER}\` with your prose.`,
    ...(known
      ? ["Its Acceptance block is the dispatcher's too: never edit, add or remove a bullet in it."]
      : [
          `${request.testFiles.length > 0 ? "No named failing test witness was supplied" : "No failing test file was parsed"}, so replace the line \`${MAIN_REPAIR_ACCEPTANCE_PLACEHOLDER}\``,
          "with ONE executable bullet per check you repair, in this grammar:",
          ...PR_BODY_ACCEPTANCE_GRAMMAR,
          "The dispatcher reads those bullets before it opens the PR. An undialected proof is a defect it never",
          "opens as written: it is replaced by a `grep:` of a line your pushed change adds, or no PR is opened.",
        ]),
    "",
    "Then, from the working directory:",
    ...(harnessOwnsGit ? harnessOwnedRepairSteps() : [
    "- git add the changed files && commit;",
    ...commitMessageContractLines(),
    "- `git push origin HEAD` (NOT -u); never push to main;",
    ...(known
      ? [
          `- open the PR with an EXPLICIT title and the dispatcher's body: \`gh pr create --title "fix(scope): subject" --body-file ${bodyFile} --base main\`.`,
          "  PR TITLE: a conventional-commit subject of <= 100 characters, written by you.",
          ...bodyVsDiffContractLines(),
          "- End your REPORT with exactly: PR_URL: <the pull request url>",
        ]
      : [
          "- do NOT open a PR: the dispatcher opens it over REST from the body file above, titled with your",
          "  commit's subject, so that subject must be a conventional-commit subject of <= 100 characters.",
          ...bodyVsDiffContractLines(),
          "- End your REPORT with a line `PUSHED: <your branch>`, and write no PR_URL line.",
        ])]),
  ].join("\n");
}

function harnessOwnedRepairSteps(): string[] { // W1-T9667: a harness-committed repair worker's steps (the implement lane's wording)
  return [
    "- save your edits to the files and run NO git or gh command: the harness commits, pushes and opens the PR;",
    ...commitMessageContractLines(),
    ...bodyVsDiffContractLines(),
    "- End your REPORT with a line `COMMIT_MESSAGE: <type>(<scope>): <subject>` (it titles the PR), and write no PR_URL line.",
  ];
}

/** W1-T8572 — where the dispatcher writes the fix PR's body: a fresh file under `config.root/tmp`, outside the
 *  worker's checkout, so `git add` can never commit it. */
function mainRepairBodyFile(config: Config, taskId: string): string {
  return join(config.root, "tmp", `main-repair-body-${taskId}-${systemClock.now()}.md`);
}

/** W1-T8572 — the one inert-proof row: what was inert, how many, and whether the body was rewritten or refused. */
export const MAIN_REPAIR_ACCEPTANCE_DEFECT_STEP = "main-repair.acceptance_defect";

/** W1-T8572 — a no-test-file worker body, checked BEFORE the dispatcher opens it. A body whose proofs all execute is
 *  returned as written. Otherwise its inert bullets ({@link inertAcceptanceProofs}: undialected, a demonstration, or
 *  unparseable — a prose proof naming a test path counts, though `parseWhitelistedProof` reads it) are dropped and one
 *  `grep:` of a line the pushed fix ADDS ({@link diffAnchor}) takes their place; with no such line the body is
 *  refused. Never trusts `acceptanceAuthorTimeCheck`: its trailer arm returns `ok` before it reads the block. */
export function checkMainRepairWorkerBody(
  body: string,
  diffText: string | undefined,
): { body: string } | { body: string; defect: "inert-proofs" | "no-proofs"; inert: string[]; resolution: "rewritten" } | { defect: "inert-proofs" | "no-proofs"; inert: string[]; resolution: "refused"; reason: DiffAnchorUnavailableReason } {
  const criteria = parseAcceptanceBlock(body);
  const inert = inertAcceptanceProofs(body);
  if (criteria.length > 0 && inert.length === 0) return { body };
  const defect = criteria.length === 0 ? "no-proofs" : "inert-proofs";
  const anchor = diffAnchor(diffText);
  if (anchor.kind === "unavailable") return { defect, inert, resolution: "refused", reason: anchor.reason };
  const inertSet = new Set(inert);
  const kept = criteria.filter((c) => !inertSet.has(c.proof ?? "")) as AcceptanceCriterion[];
  const block = renderAcceptanceBlock([...kept, { claim: `the pushed repair adds this line to ${anchor.path}`, proof: anchor.proof }]);
  const region = acceptanceBlockRegion(body);
  const lines = body.split("\n");
  const rewritten =
    region === undefined
      ? `${body.replace(/\s*$/, "")}\n\n${block}\n`
      : [...lines.slice(0, region.headerLine), block, ...lines.slice(region.endLine)].join("\n");
  return { body: rewritten, defect, inert, resolution: "rewritten" };
}

/** W1-T8572 — the defect row for a no-test-file worker that opened its own PR instead of leaving the open to the
 *  dispatcher: the body was never checked before it opened, so this records the breach and the body file's inert
 *  proofs (`body === undefined` when the worker removed that file). */
export function mainRepairWorkerOpenedDefect(prUrl: string, body: string | undefined): Record<string, unknown> {
  const inert = body === undefined ? [] : inertAcceptanceProofs(body);
  return { defect: "worker-opened", count: inert.length, inert_proofs: inert, resolution: "opened-unchecked", pr_url: prUrl, body_file_read: body !== undefined };
}

const REAL_MAIN_REPAIR_FIX_DEPS: AlertFixDispatchDeps = { ...REAL_ALERT_FIX_DISPATCH_DEPS, spawn: ledgeredNonDispatchSpawn("main-repair-fix") };

/**
 * W1-T6403 — the priority fix PR for a red main: {@link dispatchAlertFixRun}'s fresh-branch path, one
 * worker on a branch off origin/main that commits and pushes. W1-T8572: the dispatcher writes the PR body first
 * ({@link mainRepairFixBody}). With failing test files known the worker opens the PR with that body; with none the
 * dispatcher checks the worker's bullets ({@link checkMainRepairWorkerBody}), ledgers any inert proof, and opens the
 * PR over REST with the body it checked, so the opening payload carries it. Returns the PR url, or undefined when
 * none was opened.
 */
export async function dispatchMainRepairFixRun(
  owner: string,
  repo: string,
  config: Config,
  request: MainRepairFixRequest,
  ledgerPath: string,
  runId: string,
  deps: AlertFixDispatchDeps = REAL_MAIN_REPAIR_FIX_DEPS,
): Promise<string | undefined> {
  const taskId = mainRepairTaskId(request.offendingSha);
  const log = (step: string, extra: Record<string, unknown> = {}) =>
    appendLedger(ledgerPath, { run_id: runId, task_id: taskId, step, lane: "main-repair", ...extra });
  const repoDir = repo === resolveOwnerRepo().repo ? repoRoot : join(config.root, "repos", repo);
  const branch = `run-${taskId}-${systemClock.now()}`;
  const worktreePath = join(worktreesDir(config), branch);
  const bodyFile = mainRepairBodyFile(config, taskId);
  try {
    await deps.worktreeAdd(repoDir, worktreePath, branch, "origin/main", { log });
    mkdirSync(dirname(bodyFile), { recursive: true });
    writeFileSync(bodyFile, mainRepairFixBody(request));
    const settingsFile = deps.renderWorkerSettings({
      templatePath: join(resolveInstallRoot(config), "settings", "worker.json"),
      hooksDir: join(resolveInstallRoot(config), "hooks"),
      outPath: join(config.root, "tmp", `main-repair-settings-${taskId}-${systemClock.now()}.json`),
    });
    // A red main blocks every merge, so this rides the fix route at the "high" band (blast-radius).
    const fixMount: Mount = deps.resolveMount(deps.loadMounts(mountsPath(repoRoot)), "fix", "high");
    log("main-repair.dispatching", { branch, mount: fixMount.model, offending_sha: request.offendingSha, body_file: bodyFile });
    const toolBound = [...resolveDispatchLaneToolBound("alert_fix", fixMount.provider ?? "claude")];
    const worker = await deps.spawn({
      cwd: worktreePath,
      permissionMode: "bypassPermissions",
      tools: toolBound,
      settingsFile,
      model: fixMount.model,
      mountProvider: fixMount.provider,
      effort: fixMount.effort,
      maxTurns: fixMount.maxTurns,
      maxBudgetUsd: DEFAULT_BUDGET_USD,
      config,
      prompt: mainRepairFixPrompt(request, bodyFile, repairHarnessOwnsGit({ provider: fixMount.provider, tools: toolBound })),
    });
    log("main-repair.dispatched_worker", { session_id: worker.sessionId, subtype: worker.subtype, ...workerLedgerFields(worker) });
    let prUrl = parseReport(workerTranscript(worker))?.prUrl;
    const owned = !prUrl && repairHarnessOwnsGit({ provider: worker.provider, tools: toolBound, harnessCommit: workerHarnessCommit(worker) });
    if (owned) {
      const landed = await landHarnessCommit("main-repair", worker, branch, worktreePath, log, deps);
      if (landed === undefined) return undefined;
      prUrl = await openCheckedMainRepairPr(owner, repo, request, branch, worktreePath, bodyFile, log, deps, landed);
    } else if (!mainRepairUsesFileProofs(request)) {
      // A no-test-file worker that opened its own PR broke the contract: its body reached GitHub unchecked, so the
      // breach is ledgered with whatever the body file holds. The PR exists, so it is still returned for review.
      if (prUrl) log(MAIN_REPAIR_ACCEPTANCE_DEFECT_STEP, mainRepairWorkerOpenedDefect(prUrl, existsSync(bodyFile) ? readFileSync(bodyFile, "utf8") : undefined));
      else prUrl = await openCheckedMainRepairPr(owner, repo, request, branch, worktreePath, bodyFile, log, deps);
    }
    if (!prUrl) {
      log("main-repair.no_pr", { subtype: worker.subtype });
      return undefined;
    }
    deps.ensureTaskTrailer(prUrl, taskId, log);
    log("main-repair.pr_opened", { pr_url: prUrl, origin: `main-repair#${request.offendingSha}` });
    return prUrl;
  } finally {
    rmSync(bodyFile, { force: true });
    try {
      deps.worktreeRemove(repoDir, worktreePath);
    } catch (error) {
      log("main-repair.worktree_remove_failed", { error: String((error as Error)?.message ?? error) });
    }
  }
}

/** W1-T8572 — the no-test-file open: read the worker's body, check it, ledger a defect, open the checked body over
 *  REST. Undefined when the body is refused or the open fails, so the lane's fix-then-revert path continues. */
async function openCheckedMainRepairPr(
  owner: string,
  repo: string,
  request: MainRepairFixRequest,
  branch: string,
  worktreePath: string,
  bodyFile: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  deps: AlertFixDispatchDeps,
  pushedHead?: string,
): Promise<string | undefined> {
  const pr = request.offendingPr !== undefined ? `PR #${request.offendingPr}` : "an unnamed PR";
  const failing = request.testFiles.join(", ") || request.failingTestTitles.join("; ") || request.failingChecks.join(", ") || "(none named)";
  return openCheckedRepairPr(owner, repo, "main-repair", { branch, base: request.branch, worktreePath, bodyFile, pushedHead,
    prose: `Repairs \`${request.branch}\`, red since \`${request.offendingSha}\` (${pr}) on: ${failing}.`,
    fallbackTitle: `fix(main): repair ${request.offendingSha.slice(0, 12)}` }, log, deps);
}

export function workerHarnessCommit(worker: WorkerResult): CodexHarnessCommit | undefined { // W1-T9667: off the result, not the mount
  return (worker as WorkerResult & { harnessCommit?: CodexHarnessCommit }).harnessCommit;
}

export function repairHarnessOwnsGit(spawn: { provider?: string; tools: readonly string[]; harnessCommit?: CodexHarnessCommit }): boolean { // W1-T9667: both repair lanes
  return spawn.harnessCommit !== undefined || (spawn.provider === "codex" && codexHarnessCommits({ tools: [...spawn.tools] }));
}

async function landHarnessCommit( // W1-T9667: host push + ls-remote; the pushed sha, or undefined after a named row
  lane: "main-repair" | "alert-fix",
  worker: WorkerResult,
  branch: string,
  worktreePath: string,
  log: (step: string, extra?: Record<string, unknown>) => void,
  deps: AlertFixDispatchDeps,
): Promise<string | undefined> {
  const commit = workerHarnessCommit(worker);
  if (commit?.outcome !== "committed") {
    if (commit?.outcome === "nothing-to-commit") log(`${lane}.no_change`, { branch, reason: "the harness found nothing to commit", subtype: worker.subtype });
    else log(`${lane}.harness_commit_refused`, { branch, outcome: commit?.outcome ?? "absent", subtype: worker.subtype, ...(commit?.outcome === "refused" ? { reason: commit.reason } : {}) });
    return undefined;
  }
  try {
    await (deps.pushBranch ?? ((wt: string, sha: string) => gitPushRunBranchAsync(wt, { expectedHeadSha: sha, stdio: "ignore" })))(worktreePath, commit.sha);
  } catch (error) {
    log(`${lane}.push_failed`, { branch, head_sha: commit.sha, error: String((error as Error)?.message ?? error).slice(0, 500) });
    return undefined;
  }
  const remote = await readRepairRemoteHead(worktreePath, branch, deps);
  if (remote.head !== commit.sha) {
    log(`${lane}.push_unconfirmed`, { branch, head_sha: commit.sha, remote_head_sha: remote.head ?? null, ...(remote.error ? { error: remote.error } : {}) });
    return undefined;
  }
  log(`${lane}.pushed`, { branch, head_sha: commit.sha });
  return commit.sha;
}

async function readRepairRemoteHead(worktreePath: string, branch: string, deps: AlertFixDispatchDeps): Promise<{ head?: string; error?: string }> {
  const read = deps.readRemoteBranchHead ?? (async (wt: string, b: string) => (await hostWorktreeGitAsync(wt, ["ls-remote", "origin", `refs/heads/${b}`])).split(/\s/)[0] || undefined);
  return read(worktreePath, branch).then((head) => ({ head }), (error: unknown) => ({ error: String((error as Error)?.message ?? error).slice(0, 500) }));
}

export function withoutRepairPlaceholders(body: string, prose: string): string { // W1-T9667: no placeholder line is ever opened
  return body.split("\n").filter((line) => line !== MAIN_REPAIR_ACCEPTANCE_PLACEHOLDER).map((line) => (line === MAIN_REPAIR_PROSE_PLACEHOLDER ? prose : line)).join("\n");
}

export function alertFixBody(alert: AlertLaneAlert, taskId: string): string { // W1-T9667: the dispatcher's body, `Remudero-Task:` last
  return [MAIN_REPAIR_PROSE_PLACEHOLDER, "", `Acceptance:\n${MAIN_REPAIR_ACCEPTANCE_PLACEHOLDER}`, "", `origin: alert#${alertOriginId(alert)}`, "", `Remudero-Task: ${taskId}`, ""].join("\n");
}

async function openCheckedRepairPr(
  owner: string,
  repo: string,
  lane: "main-repair" | "alert-fix",
  pr: { branch: string; base: string; worktreePath: string; bodyFile: string; pushedHead?: string; prose: string; fallbackTitle: string },
  log: (step: string, extra?: Record<string, unknown>) => void,
  deps: AlertFixDispatchDeps,
): Promise<string | undefined> {
  const { branch, worktreePath } = pr;
  const diffText = (deps.readDiff ?? diffSinceMergeBase)(worktreePath);
  if (diffText === undefined || diffText.trim() === "") {
    log(`${lane}.no_change`, { branch, reason: diffText === undefined ? "diff unreadable" : "the branch adds nothing to origin/main" });
    return undefined;
  }
  const checked = checkMainRepairWorkerBody(readFileSync(pr.bodyFile, "utf8"), diffText);
  if ("defect" in checked) {
    log(`${lane}.acceptance_defect`, {
      defect: checked.defect,
      count: checked.inert.length,
      inert_proofs: checked.inert,
      resolution: checked.resolution,
      ...("reason" in checked ? { reason: checked.reason } : {}),
    });
  }
  if (!("body" in checked)) return undefined;
  if (pr.pushedHead === undefined) {
    const remote = await readRepairRemoteHead(worktreePath, branch, deps);
    if (remote.head === undefined) {
      log(`${lane}.unpushed_head`, { branch, reason: remote.error ?? `refs/heads/${branch} is absent on origin`, ...(remote.error ? { error: remote.error } : {}) });
      return undefined;
    }
  }
  try {
    const title = (deps.readHeadSubject ?? ((wt: string) => hostWorktreeGitAtTopLevel(wt, ["log", "-1", "--format=%s", "HEAD"])))(worktreePath).trim();
    const created = (await (deps.fetch ?? ((args: string[]) => ghJsonAsync(args)))(
      ratifyPrCreateRestArgs(owner, repo, { title: title || pr.fallbackTitle, body: withoutRepairPlaceholders(checked.body, pr.prose), head: branch, base: pr.base }),
    )) as { html_url?: unknown };
    if (typeof created?.html_url !== "string") throw new Error(`GitHub's PR create for ${branch} returned no html_url`);
    return created.html_url;
  } catch (error) {
    log(`${lane}.pr_open_failed`, { branch, error: String((error as Error)?.message ?? error) });
    return undefined;
  }
}

/** W1-T8572 — the revert PR's criteria, executable only: `unit test:` per failing test file the fix request had; with
 *  none, a `grep:` of a line the revert's own diff restores ({@link diffAnchor}); with neither, the dialected
 *  PR-open-time fallback. Never `ci:`, which no reviewer executes. */
export function mainRepairRevertCriteria(
  request: MainRepairRevertRequest,
  evidence: { testFiles?: readonly string[]; revertDiff?: string } = {},
): AcceptanceCriterion[] {
  const sha = request.offendingSha.slice(0, 12);
  const testFiles = evidence.testFiles ?? [];
  if (testFiles.length > 0) return testFiles.map((path) => ({ claim: `${path} passes again with ${sha} reverted`, proof: `unit test: ${path}` }));
  const anchor = diffAnchor(evidence.revertDiff);
  if (anchor.kind === "anchored") return [{ claim: `reverting ${sha} restores its parent's ${anchor.path}`, proof: anchor.proof }];
  return PR_OPEN_TIME_ACCEPTANCE_FALLBACK;
}

/** The revert PR body: the failing check, the fix PR, and why that fix was not enough. */
export function mainRepairRevertBody(request: MainRepairRevertRequest, evidence: { testFiles?: readonly string[]; revertDiff?: string } = {}): string {
  const taskId = mainRepairRevertTaskId(request.offendingSha);
  const pr = request.offendingPr !== undefined ? `#${request.offendingPr}` : "an unnamed PR";
  // W1-T10269: a reviewer regression names its outcome-mix evidence, not failing checks.
  const regression = reviewerRegressionRevertText(request);
  if (regression) return [...regression.lead, "", renderAcceptanceBlock(mainRepairRevertCriteria(request, evidence)), "", `Remudero-Task: ${taskId}`].join("\n");
  return [
    `Reverts \`${request.offendingSha}\` (${pr}), the first red merge on \`${request.branch}\`.`,
    "",
    `\`${request.branch}\` is red at \`${request.headSha}\`; failing check(s): ${request.failingChecks.join(", ") || "(none named)"}.`,
    `The priority fix ${request.fixPrUrl ? `PR ${request.fixPrUrl}` : "run"} was not enough: ${request.whyFixInsufficient}.`,
    "",
    "Opened by the red-main repair lane (W1-T6403) as an ordinary PR: review, CI and branch protection",
    "judge it like any other. It is closed automatically if main turns green on its own head first.",
    "",
    renderAcceptanceBlock(mainRepairRevertCriteria(request, evidence)),
    "",
    `Remudero-Task: ${taskId}`,
  ].join("\n");
}
/**
 * W1-T6403 — ONE revert PR of the offending merge: `git revert --no-edit <sha>` on a fresh branch off
 * origin/main, the branch pushed (never forced, never to main) and the PR opened over REST through
 * `fetch`. A revert that does not apply cleanly is aborted and refused with its conflicting paths.
 * W1-T8572: its body proves the revert with `unit test:` per failing test file the fix request had (`testFiles`)
 * or a `grep:` of a line the revert restores, read from its own diff before the push ({@link mainRepairRevertCriteria}).
 */
export async function openMainRepairRevertPr(
  owner: string,
  repo: string,
  config: Config,
  request: MainRepairRevertRequest,
  ledgerPath: string,
  runId: string,
  fetch: GhApiFetcher = (args) => ghJsonAsync(args),
  testFiles: readonly string[] = [],
): Promise<MainRepairRevertOutcome> {
  const taskId = mainRepairTaskId(request.offendingSha);
  const log = (step: string, extra: Record<string, unknown> = {}) =>
    appendLedger(ledgerPath, { run_id: runId, task_id: taskId, step, lane: "main-repair", ...extra });
  const repoDir = repo === resolveOwnerRepo().repo ? repoRoot : join(config.root, "repos", repo);
  const branch = `run-${mainRepairRevertTaskId(request.offendingSha)}-${systemClock.now()}`;
  const worktreePath = join(worktreesDir(config), branch);
  try {
    await worktreeAddAsync(repoDir, worktreePath, branch, "origin/main", { log });
    try {
      await hostWorktreeGitAsync(worktreePath, ["revert", "--no-edit", request.offendingSha]);
      await hostWorktreeGitAsync(worktreePath, ["commit", "--amend", "--quiet", "--no-edit", "--trailer", `Remudero-Task: ${mainRepairRevertTaskId(request.offendingSha)}`]);
    } catch (error) {
      const conflictPaths = (await hostWorktreeGitAsync(worktreePath, ["diff", "--name-only", "--diff-filter=U"]))
        .split("\n")
        .map((path) => path.trim())
        .filter(Boolean);
      await hostWorktreeGitAsync(worktreePath, ["revert", "--abort"]).catch((abortError: unknown) =>
        log("main-repair.revert_abort_failed", { error: String((abortError as Error)?.message ?? abortError) }),
      );
      return {
        refused: `git revert of ${request.offendingSha} did not apply cleanly on origin/main: ${String((error as Error)?.message ?? error).split("\n")[0]}`,
        conflictPaths,
      };
    }
    const revertDiff = testFiles.length > 0 ? undefined : diffSinceMergeBase(worktreePath);
    const evidence = { testFiles, ...(revertDiff === undefined ? {} : { revertDiff }) };
    const anchor = testFiles.length > 0 ? undefined : diffAnchor(revertDiff);
    if (anchor?.kind === "unavailable") log("main-repair.revert_anchor_unavailable", { offending_sha: request.offendingSha, reason: anchor.reason });
    await gitPushRunBranchAsync(worktreePath, { stdio: "ignore" });
    const subject = request.offendingPr !== undefined ? `revert #${request.offendingPr}` : `revert ${request.offendingSha.slice(0, 12)}`;
    const created = (await fetch(
      ratifyPrCreateRestArgs(owner, repo, {
        title: reviewerRegressionRevertText(request)?.title ?? `revert(main): ${subject}, the first red merge on ${request.branch}`,
        body: mainRepairRevertBody(request, evidence),
        head: branch,
        base: request.branch,
      }),
    )) as { html_url?: unknown };
    if (typeof created?.html_url !== "string") throw new Error(`GitHub's PR create for ${branch} returned no html_url`);
    const prUrl = created.html_url;
    log("main-repair.revert_pr_opened", { pr_url: prUrl, branch, offending_sha: request.offendingSha });
    return { prUrl };
  } finally {
    try {
      await worktreeRemoveAsync(repoDir, worktreePath);
    } catch (error) {
      log("main-repair.worktree_remove_failed", { error: String((error as Error)?.message ?? error) });
    }
  }
}

/** A failing check's whole job log, streamed through {@link mainCeilingLogReducer}; undefined with no job id. */
export async function readMainCeilingVerdictAsync(
  owner: string,
  repo: string,
  check: Pick<RollupCheckEntry, "detailsUrl" | "externalId">,
  lines: typeof ghLinesAsync = ghLinesAsync,
): Promise<MainCeilingLogVerdict | undefined> {
  const jobId = checkJobId(check);
  if (!jobId) return undefined;
  const reducer = mainCeilingLogReducer();
  await lines(["api", `repos/${owner}/${repo}/actions/jobs/${jobId}/logs`], (line) => reducer.push(line));
  return reducer.finish();
}

/** `npm run --silent <script> [-- args]` off the event loop: a ceiling writer measures every tracked file. */
export function runNpmScriptAsync(script: string, cwd: string, args: readonly string[] = []): Promise<{ status: number }> {
  return new Promise((resolve) => {
    const child = spawn("npm", ["run", "--silent", script, ...(args.length > 0 ? ["--", ...args] : [])], { cwd, stdio: "ignore" });
    // A script that could not start is a red script: every caller below reads red as "do not record".
    child.once("error", () => resolve({ status: 1 }));
    child.once("close", (code) => resolve({ status: code ?? 1 }));
  });
}

/** A record PR's head is `run-<its trailer's id>-<epochMs>`: head-identity-gate and worker-branch-shape both admit that. */
export const MAIN_RATCHET_RECORD_BRANCH_PREFIX = "run-main-repair-ratchet-";
export const mainRatchetRecordTaskId = (sha: string): string => `main-repair-ratchet-${sha.slice(0, 12)}`;
const isMainRatchetRecordBranch = (ref: string): boolean => /^(?:run-)?main-repair-ratchet-/.test(ref);

/** How ci.yml's main-ceiling-drift runs each signal on main (`run_main_ceiling_gate`). On a branch cut
 *  from main the bare signal reads main's own crossing as inherited and passes, so only main's form can
 *  say whether main is red, or green again once recorded. A signal with no entry here is never recorded. */
export const MAIN_PUSH_SIGNAL_ARGS: Readonly<Record<string, readonly string[]>> = {
  "comment-load-signal": ["--base", "HEAD^", "--strict"],
};

/** A baseline's numeric rows; undefined for a file that is absent or is not a JSON object. */
function baselineRowsOf(text: string | undefined): Record<string, number> | undefined {
  if (text === undefined) return undefined;
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    // An unparseable baseline records no row, so it can never be read as covering main's ceiling.
    return undefined;
  }
  if (typeof parsed !== "object" || parsed === null) return undefined;
  return Object.fromEntries(Object.entries(parsed).filter((entry): entry is [string, number] => typeof entry[1] === "number"));
}

/**
 * The recorded-baseline PR for a main that is red only on a ratified ceiling. On a fresh branch off
 * origin/main it re-measures main in main's own form first (red at the tip, or it declines), then runs
 * the SAME fenced writer the PR-side repair runs (W1-T4004's registry, so a coverage or mutation floor
 * can never be written) and verifies main's form green. It stands down on an open PR whose baseline
 * already carries every row this record raises -- a hand fix like #10712, or this lane's own earlier PR
 * -- and pushes nothing. Only then does it commit the baseline path alone, with the trailer its branch names
 * (#11831 had neither), push, and open the PR; an older lane PR that no longer covers is closed as superseded.
 */
export async function openMainRatchetRecordPr(
  owner: string,
  repo: string,
  config: Config,
  request: MainRatchetRecordRequest,
  ledgerPath: string,
  runId: string,
  fetch: GhApiFetcher = (args) => ghJsonAsync(args),
  runScript: typeof runNpmScriptAsync = runNpmScriptAsync,
): Promise<MainRatchetRecordOutcome> {
  const unratified = request.scripts.filter((script) => !Object.hasOwn(RATIFIED_BASELINE_RATCHET_REPAIRS, script));
  if (request.scripts.length === 0 || unratified.length > 0) {
    return { declined: `not a ratified baseline writer: ${unratified.join(", ") || "(none named)"}` };
  }
  const log = (step: string, extra: Record<string, unknown> = {}) =>
    appendLedger(ledgerPath, { run_id: runId, task_id: mainRepairTaskId(request.headSha), step, lane: "main-repair", ...extra });
  const repairs = request.scripts.map((script) => ({ script, ...RATIFIED_BASELINE_RATCHET_REPAIRS[script] }));
  const repoDir = repo === resolveOwnerRepo().repo ? repoRoot : join(config.root, "repos", repo);
  const taskId = mainRatchetRecordTaskId(request.headSha);
  const branch = `run-${taskId}-${systemClock.now()}`;
  const wt = join(worktreesDir(config), branch);
  const git = (args: readonly string[]): Promise<string> => hostWorktreeGitAsync(wt, args);
  const readAt = (rev: string, path: string): Promise<string | undefined> =>
    git(["show", `${rev}:${path}`]).then(
      (text) => text,
      () => undefined, // The path is absent at that revision: it records no row.
    );
  await worktreeAddAsync(repoDir, wt, branch, "origin/main", { log });
  try {
    const head = (await git(["rev-parse", "HEAD"])).trim();
    const declared = readPackageScriptsFor(wt);
    for (const { script, signalScript } of repairs) {
      const mainForm = MAIN_PUSH_SIGNAL_ARGS[signalScript];
      if (!mainForm) return { declined: `no main-ceiling-drift form is known for ${signalScript}` };
      if (typeof declared[script] !== "string" || typeof declared[signalScript] !== "string") {
        return { declined: `${script} or ${signalScript} is not declared at ${head}` };
      }
      if ((await runScript(signalScript, wt, mainForm)).status === 0) {
        return { declined: `${signalScript} is green at main's tip ${head}: main no longer crosses that ceiling` };
      }
      if ((await runScript(script, wt)).status !== 0) return { declined: `${script} could not record the ceiling at ${head}` };
      if ((await runScript(signalScript, wt, mainForm)).status !== 0) {
        return { declined: `${signalScript} is still red at ${head} after ${script} recorded` };
      }
    }
    const tracked = (await git(["diff", "--name-only", "HEAD"])).split("\n").filter(Boolean);
    const untracked = (await git(["ls-files", "--others", "--exclude-standard"])).split("\n").filter(Boolean);
    const changed = [...new Set([...tracked, ...untracked])].sort();
    const allowed = new Set<string>(repairs.map((repair) => repair.baselinePath));
    const stray = changed.filter((path) => !allowed.has(path));
    if (stray.length > 0) return { declined: `the writers changed more than their baselines: ${stray.join(", ")}` };
    // Only the rows this record RAISES are the claim; another open PR is redundant with it once it carries them all.
    const raised = new Map<string, Record<string, number>>();
    for (const path of changed) {
      const before = baselineRowsOf(await readAt("HEAD", path)) ?? {};
      const after = baselineRowsOf(readFileSync(join(wt, path), "utf8")) ?? {};
      const up = Object.entries(after).filter(([row, value]) => value > (before[row] ?? Number.NEGATIVE_INFINITY));
      if (up.length > 0) raised.set(path, Object.fromEntries(up));
    }
    if (raised.size === 0) return { declined: `the writers raised no ceiling at ${head}` };

    const listed = (await fetch(["api", `repos/${owner}/${repo}/pulls?state=open&per_page=100`])) as unknown;
    if (!Array.isArray(listed)) throw new Error("GitHub's open pull request list was not a list");
    const open = (listed as Array<{ number?: unknown; html_url?: unknown; head?: { ref?: unknown; sha?: unknown } }>).flatMap((pr) =>
      typeof pr.number === "number" && typeof pr.html_url === "string" && typeof pr.head?.sha === "string"
        ? [{ number: pr.number, url: pr.html_url, ref: String(pr.head.ref ?? ""), sha: pr.head.sha }]
        : [],
    );
    if (open.length > 0) await git(["fetch", "--quiet", "--no-tags", "origin", ...open.map((pr) => `refs/pull/${pr.number}/head`)]);
    const superseded: string[] = [];
    for (const pr of open) {
      if (isMainRatchetRecordBranch(pr.ref) && !pr.ref.startsWith(MAIN_RATCHET_RECORD_BRANCH_PREFIX)) { superseded.push(pr.url); continue; } // pre-run- head (#11831) can never merge
      let covers = true;
      for (const [path, rows] of raised) {
        const theirs = baselineRowsOf(await readAt(pr.sha, path)) ?? {};
        if (Object.entries(rows).some(([row, value]) => (theirs[row] ?? Number.NEGATIVE_INFINITY) < value)) covers = false;
      }
      if (covers) {
        log("main-repair.ratchet_standing", { pr_url: pr.url, head_sha: head });
        return { standing: pr.url };
      }
      if (isMainRatchetRecordBranch(pr.ref)) superseded.push(pr.url);
    }

    const gates = request.gates.join(", ");
    await git(["add", "--", ...changed]);
    await git(["commit", "--quiet", "-m", `chore(ci): record the ceiling main crossed at ${head.slice(0, 12)}`, "-m", `Remudero-Task: ${taskId}`]);
    await gitPushRunBranchAsync(wt, { stdio: "ignore" });
    const proofs = [...raised].flatMap(([path, rows]) =>
      Object.entries(rows).map(([row, value]) => `- main's ceiling for ${row} is recorded at ${value} | grep: "${row}": ${value} in ${path}`),
    );
    const created = (await fetch(
      ratifyPrCreateRestArgs(owner, repo, {
        title: `chore(ci): record the ceiling main crossed on ${gates}`.slice(0, 100),
        body: [
          `\`${request.branch}\` is red at \`${head}\` only because main itself crossed a recorded ceiling: ${gates}`,
          "BLOCKED on main itself, with every test passing. No pull request is wrong; main is.",
          "",
          `Recorded by the ratified writer(s) ${request.scripts.join(", ")} and verified in main's own form;`,
          "nothing else in the tree changed. Opened by the red-main repair lane, which closes it if main turns green without it.",
          "",
          "## Acceptance",
          ...proofs,
          "",
          `Remudero-Task: ${taskId}`,
        ].join("\n"),
        head: branch,
        base: request.branch,
      }),
    )) as { html_url?: unknown };
    if (typeof created?.html_url !== "string") throw new Error(`GitHub's PR create for ${branch} returned no html_url`);
    const prUrl = created.html_url;
    log("main-repair.ratchet_pr_opened", { pr_url: prUrl, branch, head_sha: head, rows: Object.fromEntries(raised) });
    for (const url of superseded) {
      const n = /\/pull\/(\d+)/.exec(url)?.[1];
      await fetch(["api", "--method", "POST", `repos/${owner}/${repo}/issues/${n}/comments`, "-f", `body=Superseded by ${prUrl}, which records main's ceiling at \`${head}\`.`]);
      await fetch(["api", "--method", "PATCH", `repos/${owner}/${repo}/pulls/${n}`, "-f", "state=closed"]);
      log("main-repair.ratchet_pr_superseded", { pr_url: url, by: prUrl });
    }
    return { opened: prUrl };
  } finally {
    try {
      await worktreeRemoveAsync(repoDir, wt);
    } catch (error) {
      log("main-repair.worktree_remove_failed", { error: String((error as Error)?.message ?? error) });
    }
  }
}

/** W1-T6403 — the daemon's {@link MainRepairLane}: the fix worker, the revert PR, and the recorded baseline above. */
export function mainRepairLaneFor(
  owner: string, repo: string, config: Config, ledgerPath: string, runId: string,
  dispatchFix: typeof dispatchMainRepairFixRun = dispatchMainRepairFixRun,
  openRevert: typeof openMainRepairRevertPr = openMainRepairRevertPr,
): MainRepairLane {
  // W1-T8572: the failing test files each fix request carried, so the revert of the same merge proves itself with them.
  const testFilesBySha = new Map<string, readonly string[]>();
  return {
    reproduceAt: async (sha, files) => {
      const repoDir = repo === resolveOwnerRepo().repo ? repoRoot : join(config.root, "repos", repo);
      const log = (step: string, extra: Record<string, unknown> = {}) =>
        appendLedger(ledgerPath, { run_id: runId, task_id: mainRepairTaskId(sha), step, ...extra });
      const outcomes = await buildBaseReproductionProbe(config, repoDir, ledgerPath, log)({ prNumber: 0, headSha: sha } as OpenPrView, files, sha);
      log("sweep.base_reproduction", { main_sha: sha, files: [...outcomes], verdict: decideBaseReproduction(files, outcomes),
        ...(outcomes.setup_error === undefined ? {} : { setup_error: outcomes.setup_error }),
        ...(outcomes.reason === undefined ? {} : { reason: outcomes.reason }) });
      return outcomes;
    },
    openFixPr: (request) => {
      testFilesBySha.set(request.offendingSha, request.testFiles);
      return dispatchFix(owner, repo, config, request, ledgerPath, runId);
    },
    openRevertPr: (request) =>
      openRevert(owner, repo, config, request, ledgerPath, runId, undefined, testFilesBySha.get(request.offendingSha) ?? []),
    recordRatchet: (request) => openMainRatchetRecordPr(owner, repo, config, request, ledgerPath, runId),
  };
}

/**
 * `rmd alert-fix [--repo <name>] [--dry-run]` — the alert-fix lane's real CLI wiring (W1-T90,
 * ratifies P20, MASTER-PLAN.md:686 — §5D lane 2's dep-review precedent, applied to scanners).
 *
 * Fetches every OPEN alert via the SAME `ghAlertGateway()` `rmd ops` already uses (ops.ts,
 * W1-T55), loads `plan/alert-policy.yaml` (data, rule 2 — no LLM ever decides act-vs-escalate),
 * and runs {@link runAlertLane} (src/lib/alert-lane.ts): a policy-matched "act" dispatches ONE
 * ephemeral, lane-owned fix run through the full [ci-gate, remudero-review] gate (never a per-item
 * `plan/tasks.yaml` write — rule 15, the lane owns its run shape exactly like `rmd dep-review`);
 * a critical/high or gate-critical-path alert escalates via the SAME `escalate()`/
 * `buildAlertEscalation` machinery `rmd ops`'s own critical/high poll uses, sharing ONE
 * escalation-ledger dedup namespace so an alert already escalated by `rmd ops` is never
 * escalated again here (and vice versa) — see alert-lane.ts's own module doc.
 *
 * `--dry-run` previews every open alert's disposition; escalates/dispatches NOTHING.
 */
export interface AlertFixCommandDeps {
  config?: Config;
  resolveOwnerRepo?: () => { owner: string; repo: string };
  gateway?: AlertGateway;
  ledgerPath?: string;
  runId?: string;
  escalate?: (alert: AlertLaneAlert) => string | Promise<string>;
  dispatch?: (alert: AlertLaneAlert) => void | Promise<void>;
}

export async function alertFixCommand(rest: string[], deps: AlertFixCommandDeps = {}): Promise<number> {
  const badArg = unknownArgError("alert-fix", rest, ["--repo"], ["--dry-run"]);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const dryRun = rest.includes("--dry-run");
  const config = deps.config ?? loadConfig();
  const ledgerPath = deps.ledgerPath ?? ledgerPathFor(config);
  const self = deps.resolveOwnerRepo ? deps.resolveOwnerRepo() : resolveOwnerRepo();
  const repo = flagValue(rest, "--repo") ?? self.repo;
  const owner = self.owner;
  const runId = deps.runId ?? `ALERT-FIX-${Date.now()}`;

  const policy = loadAlertPolicy(join(repoRoot, "plan", "alert-policy.yaml"));
  const gateway = deps.gateway ?? ghAlertGateway();
  const open: AlertLaneAlert[] = [
    ...gateway.codeScanning(owner, repo),
    ...gateway.dependabot(owner, repo),
    ...gateway.secretScanning(owner, repo),
  ].filter((a) => a.state === "open");

  if (dryRun) {
    const previews = open.map((a) => `  ${a.source}#${a.id} [${a.severity}] -> ${decideAlertDisposition(a, policy)}`);
    console.log(
      `### rmd alert-fix --dry-run — ${owner}/${repo}\n` + (previews.length ? previews.join("\n") : "no open alerts"),
    );
    return 0;
  }

  const result = await runAlertLane(open, policy, {
    ledgerPath,
    runId,
    escalate:
      deps.escalate ??
      ((alert) => escalate(buildAlertEscalation(alert), { issues: ghIssueGateway(owner, repo), ledgerPath, runId })),
    dispatch: deps.dispatch ?? (async (alert) => dispatchAlertFixRun(owner, repo, config, alert, ledgerPath, runId)),
  });

  console.log(
    `### rmd alert-fix — ${owner}/${repo}\n` +
      `dispatched ${result.dispatched.length} · escalated ${result.escalated.length} · ` +
      `skipped(dup-dispatch) ${result.skippedDuplicateDispatch.length} · skipped(dup-escalate) ${result.skippedDuplicateEscalate.length}`,
  );
  return 0;
}

export function feedbackIntakeAdmission(config: Pick<Config, "contributorAdmission">, ledgerPath: string, runId: string): FeedbackAdmissionContext | undefined {
  return config.contributorAdmission === undefined ? undefined : { ...config.contributorAdmission,
    record: (step, fields) => appendLedger(ledgerPath, { run_id: runId, task_id: "ISSUES", step, ...fields }) };
}

/**
 * `rmd issues [--dry-run]` — issues intake (W1-T57, MASTER-PLAN §5D lane 3): poll open issues
 * for every repo in `.remudero/managed-repos.json` via `gh api` (lib/issues-intake.ts), create a
 * `plan/feedback/<id>.yaml` entry (origin: `issue#<n>`) for each one not already captured, and
 * fold an issues-reviewed count into the next `rmd digest`. Dedup is id-keyed (a deterministic
 * `fb-issue-<owner>-<repo>-<n>` id) — a re-poll of the SAME open issues creates nothing new.
 * --dry-run previews the reviewed count + which issues WOULD create a new entry; it creates none
 * and writes no ledger line. An empty/missing managed-repos.json is a safe no-op, not an error.
 */
async function issuesCommand(rest: string[]): Promise<number> {
  const badArg = unknownArgError("issues", rest, [], ["--dry-run"]);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const dryRun = rest.includes("--dry-run");
  let managed;
  try {
    managed = loadManagedRepos(repoRoot);
  } catch (err) {
    if (err instanceof ManagedReposError) {
      console.error(`rmd issues: ${err.message}`);
      return 1;
    }
    throw err;
  }
  const config = loadConfig();
  const ledgerPath = ledgerPathFor(config);
  const runId = `ISSUES-${Date.now()}`;
  const result = await pollIssues(managed, {
    issues: ghIssueListGateway(),
    root: repoRoot,
    ledgerPath,
    runId,
    dryRun,
    admission: feedbackIntakeAdmission(config, ledgerPath, runId),
    capture: captureFeedback,
  });
  console.log(`### rmd issues${dryRun ? " --dry-run" : ""}\nissues reviewed: ${renderIssuesSummary(result.summary)}`);
  if (dryRun) {
    console.log(
      result.newIssues.length
        ? `would create ${result.newIssues.length} new feedback entr${result.newIssues.length === 1 ? "y" : "ies"}: ${result.newIssues
            .map((i) => `${i.owner}/${i.repo}#${i.number}`)
            .join(", ")}`
        : "no new issues to capture",
    );
  } else if (result.created.length > 0) {
    console.log(`created ${result.created.length} new feedback entr${result.created.length === 1 ? "y" : "ies"}:`);
    for (const e of result.created) console.log(`  ${e.origin} -> plan/feedback/${e.id}.yaml`);
  } else {
    console.log("no new issues to capture");
  }
  return 0;
}

/**
 * Interactive `--tier` confirm prompt (readline/promises). ONLY ever wired up
 * (and only ever called) when `process.stdin.isTTY` is true — a headless run
 * never reaches this function (Standing rule 18 / init.ts). Blank input accepts
 * the suggested tier; anything else is re-parsed as a `--tier` value.
 */
async function promptForTier(suggested: Tier, detection: TierDetection): Promise<Tier> {
  const { createInterface } = await import("node:readline/promises");
  const rl = createInterface({ input: process.stdin, output: process.stdout });
  try {
    console.log(`\n### [init] ${detection.detail}`);
    for (;;) {
      const answer = (
        await rl.question(`Confirm Claude Code tier [pro/max5x/max20x] (default "${suggested}"): `)
      ).trim();
      if (!answer) return suggested;
      const t = answer.toLowerCase();
      if (t === "pro" || t === "max5x" || t === "max20x") return t;
      console.log(`  not a known tier: "${answer}" — try again.`);
    }
  } finally {
    rl.close();
  }
}

/**
 * `rmd init [--tier <pro|max5x|max20x>] [--yes]` — headless-safe first-run tier
 * wizard (lib/init.ts, W1-T9c). Resolution order: an explicit `--tier` override
 * (never prompts) → confident `~/.claude.json`/`/usage` evidence (never prompts)
 * → an interactive confirm (ONLY when a real TTY is present and neither of the
 * above resolved it) → a logged TTY-absent safe default. NEVER blocks on an
 * operator that may not exist (Standing rule 18 / LEARNINGS.md
 * no-live-operator-in-headless-worker — the failure mode that killed W1-T9).
 */
async function initCommand(rest: string[]): Promise<number> {
  const tierFlag = flagValue(rest, "--tier");
  const yes = rest.includes("--yes");
  const isTTY = Boolean(process.stdin.isTTY);

  const claudeJson = readClaudeJsonKeys(join(homedir(), ".claude.json"));
  // Best-effort `/usage` capture (rung 3): needs a resolved claudeBin, which may
  // not exist yet on a genuinely first run. Unavailable ⇒ detection just degrades
  // a rung (same contract as readUsageSnapshot itself) — init.ts never requires it.
  let usage: UsageSnapshot | undefined;
  try {
    usage = readUsageSnapshot(loadConfig());
  } catch {
    usage = undefined;
  }

  try {
    const result = await runInit({
      tierFlag,
      yes,
      isTTY,
      configPath: instanceConfigPath(),
      claudeJson,
      usage,
      confirm: isTTY ? promptForTier : undefined,
      log: (line) => console.log(`### [init] ${line}`),
    });
    console.log(`\nrmd init done — tier=${result.tier} source=${result.source} → ${result.configPath}`);
    return 0;
  } catch (e) {
    if (e instanceof InitError) {
      console.error(`### rmd init: ${e.message}`);
      return 2;
    }
    throw e;
  }
}

/**
 * `rmd project init <repo> [--profile ts-node|ts-web|python|dotnet] --coverage-pct <n>
 * --branches-pct <n> --mutation-pct <n> --dup-pct <n>` — the fleet-inheritance onboarding
 * primitive (MASTER-PLAN §5A, W1-T27). A thin wrapper over the pure generator
 * {@link buildProjectInit} (lib/project-init.ts, independently unit-tested over fixtures — no
 * live repo needed for that proof): all argument validation happens in
 * {@link parseProjectInitArgs} BEFORE any work runs (fail loud, spawn nothing — Standing rule /
 * LEARNINGS.md control-surface-fail-loud-stop-one-shot), and this command never defaults an
 * unmeasured baseline to zero (§5A: "a repo never onboards at zero").
 *
 * DELIBERATELY MANUAL PAST GENERATION: this command prints the generated file list and the
 * branch-protection PATCH payload rather than pushing a branch / opening a PR / calling
 * `gh api` against the target repo itself. Automating that mutation against an ARBITRARY
 * external repo (auth, default-branch detection, PR conflicts, etc.) is out of this task's
 * scope — the note on W1-T27 calls the live end-to-end provisioning a separate
 * operator-attested confirmation (Rule 18), not part of auto-verify. Keeping the live-mutation
 * path manual also keeps this command trivially safe to run against any repo name.
 */
async function projectCommand(rest: string[]): Promise<number> {
  const sub = rest[0];
  if (sub !== "init") {
    console.error(`rmd project: unknown subcommand '${sub ?? ""}' — usage: ${commandSyntax("project")}\n` + USAGE);
    return 2;
  }

  const parsed = parseProjectInitArgs(rest.slice(1));
  if (!parsed.ok) {
    console.error(parsed.error + "\n" + USAGE);
    return 2;
  }

  const { owner: selfOwner } = resolveOwnerRepo();
  const owner = parsed.args.owner ?? selfOwner;
  const payload = buildProjectInit({
    owner,
    repo: parsed.args.repo,
    profile: parsed.args.profile,
    baselines: parsed.args.baselines,
  });

  console.log(`### rmd project init — generated gate stack for ${owner}/${parsed.args.repo} (profile: ${parsed.args.profile})`);
  console.log(`workflows: ${Object.keys(payload.workflows).map((f) => `.github/workflows/${f}`).join(", ")}`);
  console.log(
    `configs: .remudero/principles.yaml, ${Object.keys(payload.configs).join(", ")}`,
  );
  console.log(
    `baselines captured: coverage=${payload.baselines.coveragePct}% branches=${payload.baselines.branchesPct}% ` +
      `mutation=${payload.baselines.mutationScorePct}% dup=${payload.baselines.dupPct}% (at ${payload.baselines.capturedAt})`,
  );
  console.log(
    "\nThis command GENERATES the stack; it does not push/open a PR or arm branch protection " +
      "itself (manual next steps):",
  );
  console.log(
    `  1. Write the files listed above into a branch of ${owner}/${parsed.args.repo} and open a PR gated by ci-gate + remudero-review.`,
  );
  console.log(`  2. Once that PR is merged, arm branch protection:`);
  console.log(
    `     gh api -X PUT repos/${owner}/${parsed.args.repo}/branches/main/protection --input - <<'JSON'\n` +
      JSON.stringify(payload.branchProtection, null, 2) +
      `\nJSON`,
  );
  return 0;
}

/**
 * `rmd onboard <target-dir> --phase inventory [--owner <o> --repo <r>]` — phase 1 of the
 * four-phase `rmd onboard` family (MASTER-PLAN ★P24(1), W1-T82): a DETERMINISTIC, NO-LLM
 * repo inventory over a TARGET checkout — languages, build/CI systems, docs presence,
 * branch-protection state, issue/milestone counts, test-signal presence — via policy-as-data
 * detector tables (src/lib/onboard/inventory.ts) plus `gh api` reads. Read-only against the
 * target checkout + GitHub; the ONLY write is `<target-dir>/plan/onboarding/inventory.json`.
 * GitHub facts this command could not resolve (auth/network failure) render as the literal
 * `"unknown"` — never guessed or silently defaulted. `--phase` is REQUIRED; `inventory`
 * (this function's own body), `recon` ({@link reconCommand}), and `session`
 * ({@link sessionCommand}) — both routed to BELOW before inventory.ts's own parser ever
 * runs — its `KNOWN_ONBOARD_PHASES` stays `["inventory"]` exactly as W1-T82 shipped it — are
 * implemented; synthesis is W1-T85, a separate future task not built here; any other
 * `--phase` value fails loud (usage + non-zero exit,
 * zero work done) before any fs/gh call, the same `parseProjectInitArgs`-style
 * validate-first discipline `rmd project init` already applies (Standing rule / LEARNINGS.md
 * control-surface-fail-loud-stop-one-shot). `--owner`/`--repo` override auto-detection;
 * omitted, they are derived from the target checkout's own `git remote.origin.url`
 * ({@link resolveTargetOwnerRepo}) — unresolved leaves every GitHub fact `"unknown"` rather
 * than guessing an owner/repo to query.
 */
interface OnboardCommandDeps {
  fs?: OnboardFsDeps;
  gh?: OnboardGhGateway;
  /** W1-T9700: the real one is awaited; a fake may answer synchronously. */
  resolveOwnerRepo?: (targetDir: string) => Awaited<ReturnType<typeof resolveTargetOwnerRepo>> | ReturnType<typeof resolveTargetOwnerRepo>;
}

export async function onboardCommand(rest: string[], deps: OnboardCommandDeps = {}): Promise<number> {
  // `--phase recon`/`--phase session` route to THEIR OWN parser/runner (src/lib/onboard/
  // recon.ts, src/lib/onboard/session.ts) BEFORE inventory.ts's parseOnboardArgs ever sees
  // it — inventory.ts's own KNOWN_ONBOARD_PHASES (and its committed W1-T82 test asserting
  // "recon" is unknown to THAT parser) stays exactly as shipped; only this command-level
  // routing is new.
  if (flagValue(rest, "--phase") === RECON_PHASE) {
    return reconCommand(rest);
  }
  if (flagValue(rest, "--phase") === SESSION_PHASE) {
    return sessionCommand(rest);
  }
  if (flagValue(rest, "--phase") === SYNTHESIZE_PHASE) {
    return synthesizeCommand(rest);
  }

  const { fs: fsDep, gh: ghDep, resolveOwnerRepo } = {
    fs: realDeps().onboard.fs,
    gh: realDeps().onboard.gh,
    resolveOwnerRepo: realDeps().onboard.resolveOwnerRepo,
    ...deps,
  };
  const parsed = parseOnboardArgs(rest);
  if (!parsed.ok) {
    console.error(parsed.error + "\n" + USAGE);
    return 2;
  }
  const { targetDir, owner: ownerFlag, repo: repoFlag } = parsed.args;

  const resolved = ownerFlag && repoFlag ? undefined : await resolveOwnerRepo(targetDir);
  const owner = ownerFlag ?? resolved?.owner;
  const repo = repoFlag ?? resolved?.repo;

  let inventory, writtenPath;
  try {
    ({ inventory, writtenPath } = runOnboardInventory(targetDir, { owner, repo }, { fs: fsDep, gh: ghDep }));
  } catch (e) {
    if (e instanceof OnboardError) {
      console.error(e.message);
      return 2;
    }
    throw e;
  }

  console.log(`### rmd onboard ${targetDir} --phase inventory`);
  console.log(`target: ${inventory.target.owner}/${inventory.target.repo}`);
  console.log(`languages: ${inventory.languages.join(", ") || "(none detected)"}`);
  console.log(`build systems: ${inventory.buildSystems.join(", ") || "(none detected)"}`);
  console.log(`CI systems: ${inventory.ciSystems.join(", ") || "(none detected)"}`);
  console.log(`docs: ${Object.entries(inventory.docs).map(([k, v]) => `${k}=${v}`).join(", ")}`);
  console.log(`test signals: ${inventory.testSignals.join(", ") || "(none detected)"}`);
  console.log(
    `github: exists=${inventory.github.repoExists} defaultBranch=${inventory.github.defaultBranch} ` +
      `branchProtected=${inventory.github.branchProtected} openIssues=${inventory.github.openIssueCount} ` +
      `milestones=${inventory.github.milestoneCount}`,
  );
  console.log(`\nwrote ${writtenPath}`);
  return 0;
}

/**
 * `rmd onboard <target-dir> --phase recon [--owner <o> --repo <r>]` — phase 2 of the
 * four-phase `rmd onboard` family (MASTER-PLAN ★P24(2), W1-T83): mines existing plan
 * artifacts (ROADMAP/TODO/ADR intents/open issues) deterministically AND consults all four
 * W2-T1 specialist lenses (security/testing/design/containment — src/lib/specialist-panel.ts),
 * read-only, pointed at the WHOLE target repo instead of a diff (src/lib/onboard/recon.ts).
 * Writes ONLY `plan/onboarding/findings.md` + `plan/onboarding/candidates.json`; every
 * candidate cites its source verbatim, and mined vs inferred stays a labeled distinction end
 * to end. Candidates are inputs to the phase 3 planning session, never dispatchable tasks
 * (Standing rule 15). `onboardCommand` above routes `--phase recon` HERE before inventory.ts's
 * own parser ever runs.
 *
 * The default real `runLens` renders the SAME worker-settings template + hooks every task
 * worker uses (`renderWorkerSettings`/`validateWorkerSettingsFile`, FF10a) and runs the SAME
 * once-per-run containment preflight (`probeContainment`, containment.ts, W1-T2) before the
 * first lens spawn — proven empirically, not merely configured, exactly like every other real
 * spawn in this repo. A lens that fails to spawn, times out, or errors contributes ZERO
 * inferred candidates (logged, advisory only — Standing rule 12) rather than aborting the
 * whole recon: the deterministic miner's candidates must never be held hostage to one flaky
 * LLM call.
 */
interface ReconCommandDeps {
  fs?: ReconFsDeps;
  gh?: ReconGhGateway;
  /** W1-T9700: the real one is awaited; a fake may answer synchronously. */
  resolveOwnerRepo?: (targetDir: string) => Awaited<ReturnType<typeof resolveTargetOwnerRepo>> | ReturnType<typeof resolveTargetOwnerRepo>;
  /** Injectable per-lens raw-text runner — tests supply canned text; omitted, the real
   *  spawn-backed default below is used. */
  runLens?: (specialist: SpecialistName) => Promise<string>;
}

/** A deliberately modest, fixed mount for the recon lenses — there is no mounts.yaml row for
 *  an ad hoc whole-repo recon read (that table routes DRAINED plan tasks, W1-T83 is a
 *  one-off CLI spawn), so this is a conservative, explicit default rather than a borrowed
 *  task-routing cell. */
const RECON_LENS_MOUNT: Mount = { model: "sonnet", effort: "medium", maxTurns: 30, contextBudget: 150_000 };

/** The real, spawn-backed `runLens`: settings are rendered and containment is
 *  probed ONCE (lazily, on the first lens) and reused for the remaining three — the
 *  invariant containment.ts documents is per-RUN, not per-spawn.
 *
 *  `deps` is injectable — the SAME `opts.spawn ?? spawnWorker` / `opts.config ?? loadConfig()`
 *  shape `runTask` above already uses, so a unit test can drive both the happy path and the
 *  advisory-only catch path with a fake `spawn`/`probeExec`, never touching `loadConfig()`
 *  (which shells `which claude` — unavailable in CI, containment.ts's own documented gotcha)
 *  or a real Agent SDK spawn. Every field defaults to the real implementation, so the
 *  production call site below (no `deps` passed) is unchanged. */
export function defaultReconRunLens(
  targetDir: string,
  owner: string | undefined,
  repo: string | undefined,
  deps: {
    config?: Config;
    spawn?: typeof spawnReconSpecialist;
    probeExec?: ProbeExecutor;
  } = {},
): (specialist: SpecialistName) => Promise<string> {
  const config = deps.config ?? loadConfig();
  const spawn = deps.spawn ?? spawnReconSpecialist;
  let preparedSettingsFile: string | undefined;
  return async (specialist) => {
    try {
      if (!preparedSettingsFile) {
        const settingsFile = renderWorkerSettings({
          templatePath: join(resolveInstallRoot(config), "settings", "worker.json"),
          hooksDir: join(resolveInstallRoot(config), "hooks"),
          outPath: join(config.root, "tmp", `onboard-recon-settings-${Date.now()}.json`),
        });
        validateWorkerSettingsFile(settingsFile);
        await probeContainment({ settingsFile, config, exec: deps.probeExec });
        preparedSettingsFile = settingsFile;
      }
      const result = await spawn({
        input: { specialist, targetDir, owner, repo },
        mount: RECON_LENS_MOUNT,
        settingsFile: preparedSettingsFile,
      });
      return result.text;
    } catch (e) {
      console.error(`rmd onboard recon: ${specialist} lens unavailable (advisory only, continuing): ${String((e as Error)?.message ?? e)}`);
      return "";
    }
  };
}

export async function reconCommand(rest: string[], deps: ReconCommandDeps = {}): Promise<number> {
  const parsed = parseReconArgs(rest);
  if (!parsed.ok) {
    console.error(parsed.error + "\n" + USAGE);
    return 2;
  }
  const { targetDir, owner: ownerFlag, repo: repoFlag } = parsed.args;

  const { fs: fsDep, gh: ghDep, resolveOwnerRepo } = {
    fs: realDeps().recon.fs,
    gh: realDeps().recon.gh,
    resolveOwnerRepo: realDeps().onboard.resolveOwnerRepo,
    ...deps,
  };

  const resolved = ownerFlag && repoFlag ? undefined : await resolveOwnerRepo(targetDir);
  const owner = ownerFlag ?? resolved?.owner;
  const repo = repoFlag ?? resolved?.repo;

  const runLens = deps.runLens ?? defaultReconRunLens(targetDir, owner, repo);

  let candidates, findingsPath, candidatesPath;
  try {
    ({ candidates, findingsPath, candidatesPath } = await runOnboardRecon(targetDir, { owner, repo }, { fs: fsDep, gh: ghDep, runLens }));
  } catch (e) {
    if (e instanceof ReconError) {
      console.error(e.message);
      return 2;
    }
    throw e;
  }

  const minedCount = candidates.filter((c) => c.confidence === "mined").length;
  const inferredCount = candidates.filter((c) => c.confidence === "inferred").length;
  console.log(`### rmd onboard ${targetDir} --phase recon`);
  console.log(`target: ${owner ?? "unknown"}/${repo ?? "unknown"}`);
  console.log(`lenses consulted: ${RECON_LENSES.join(", ")}`);
  console.log(`candidates: ${candidates.length} (${minedCount} mined, ${inferredCount} inferred)`);
  console.log(`wrote ${findingsPath}`);
  console.log(`wrote ${candidatesPath}`);
  return 0;
}

/**
 * `rmd onboard <target-dir> --phase session` — phase 3 of the four-phase `rmd onboard`
 * family (MASTER-PLAN ★P24(3)+(4), W1-T84): renders the phase-1/2 findings location plus a
 * §2-contract question set (src/lib/onboard/session.ts) and drives the answer loop.
 * `onboardCommand` above routes `--phase session` HERE before inventory.ts's own parser
 * ever runs.
 *
 * NO-TTY NEVER BLOCKS (Standing rule 18 / LEARNINGS.md no-live-operator-in-headless-worker):
 * a headless invocation (no real TTY on stdin — e.g. a drained worker shelling this out)
 * never reaches `readline`; it prints the unanswered backlog and returns immediately,
 * exactly as {@link loadOnboardSessionState} left it, so a second, INTERACTIVE invocation
 * later re-presents that same backlog (resumability, acceptance criterion 3) rather than
 * this command ever hanging on an operator that may not be there.
 */
interface SessionCommandDeps {
  fs?: SessionFsDeps;
  isTTY?: boolean;
  ask?: (question: OnboardQuestion) => Promise<string>;
}

/** Render one question the same way for both the no-TTY preview and the interactive
 *  readline prompt — decision, question text, and its named candidate answers. */
function renderQuestionPrompt(question: OnboardQuestion): string {
  const options = question.candidateAnswers.map((a, i) => `    ${i + 1}. ${a}`).join("\n");
  return (
    `  [${question.id}] decides: ${question.decision}\n` +
    `  ${question.question}\n${options}\n` +
    `  (answer with a number above, or type your own answer; blank leaves it unanswered)`
  );
}

/** The real, readline-backed `ask` — ONLY ever constructed when `process.stdin.isTTY` is
 *  true (mirrors `promptForTier`'s own TTY-gated shape). A numeric reply matching a listed
 *  candidate answer is resolved to that answer's own text; anything else is accepted
 *  verbatim as a free-text answer. */
export async function readlineAsk(
  question: OnboardQuestion,
  io: { input: NodeJS.ReadableStream; output: NodeJS.WritableStream } = { input: process.stdin, output: process.stdout },
): Promise<string> {
  const { createInterface } = await import("node:readline/promises");
  const rl = createInterface({ input: io.input, output: io.output });
  try {
    console.log(`\n${renderQuestionPrompt(question)}`);
    const raw = (await rl.question("> ")).trim();
    const asIndex = Number(raw);
    if (Number.isInteger(asIndex) && asIndex >= 1 && asIndex <= question.candidateAnswers.length) {
      return question.candidateAnswers[asIndex - 1]!;
    }
    return raw;
  } finally {
    rl.close();
  }
}

export async function sessionCommand(rest: string[], deps: SessionCommandDeps = {}): Promise<number> {
  const parsed = parseSessionArgs(rest);
  if (!parsed.ok) {
    console.error(parsed.error + "\n" + USAGE);
    return 2;
  }
  const { targetDir } = parsed.args;
  const fsDep = deps.fs ?? realDeps().session.fs;
  const isTTY = deps.isTTY ?? Boolean(process.stdin.isTTY);

  console.log(`### rmd onboard ${targetDir} --phase session`);

  if (!isTTY) {
    // Never block on an operator that may not exist — preview the backlog and return.
    let state;
    try {
      state = loadOnboardSessionState(targetDir, fsDep);
    } catch (e) {
      if (e instanceof SessionError) {
        console.error(e.message);
        return 2;
      }
      throw e;
    }
    console.log(`no TTY on stdin — previewing the question backlog without asking (run interactively to answer):`);
    console.log(`questions: ${state.questions.length} total, ${state.unanswered.length} unanswered`);
    for (const q of state.unanswered) console.log(`\n${renderQuestionPrompt(q)}`);
    return 0;
  }

  const ask = deps.ask ?? readlineAsk;
  let result;
  try {
    result = await runOnboardSession(targetDir, { fs: fsDep, ask });
  } catch (e) {
    if (e instanceof SessionError) {
      console.error(e.message);
      return 2;
    }
    throw e;
  }

  console.log(`questions: ${result.questions.length} total, ${result.newlyAnswered.length} answered this session, ${result.unanswered.length} still unanswered`);
  console.log(`wrote ${result.answersPath}`);
  if (result.newlyAnswered.length > 0) console.log(`wrote ${result.ledgerPath}`);
  return 0;
}

/**
 * `rmd onboard <target-dir> --phase synthesize` — phase 4 (and last) of the four-phase
 * `rmd onboard` family (MASTER-PLAN ★P24(5)+(6), W1-T85): drafts `MASTER-PLAN.md`,
 * `plan/tasks.yaml`, and `AGENTS.md` for the TARGET repo as ONE ratifiable draft PR
 * (src/lib/onboard/synthesize.ts). REFUSES loud (non-zero exit, naming every unanswered
 * question id) unless the phase-3 session's FULL question set is answered — goals are
 * never guessed. The drafted `tasks.yaml` is iterated against the REAL `rmd lint-plan`
 * linter until clean BEFORE a branch/PR is ever opened; opens EXACTLY ONE draft PR
 * (`onboard/<repo>-plan`), writing nothing outside that branch. `onboardCommand` above
 * routes `--phase synthesize` HERE before inventory.ts's own parser ever runs.
 *
 * Composition: `rmd onboard` (this whole family) produces the BRAIN; `rmd project init`
 * (W1-T27) installs the BAR; the daemon drains.
 */
interface SynthesizeCommandDeps {
  fs?: SynthesizeFsDeps;
  git?: SynthesizeGitGateway;
  gh?: SynthesizeGhGateway;
  draft?: SynthesizeDraftFn;
}

/** A deliberately generous, fixed mount for the synthesis Architect worker — like
 *  RECON_LENS_MOUNT, there is no mounts.yaml row for an ad hoc onboarding draft (a one-off
 *  CLI spawn, not a drained plan task); higher effort/turns than recon's read-only lenses
 *  because this worker actually PRODUCES the three documents, not just flags findings. */
const SYNTHESIZE_MOUNT: Mount = { model: "sonnet", effort: "high", maxTurns: 45, contextBudget: 200_000 };

function buildSynthesizeMasterPlanPrompt(input: Parameters<SynthesizeDraftFn>[0]): string {
  return [
    `You are the ARCHITECT worker for \`rmd onboard ${input.targetDir} --phase synthesize\` (MASTER-PLAN`,
    `★P24(5), W1-T85), drafting a ratifiable onboarding PR for ${input.owner}/${input.repo}. You are`,
    `READ-ONLY: inspect this checkout, but never edit/write any file yourself — your ENTIRE job is to`,
    `return ONE document (raw Markdown, no wrapping fences) as your final response text; the harness`,
    `(never you) writes it to disk on a fresh branch.`,
    ``,
    `Write this target repo's MASTER-PLAN.md: its mission (in one or two sentences) and its CONVENTIONS`,
    `AS FOUND (languages/build/CI/test conventions already present — never invented). Ground every claim`,
    `in the phase 1-3 onboarding artifacts below; never guess a goal the operator did not ratify.`,
    ``,
    `INVENTORY (phase 1, deterministic): ${JSON.stringify(input.inventory)}`,
    `FINDINGS (phase 2, mined + specialist-inferred): ${input.findings || "(none)"}`,
    `RATIFIED ANSWERS (phase 3, the operator's own words): ${JSON.stringify(input.answers)}`,
  ].join("\n");
}

/** EXPORTED for W1-T512's contract test: the other four drafting prompts are exported and their
 *  field lists are asserted by DRIVING them, and asserting this one from source text instead
 *  would be the weaker check on the one lane whose worker is furthest from the plan. */
export function buildSynthesizeTasksYamlPrompt(input: Parameters<SynthesizeDraftFn>[0], feedback: string[] | undefined): string {
  const feedbackBlock =
    feedback && feedback.length > 0
      ? [
          ``,
          `YOUR PREVIOUS DRAFT FAILED \`rmd lint-plan\` (§5C Layer A) with these BLOCKING violations — fix`,
          `every one of them in this redraft:`,
          ...feedback.map((f) => `  - ${f}`),
        ].join("\n")
      : "";
  return [
    `You are the ARCHITECT worker for \`rmd onboard ${input.targetDir} --phase synthesize\` (MASTER-PLAN`,
    `★P24(5)+(6), W1-T85), drafting a ratifiable onboarding PR for ${input.owner}/${input.repo}. You are`,
    `READ-ONLY: inspect this checkout, but never edit/write any file yourself — your ENTIRE job is to`,
    `return ONE document (a raw YAML list, no wrapping fences) as your final response text.`,
    ``,
    `Draft a CHANGE-LEVEL plan/tasks.yaml SEED (progressive adoption — NEVER a big-bang respec) from the`,
    `ratified goals below. Every task you emit MUST pass \`rmd lint-plan\` (§5C Layer A) AT BIRTH:`,
    `  - every task needs id/title/repo/type/acceptance/files, and an origin: field citing the SPECIFIC answer`,
    `  - files: is the repo-relative paths the task will touch. NEVER omit it and never leave it empty:`,
    `    an undeclared scope is fail-closed at dispatch (overlappingPaths reports it as overlapping`,
    `    every co-dispatched candidate), so the task can never batch and serialises the lane.`,
    `    id or candidate source that justified it (e.g. origin: "onboard:<answer-id>") — never omitted,`,
    `    never a generic "architect".`,
    `  - every acceptance criterion's proof: must be EXECUTABLE dialect — "unit test: <literal test`,
    `    title>" or "grep: <pattern> in <path>" — never free prose, never a vibe phrase ("works"/"correct").`,
    `  - an auto-verify task's criteria must never require a live human/TTY/overnight action (no`,
    `    "operator confirms", "reboot", "launchctl", etc.) — use verify: human for anything that does.`,
    `  - a task spanning ≥2 distinct subsystems must be risk: high or split into one task per concern.`,
    feedbackBlock,
    ``,
    `INVENTORY (phase 1): ${JSON.stringify(input.inventory)}`,
    `CANDIDATES (phase 2, ${input.candidates.length} mined/inferred goals): ${JSON.stringify(input.candidates)}`,
    `RATIFIED ANSWERS (phase 3, the operator's own words — goals are NEVER guessed beyond these):`,
    `  ${JSON.stringify(input.answers)}`,
  ].join("\n");
}

function buildSynthesizeAgentsMdPrompt(input: Parameters<SynthesizeDraftFn>[0]): string {
  return [
    `You are the ARCHITECT worker for \`rmd onboard ${input.targetDir} --phase synthesize\` (MASTER-PLAN`,
    `★P24(6), W1-T85), drafting a ratifiable onboarding PR for ${input.owner}/${input.repo}. You are`,
    `READ-ONLY: inspect this checkout, but never edit/write any file yourself — your ENTIRE job is to`,
    `return ONE document (raw Markdown, no wrapping fences) as your final response text.`,
    ``,
    `Write this target repo's AGENTS.md — the cross-tool convention doc (so any coding agent, not just`,
    `this one, respects the same constitution this PR proposes): conventions AS FOUND (build/test/lint`,
    `commands actually present in this checkout), plus the no-touch zones and verify:human boundaries`,
    `named in the ratified answers below. Never invent a convention this checkout does not evidence.`,
    ``,
    `INVENTORY (phase 1): ${JSON.stringify(input.inventory)}`,
    `RATIFIED ANSWERS (phase 3): ${JSON.stringify(input.answers)}`,
  ].join("\n");
}

/** The real, spawn-backed `draft` fn `synthesizeCommand` falls back to when no `deps.draft`
 *  is injected — NOT unit tested directly (mirrors `defaultReconRunLens`): settings are
 *  rendered and containment probed ONCE (lazily, on the first call) and reused across every
 *  attempt of the iterate-until-clean loop. Three independent, read-only spawns per attempt
 *  (one per document) — simple, deterministic to parse (each worker's `.text` IS the
 *  document, no fenced-block parsing needed), and a redraft only needs to re-spawn all
 *  three, never a partial/patchy edit. */
export function defaultSynthesizeDraft(
  deps: { config?: Config; spawn?: typeof spawnWorker; probeExec?: ProbeExecutor } = {},
): SynthesizeDraftFn {
  const config = deps.config ?? loadConfig();
  const spawn = deps.spawn ?? ledgeredNonDispatchSpawn("onboard-synthesis");
  let preparedSettingsFile: string | undefined;

  const ensureSettingsFile = async (): Promise<string> => {
    if (!preparedSettingsFile) {
      const settingsFile = renderWorkerSettings({
        templatePath: join(resolveInstallRoot(config), "settings", "worker.json"),
        hooksDir: join(resolveInstallRoot(config), "hooks"),
        outPath: join(config.root, "tmp", `onboard-synthesize-settings-${Date.now()}.json`),
      });
      validateWorkerSettingsFile(settingsFile);
      await probeContainment({ settingsFile, config, exec: deps.probeExec });
      preparedSettingsFile = settingsFile;
    }
    return preparedSettingsFile;
  };

  return async (input, feedback) => {
    const settingsFile = await ensureSettingsFile();
    const runOne = async (prompt: string): Promise<string> => {
      const result = await spawn({
        cwd: input.targetDir,
        permissionMode: "bypassPermissions",
        settingsFile,
        prompt,
        model: SYNTHESIZE_MOUNT.model,
        effort: SYNTHESIZE_MOUNT.effort,
        maxTurns: SYNTHESIZE_MOUNT.maxTurns,
        tools: SPECIALIST_TOOLS,
      });
      return result.text.trim();
    };

    const [masterPlan, tasksYaml, agentsMd] = await Promise.all([
      runOne(buildSynthesizeMasterPlanPrompt(input)),
      runOne(buildSynthesizeTasksYamlPrompt(input, feedback)),
      runOne(buildSynthesizeAgentsMdPrompt(input)),
    ]);
    return { masterPlan, tasksYaml, agentsMd };
  };
}

export async function synthesizeCommand(rest: string[], deps: SynthesizeCommandDeps = {}): Promise<number> {
  const parsed = parseSynthesizeArgs(rest);
  if (!parsed.ok) {
    console.error(parsed.error + "\n" + USAGE);
    return 2;
  }
  const { targetDir } = parsed.args;

  console.log(`### rmd onboard ${targetDir} --phase synthesize`);

  const fsDep = deps.fs ?? realDeps().synthesize.fs;
  const gitDep = deps.git ?? realDeps().synthesize.git;
  const ghDep = deps.gh ?? realDeps().synthesize.gh;
  const draftDep = deps.draft ?? defaultSynthesizeDraft();

  let result;
  try {
    result = await runOnboardSynthesize(targetDir, { fs: fsDep, git: gitDep, gh: ghDep, draft: draftDep });
  } catch (e) {
    if (e instanceof SynthesizeError) {
      console.error(e.message);
      return 2;
    }
    throw e;
  }

  console.log(`branch: ${result.branch}`);
  console.log(`tasks drafted: ${result.tasks.length} (lint-plan clean after ${result.attempts} attempt(s))`);
  console.log(`wrote ${result.masterPlanPath}`);
  console.log(`wrote ${result.tasksYamlPath}`);
  console.log(`wrote ${result.agentsMdPath}`);
  console.log(`opened draft PR: ${result.prUrl}`);
  return 0;
}

/**
 * `rmd skill list|effectiveness` — the §5B skill-registry reader (W1-T44). Setup, Plan,
 * Feedback/triage, Retro, Review, Refactor, and Design Review are ALL the same
 * ground->research->grill-or-produce primitive, differing only by a
 * declarative profile; this prints every `.remudero/skills/<name>.yaml`
 * resolved, so a skill added by CONFIG ALONE (no source change) shows up here
 * with zero code touched. `skill` keeps explicit subcommands (not bare `rmd skill`) so a future
 * write verb (e.g. an `add`/`run`) has room without a breaking reshape. `effectiveness` is deliberately
 * read-only and implement-only for W1-T3379's first procedure-class pilot.
 */
export async function skillCommand(
  rest: string[],
  deps: { effectiveness?: typeof skillEffectivenessCommand; lifecycle?: typeof skillLifecycleCommand } = {},
): Promise<number> {
  const sub = rest[0];
  if (sub === "effectiveness") return (deps.effectiveness ?? skillEffectivenessCommand)(rest.slice(1));
  if (sub === "lifecycle") return (deps.lifecycle ?? skillLifecycleCommand)(rest.slice(1));
  if (sub !== "list") {
    console.error(`rmd skill: unknown subcommand '${sub ?? ""}' — usage: rmd skill list | rmd skill effectiveness <approved-skill> | rmd skill lifecycle <approved-skill>\n` + USAGE);
    return 2;
  }
  const badArg = unknownArgError("skill list", rest.slice(1), [], []);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }

  let skills;
  try {
    skills = loadSkillRegistry(skillsDir(repoRoot));
  } catch (e) {
    const message = e instanceof SkillError ? e.message : String((e as Error)?.message ?? e);
    console.error(`rmd skill list: ${message}`);
    return 1;
  }

  console.log(`### rmd skill list — ${skills.length} registered (.remudero/skills/)`);
  console.log(renderSkillList(skills));
  return 0;
}

/**
 * W1-T3379's evidence reader.  It reads the full rotated-ledger union, refuses an incomplete
 * corpus rather than silently turning missing history into a lifecycle recommendation, and makes
 * no writes—not even an analytics row—while reporting.
 */
export function skillEffectivenessCommand(
  rest: string[],
  deps: {
    stateDir?: string;
    readLedger?: typeof readLedgerUnionRecordsSync;
    write?: (text: string) => void;
    error?: (text: string) => void;
  } = {},
): number {
  const skillName = rest[0];
  if (!skillName || skillName.startsWith("-")) {
    (deps.error ?? console.error)("rmd skill effectiveness: usage: rmd skill effectiveness <approved-skill>");
    return 2;
  }
  const badArg = unknownArgError("skill effectiveness", rest.slice(1), [], []);
  if (badArg) {
    (deps.error ?? console.error)(badArg + "\n" + USAGE);
    return 2;
  }
  const stateDir = deps.stateDir ?? dirname(ledgerPathFor(loadConfig()));
  let ledgerUnion: ReturnType<typeof readLedgerUnionRecordsSync>;
  try {
    ledgerUnion = (deps.readLedger ?? readLedgerUnionRecordsSync)(stateDir, {
      step: SKILL_EFFECTIVENESS_LEDGER_STEPS,
      refuseIncomplete: true,
    });
  } catch (error) {
    const reason = String(error);
    (deps.error ?? console.error)(`rmd skill effectiveness: REFUSED unreadable ledger union: ${reason}`);
    return 1;
  }
  if (!ledgerUnion.ok) {
    (deps.error ?? console.error)(
      `rmd skill effectiveness: REFUSED incomplete ledger union under ${stateDir}: ` +
      `${ledgerUnion.unread.length} unread rotation(s)`,
    );
    return 1;
  }
  const report = buildSkillEffectivenessReport(ledgerUnion.rows, skillName);
  (deps.write ?? console.log)(renderSkillEffectivenessReport(report));
  return 0;
}

/**
 * W1-T3413's lifecycle bridge. It measures with the same reducer as `rmd skill effectiveness`,
 * then stages exactly one structured retirement proposal for qualified negative evidence.
 */
export function skillLifecycleCommand(
  rest: string[],
  deps: {
    stateDir?: string;
    registryPath?: string;
    approvedSkillsDir?: string;
    readLedger?: typeof readLedgerUnionRecordsSync;
    write?: (text: string) => void;
    error?: (text: string) => void;
  } = {},
): number {
  const skillName = rest[0];
  if (!skillName || skillName.startsWith("-")) {
    (deps.error ?? console.error)("rmd skill lifecycle: usage: rmd skill lifecycle <approved-skill>");
    return 2;
  }
  const badArg = unknownArgError("skill lifecycle", rest.slice(1), [], []);
  if (badArg) {
    (deps.error ?? console.error)(badArg + "\n" + USAGE);
    return 2;
  }
  const config = deps.stateDir && deps.registryPath && deps.approvedSkillsDir ? undefined : loadConfig();
  const stateDir = deps.stateDir ?? dirname(ledgerPathFor(config as Config));
  let ledgerUnion: ReturnType<typeof readLedgerUnionRecordsSync>;
  try {
    ledgerUnion = (deps.readLedger ?? readLedgerUnionRecordsSync)(stateDir, {
      step: SKILL_EFFECTIVENESS_LEDGER_STEPS,
      refuseIncomplete: true,
    });
  } catch (error) {
    const reason = String(error);
    (deps.error ?? console.error)(`rmd skill lifecycle: REFUSED unreadable ledger union: ${reason}`);
    return 1;
  }
  if (!ledgerUnion.ok) {
    (deps.error ?? console.error)(
      `rmd skill lifecycle: REFUSED incomplete ledger union under ${stateDir}: ` +
      `${ledgerUnion.unread.length} unread rotation(s)`,
    );
    return 1;
  }
  const report = buildSkillEffectivenessReport(ledgerUnion.rows, skillName);
  (deps.write ?? console.log)(renderSkillEffectivenessReport(report));
  const registryPath = deps.registryPath ?? join((config as Config).root, "state", "inbox-proposals.json");
  const approvedSkillsDir = deps.approvedSkillsDir ?? join(repoRoot, ".claude", "skills");
  const staged = stageSkillLifecycleProposal(registryPath, approvedSkillsDir, report);
  if (staged.refused) {
    (deps.error ?? console.error)(
      `rmd skill lifecycle: REFUSED ${staged.reason}; selected terminal_runs=${report.selected.terminal_runs}, ` +
      `control terminal_runs=${report.control.terminal_runs}` +
      (staged.withdrawn ? "; withdrew the stale staged retirement from the inbox" : ""),
    );
    return report.status === "REVIEW-CANDIDATE" ? 0 : 1;
  }
  const verb = staged.staged ? "staged" : staged.refreshed ? "refreshed" : "already staged";
  (deps.write ?? console.log)(
    `rmd skill lifecycle: ${verb} ${staged.proposalId} ` +
    `(evidence_fingerprint=${staged.evidenceFingerprint})`,
  );
  return 0;
}

// learningsCommand/learningsExportCommand/learningsImportCommand live in src/lib/report-commands.ts (W1-T2888).

const NARRATIVE_FOLD_KINDS: NarrativeFoldKind[] = ["decisions", "master-plan", "forensics"];

/** `rmd knowledge fold` (W1-T4096): {@link foldNarrativeStore} per store; its COMMANDS `detail` is the contract. */
export function knowledgeCommand(rest: string[], opts: { root?: string } = {}): number {
  const sub = rest[0];
  if (sub !== "fold") {
    console.error(`rmd knowledge: unknown subcommand '${sub ?? ""}' — usage: rmd knowledge fold [--store <kind>] [--dry-run]\n` + USAGE);
    return 2;
  }
  const args = rest.slice(1);
  const badArg = unknownArgError("knowledge fold", args, ["--store"], ["--dry-run"]);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const storeFlag = flagValue(args, "--store");
  if (storeFlag && !NARRATIVE_FOLD_KINDS.includes(storeFlag as NarrativeFoldKind)) {
    console.error(`rmd knowledge fold: unknown --store '${storeFlag}' — one of ${NARRATIVE_FOLD_KINDS.join(", ")}\n` + USAGE);
    return 2;
  }
  const kinds = storeFlag ? [storeFlag as NarrativeFoldKind] : NARRATIVE_FOLD_KINDS;
  const dryRun = args.includes("--dry-run");
  const root = opts.root ?? repoRoot;
  let anyChanged = false;
  for (const kind of kinds) {
    const report = foldNarrativeStore({ root, kind, dryRun });
    anyChanged = anyChanged || report.changed;
    console.log(`rmd knowledge fold: ${kind} — ${report.changed ? `${report.filesWritten.length} file(s) written` : "already folded"}`);
    for (const note of report.notes) console.log(`  ${note}`);
  }
  if (!anyChanged) console.log("rmd knowledge fold: nothing to fold");
  return 0;
}

/**
 * `rmd bundle export|import` — dispatches the day-one knowledge bundle verbs (W1-T2580 export,
 * W1-T2702 import). `import` is genuinely new CLI surface, not a reuse of the shipped `rmd
 * learnings import <file> --pin <hash>` (W1-T425) under a second name: {@link bundleImportCommand}
 * calls THAT command for the learnings/doctrine/worker-settings half (a {@link Bundle} really is
 * the `GlobalArtifact` shape it already verifies and writes, so that half needs no new code), then
 * ADDS the W1-T2702 half — staging `policy_proposals` into the inbox — which `rmd learnings
 * import` knows nothing about and never will.
 */
export function bundleCommand(rest: string[]): number {
  const sub = rest[0];
  if (sub === "export") return bundleExportCommand(rest.slice(1));
  if (sub === "import") return bundleImportCommand(rest.slice(1));
  console.error(
    `rmd bundle: unknown subcommand '${sub ?? ""}' — usage: rmd bundle export <path> | rmd bundle import <file> --pin <hash>\n` +
      USAGE,
  );
  return 2;
}

/**
 * `rmd bundle import <file> --pin <hash>` (W1-T2702, design (ii)): the receiving side of {@link
 * bundleExportCommand}. Two phases, in order:
 *
 * 1. THE LEARNINGS HALF (W1-T2580/W1-T425, unchanged): delegates to {@link learningsImportCommand}
 *    verbatim — same pin check ({@link verifyBundlePin}), same write to the RMD-GLOBAL artifact
 *    path. A phase-1 failure (bad pin, unreadable file, missing `--pin`) stops here; phase 2 never
 *    runs against a bundle that failed its OWN entries check.
 * 2. THE POLICY-PROPOSALS HALF (W1-T2702, new): an INDEPENDENT tamper check over `policy_proposals`
 *    ({@link verifyBundlePolicyProposalsPin} — `verifyBundlePin` above only ever covers `entries`,
 *    never this section, by design; see bundle.ts's `computePolicyProposalsHash` doc for why it is
 *    a separate pin rather than folded into the one hash), then {@link stageBundleProposals}
 *    (inbox.ts) — the ONLY write this phase performs. `plan/policy.yaml` is NEVER written by this
 *    command; only `rmd approve` merging a plan PR moves a value into it.
 *
 * `opts.registryPath` is injectable (tests) the same way every other registry-writing command in
 * this file takes one; defaults to the real `<config.root>/state/inbox-proposals.json`.
 */
export function bundleImportCommand(rest: string[], opts: { registryPath?: string } = {}): number {
  const file = rest[0];
  const badArg = unknownArgError("bundle import", rest.slice(1), ["--pin"], []);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  if (!file) {
    console.error(`rmd bundle import: <file> is required — usage: rmd bundle import <file> --pin <hash>\n` + USAGE);
    return 2;
  }
  const pin = flagValue(rest, "--pin");
  if (!pin) {
    console.error(`rmd bundle import: --pin <hash> is required — the operator-supplied hash the bundle must match\n` + USAGE);
    return 2;
  }
  let text: string;
  try {
    text = readFileSync(file, "utf8");
  } catch (e) {
    console.error(`rmd bundle import: cannot read ${file}: ${String((e as Error)?.message ?? e)}`);
    return 2;
  }

  const learningsExit = learningsImportCommand(rest, { usage: USAGE });
  if (learningsExit !== 0) return learningsExit;

  const proposalsCheck = verifyBundlePolicyProposalsPin(text);
  if (!proposalsCheck.ok) {
    console.error(`rmd bundle import: ${proposalsCheck.reason}`);
    return 1;
  }
  if (proposalsCheck.rows.length === 0) {
    console.log(
      "### rmd bundle import — the learnings/doctrine/worker-settings half imported above; " +
        "0 policy proposals in this bundle, nothing staged.",
    );
    return 0;
  }
  let sourceRepo = "unknown";
  let sourceSha = "unknown";
  try {
    const parsed = parseYaml(text) as { provenance?: { sourceRepo?: unknown; sourceSha?: unknown } };
    if (typeof parsed.provenance?.sourceRepo === "string") sourceRepo = parsed.provenance.sourceRepo;
    if (typeof parsed.provenance?.sourceSha === "string") sourceSha = parsed.provenance.sourceSha;
  } catch {
    // unreachable: verifyBundlePolicyProposalsPin above already parsed this exact text successfully.
  }
  const config = loadConfig();
  const registryPath = opts.registryPath ?? join(config.root, "state", "inbox-proposals.json");
  const result = stageBundleProposals(registryPath, proposalsCheck.rows, { sourceRepo, sourceSha, pin });
  console.log(
    `### rmd bundle import — staged ${result.staged.length} policy proposal(s)` +
      `${result.alreadyStaged.length > 0 ? `, ${result.alreadyStaged.length} already staged (skipped)` : ""}` +
      `${result.staged.length > 0 ? `: ${result.staged.join(", ")}` : ""}.\n` +
      `rmd inbox tiers them like any other proposal; rmd approve ratifies each into its own plan PR. ` +
      `plan/policy.yaml was not written by this command.`,
  );
  return 0;
}

/**
 * `rmd bundle export <path>` — THE MISSING EXPORT HALF (W1-T2580, extended by W1-T2702): assembles
 * this checkout's doctrine preamble, its BUDGET-SELECTED project learnings corpus (legacy `src`
 * lineage retained but structured `origin` omitted under the V1 canon — never filtered to `share: public`, unlike `rmd learnings export`'s §6
 * commons transport), the committed worker-settings template's ASSERTED values, and (W1-T2702)
 * every operator-ratified `plan/policy.yaml` row as a proposal, into one deterministic,
 * hash-pinned bundle ({@link buildBundle}, src/lib/bundle.ts) written to `<path>`. Refuses (writes
 * nothing) when the corpus selects zero entries, a candidate matches the leak-grep tripwire, the
 * worker-settings template fails validation, or `plan/policy.yaml` fails to parse — every refusal
 * is reported via the SAME {@link buildBundle} this command is a thin wrapper over, never
 * reimplemented here.
 *
 * `opts.projectDir`/`opts.headSha`/`opts.settingsPath`/`opts.policyPath`/`opts.now` are injectable,
 * same seam `learningsExportCommand` uses for `projectDir`/`headSha` — so a test can drive the real
 * success path over a fixture corpus, a fixture settings template, and a fixture policy file, and
 * can assert byte-identical output across two calls by pinning `now`/`headSha` rather than reading
 * the real clock/git history.
 */
export function bundleExportCommand(
  rest: string[],
  opts: { projectDir?: string; headSha?: () => string; settingsPath?: string; policyPath?: string; now?: () => string } = {},
): number {
  const out = rest[0];
  const badArg = unknownArgError("bundle export", rest.slice(1), [], []);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  if (!out) {
    console.error(`rmd bundle export: <path> is required — usage: rmd bundle export <path>\n` + USAGE);
    return 2;
  }
  const settingsPath = opts.settingsPath ?? join(repoRoot, "settings", "worker.json");
  let rawSettings: unknown;
  try {
    rawSettings = JSON.parse(readFileSync(settingsPath, "utf8"));
  } catch (e) {
    console.error(`rmd bundle export: cannot read worker-settings template ${settingsPath}: ${String((e as Error)?.message ?? e)}`);
    return 1;
  }
  const policyPath = opts.policyPath ?? join(repoRoot, "plan", "policy.yaml");
  let policyYamlText: string;
  try {
    policyYamlText = readFileSync(policyPath, "utf8");
  } catch (e) {
    console.error(`rmd bundle export: cannot read policy file ${policyPath}: ${String((e as Error)?.message ?? e)}`);
    return 1;
  }
  const entries = loadLearningsCorpus(opts.projectDir ?? projectLearningsHome(repoRoot));
  let sourceRepo = "unknown";
  try {
    const { owner, repo } = resolveOwnerRepo();
    sourceRepo = `${owner}/${repo}`;
  } catch {
    // no origin remote configured — provenance degrades to "unknown", never a crash.
  }
  const readHeadSha =
    opts.headSha ?? (() => execFileSync("git", ["-C", repoRoot, "rev-parse", "HEAD"], { encoding: "utf8" }).trim());
  let sourceSha = "unknown";
  try {
    sourceSha = readHeadSha() || "unknown";
  } catch {
    // no git history readable — same degrade-to-"unknown" as above.
  }
  const readNow = opts.now ?? (() => new Date().toISOString());
  const result = buildBundle(entries, rawSettings, { sourceRepo, sourceSha, exportedAt: readNow() }, { policyYamlText });
  if (!result.ok) {
    console.error(`rmd bundle export: ${result.reason}`);
    return 1;
  }
  writeFileSync(out, renderBundle(result.bundle), "utf8");
  const n = result.bundle.entries.length;
  const p = result.bundle.policy_proposals.length;
  console.log(
    `### rmd bundle export — wrote ${out}: ${n} learning${n === 1 ? "" : "s"} + doctrine + worker-settings ` +
      `conventions + ${p} policy proposal${p === 1 ? "" : "s"} from ${sourceRepo}@${sourceSha.slice(0, 12)}.\n` +
      `hash=${result.bundle.hash}\n` +
      `Carry this file to a fresh deployment: rmd bundle import ${out} --pin ${result.bundle.hash} — stages the ` +
      `learnings/doctrine/worker-settings half AND the ${p} policy proposal${p === 1 ? "" : "s"} into the inbox for ` +
      `the receiving operator to ratify. plan/policy.yaml is never written by import.`,
  );
  return 0;
}

/** `before`/`after` line for `rmd correct` — the operator-facing flip. */
function describeProjection(label: string, proj: StatusProjection): string {
  const pr = proj.prUrl ? `${proj.prUrl}${proj.prState ? ` (${proj.prState})` : ""}` : "none";
  return `### rmd correct — ${label}: status=${proj.status} merged=${proj.merged} source=${proj.source} pr=${pr}`;
}

/**
 * `rmd correct <task-id> --pr <n> [--reason <text>]` — the SANCTIONED correction
 * writer (MASTER-PLAN P9 / W1-T75, the W1-T20c/#134 stranding): a thin CLI wrapper
 * over {@link applyCorrection} (unit-tested independently, the same split
 * `fleet-control.ts`'s `requestStop`/`requestPause` use for `rmd stop`/`rmd pause`).
 * Prints the derived status before and after so the operator SEES the flip.
 */
async function correctCommand(rest: string[]): Promise<number> {
  const taskId = rest[0];
  const badArg = unknownArgError("correct", rest.slice(1), ["--pr", "--reason"], []);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const prFlag = flagValue(rest, "--pr");
  if (!prFlag) {
    console.error(`rmd correct: --pr <n> is required — usage: ${commandSyntax("correct")}\n` + USAGE);
    return 2;
  }

  const planPath = join(repoRoot, "plan", "tasks.yaml");
  const plan = loadPlan(planPath);
  const task = plan.byId.get(taskId);
  if (!task) {
    console.error(`rmd correct: unknown task '${taskId}' (not found in ${planPath})`);
    return 2;
  }

  const config = loadConfig();
  const { owner } = resolveOwnerRepo();
  const github = ghGateway(owner, task.repo);
  const ledgerPath = ledgerPathFor(config);
  const result = applyCorrection(task, prFlag, { ledgerPath, github }, { reason: flagValue(rest, "--reason") });

  console.log(describeProjection("before", result.before));
  if (!result.written) {
    console.error(
      `rmd correct: could not resolve PR '${prFlag}' in ${owner}/${task.repo} via \`gh\` — nothing written.`,
    );
    return 1;
  }
  console.log(describeProjection("after", result.after));
  console.log(
    `### rmd correct — ${taskId} now credits ${result.prUrl} (source=correction, supreme over rungs a/b/c). ` +
      `Append-only; no ledger rewrite.`,
  );
  return 0;
}

/**
 * W1-T4691 — THE SANCTIONED RELEASE FOR A HALTED TASK. `dispatch.circuit_broken`'s trip deliberately
 * survives a rotation and a daemon restart (W1-T2425), and the ONLY reset the breaker itself
 * understands is a new owned `pr.opened` — which a task the breaker refuses to dispatch can never
 * produce. Reading the archive to manufacture a reset was tried and rejected (it broke three
 * W1-T2425 invariants — see this task's rationale); the sanctioned alternative is an EXPLICIT,
 * ATTRIBUTABLE operator row, never an inference. Appends `dispatch.breaker_released`, which
 * `seedCountFromCircuitBreak`/`dispatchStreakTally` (status.ts) read exactly like a `pr.opened` reset,
 * so the task is dispatchable on the daemon's next tick. Best-effort closes the task's open
 * circuit-breaker needs-human issue (`dispatch.circuit_broken.escalated`'s `issue_url`, if one
 * exists and has not already gone terminal) with a pointer to the release row — a close failure is
 * reported but never blocks the release itself, since the ledger row is what dispatch reads.
 */
async function releaseCommand(rest: string[]): Promise<number> {
  const taskId = rest[0];
  const badArg = unknownArgError("release", rest.slice(1), ["--reason"], []);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const reason = flagValue(rest, "--reason");
  if (!reason) {
    console.error(`rmd release: --reason <text> is required — usage: ${commandSyntax("release")}\n` + USAGE);
    return 2;
  }

  const planPath = join(repoRoot, "plan", "tasks.yaml");
  const plan = loadPlan(planPath);
  const task = plan.byId.get(taskId);
  if (!task) {
    console.error(`rmd release: unknown task '${taskId}' (not found in ${planPath})`);
    return 2;
  }

  const config = loadConfig();
  const ledgerPath = ledgerPathFor(config);
  // W1-T8241: one release writer — the `release-non-worker-breaker` runbook calls the same function.
  const result = await releaseBreaker({
    ledgerPath,
    taskId,
    repo: task.repo,
    reason,
    actor: process.env.USER ?? "operator",
    releasedBy: `operator (\`rmd release ${taskId}\`)`,
    closeIssue: (url, comment) => {
      const { owner } = resolveOwnerRepo();
      ghIssueGateway(owner, task.repo).closeWithComment?.(url, comment);
    },
  });
  if (result.issue.kind === "closed") {
    console.log(`### rmd release — closed ${result.issue.url} (the circuit-breaker escalation this release resets).`);
  } else if (result.issue.kind === "close_failed") {
    console.error(`rmd release: could not close ${result.issue.url}: ${result.issue.error} — release row still written.`);
  }

  console.log(
    `### rmd release — ${taskId}: circuit breaker released (was ${result.releasedCount} dispatch(es) with no new ` +
      `owned PR). Reason: ${reason}. Dispatchable on the next tick; append-only, no ledger rewrite.`,
  );
  return 0;
}

// traceCommand moved to src/lib/report-commands.ts (W1-T2888) — imported/re-exported below.

// ── CLI entry (invoked by bin/rmd). Kept tiny; all logic is above/lib.
//
// COMMAND REGISTRY — the ONE source of truth for every `rmd <cmd>` name and its usage
// line. `rmd --help` (top-level) and `rmd <cmd> --help` (per-command) are BOTH generated
// from this array — neither is hand-maintained prose, so they cannot drift from each
// other. bin/rmd's header comment is documentation for humans reading the script; this
// array is what the running binary actually prints and dispatches against.
/**
 * PRIMARY CONTROL (W1-T1266's declared-kind convention): the ONLY thing keeping `summary` below
 * short — there is no runtime truncation behind it, so this cap binding is what actually stops a
 * summary from growing back into a paragraph, not a backstop behind some other check. Caps
 * `summary` below (W1-T2480) — long enough for a genuinely useful one-liner, short enough that
 * 63 of them printed together (`rmd --help`) stay a skimmable list rather than the
 * 41111-character wall of unwrapped prose it used to be. Enforced by
 * test/help-renders-a-summary-not-a-paragraph.test.ts: an over-cap summary is an authoring
 * mistake to catch in review, and silently truncating one at render time would be the exact
 * "quietly drops prose" regression that task guards against.
 */
export const SUMMARY_CHAR_CAP = 100;

// CommandSpec MOVED to src/cli/registry.ts (W1-T2893, decomposition step 10) — that file is now
// the one place a verb's help metadata is DECLARED as a type, alongside CommandHandler,
// RegisteredCommand, buildRegistry and dispatchCommand, so the registry can carry (and
// dispatchCommand can resolve) a verb's handler, not just its `--help` text. `COMMANDS` (the
// literal data array, just below) STAYS here: it is built from `renderFastGateScriptList`, a
// local function (scripts/rmd-help.mjs also source-scans src/run-task.ts's COMMANDS block
// directly for the no-SDK-load `rmd --help` path), so only the shared TYPE moved.
import {
  type CommandSpec,
  type CommandHandler,
  type RegisteredCommand,
  buildRegistry,
  dispatchCommand,
} from "./cli/registry.js";

export type HeavyVerbName = "review" | "dep-review" | "drain" | "daemon";

/** Exported for test only: the whole point of this switch is that a verb's heavy module is loaded
 *  ON DEMAND rather than at import, and "on demand" is a claim about which module each name pulls
 *  in. Unexported it was unreachable, and diff-coverage named every arm. */
export async function loadHeavyVerb(name: HeavyVerbName): Promise<void> {
  switch (name) {
    case "review":
    case "dep-review":
      await import("./lib/review.js");
      return;
    case "drain":
      await import("./lib/drain.js");
      return;
    case "daemon":
      await import("./lib/daemon.js");
      return;
  }
}

// W1-T5687: capture-diagnostics writes a bundle under <state>/diagnostics/, at most one per 15 min.
// Runs docker; recycles nothing (W1-T5688).
export function progressWatchdogCommand(
  rest: string[],
  run: (file: string, args: string[]) => string = (file, args) => execFileSync(file, args, { encoding: "utf8", timeout: 30_000 }),
): number {
  const badArg = unknownArgError("progress-watchdog", rest, ["--state-root"], ["--json"]);
  if (badArg) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const stateDir = flagValue(rest, "--state-root") ?? join(loadConfig().root, "state");
  const nowMs = systemClock.now();
  const read = readLedgerUnionRecordsSync(stateDir, {
    since: new Date(nowMs - 24 * 3_600_000).toISOString(),
    step: PROGRESS_WATCHDOG_READ_STEPS,
  });
  const count = openPrCountReadingFromRows(read.rows);
  const verdict = decideProgressWatchdog({ rows: read.rows, nowMs, openPrCount: count.count, openPrCountSource: count.source });
  const bundle = verdict.action === "capture-diagnostics"
    ? captureDiagnosticsBundle(stateDir, nowMs, verdict, read.rows, { run })
    : undefined;
  if (rest.includes("--json")) console.log(JSON.stringify({ stateDir, rowsRead: read.rows.length, ...verdict, bundle }));
  else {
    console.log(renderProgressWatchdogVerdict(verdict));
    if (bundle?.written) console.log(`diagnostics bundle: ${bundle.dir}`);
    else if (bundle) console.log(`diagnostics bundle skipped: ${bundle.skippedReason}`);
  }
  return 0;
}

export interface ClaimVerbOpts {
  reserver?: DispatchClaimReserver;
  isPlanned?: (taskId: string) => boolean;
  localHost?: string;
}

export function plannedOnOriginMain(taskId: string, dir: string = repoRoot): boolean {
  const git = (args: string[]) => spawnSync("git", ["-C", dir, ...args], { encoding: "utf8" });
  git(["fetch", "--quiet", "origin", "main"]);
  const shards = git(["ls-tree", "--name-only", "origin/main:plan/tasks.d"]);
  if (shards.status === 0 && (shards.stdout ?? "").split("\n").some((n) => isTaskShardName(n, taskId))) return true;
  const mono = git(["show", "origin/main:plan/tasks.yaml"]);
  const escaped = taskId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return mono.status === 0 && new RegExp(`^\\s*-?\\s*id:\\s*"?${escaped}"?\\s*$`, "m").test(mono.stdout ?? "");
}

export function claimCommand(rest: string[], opts: ClaimVerbOpts = {}): number {
  const taskId = rest[0];
  const badArg = taskId === undefined || taskId.startsWith("-")
    ? "rmd claim: a task id is required"
    : unknownArgError("claim", rest.slice(1), [], ["--drop", "--renew"]);
  if (badArg !== null) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(taskId)) {
    console.error(`rmd claim: '${taskId}' is not a task id`);
    return 2;
  }
  if (!(opts.isPlanned ?? plannedOnOriginMain)(taskId)) {
    console.error(`rmd claim: ${taskId} is not in the plan on origin/main — refusing to claim an unplanned id`);
    return 1;
  }
  const reserver = opts.reserver ?? dispatchClaimReserverFor(repoRoot);
  const ref = dispatchClaimRef(taskId);
  if (rest.includes("--drop")) {
    const sha = reserver.holder(taskId);
    if (!sha) {
      console.error(`rmd claim: ${ref} is not held — nothing to drop`);
      return 1;
    }
    const refusal = claimDropRefusal(ref, reserver.anchorMessage?.(taskId), opts.localHost ?? hostname());
    if (refusal !== undefined) {
      console.error(`rmd claim: ${refusal}`);
      return 1;
    }
    if (!reserver.drop(taskId, { expect: sha })) {
      console.error(`rmd claim: could not drop ${ref} (it moved or origin is unreachable)`);
      return 1;
    }
    console.log(`dropped ${ref}`);
    return 0;
  }
  if (rest.includes("--renew")) {
    const sha = reserver.holder(taskId);
    if (!sha) {
      console.error(`rmd claim: ${ref} is not held — nothing to renew`);
      return 1;
    }
    const refusal = claimDropRefusal(ref, reserver.anchorMessage?.(taskId), opts.localHost ?? hostname(), "renew");
    if (refusal !== undefined) {
      console.error(`rmd claim: ${refusal}`);
      return 1;
    }
    return reportClaimRenewal(ref, renewDispatchClaim(reserver, taskId, sha)) === undefined ? 1 : 0;
  }
  const outcome = reserver.attempt(taskId, reserver.mintAnchor());
  const decision = decideDispatchClaim(outcome, {
    taskId,
    holder: outcome === "taken" ? reserver.holder(taskId) : undefined,
    stderr: outcome === "unreachable" ? reserver.lastAttemptStderr?.() : undefined,
  });
  if (!decision.proceed) {
    console.error(`rmd claim: ${decision.reason}`);
    return 1;
  }
  console.log(`claimed ${ref}`);
  return 0;
}

function reportClaimRenewal(ref: string, renewal: DispatchClaimRenewal): string | undefined {
  if (renewal.outcome === "renewed") {
    console.log(`renewed ${ref} ${renewal.sha} ${new Date().toISOString()}`);
    return renewal.sha;
  }
  console.error(renewal.outcome === "lost"
    ? `rmd claim: lost ${ref} — it is now held by ${renewal.holder ?? "nobody"}`
    : `rmd claim: could not renew ${ref}: ${renewal.stderr}`);
  return undefined;
}

export type ClaimHoldSignal = "SIGINT" | "SIGTERM" | "SIGHUP";

export interface ClaimHoldOpts extends ClaimVerbOpts {
  signals?: {
    once(event: ClaimHoldSignal, listener: () => void): unknown;
    removeListener(event: ClaimHoldSignal, listener: () => void): unknown;
  };
}

export async function claimHoldCommand(rest: string[], opts: ClaimHoldOpts = {}): Promise<number> {
  const taskId = rest[0];
  const badArg = taskId === undefined || taskId.startsWith("-")
    ? "rmd claim: a task id is required"
    : unknownArgError("claim", rest.slice(1), ["--interval-ms"], ["--hold"]);
  if (badArg !== null) {
    console.error(badArg + "\n" + USAGE);
    return 2;
  }
  const intervalMs = Number(flagValue(rest, "--interval-ms") ?? DISPATCH_CLAIM_RENEW_INTERVAL_MS);
  if (!Number.isSafeInteger(intervalMs) || intervalMs <= 0 || !/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(taskId)) {
    console.error(`rmd claim: '${taskId}' is not a task id, or --interval-ms is not a positive integer`);
    return 2;
  }
  if (!(opts.isPlanned ?? plannedOnOriginMain)(taskId)) {
    console.error(`rmd claim: ${taskId} is not in the plan on origin/main — refusing to claim an unplanned id`);
    return 1;
  }
  const reserver = opts.reserver ?? dispatchClaimReserverFor(repoRoot);
  const held = takeOrAdoptClaim(taskId, reserver, opts.localHost ?? hostname());
  if (held === undefined) return 1;
  console.log(`holding ${dispatchClaimRef(taskId)} ${held}`);
  return await holdClaimUntilSignalled(taskId, reserver, held, intervalMs, opts.signals ?? process);
}

function takeOrAdoptClaim(taskId: string, reserver: DispatchClaimReserver, localHost: string): string | undefined {
  const anchor = reserver.mintAnchor();
  const outcome = reserver.attempt(taskId, anchor);
  if (outcome === "created") return anchor;
  const holder = outcome === "taken" ? reserver.holder(taskId) : undefined;
  if (holder !== undefined && claimDropRefusal(dispatchClaimRef(taskId), reserver.anchorMessage?.(taskId), localHost, "renew") === undefined) return holder;
  const stderr = outcome === "unreachable" ? reserver.lastAttemptStderr?.() : undefined;
  console.error(`rmd claim: ${decideDispatchClaim(outcome, { taskId, holder, stderr }).reason}`);
  return undefined;
}

function holdClaimUntilSignalled(
  taskId: string,
  reserver: DispatchClaimReserver,
  anchor: string,
  intervalMs: number,
  signals: NonNullable<ClaimHoldOpts["signals"]>,
): Promise<number> {
  const ref = dispatchClaimRef(taskId);
  const names: ClaimHoldSignal[] = ["SIGINT", "SIGTERM", "SIGHUP"];
  let held = anchor;
  return new Promise((resolve) => {
    const end = (code: number, drop: boolean): void => {
      clearInterval(timer);
      for (const name of names) signals.removeListener(name, onSignal);
      if (drop && reserver.drop(taskId, { expect: held })) console.log(`dropped ${ref}`);
      else if (drop) {
        console.error(`rmd claim: could not drop ${ref} (it moved or origin is unreachable)`);
        return resolve(1);
      }
      resolve(code);
    };
    const onSignal = (): void => end(0, true);
    const timer = setInterval(() => {
      const renewal = renewDispatchClaim(reserver, taskId, held);
      const next = reportClaimRenewal(ref, renewal);
      if (next !== undefined) held = next;
      else if (renewal.outcome === "lost") end(1, false);
    }, intervalMs);
    for (const name of names) signals.once(name, onSignal);
  });
}

export function capabilityInspectCommand(rest: string[], deps: Pick<AuthorityCommandDeps, "out" | "err"> = {}): number {
  const out = deps.out ?? console.log;
  const err = deps.err ?? console.error;
  if (rest.length === 1 && (rest[0] === "--help" || rest[0] === "-h")) {
    out(commandHelp(commandSpec("authority")));
    return 0;
  }
  const flags = new Map<string, string>();
  const permitted = new Set(["--store", "--request", "--cases", "--compare-cases", "--at"]);
  for (let i = 0; i < rest.length; i += 2) {
    const flag = rest[i];
    const value = rest[i + 1];
    if (!permitted.has(flag) || flags.has(flag) || !value || value.startsWith("--")) {
      err("rmd authority inspect: invalid arguments; see --help");
      return 2;
    }
    flags.set(flag, value);
  }
  const storePath = flags.get("--store");
  const at = flags.get("--at");
  const requestPath = flags.get("--request");
  const casesPath = flags.get("--cases");
  const comparePath = flags.get("--compare-cases");
  if (!storePath || !at || Boolean(requestPath) === Boolean(casesPath) || (comparePath && !casesPath)) {
    err("rmd authority inspect: require --store, --at and either --request or --cases; see --help");
    return 2;
  }
  const source = loadCapabilityInspectionSource(storePath);
  const read = readInspectionJson((requestPath ?? casesPath)!);
  if (requestPath) {
    const decision = inspectCapabilityDecision(source, read.ok ? read.value : null, at);
    out(JSON.stringify(decision));
    return decision.verdict === "allow" ? 0 : decision.verdict === "refuse" ? 1 : 2;
  }
  const baseline = replayCapabilityDecisions(source, read.ok ? read.value : null, at);
  const batches = [baseline];
  if (comparePath) {
    const comparisonRead = readInspectionJson(comparePath);
    const candidate = replayCapabilityDecisions(source, comparisonRead.ok ? comparisonRead.value : null, at);
    batches.push(candidate);
    out(JSON.stringify({ baseline, candidate, comparison: compareCapabilityReplays(baseline, candidate) }));
  } else out(JSON.stringify(baseline));
  if (batches.some((batch) => batch.code !== "evaluated"
    || batch.results.some((r) => r.verdict === "unknown" || r.verdict === "unavailable"))) return 2;
  return batches.some((batch) => batch.results.some((r) => r.verdict === "refuse")) ? 1 : 0;
}

