/**
 * W1-T2893 — `COMMANDS`' help metadata joined with {@link HANDLERS}, built ONCE at module load.
 * `buildRegistry` throws immediately if the two have drifted apart (a COMMANDS entry with no
 * handler, or vice versa is simply impossible to express — HANDLERS only has entries someone
 * wrote), which is what replaces test/help-registry.test.ts's old source-text scan of main()'s
 * if-ladder: the drift it used to catch by reading text is now a crash the first time `rmd` runs
 * at all, main() included.
 */
const REGISTRY: readonly RegisteredCommand[] = buildRegistry(COMMANDS, HANDLERS);

// ── CLI entry (invoked by bin/rmd). Kept tiny; all logic is above/lib.
export async function main(
  // W1-T79/W1-T221: the freshness check is injectable so a `callMain` test can drive the
  // "refused" branch below (its console.error+process.exit can't otherwise be covered — in CI
  // the real check returns "guarded", never "refused"). Default = the real self-sync check.
  deps: {
    checkFreshness?: typeof checkCliFreshness;
    checkServiceFreshness?: typeof checkServiceFreshness;
    /** The verb dispatch past the gate. Injectable so a test proves the GATE admits a verb
     *  without running that verb — `preflight`'s real handler is the whole fast gate. */
    dispatch?: typeof dispatchCommand;
  } = {},
): Promise<void> {
  const inspectionArgv = stripRepoRootFlag(process.argv.slice(2));
  if (inspectionArgv[0] === "inspect") {
    if (inspectionArgv.includes("--help") || inspectionArgv.includes("-h")) {
      console.log(commandHelp(commandSpec("inspect")));
      return await flushThenExit(0);
    }
    return await flushThenExit(readOnlyInspectionCommand(inspectionArgv.slice(1)));
  }
  if (inspectionArgv[0] === "gh" && inspectionArgv[1] !== "--help" && inspectionArgv[1] !== "-h") {
    return await flushThenExit(await ghCommand(inspectionArgv.slice(1)));
  }
  // Local inspection bypasses invocation logging, housekeeping, credentials and self-sync.
  if (inspectionArgv[0] === "authority" && inspectionArgv[1] === "inspect") {
    await flushThenExit(await dispatchCommand(inspectionArgv[0], inspectionArgv.slice(1), REGISTRY, USAGE));
    return;
  }
  // FIRST, before argv is even read: a rejection escaping any line below (the freshness gate's
  // own spawns included) must reach a ledger row and a named exit code, not Node's default crash.
  // See {@link installUnhandledRejectionGuard} — it is idempotent, so the in-process `main()`
  // calls this repo's `callMain` tests make do not stack listeners.
  installUnhandledRejectionGuard();
  setGhReadActorResolver((env) => deriveLedgerActor(env));
  // W1-T3065 — THE HAND LANE REAPS TOO. Until this line the temp sweep had exactly two callers,
  // both daemon rungs, so a machine running `rmd` by hand and no daemon reclaimed NOTHING: the
  // operator's Mac reached 100% of a 228 GiB volume with 138 stale dirs and 11 GiB of debris, and
  // an agent session failed outright because the harness could not write its own output file.
  //
  // ⚠ IT CAN NEVER FAIL THE VERB. `sweepStaleTempDirs` is documented best-effort and non-throwing,
  // and this call is wrapped anyway: a CLI command that died because a tmp sweep threw would be a
  // far worse defect than the disk filling. The age ceiling is unchanged, so a dir a concurrent
  // invocation is still using is never collateral.
  try {
    sweepStaleTempDirs();
  } catch {
    /* best-effort by contract — never let housekeeping fail the verb the operator asked for */
  }
  const [cmd, ...rest] = stripRepoRootFlag(process.argv.slice(2));
  if (cmd === "serve") markLedgerProcessActor("service");
  else if (cmd === "deploy-run") markLedgerProcessActor("host_automation");
  else if (cmd === "daemon") markDaemonProcessActor();
  // W1-T7094: every worker start this process makes writes its counterfactual `memory_budget.shadow` row to the
  // ledger of the root that start names. The recorder never throws and never delays the start; SHADOW ONLY.
  installShadowMemorySink((path, row) => appendLedger(path, row));
  installStarvationAlertSink(spoolingStarvationAlert({ source: "memory-budget", host: hostname(), clock: systemClock }));
  // W1-T2893: `arg` (== rest[0]) is no longer read here — each HANDLERS entry that needs it
  // (registry.ts's REGISTRY, built above) derives its own from `rest`, since the old flat
  // if-ladder this replaced is gone and this was its only remaining reader in main() itself.
  // W1-T477 signal (i): see logCliInvocation's own doc — first, unconditional, one row per
  // process regardless of which dispatch arm below (if any) ends up matching `cmd`.
  let invocationStateRoot = cmd === "deploy-run" && rest.includes("--state-root") ? flagValue(rest, "--state-root") ?? "" : undefined;
  if (cmd === "reframe" && (rest.includes("--input-id") || rest.includes("--instance"))) {
    const instance = flagValue(rest, "--instance");
    const selected = instance && flagValue(rest, "--input-id") ? explicitReframeTarget(instance) : undefined;
    invocationStateRoot = selected?.ok ? selected.target.root : "";
  }
  const registryObserver = logCliInvocation(cmd, rest, invocationStateRoot);
  if (cmd === "--help" || cmd === "-h" || cmd === "help") {
    console.log(USAGE);
    process.exit(0);
  }
  // Per-command help — checked BEFORE any dispatch below so `rmd <cmd> --help` never
  // reaches a command's business logic (e.g. `rmd notify --help` must not send a
  // notification whose message is the literal string "--help").
  const helpSpec = COMMANDS.find((c) => c.name === cmd);
  if (helpSpec && (rest.includes("--help") || rest.includes("-h"))) {
    console.log(commandHelp(helpSpec));
    process.exit(0);
  }
  // THE GITHUB APP IS THE FLEET HOST'S ONLY CREDENTIAL, and until now only `daemonCommand` and
  // `serveCommand` minted from it. `gh auth login` is never run there and the boot env deliberately
  // carries NO `GH_TOKEN` (deploy/recycle-container.sh, see github-app.ts's header), so every OTHER
  // verb that shells to `gh` — 32 call sites — failed on the one host the fleet actually runs on.
  // MEASURED 2026-09-06: `rmd review <pr>` inside the daemon container died in `ghJson`, which is
  // how a CAPPED verdict's own documented remedy, `--override-capped-by`, became unrunnable there.
  // Absent `GH_APP_*` — any dev machine — this is NOT AN ATTEMPT: it mints nothing, logs nothing and
  // leaves `GH_TOKEN` alone, so behaviour off the fleet host is byte-identical. Guarded on an absent
  // token so an operator's own exported `GH_TOKEN` is never clobbered, and unawaited failure is
  // reported rather than swallowed, because falling through to a bare `gh` error is what cost the
  // diagnosis above.
  // W1-T3071: THE MINT SITS BELOW THE HELP ARMS, and the four lines above are why. Both arms
  // `process.exit(0)` before any dispatch, so a help invocation cannot shell `gh` BY CONSTRUCTION
  // -- which makes this an exemption that cannot silently grow, not a verb list to curate. An
  // UNKNOWN verb matches neither arm, falls through here, and still mints before dispatch, so
  // #4298's guarantee is unchanged for every path that can actually use a token.
  //
  // MEASURED 2026-09-07 with the mint above the arms: `rmd --help` emitted
  // `github_app.token_refreshed {...}` to stderr on every invocation, reddening
  // doctor-node-pin's two assertions (exactly-one-line, and empty) on the fleet host itself, and
  // cost ~120ms (700/723/734 vs 592/615/592 with GH_TOKEN preset). The mint is AWAITED and carries
  // EXCHANGE_TIMEOUT_MS (20s, src/lib/github-app.ts:66), so on an unreachable network that ceiling
  // stood between the operator and `usage:`.
  if (!process.env.GH_TOKEN) {
    await refreshInstallationToken({
      log: (step, extra) => console.error(`rmd: ${step} ${extra ? JSON.stringify(extra) : ""}`.trim()),
    });
  }
  // W1-T79: CLI self-freshness, checked directly after the (mandatory, every-call) help
  // preamble above and BEFORE any command's real dispatch — the #138 incident shape: `rmd
  // correct` existed on origin/main, but the OPERATOR's own invocation was a stale checkout
  // that predated the merge and printed the old usage instead. "rmd should be managing git
  // for me" is the requirement, verbatim (see src/lib/self-sync.ts for the full contract:
  // clean+behind auto-ff-pulls and re-execs once; dirty/diverged refuses with the exact
  // remedy and never mutates; up-to-date and the loop-guarded re-exec's child are both
  // total no-ops). A "refused" result must never fall through to dispatch below.
  // W1-T255: a LONG-RUNNING SERVICE (`rmd daemon`/`rmd serve`) NEVER exit-1s on tree state. The
  // interactive-operator refusal below crash-looped the daemon after the #707 aftermath — the
  // daemon dirties its OWN tree (DECISIONS.md/feedback/state exhaust), so every launchd restart hit
  // "dirty + behind -> refuse -> exit 1". Dirt never blocks a service; behind-origin is the deploy
  // supervisor's remit (WS-2) — assess + ledger + proceed, never refuse, never self-re-exec.
  if (cmd === "daemon" || cmd === "serve") {
    serviceFreshnessGate(cmd, repoRoot, process.env, deps);
    // ALWAYS proceed — never exit, never re-exec. Genuine corruption fails later in loadPlan.
  } else if (cmd === "deploy-run") {
    // impl-BD — THE CIRCULAR REFUSAL. `deploy-run` is the deploy supervisor's cycle (the
    // com.remudero.supervisor launchd unit invokes it every 120s), and its entire purpose is to
    // fast-forward a stale checkout. `checkCliFreshness` refuses when the tree is BEHIND *and*
    // DIRTY (self-sync.ts:164-176), so the verb that exists to fix staleness was refused FOR
    // BEING STALE. Reproduced live: "rmd is behind origin/main (e9fa9ac..97e6857) and the
    // working tree has uncommitted changes -- refusing to auto-sync". The ledger carries ZERO
    // deploy.* events across the live file and all 661 rotations — the supervisor has never
    // completed a cycle.
    //
    // NO GATE AT ALL here, deliberately, and NOT `serviceFreshnessGate` like daemon/serve:
    // that gate's last line calls `ensureInstallFresh`, which runs `npm ci` when the lockfile
    // hash moved (run-task.ts's ensureInstallFresh). An unattended `npm ci` on a 120-second
    // supervisor cycle is the exact shape that emptied this host's node_modules and
    // crash-looped the daemon. deploy-run needs the REFUSAL lifted, not an installer added.
    //
    // The safety this removes is replaced by a strictly BETTER guard the deployer already
    // owns: `treeFfSafe` (lib/deployer.ts:102) refuses only when a locally-modified path is
    // ALSO in the incoming diff — path-aware, returning "dirty-tree-conflict" and ledgering
    // `deploy.abort_dirty_tree` (lib/deployer.ts:236-242) — and it sits directly in front of
    // `pullFf()`. The outer gate was blunt (any dirt + any staleness) and fired first, which is
    // why the precise one had never run. Every OTHER verb keeps the refusal: `review`,
    // `lint-plan`, `triage`, `approve` and the rest read the plan, and a stale plan gives a
    // wrong answer — which is the whole point of the gate.
  } else if (cmd === "sync") {
    // W1-T907: `rmd sync` is the explicit operator verb that EXISTS to unstick exactly the case
    // this gate refuses below (behind origin/main AND dirty) — gating it behind that same
    // refusal would mean it could only ever run when it had nothing left to do. This does NOT
    // touch `checkCliFreshness`'s own predicate (W1-T446 owns that; design (i) of the task
    // record keeps self-sync.ts out of this task's `files:` entirely) — it only exempts THIS
    // verb's own entry point from a guard whose refusal is the exact problem it exists to fix.
    // src/lib/operator-sync.ts owns its own, independent safety (the BLOCKING/off-main refusals
    // and the preserve-aside-before-discard ordering), unrelated to this gate's dirty check.
  } else if (READ_ONLY_FRESHNESS_EXEMPT_VERBS.has(cmd ?? "")) {
    // W1-T1134: THE GATE'S AXIS IS DISPATCH-OR-DECIDE, NOT "WRITES NOTHING" (rationale (5) of
    // the task record). `checkCliFreshness`'s off-main arm refuses because fast-forwarding
    // "would move your work's base out from under it" — a refusal to MUTATE. The blanket `else`
    // below escalates that into a refusal to RUN, which is right for a verb whose ANSWER is
    // derived from the plan and then ACTED ON (`run-task`, `drain`, `triage`, `fix`, `approve`,
    // `review`, `lint-plan` — all unchanged, all still fall to the `else`), but wrong for a verb
    // that only reads the ledger/state/plan and prints. `deploy/entrypoint.sh` detaches the
    // daemon's checkout on every boot, so these are exactly the verbs an operator reaches for on
    // that host and finds refused until the next merge to `main`.
    //
    // THE EXEMPT SET IS THIS DECLARED LIST — see READ_ONLY_FRESHNESS_EXEMPT_VERBS below — not a
    // heuristic over the verb name and not `--dry-run` flag-sniffing (design (ii)): a flag can be
    // absent and the verb still dispatch, so `sweep`/`inbox` stay OUT even though their
    // `--dry-run` forms are read-only — exempting the verb name would also exempt their
    // non-dry-run dispatch. `doctor`'s own registry entry is READ-ONLY by construction (`--fix`
    // is refused by name; every check reads the ledger, state/, plan/, /proc or ps) and is
    // explicitly built for "a cold ssh session while remudero-serve is down" — precisely when
    // this gate would otherwise block it. `status` is the one genuine judgement call (design
    // (v)): its own registry entry says "writes nothing", but `src/lib/status.ts` documents that
    // its `state/status.json` cache write is real — included here anyway because that write is a
    // machine-owned cache, never a decision this gate exists to protect, so it sits on the same
    // side of the dispatch-or-decide axis as `doctor`.
    //
    // Does NOT touch `checkCliFreshness`'s own predicate, message or ledger row (W1-T446 owns
    // that) — only where the gate applies, never what it decides (design (i)).
  } else {
    const freshness = (deps.checkFreshness ?? checkCliFreshness)(repoRoot, process.env, selfSyncRefusalSink(cmd, rest));
    if (freshness.status === "refused") {
      console.error(freshness.message);
      process.exit(1);
    }
    if (freshness.status === "synced") return;
  }
  // W1-T2893: every verb's dispatch used to be a flat if-ladder here (one `if (cmd === "x")
  // { process.exit(await xCommand(rest)); }` per verb, ~300 lines). That ladder is now
  // src/cli/registry.ts's HANDLERS map (built once, just above) plus dispatchCommand, which
  // resolves `cmd` against REGISTRY and invokes its handler -- main() keeps only the
  // process-boundary concerns the task record calls out: the freshness gate above, and the
  // exit code translation right here.
  realDeps();
  if (!deps.dispatch) {
    let runtime: ReturnType<typeof buildEscalationTriageRuntime> | undefined;
    configureEscalationTriage((escalationDeps) => {
      if (!runtime) {
        const config = loadConfig();
        const { owner, repo } = resolveOwnerRepo();
        runtime = buildEscalationTriageRuntime({ root: repoRoot, config, owner, repo });
      }
      return runtime(escalationDeps);
    });
  }
  // W1-T4063: exit only after stdout/stderr have drained — a bare process.exit() dropped every line a
  // pipe had not yet taken (522 of 280,672 for a piped `rmd ledger-grep`).
  await flushThenExit(
    await withSelectedRegistryContext(registryObserver, async () => deps.dispatch
      ? await deps.dispatch(cmd, rest, REGISTRY, USAGE) : await dispatchCommand(cmd, rest, REGISTRY, USAGE)),
  );
}

// W1-T9722: the read-plane worker starts from ./lib/tick-read-worker.ts, never from this module; a worker
// that loads this module anyway still never runs the CLI. Kept OUTSIDE the process-boundary region below.
const readWorkerOptions = readPlaneWorkerInput();

// diff-cov: process-boundary - direct CLI guard; imported tests cover `main()` and
// `exitCodeFor()`, while this wrapper only prints and exits the current process.
// Only run when invoked directly (not when imported by tests).
if (!readWorkerOptions && process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main().catch((err) => {
    console.error("\n### RUN-TASK ERROR\n" + (err?.stack ?? String(err)));
    // W1-T2901: the process boundary asks the error its own exit code (an `RmdError` such as
    // `PlanError` answers with its declared code) instead of hardcoding the generic one for
    // every uncaught throw — a foreign `Error` still falls through to the same code as before.
    void flushThenExit(exitCodeFor(err));
  });
}

